; ===== j_start =====
; prototype: void __usercall j_start()

    SECTION text,CODE
j_start:
                jmp     start
aSensibleWorldO:
                dc.b 'SENSIBLE WORLD OF SOCCER',0
aCopyrightC1994:
                dc.b 'Copyright (C) 1994/1995 Sensible Software (6/11/1996)',0
aCopyrightC1994_0:
                dc.b 'Copyright (C) 1994/1995 Chris Chapman (6/11/1996)',0
aSwosVersion152:
                dc.b 'SWOS VERSION 152',0
a0611961355Asm6:
                dc.b '(06/11/96 13.55) ASM 6/11/1996',0,0
aCj0611143807:
                dc.b 'CJ0611143807'

; ===== start =====
; prototype: void __usercall start()
start:
                ;move.l  #loc_1000D0,(DIVIDE_BY_ZERO).w
                ;divu.w  #0,d0
loc_1000D0:
                move.l  sp,S_SavedSP
                movea.l  #stackTop,sp
                ;movea.l #$CC8C,sp
                jsr     SafeStart
                jsr     LoadDosLibrary
                jsr     DetachOSDisplay
                jsr     InitHardwareAtFrameStart
                lea     (loaderBankBitmap).l,a0
loc_1000E2:
                move.w  #$5555,(a0)+
                cmpa.l  #chipRamBitmapEnd,a0
                bne.s   loc_1000E2
                lea     (pitchDatBuffer).l,a0
                lea     (currentMenu).l,a1
loc_1000F4:
                move.w  #$BBBB,(a0)+
                ;cmpa.l  #1043190,a0
                cmpa.l  a1,a0
                bne.s   loc_1000F4
                move.l  #$12345678,(magicValue).l
                move.l  #CHIPMEMSIZE,(loaderMemTop).l
                move.l  #(CHIPBITS|FASTBITS),(loaderBankBitmap).l
                move.l  #FASTBITS,(loaderParam).l
                ;move    #$2000,sr
                move.w  #0,(COLOR00).l
                lea     (frontbufferBase).l,a0
                lea     (frontbufferBaseAlt).l,a1
                lea     (frontbufferMaskBuffer).l,a2
                move.l  #FRONTBUFFER_SIZE_TOTAL_BYTES,d0
loc_100140:
                move.w  #$0,(a0)+
                move.w  #$0,(a1)+
                move.w  #$0,(a2)+
                subq.l  #2,d0
                bne.s   loc_100140
                move.w  #$8340,(DMACON).l
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  S_VBR,a0
                move.l  #Int2KeyboardHandler,LEVEL_2_INTERRUPT_AUTOVECTOR(a0)
                move.l  #Int3TimerHandler,LEVEL_3_INTERRUPT_AUTOVECTOR(a0)
                move.l  #Int4Handler,LEVEL_4_INTERRUPT_AUTOVECTOR(a0)
                jsr     SetupInterrupts
                move.b  #$88,(CIAA_ICR).l
                move.w  #$C008,(INTENA).l
                move.b  #$82,(CIAA_ICR).l
                bset    #1,(CIAA_DDRA).l
                bset    #1,(CIAA_PRA).l
                jsr     main
                jsr     ExitToDos
                rts

