; ===== AssetSys_InitContext =====
; prototype: __int16 __usercall AssetSys_InitContext@<d0>(void *loaderBase@<a0>, const char *disk0Path@<a1>, const char *disk1Path@<a2>, const char *disk2Path@<a3>, const char *disk3Path@<a4>)
AssetSys_InitContext:
                movem.l d1-d7/a0-a6,-(sp)
                lea     assetBasePtr(pc),a6
                move.l  a0,(a6)
                lea     $4D00(a0),a0
                lea     assetAltBasePtr(pc),a6
                move.l  a0,(a6)
                lea     assetSource0(pc),a0
                move.l  a1,(a0)
                lea     assetSource1(pc),a0
                move.l  a2,(a0)
                lea     assetSource2(pc),a0
                move.l  a3,(a0)
                lea     assetSource3(pc),a0
                move.l  a4,(a0)
                move.w  #3,d3
                movea.l assetBasePtr(pc),a1
                bsr.w   FloppyDev_TransferImpl
                lea     assetSourceVec(pc),a6
                lea     (kDriveListPtrs).l,a3
                clr.w   d1
build_source_vec_loop:
                movea.l (a3)+,a0
                btst    d1,d0
                bne.s   store_source_entry
                movea.l #0,a0
store_source_entry:
                move.l  a0,(a6)+
                addq.w  #1,d1
                cmpi.w  #4,d1
                bne.s   build_source_vec_loop
                lea     assetIndexStartBytes(pc),a0
                clr.l   (a0)
                lea     assetCurrentSourceSlot(pc),a0
                clr.w   (a0)
                lea     assetCurrentIndex(pc),a0
                clr.w   (a0)
                clr.w   d0
                movem.l (sp)+,d1-d7/a0-a6
                rts
