; ===== AssetSys_SelectAndOpen =====
; prototype: __int32 __usercall AssetSys_SelectAndOpen@<d0>(unsigned __int16 asset_index@<d0>)
AssetSys_SelectAndOpen:
                movem.l d1-d7/a0-a6,-(sp)
                move.w  d0,d7
                bra.w   loc_10049E
                lea     assetIndexStartBytes(pc),a5
                lea     -1(a5,d0.w),a5
                move.b  (a5),d6
                ext.w   d6
                lea     assetSource0(pc),a1
                subq.w  #1,d0
                lsl.w   #2,d0
                movea.l (a1,d0.w),a6
                lea     assetSourceVec(pc),a4
                move.w  #3,d5
asset_select_and_open_attempt_loop:
                move.w  d6,d0
                lsl.w   #2,d0
                movea.l (a4,d0.w),a0
                cmpa.l  #0,a0
                beq.s   asset_select_and_open_next_slot
                move.w  (assetCurrentSourceSlot).l,d2
                move.w  d6,(assetCurrentSourceSlot).l
                movea.l a6,a0
                bsr.s   AssetSys_Op5ThenMaybe6
                move.w  d2,(assetCurrentSourceSlot).l
                tst.l   d0
                beq.s   asset_select_and_open_success
asset_select_and_open_next_slot:
                addq.w  #1,d6
                andi.w  #3,d6
                dbf     d5,asset_select_and_open_attempt_loop
                moveq   #$FFFFFFFF,d0
                bra.s   asset_select_and_open_exit
asset_select_and_open_success:
                lea     assetCurrentSourceSlot(pc),a0
                move.w  d6,(a0)
                move.b  d6,(a5)
loc_10049E:
                lea     assetCurrentIndex(pc),a0
                move.w  d7,(a0)
                clr.w   d0
asset_select_and_open_exit:
                movem.l (sp)+,d1-d7/a0-a6
                rts

; ===== AssetSys_OpenAnySource =====
; prototype: __int16 __usercall AssetSys_OpenAnySource@<d0>()
AssetSys_OpenAnySource:
                movem.l d1-d7/a0-a6,-(sp)
