                move.w  #$4000,$24(a1)
                move.w  #$8210,$96(a1)
                move.w  #$6600,$9E(a1)
                move.w  #$9500,$9E(a1)
                move.w  #$4489,$7E(a1)
                move.l  a0,$20(a1)
                move.w  #2,$9C(a1)
                lsr.w   #1,d0
                ori.w   #$8000,d0
                move.w  d0,$24(a1)
                move.w  d0,$24(a1)
                rts

; ===== FloppyDMA_WaitBlitterDone =====
; prototype: unsigned int __usercall FloppyDMA_WaitBlitterDone@<d0>()
FloppyDMA_WaitBlitterDone:
                lea     (CUSTOM).l,a1
                move.l  #$9C4,d0
                bsr.w   FloppyTimer_StartCiaB
blitter_wait_loop:
                btst    #1,$1F(a1)
                bne.s   blitter_done_ok
                bsr.w   FloppyTimer_WaitIfRunning
                bne.s   blitter_wait_loop
                moveq   #$FFFFFFFF,d0
