                move.w  #$4000,(DSKLEN).l
                tst.l   d0
                rts

; ===== FloppyHW_PrepareAdkcon =====
; prototype: void __usercall FloppyHW_PrepareAdkcon()
FloppyHW_PrepareAdkcon:
