        xdef    Int2KeyboardHandler
; ===== Int2KeyboardHandler =====
; prototype: void __interrupt Int2KeyboardHandler()
Int2KeyboardHandler:
                movem.l d0-d7/a0-a6,-(sp)
                lea     (CUSTOM).l,a6
                move.w  $1E(a6),d0
                btst    #3,d0           ; I/O Ports and timers fired?
                beq.w   _101BB4_done
                move.b  (CIAA_ICR).l,d0 ; CIAA interrupt control register
                btst    #7,d0           ; IR
                beq.w   acknowledge_int
                btst    #3,d0           ; SP
                beq.w   acknowledge_int
                jsr     KBHook
                ;move.b  (CIAA_SDR).l,d0
                bset    #6,(CIAA_CRA).l
                move.w  #300,d1
loc_101B6A:
                move.l  (VPOSR).l,d2
                dbf     d1,loc_101B6A
                bclr    #6,(CIAA_CRA).l
                not.b   d0
                ror.b   #1,d0
                clr.w   (keyDelay).l
                move.b  d0,(keyIn).l
                bmi.s   acknowledge_int
                move.w  keyCount(pc),d1
                cmpi.w  #9,d1
                beq.s   acknowledge_int
                move.w  #$800C,(keyDelay).l
                lea     keyBuffer(pc),a0
                move.b  d0,(a0,d1.w)
                addq.w  #1,(keyCount).l
acknowledge_int:
                move.w  #8,$9C(a6)      ; ack I/O Ports and timers
_101BB4_done:
                movem.l (sp)+,d0-d7/a0-a6
                rte
keyDelay:
                dc.w $0000
keyCount:
                dc.w $0000              ; Number of keys in the buffer
keyBuffer:
                dc.b $00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
writeOnly01:
                dc.w $0001
lastVBlankServiceTick:
                dc.w $0000

; ===== Int3TimerHandler =====
; prototype: void __interrupt Int3TimerHandler()
Int3TimerHandler:
                movem.l d0-d7/a0-a6,-(sp)
                lea     (CUSTOM).l,a6
                tst.w   (waitingInterrupt).l
                beq.w   isr_common_housekeeping
                move.w  (currentGameTick).l,d0
                sub.w   lastVBlankServiceTick(pc),d0
                cmp.w   writeOnly01(pc),d0
                bcs.s   isr_common_housekeeping
                move.w  (currentGameTick).l,(lastVBlankServiceTick).l
                bsr.w   UpdatePlanePtrsAndBlitParams
                move.w  (cameraX).l,d1
                move.w  (cameraY).l,d2
                bsr.w   SwapBuffersAndCameraViewState
                bsr.w   SetCameraCoordinates
                clr.w   (waitingInterrupt).l
                move.w  #1,(didSwapThisFrame).l
                bra.w   *+4
isr_common_housekeeping:
                bsr.w   FadeOutTick
                bsr.w   FadeInTick
                clr.b   (audioDbgFlagA).l
                tst.w   (audioActive).l
                beq.s   isr_after_audio_irq
                jsr     AudioIRQEntryThunk
                move.b  d0,(audioDbgFlagA).l
isr_after_audio_irq:
                tst.w   (debug_mode).l
                beq.s   isr_update_ticks_and_input
                dc.b -96
                dc.b $00
isr_update_ticks_and_input:
                addq.w  #1,(currentTick).l
                tst.w   (showingUserStats).l
                bne.s   isr_paused_path
                tst.w   (paused).l
                bne.s   isr_paused_path
                addq.w  #1,(currentGameTick).l
                tst.w   (keyDelay).l
                bpl.s   isr_paused_path
                subq.w  #1,(keyDelay).l
                bmi.s   isr_paused_path
                move.b  (keyIn).l,d0
                move.w  keyCount(pc),d1
                cmpi.w  #9,d1
                beq.s   kb_buffer_full
                lea     keyBuffer(pc),a0
                move.b  d0,(a0,d1.w)
                addq.w  #1,(keyCount).l
kb_buffer_full:
                move.w  #$8004,(keyDelay).l
isr_paused_path:
                move.w  #%100,(INTREQ).l ; clear software initiated interrupt.
                bra.w   return_interrupt
                btst    #4,(INTREQR+1).l
                beq.w   return_interrupt
                move.w  #$10,(INTREQ).l
return_interrupt:
                movem.l (sp)+,d0-d7/a0-a6
                rte
blank_bytes:
                dc.b $00
                dc.b $00

; ===== GetKey =====
; prototype: unsigned __int16 __usercall GetKey@<d0>()
; out:
;       ASCII code in convertedKey 
;       scan code in lastKey
;       0 if nothing pressed
;       
; destroys: eax, ebx, esi
; [ebp safe]
GetKey:
                moveq   #0,d0
read_next_key:
                move.w  keyCount(pc),(currentKey).l
                beq.s   return_no_key
                move.w  #8,(INTENA).l
                lea     keyBuffer(pc),a0
                move.b  (a0),d0
                move.b  1(a0),(a0)+
                move.b  1(a0),(a0)+
                move.b  1(a0),(a0)+
                move.b  1(a0),(a0)+
                move.b  1(a0),(a0)+
                move.b  1(a0),(a0)+
                move.b  1(a0),(a0)+
                move.b  1(a0),(a0)+
                move.b  1(a0),(a0)+
                subq.w  #1,(keyCount).l
                move.w  #$8008,(INTENA).l
                move.b  keycodeLut(pc,d0.w),d0
                cmpi.b  #$3F,d0         ; '?'
                beq.s   read_next_key
                move.w  d0,(currentKey).l
return_no_key:
                rts
; unsigned __int8[128]
keycodeLut:
                dc.b $27,$31,$32,$33,$34,$35,$36,$37,$38,$39,$30,$2D,$3D,$5C,$3F,$B0
                dc.b $51,$57,$45,$52,$54,$59,$55,$49,$4F,$50,$5B,$5D,$3F,$B1,$B2,$B3
                dc.b $41,$53,$44,$46,$47,$48,$4A,$4B,$4C,$3B,$27,$3F,$3F,$B4,$B5,$B6
                dc.b $3F,$5A,$58,$43,$56,$42,$4E,$4D,$2C,$2E,$2F,$3F,$3F,$B7,$B8,$B9
                dc.b $20,$7F,$3F,$0D,$0D,$1B,$7E,$3F,$3F,$3F,$AD,$3F,$10,$11,$12,$13
                dc.b $80,$81,$82,$83,$84,$85,$86,$87,$88,$89,$A8,$A9,$AF,$AA,$AB,$3F
                dc.b $3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F
                dc.b $3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F,$3F

; --------------------------------------------------------------------------
; WriteCopperPalette
; Patch palette VALUE words in copperListBuffer using fixed offsets (no scan).
;
; In:
;   A0 = 256-word palette (8 banks x 32 colors) in $0RGB format
;
; Trashes:
;   D0-D2, A1-A3
; --------------------------------------------------------------------------
WriteCopperPalette:
                lea     (copperListBuffer).l,a1

                lea     COP_PAL_B0_C0_VAL_OFF(a1),a2
                movea.l a0,a3
                bsr.w   .PatchBank_ValPtr

                lea     COP_PAL_B1_C0_VAL_OFF(a1),a2
                lea     64(a0),a3
                bsr.w   .PatchBank_ValPtr

                lea     COP_PAL_B2_C0_VAL_OFF(a1),a2
                lea     128(a0),a3
                bsr.w   .PatchBank_ValPtr

                lea     COP_PAL_B3_C0_VAL_OFF(a1),a2
                lea     192(a0),a3
                bsr.w   .PatchBank_ValPtr

                lea     COP_PAL_B4_C0_VAL_OFF(a1),a2
                lea     256(a0),a3
                bsr.w   .PatchBank_ValPtr

                lea     COP_PAL_B5_C0_VAL_OFF(a1),a2
                lea     320(a0),a3
                bsr.w   .PatchBank_ValPtr

                lea     COP_PAL_B6_C0_VAL_OFF(a1),a2
                lea     384(a0),a3
                bsr.w   .PatchBank_ValPtr

                lea     COP_PAL_B7_C0_VAL_OFF(a1),a2
                lea     448(a0),a3
                bsr.w   .PatchBank_ValPtr

                rts

.PatchBank_ValPtr:
                moveq   #31,d0
.loop:
                move.w  (a3)+,(a2)
                adda.l  #4,a2
                dbf     d0,.loop
                rts

; Bank layout includes WAIT pairs in slots 7 and 8 (do not touch their VALUE words).
; We still advance A2 by 4 and A3 by 1 word for those slots to keep alignment.
.PatchBank_Skip7_8:
                moveq   #31,d0                  ; slot index 31..0 with DBF, we want 0..31
                moveq   #0,d2                   ; slot counter 0..31
.p1_loop:
                move.w  (a3)+,d1                ; next palette word

                cmpi.w  #7,d2
                beq.s   .p1_skip_write
                cmpi.w  #8,d2
                beq.s   .p1_skip_write

                move.w  d1,2(a2)                ; patch VALUE (non-WAIT slot)

.p1_skip_write:
                adda.l  #4,a2                   ; next copper pair slot
                addq.w  #1,d2
                dbf     d0,.p1_loop
                rts

; --------------------------------------------------------------------------
; WriteCopperPitchPalette
; Build/update gamePalette[256] by applying 9 pitch-specific entries, then
; push gamePalette into the copper buffer using WriteCopperPalette.
;
; Uses:
;   pitchNumberAndType (word) as index 0..6 into pitchPalettePtrs (clamped)
;   paletteIndices     (9 bytes) as destination indices into gamePalette
;   pitchPalettePtrs   (7 longwords) -> each points to 9-word palette
;
; Trashes:
;   D0-D3/D7, A0-A3
; --------------------------------------------------------------------------
WriteCopperPitchPalette:
                ; --- select pitch palette pointer ---
                move.w  (pitchNumberAndType).l,d0
                cmpi.w  #6,d0
                bls.s   .idx_ok
                moveq   #4,d0                   ; default to "normal" if out of range
.idx_ok:
                lsl.w   #2,d0                   ; longword index
                lea     (pitchPalettePtrs).l,a2
                movea.l (a2,d0.w),a2            ; A2 = selected 9-word pitch palette

                ; --- apply 9 entries into gamePalette ---
                lea     (paletteIndices).l,a1   ; bytes: 0..255
                lea     (gamePalette).l,a3      ; destination 256-word table

                moveq   #8,d7                   ; 9 entries (0..8)
.apply_loop:
                moveq   #0,d1
                move.b  (a1)+,d1                ; d1 = palette index (0..255)
                lsl.w   #1,d1                   ; word offset (idx*2)

                move.w  (a2)+,d2                ; next pitch color word
                move.w  d2,(a3,d1.w)            ; gamePalette[idx] = color

                dbf     d7,.apply_loop

                ; --- push full 256-color gamePalette into copper buffer ---
                lea     (gamePalette).l,a0
                bsr.w   WriteCopperPalette
                rts

; ===== InitDisplayAndCopper =====
; prototype: void __usercall InitDisplayAndCopper()
InitDisplayAndCopper:
                movem.l d0-d1/a0-a1,-(sp)
                move.l  #frontbufferBase,(frontbufferBasePtr).l
                move.l  #frontbufferBaseAlt,(frontbufferBaseAltPtr).l
                lea     (kSpriteBlitQueueSentinel_A).l,a0
                move.l  #$FFFFFFFF,(a0)
                lea     (kSpriteBlitQueueSentinel_B).l,a0
                move.l  #$FFFFFFFF,(a0)
                lea     (copperListTemplate).l,a0
                lea     (copperListBuffer).l,a1
                move.w  #COPPERLIST_SIZE_BYTES_MINUS_ONE,d0
copy_copperlist_loop:
                move.b  (a0)+,(a1)+
                dbf     d0,copy_copperlist_loop
                clr.l   (copperZeroLong).l
                move.w  #$4000,(INTENA).l
wait_top_of_frame:
                move.l  (VPOSR).l,d0
                andi.l  #$1FFFF,d0
                lsr.l   #8,d0
                cmpi.l  #$A,d0
                bhi.s   wait_top_of_frame
                move.w  #$C000,(INTENA).l
                lea     ((copperListBuffer+COP_SPR_B0_OFF)).l,a0
                move.l  #copperZeroLong,d0
                move.w  #7,d1
write_ptr_template_loop:
                move.w  d0,6(a0)
                swap    d0
                move.w  d0,2(a0)
                swap    d0
                addq.l  #8,a0
                dbf     d1,write_ptr_template_loop
                lea     (copperListBuffer+COP_PAL_B0_C0_VAL_OFF).l,a1
                move.w  #$1F,d0                         ; 32 entries
.clear_pal_bank0:
                clr.w   (a1)+
                addq.l  #2,a1                            ; skip reg word => net +4 per entry
                dbf     d0,.clear_pal_bank0

                lea     (copperListBuffer+COP_PAL_B1_C0_VAL_OFF).l,a1
                move.w  #$1F,d0
.clear_pal_bank1:
                clr.w   (a1)+
                addq.l  #2,a1
                dbf     d0,.clear_pal_bank1

                lea     (copperListBuffer+COP_PAL_B2_C0_VAL_OFF).l,a1
                move.w  #$1F,d0
.clear_pal_bank2:
                clr.w   (a1)+
                addq.l  #2,a1
                dbf     d0,.clear_pal_bank2

                lea     (copperListBuffer+COP_PAL_B3_C0_VAL_OFF).l,a1
                move.w  #$1F,d0
.clear_pal_bank3:
                clr.w   (a1)+
                addq.l  #2,a1
                dbf     d0,.clear_pal_bank3

                lea     (copperListBuffer+COP_PAL_B4_C0_VAL_OFF).l,a1
                move.w  #$1F,d0
.clear_pal_bank4:
                clr.w   (a1)+
                addq.l  #2,a1
                dbf     d0,.clear_pal_bank4

                lea     (copperListBuffer+COP_PAL_B5_C0_VAL_OFF).l,a1
                move.w  #$1F,d0
.clear_pal_bank5:
                clr.w   (a1)+
                addq.l  #2,a1
                dbf     d0,.clear_pal_bank5

                lea     (copperListBuffer+COP_PAL_B6_C0_VAL_OFF).l,a1
                move.w  #$1F,d0
.clear_pal_bank6:
                clr.w   (a1)+
                addq.l  #2,a1
                dbf     d0,.clear_pal_bank6

                lea     (copperListBuffer+COP_PAL_B7_C0_VAL_OFF).l,a1
                move.w  #$1F,d0

.clear_pal_bank7:
                clr.w   (a1)+
                addq.l  #2,a1
                dbf     d0,.clear_pal_bank7
                move.l  #bitPlane0Base,(bitPlane0BasePtr).l
                move.l  #bitPlane1Base,(bitPlane1BasePtr).l
                move.l  #bitPlane2Base,(bitPlane2BasePtr).l
                move.l  #bitPlane3Base,(bitPlane3BasePtr).l
                move.l  #bitPlane4Base,(bitPlane4BasePtr).l
