                move.w  d0,6(a0)
                swap    d0
                move.w  d0,2(a0)

                move.w  (cameraXMod320).l,d1
                andi.w  #$F,d1
                bne.s   unaligned_scroll_setup
                move.w  #PITCH_DEST_MOD_ALIGNED,(copperListBuffer+COP_BPL1MOD_VAL_OFF).l
                move.w  #PITCH_DEST_MOD_ALIGNED,(copperListBuffer+COP_BPL2MOD_VAL_OFF).l
                move.w  #$30,(copperListBuffer+COP_DDFSTRT_VAL_OFF).l
                move.w  #0,(copperListBuffer+COP_BPLCON1_VAL_OFF).l
