                move.w  #PITCH_DEST_MOD_UNALIGNED,(copperListBuffer+COP_BPL1MOD_VAL_OFF).l
                move.w  #PITCH_DEST_MOD_UNALIGNED,(copperListBuffer+COP_BPL2MOD_VAL_OFF).l
