emit_plane_ptr_tables:
                lea     ((copperListBuffer+COP_BPLPTR_BLOCKA_OFF)).l,a0
                lea     ((copperListBuffer+COP_BPLPTR_BLOCKB_OFF)).l,a1
                move.w  (cameraYMod320).l,d0
