write_plane_ptrs_loop:
                move.w  d0,6(a0)
                swap    d0
                move.w  d0,2(a0)
                swap    d0
                move.w  d1,6(a1)
                swap    d1
                move.w  d1,2(a1)
                swap    d1
                addi.l  #PLANE_STRIDE,d0
                addi.l  #PLANE_STRIDE,d1
                addq.l  #8,a0
                addq.l  #8,a1
                dbf     d2,write_plane_ptrs_loop
