                sub.w   (cameraYMod320).l,d0
                addi.w  #$24,d0         ; '$'
                cmpi.w  #$FF,d0
                bhi.s   set_bltdmod_negative
                move.w  #1,(copperListBuffer+COP_WAIT_VHPOS).l
                bra.s   finalize_bltsize
set_bltdmod_negative:
                move.w  #$FFE1,(copperListBuffer+COP_WAIT_VHPOS).l
finalize_bltsize:
                andi.w  #$FF,d0
                lsl.w   #8,d0
                ori.w   #1,d0
                move.w  d0,(copperListBuffer+COP_WAIT_WAIT).l
                rts
