PanicHaltLoop:
                movem.l d0-d7/a0-a6,(panicRegDumpBlock).l
                move.w  (panicReasonCode).l,d0
                jsr     PanicLookupMessagePtr
                movea.l a0,a2
                lea     (panicFormatStr).l,a0
                lea     (panicOutBuf).l,a1
                jsr     PrintFormatted
                jsr     FadeOutToBlack
wait_buttons:
                jsr     Player1StatusProc ; Returns
                tst.b   (pl1Fire).l     ; Wait for joy1 button
                beq.s   wait_buttons
                tst.w   (pl1Direction).l
                bne.s   wait_buttons    ; Wait for joy1 movement to stop
                jsr     Player2StatusProc ; Returns
                tst.b   (pl2Fire).l
                beq.s   wait_buttons
                tst.w   (pl2Direction).l
                bne.s   wait_buttons
                move.w  #$98,d1
                move.w  #$E1,d2
                move.w  #$F,d3
                lea     (bigCharsTable).l,a1
                lea     (panicOutBuf).l,a0
                jsr     DrawMenuTextCentered
                jsr     WaitForVSync
                move.w  #4,(paletteIndex).l
                jsr     FadeIn
panic_spin_forever:
                bra.s   panic_spin_forever
; char[3]
panicFormatStr:
                dc.b '%a',0
; char[96]
panicOutBuf:
                dcb.b $60,0
pad_102555:
                dc.b $00,$00,$00,$00,$00,$C0,$FC,$00,$0A

; ===== FlashColor0Delay =====
; prototype: void __usercall FlashColor0Delay(unsigned __int32 loopCount, unsigned __int16 color)
FlashColor0Delay:
                move.w  d1,(COLOR00).l
                subq.l  #1,d0
                bne.s   FlashColor0Delay
                move.w  (copperListBuffer+COP_PAL_B0_C0_VAL_OFF).l,(COLOR00).l
                rts

; ===== Player1StatusProc =====
; prototype: unsigned __int16 __usercall Player1StatusProc@<d0>()
; Returns
; 
; D0 =
; 1 = UpRight
; 3 = DownRight
; 5 = DownLeft
; 7 = UpLeft
; 0 = Up
; 2 = Right
; 4 = Down
; 6 = Left
Player1StatusProc:
                move.w  (JOY1DAT).l,d0
                btst    #1,d0
                sne     (pl1Right).l
                btst    #9,d0
                sne     (pl1Left).l
                move.w  d0,d1
                lsr.w   #1,d1
                eor.w   d1,d0
                btst    #0,d0
                sne     (pl1Down).l
                btst    #8,d0
                sne     (pl1Up).l
                btst    #7,(CIAA_PRA).l ; Joy Button
                seq     (pl1Fire).l
                move.b  (pl1Up).l,d0
                and.b   (pl1Right).l,d0
                move.b  d0,(pl1UpRight).l
                move.b  (pl1Down).l,d0
                and.b   (pl1Right).l,d0
                move.b  d0,(pl1DownRight).l
                move.b  (pl1Down).l,d0
                and.b   (pl1Left).l,d0
                move.b  d0,(pl1DownLeft).l
                move.b  (pl1Up).l,d0
                and.b   (pl1Left).l,d0
                move.b  d0,(pl1UpLeft).l
                tst.b   (pl1LastFired).l
                beq.s   joy1_btn_not_previously_down
                clr.b   (pl1ShortFire).l
                tst.b   (pl1Fire).l
                beq.s   joy1_btn_released_now
                tst.w   (pl1FireCounter).l
                beq.s   joy1_btn_update_done
                subq.w  #1,(pl1FireCounter).l
                bra.s   joy1_btn_update_done
joy1_btn_released_now:
                clr.b   (pl1LastFired).l
                neg.w   (pl1FireCounter).l
                bra.s   joy1_btn_update_done
joy1_btn_not_previously_down:
                tst.b   (pl1Fire).l
                sne     (pl1ShortFire).l
                sne     (pl1LastFired).l
                beq.s   joy1_btn_update_done
                move.w  #$FFFF,(pl1FireCounter).l
joy1_btn_update_done:
                tst.b   (pl1WasLeft).l
                beq.s   joy1_left_newpress_path
                clr.b   (pl1LeftPress).l
                tst.b   (pl1Left).l
                bne.s   joy1_left_still_held_path
                clr.b   (pl1WasLeft).l
joy1_left_newpress_path:
                tst.b   (pl1Left).l
                sne     (pl1LeftPress).l
                sne     (pl1WasLeft).l
joy1_left_still_held_path:
                tst.b   (pl1WasRight).l
                beq.s   joy1_right_newpress_path
                clr.b   (pl1RightPress).l
                tst.b   (pl1Right).l
                bne.s   joy1_right_still_held_path
                clr.b   (pl1WasRight).l
joy1_right_newpress_path:
                tst.b   (pl1Right).l
                sne     (pl1RightPress).l
                sne     (pl1WasRight).l
joy1_right_still_held_path:
                tst.b   (pl1WasUp).l
                beq.s   joy1_up_newpress_path
                clr.b   (pl1UpPress).l
                tst.b   (pl1Up).l
                bne.s   joy1_up_still_held_path
                clr.b   (pl1WasUp).l
joy1_up_newpress_path:
                tst.b   (pl1Up).l
                sne     (pl1UpPress).l
                sne     (pl1WasUp).l
joy1_up_still_held_path:
                tst.b   (pl1WasDown).l
                beq.s   joy1_down_newpress_path
                clr.b   (pl1DownPress).l
                tst.b   (pl1Down).l
                bne.s   joy1_down_still_held_path
                clr.b   (pl1WasDown).l
joy1_down_newpress_path:
                tst.b   (pl1Down).l
                sne     (pl1DownPress).l
                sne     (pl1WasDown).l
joy1_down_still_held_path:
                move.w  #1,d0
                tst.b   (pl1UpRight).l
                bne.s   joy1_write_compass_dir
                move.w  #3,d0
                tst.b   (pl1DownRight).l
                bne.s   joy1_write_compass_dir
                move.w  #5,d0
                tst.b   (pl1DownLeft).l
                bne.s   joy1_write_compass_dir
                move.w  #7,d0
                tst.b   (pl1UpLeft).l
                bne.s   joy1_write_compass_dir
                move.w  #0,d0
                tst.b   (pl1Up).l
                bne.s   joy1_write_compass_dir
                move.w  #2,d0
                tst.b   (pl1Right).l
                bne.s   joy1_write_compass_dir
                move.w  #4,d0
                tst.b   (pl1Down).l
                bne.s   joy1_write_compass_dir
                move.w  #6,d0
                tst.b   (pl1Left).l
                bne.s   joy1_write_compass_dir
                move.w  #$FFFF,d0
joy1_write_compass_dir:
                move.w  d0,(pl1Direction).l
                rts

; ===== Player2StatusProc =====
; prototype: unsigned __int16 __usercall Player2StatusProc@<d0>()
; Returns
; 
; D0 =
; 1 = UpRight
; 3 = DownRight
; 5 = DownLeft
; 7 = UpLeft
; 0 = Up
; 2 = Right
; 4 = Down
; 6 = Left
Player2StatusProc:
                move.w  (JOY0DAT).l,d0
                btst    #1,d0
                sne     (pl2Right).l
                btst    #9,d0
                sne     (pl2Left).l
                move.w  d0,d1
                lsr.w   #1,d1
                eor.w   d1,d0           ; Expose Up/Down State
                btst    #0,d0
                sne     (pl2Down).l
                btst    #8,d0
                sne     (pl2Up).l
                btst    #6,(CIAA_PRA).l ; Joystick Button
                seq     (pl2Fire).l
                move.b  (pl2Up).l,d0
                and.b   (pl2Right).l,d0
                move.b  d0,(pl2UpRight).l
                move.b  (pl2Down).l,d0
                and.b   (pl2Right).l,d0
                move.b  d0,(pl2DownRight).l
                move.b  (pl2Down).l,d0
                and.b   (pl2Left).l,d0
                move.b  d0,(pl2DownLeft).l
                move.b  (pl2Up).l,d0
                and.b   (pl2Left).l,d0
                move.b  d0,(pl2UpLeft).l
                tst.b   (pl2LastFired).l
                beq.s   joy0_btn_pressed_now
                clr.b   (pl2ShortFire).l
                tst.b   (pl2Fire).l
                beq.s   joy0_btn_released_now
                tst.w   (pl2FireCounter).l
                beq.s   joy0_btn_update_done
                subq.w  #1,(pl2FireCounter).l
                bra.s   joy0_btn_update_done
joy0_btn_released_now:
                clr.b   (pl2LastFired).l
                neg.w   (pl2FireCounter).l
                bra.s   joy0_btn_update_done
joy0_btn_pressed_now:
                tst.b   (pl2Fire).l
                sne     (pl2ShortFire).l
                sne     (pl2LastFired).l
                beq.s   joy0_btn_update_done
                move.w  #$FFFF,(pl2FireCounter).l
joy0_btn_update_done:
                tst.b   (pl2WasLeft).l
                beq.s   joy0_left_check_now
                clr.b   (pl2LeftPress).l
                tst.b   (pl2Left).l
                bne.s   joy0_right_was_down
                clr.b   (pl2WasLeft).l
joy0_left_check_now:
                tst.b   (pl2Left).l
                sne     (pl2LeftPress).l
                sne     (pl2WasLeft).l
joy0_right_was_down:
                tst.b   (pl2WasRight).l
                beq.s   joy0_right_check_now
                clr.b   (pl2RightPress).l
                tst.b   (pl2Right).l
                bne.s   joy0_up_was_down
                clr.b   (pl2WasRight).l
joy0_right_check_now:
                tst.b   (pl2Right).l
                sne     (pl2RightPress).l
                sne     (pl2WasRight).l
joy0_up_was_down:
                tst.b   (pl2WasUp).l
                beq.s   joy0_up_check_now
                clr.b   (pl2UpPress).l
                tst.b   (pl2Up).l
                bne.s   joy0_down_was_down
                clr.b   (pl2WasUp).l
joy0_up_check_now:
                tst.b   (pl2Up).l
                sne     (pl2UpPress).l
                sne     (pl2WasUp).l
joy0_down_was_down:
                tst.b   (pl2WasDown).l
                beq.s   joy0_down_check_now
                clr.b   (pl2DownPress).l
                tst.b   (pl2Down).l
                bne.s   joy0_encode_compass_dir
                clr.b   (pl2WasDown).l
joy0_down_check_now:
                tst.b   (pl2Down).l
                sne     (pl2DownPress).l
                sne     (pl2WasDown).l
joy0_encode_compass_dir:
                move.w  #1,d0
                tst.b   (pl2UpRight).l
                bne.s   ret_value
                move.w  #3,d0
                tst.b   (pl2DownRight).l
                bne.s   ret_value
                move.w  #5,d0
                tst.b   (pl2DownLeft).l
                bne.s   ret_value
                move.w  #7,d0
                tst.b   (pl2UpLeft).l
                bne.s   ret_value
                move.w  #0,d0
                tst.b   (pl2Up).l
                bne.s   ret_value
                move.w  #2,d0
                tst.b   (pl2Right).l
                bne.s   ret_value
                move.w  #4,d0
                tst.b   (pl2Down).l
                bne.s   ret_value
                move.w  #6,d0
                tst.b   (pl2Left).l
                bne.s   ret_value
                move.w  #$FFFF,d0
ret_value:
                move.w  d0,(pl2Direction).l
                rts                     ; Returns
                                        ; 1 = UpRight
                                        ; 3 = DownRight
                                        ; 5 = DownLeft
                                        ; 7 = UpLeft
                                        ; 0 = Up
                                        ; 2 = Right
                                        ; 4 = Down
                                        ; 6 = Left

; ===== ProcessSpriteBlitQueue =====
; prototype: void __usercall ProcessSpriteBlitQueue()
ProcessSpriteBlitQueue:
                lea     (CUSTOM).l,a6
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_idle_1:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_idle_1
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.w  #BLT_FWM_ALL,BLTAFWM(a6)
                move.w  #BLT_FWM_ALL,BLTALWM(a6)
                clr.w   BLTCON1(a6)
                move.w  #BLTCON0_USEA_USED_LF_F0,BLTCON0(a6)
                movea.l (spriteBlitQueue).l,a4
blit_queue_loop:
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
_1029C4_wait_blitter_idle_2:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   _1029C4_wait_blitter_idle_2
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  (a4),BLTAPT(a6)
                bmi.s   reset_queue_terminator
                move.l  4(a4),BLTDPT(a6)
                move.w  8(a4),BLTAMOD(a6)
                move.w  8(a4),BLTDMOD(a6)
                move.w  $A(a4),BLTSIZE(a6)
                lea     $C(a4),a4
                bra.s   blit_queue_loop
reset_queue_terminator:
                movea.l (spriteBlitQueue).l,a0
                move.l  #$FFFFFFFF,(a0)
                rts

; ===== LoadPitchMap =====
; prototype: void __usercall LoadPitchMap(unsigned __int16 mapIndex@<d0>)
LoadPitchMap:
                lea     (swcPitchMapFiles).l,a0
                lsl.w   #2,d0
                movea.l (a0,d0.w),a0
                lea     (pitchDatBuffer).l,a1
                jsr     LoadFile
                cmpi.l  #PITCHFILE_MAX_SIZE,d1
                bls.s   _102A34_done
                move.w  #3,(panicReasonCode).l
                jsr PanicHaltLoop(pc)
_102A34_done:
                rts

; ===== FixupAndColorPitchFile =====
; prototype: void __usercall FixupAndColorPitchFile()
FixupAndColorPitchFile:
                lea     (pitchDatBuffer).l,a0
                clr.w   d2
                move.w  #2309,d1        ; sizeof(g_pitchDatBuffer) / 4 ; (= 9240 / 4)
relocate_pitch_pointer_loop:
                move.l  (a0),d0
                addi.l  #currentMenu,d0
                move.l  d0,(a0)+
                dbf     d1,relocate_pitch_pointer_loop
                clr.w   (cameraX).l
                clr.w   (cameraY).l
                clr.w   (cameraXMod320).l
                clr.w   (cameraYMod320).l
                lea     (pitchDatBuffer).l,a5
                lea     ((pitchDatBuffer+$54)).l,a6
                clr.w   (fansSidesSwapped).l
                btst    #0,(topTeamInGame+TEAMGAME_TEAMNAME).l
                beq.s   maybe_swap_fans_sides
                exg     a5,a6
                move.w  #1,(fansSidesSwapped).l
maybe_swap_fans_sides:
                lea     (topTeamInGame).l,a0
                move.w  $C(a0),((pitchFansConvertTable+$16)).l
                move.w  $E(a0),d0
                cmp.w   $C(a0),d0
                bne.s   selected_kit_color_ready
                move.w  $10(a0),d0
selected_kit_color_ready:
                move.w  d0,(pitchFansConvertTable+$14).l
                move.w  #$14,d7
apply_top_team_fan_patches_loop:
                lea     (pitchFansConvertTable).l,a0
                movea.l (a6)+,a1
                movem.l d7/a5-a6,-(sp)
                jsr     AdjustFanColor
                movem.l (sp)+,d7/a5-a6
                dbf     d7,apply_top_team_fan_patches_loop
                lea     (bottomTeamInGame).l,a0
                move.w  $C(a0),(pitchFansConvertTable+$16).l
                move.w  $E(a0),d0
                cmp.w   $C(a0),d0
                bne.s   selected_bottom_team_kit_color_ready
                move.w  $10(a0),d0
selected_bottom_team_kit_color_ready:
                move.w  d0,(pitchFansConvertTable+$14).l
                movea.l a5,a6
                move.w  #20,d7          ; loop 21 times
apply_bottom_team_fan_patches_loop:
                lea     (pitchFansConvertTable).l,a0
                movea.l (a6)+,a1
                movem.l d7/a6,-(sp)
                jsr     AdjustFanColor
                movem.l (sp)+,d7/a6
                dbf     d7,apply_bottom_team_fan_patches_loop
                rts
; __int16[16]
pitchFansConvertTable:
                ; __int16[16]
                dc.w 0,1,2,3,4,5,6,7
                dc.w 8,9,-1,-1,12,13,14,15

; ===== SetCameraCoordinates =====
; prototype: void __usercall SetCameraCoordinates(__int16 newX@<d1>, __int16 newY@<d2>)
; in:
;      D1 - new x (whole part)
;      D2 - new y (whole part)
; 
; Updates *mod320 vars too.
SetCameraCoordinates:
                cmp.w   (cameraX).l,d1
                beq.w   _102B76_check_y_then_adjust
                bmi.w   _102B5E_dec_x_with_wrap
                addq.w  #1,(cameraX).l
                addq.w  #1,(cameraXMod320).l
                cmpi.w  #352,(cameraXMod320).l
                bne.s   SetCameraCoordinates
                clr.w   (cameraXMod320).l
                bra.s   SetCameraCoordinates
_102B5E_dec_x_with_wrap:
                subq.w  #1,(cameraX).l
                subq.w  #1,(cameraXMod320).l
                bpl.s   SetCameraCoordinates
                move.w  #351,(cameraXMod320).l
                bra.s   SetCameraCoordinates
_102B76_check_y_then_adjust:
                cmp.w   (cameraY).l,d2
                beq.w   _102BBA_return
                bmi.w   _102BA2_dec_y_with_wrap
                addq.w  #1,(cameraY).l
                addq.w  #1,(cameraYMod320).l
                cmpi.w  #272,(cameraYMod320).l
                bne.s   _102B76_check_y_then_adjust
                clr.w   (cameraYMod320).l
                bra.s   _102B76_check_y_then_adjust
_102BA2_dec_y_with_wrap:
                subq.w  #1,(cameraY).l
                subq.w  #1,(cameraYMod320).l
                bpl.s   _102B76_check_y_then_adjust
                move.w  #271,(cameraYMod320).l
                bra.s   _102B76_check_y_then_adjust
_102BBA_return:
                rts

; ===== InitCameraMoveView =====
; prototype: void __usercall InitCameraMoveView()
InitCameraMoveView:
                movem.l d2,-(sp)
                move.w  #272,d2
                bsr.w   SetCameraCoordinates
                bsr.w   ScrollToCurrent
                move.w  (cameraX).l,d1
                clr.w   d2
                bsr.w   SetCameraCoordinates
                bsr.w   ScrollToCurrent
                move.w  (cameraX).l,d1
                movem.l (sp)+,d2
                bsr.w   MoveView
                rts

; ===== MoveView =====
; prototype: void __usercall MoveView(__int16 newScreenX@<d1>, __int16 newScreenY@<d2>)
; in:
;      D1 - new visible screen x
;      D2 - new visible screen y
MoveView:
                movem.l d1-d2,-(sp)
                bsr.w   ScrollToCurrent
                movem.l (sp)+,d1-d2
                cmp.w   (cameraX).l,d1
                beq.w   _102C3C_check_y_then_adjust
                bmi.w   _102C24_dec_x_with_wrap
                addq.w  #1,(cameraX).l
                addq.w  #1,(cameraXMod320).l
                cmpi.w  #352,(cameraXMod320).l
                bne.s   MoveView
                clr.w   (cameraXMod320).l
                bra.s   MoveView
_102C24_dec_x_with_wrap:
                subq.w  #1,(cameraX).l
                subq.w  #1,(cameraXMod320).l
                bpl.s   MoveView
                move.w  #351,(cameraXMod320).l
                bra.s   MoveView
_102C3C_check_y_then_adjust:
                movem.l d1-d2,-(sp)
                bsr.w   ScrollToCurrent
                movem.l (sp)+,d1-d2
                cmp.w   (cameraY).l,d2
                beq.w   _102C8C_return
                bmi.w   _102C74_dec_y_with_wrap
                addq.w  #1,(cameraY).l
                addq.w  #1,(cameraYMod320).l
                cmpi.w  #272,(cameraYMod320).l
                bne.s   _102C3C_check_y_then_adjust
                clr.w   (cameraYMod320).l
                bra.s   _102C3C_check_y_then_adjust
_102C74_dec_y_with_wrap:
                subq.w  #1,(cameraY).l
                subq.w  #1,(cameraYMod320).l
                bpl.s   _102C3C_check_y_then_adjust
                move.w  #271,(cameraYMod320).l
                bra.s   _102C3C_check_y_then_adjust
_102C8C_return:
                rts

; ===== ScrollToCurrent =====
; prototype: void __usercall ScrollToCurrent()
; Sets view to cameraX and cameraY.
; Updates oldCameraX and oldCameraY.
; 
; out:
;      D1 - camera x
;      D2 - camera y
ScrollToCurrent:
                move.w  #1,(cameraCoordinatesValid).l
                bsr.w   ScrollXUpdateColumnsAndBlit
                bsr.w   ScrollYUpdateRowsAndBlit
                rts

; ===== ScrollXUpdateColumnsAndBlit =====
; prototype: void __usercall ScrollXUpdateColumnsAndBlit()
ScrollXUpdateColumnsAndBlit:
                move.w  (cameraX).l,d0
                cmp.w   (oldCameraX).l,d0
                beq.w   scroll_x_update_return
                bpl.w   x_scroll_moved_right
                bra.w   x_scroll_moved_left
x_scroll_moved_right:
                move.w  #SCROLL_RIGHT_EDGE_X,d5
                move.w  (oldCameraX).l,d0
                addi.w  #SCROLL_RIGHT_EDGE_X,d0
                asr.w   #TILE_SHIFT_X,d0
                move.w  (cameraX).l,d1
                addi.w  #SCROLL_RIGHT_EDGE_X,d1
                asr.w   #TILE_SHIFT_X,d1
                cmp.w   d0,d1
                bne.s   x_scroll_crossed_tile_boundary
                move.w  (cameraX).l,(oldCameraX).l
                clr.w   (cameraCoordinatesValid).l
                rts
x_scroll_moved_left:
                clr.w   d5
                move.w  (oldCameraX).l,d0
                asr.w   #TILE_SHIFT_X,d0
                move.w  (cameraX).l,d1
                asr.w   #TILE_SHIFT_X,d1
                cmp.w   d0,d1
                bne.s   x_scroll_crossed_tile_boundary
                move.w  (cameraX).l,(oldCameraX).l
                clr.w   (cameraCoordinatesValid).l
                rts
x_scroll_crossed_tile_boundary:
                clr.w   (cameraCoordinatesValid).l
                move.w  (cameraX).l,(oldCameraX).l
                lea     (CUSTOM).l,a6
                move.w  (cameraY).l,d0
                lsr.w   #TILE_SHIFT_X,d0
                mulu.w  #PITCH_PTR_ROW_BYTES,d0
                move.w  (cameraX).l,d1
                add.w   d5,d1
                lsr.w   #TILE_SHIFT_X,d1
                lsl.w   #2,d1
                add.w   d1,d0
                lea     (pitchDatBuffer).l,a1
                lea     (a1,d0.w),a1
                movea.l (frontbufferBasePtr).l,a0
                move.w  (cameraXMod320).l,d0
                add.w   d5,d0
                lsr.w   #3,d0
                andi.l  #WORD_ALIGN_EVEN_MASK,d0
                adda.l  d0,a0
                move.w  (cameraYMod320).l,d0
                mulu.w  #ROW_STRIDE_BYTES,d0
                adda.l  d0,a0
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_idle_for_dest_setup:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_idle_for_dest_setup
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  a0,BLTDPT(a6)
                clr.w   BLTAMOD(a6)
                move.w  #BLTDMOD_PLANE_STEP,BLTDMOD(a6)
                move.w  #BLT_FWM_ALL,BLTAFWM(a6)
                move.w  #BLT_FWM_ALL,BLTALWM(a6)
                clr.w   BLTCON1(a6)
                move.w  #BLTCON0_USEA_USED_LF_F0,BLTCON0(a6)
                move.w  (cameraYMod320).l,d2
                move.w  d2,d1
                andi.w  #TILE_MASK,d1
                beq.w   top_segments_loop_check
                move.w  #TILE_HEIGHT,d3
                sub.w   d1,d3
                add.w   d3,d2
                lsl.w   #NUM_PLANES_SHIFT_PLUS1,d1
                ext.l   d1
                ;lsl.w   #8,d3
                ;addq.w  #1,d3

                ; d3 = number of scanlines to blit (1..15)
                move.w  d3,d0
                lsl.w   #NUM_PLANES_SHIFT,d0         ; d0 = d3 * NUM_PLANES (8)
                lsl.w   #6,d0                        ; BLTSIZE height field
                ori.w   #1,d0                        ; width = 1 word
                move.w  d0,d3                        ; keep later "move.w d3,BLTSIZE" unchanged

                movea.l (a1),a0
                adda.l  #PITCH_PTR_ROW_BYTES,a1
                adda.l  d1,a0
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_idle_for_top_remainder_blit:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_idle_for_top_remainder_blit
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  a0,BLTAPT(a6)
                move.w  d3,BLTSIZE(a6)
                bra.w   top_segments_loop_check
blit_top_segments_loop:
                movea.l (a1),a0
                adda.l  #PITCH_PTR_ROW_BYTES,a1
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_idle_for_top_segment_blit:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_idle_for_top_segment_blit
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  a0,BLTAPT(a6)
                move.w  #BLTSIZE_TILE_COL,BLTSIZE(a6)
                addi.w  #TILE_HEIGHT,d2
top_segments_loop_check:
                cmpi.w  #SCREEN_HEIGHT,d2
                bcs.s   blit_top_segments_loop
                movea.l (frontbufferBasePtr).l,a0
                move.w  (cameraXMod320).l,d0
                add.w   d5,d0
                lsr.w   #3,d0
                andi.l  #WORD_ALIGN_EVEN_MASK,d0
                adda.l  d0,a0
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_idle_for_second_dest_setup:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_idle_for_second_dest_setup
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  a0,BLTDPT(a6)
                move.w  (cameraYMod320).l,d2
                cmpi.w  #TILE_HEIGHT,d2
                bcs.w   blit_bottom_remainder_or_exit
blit_bottom_segments_loop:
                movea.l (a1),a0
                adda.l  #PITCH_PTR_ROW_BYTES,a1
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_idle_for_bottom_segment_blit:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_idle_for_bottom_segment_blit
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  a0,BLTAPT(a6)
                move.w  #BLTSIZE_TILE_COL,BLTSIZE(a6)
                subi.w  #TILE_HEIGHT,d2
                cmpi.w  #TILE_HEIGHT,d2
                bcc.s   blit_bottom_segments_loop
blit_bottom_remainder_or_exit:
                tst.w   d2
                beq.w   setup_mask_copy_blit
                movea.l (a1),a0
                ;lsl.w   #8,d2
                ;addq.w  #1,d2

                ; d2 = number of scanlines to blit (1..15)
                move.w  d2,d0
                lsl.w   #NUM_PLANES_SHIFT,d0         ; d0 = d2 * NUM_PLANES (8)
                lsl.w   #6,d0                        ; BLTSIZE height field
                ori.w   #1,d0                        ; width = 1 word
                move.w  d0,d2                        ; keep later "move.w d2,BLTSIZE" unchanged

                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_idle_for_bottom_remainder_blit:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_idle_for_bottom_remainder_blit
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  a0,BLTAPT(a6)
                move.w  d2,BLTSIZE(a6)
setup_mask_copy_blit:
                move.w  (cameraXMod320).l,d0
                add.w   d5,d0
                lsr.w   #3,d0
                andi.l  #WORD_ALIGN_EVEN_MASK,d0
                add.l   (frontbufferBasePtr).l,d0
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_idle_for_mask_copy_setup:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_idle_for_mask_copy_setup
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  d0,BLTAPT(a6)
                sub.l   (frontbufferBasePtr).l,d0
                addi.l  #frontbufferMaskBuffer,d0
                move.l  d0,BLTDPT(a6)
                move.w  #BLTDMOD_PLANE_STEP,BLTAMOD(a6)
                move.w  #BLTSIZE_TILE_COL,BLTSIZE(a6)
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_idle_for_final_1word_blit:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_idle_for_final_1word_blit
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.w  #1,BLTSIZE(a6)
scroll_x_update_return:
                rts

; ===== ScrollYUpdateRowsAndBlit =====
; prototype: void __usercall ScrollYUpdateRowsAndBlit()
ScrollYUpdateRowsAndBlit:
                move.w  (cameraY).l,d1
                sub.w   (oldCameraY).l,d1
                beq.w   scroll_y_update_return
                bpl.w   y_scroll_moved_down_compute_visible_height
                clr.w   d5
                neg.w   d1
                bra.w   y_scroll_prepare_pitch_ptr_and_dest_base
y_scroll_moved_down_compute_visible_height:
                move.w  #SCREEN_HEIGHT,d5
                sub.w   d1,d5
y_scroll_prepare_pitch_ptr_and_dest_base:
                move.w  (cameraY).l,(oldCameraY).l
                clr.w   (cameraCoordinatesValid).l
                lea     (pitchDatBuffer).l,a1
                move.w  (cameraY).l,d0
                add.w   d5,d0
                lsr.w   #TILE_SHIFT_X,d0
                mulu.w  #PITCH_PTR_ROW_BYTES,d0
                adda.l  d0,a1
                move.w  (cameraX).l,d0
                lsr.w   #TILE_SHIFT_X,d0
                lsl.w   #2,d0
                ext.l   d0
                adda.l  d0,a1
                movea.l (frontbufferBasePtr).l,a3
                move.w  (cameraXMod320).l,d0
                lsr.w   #3,d0
                andi.l  #WORD_ALIGN_EVEN_MASK,d0
                adda.l  d0,a3
                move.w  (cameraYMod320).l,d0
                add.w   d5,d0
                cmpi.w  #SCREEN_HEIGHT,d0
                bcs.w   wrap_camera_y_to_visible_range
                subi.w  #SCREEN_HEIGHT,d0
wrap_camera_y_to_visible_range:
                mulu.w  #ROW_STRIDE_BYTES,d0
                adda.l  d0,a3
                move.w  (cameraX).l,d7
                andi.w  #$F,d7
                beq.s   choose_row_wordcount_and_dest_stride
                move.w  #$15,d6
                move.l  #PITCH_DEST_MOD_UNALIGNED,d7
                bra.s   init_dest_plane_ptrs_and_row_state
choose_row_wordcount_and_dest_stride:
                move.w  #$14,d6
                move.l  #PITCH_DEST_MOD_ALIGNED,d7
init_dest_plane_ptrs_and_row_state:
                lea     PLANE_STRIDE(a3),a4
                lea     PLANE_STRIDE_TIMES2(a3),a5
                lea     PITCH_DEST_MOD_UNALIGNED(a3),a6
                move.w  (cameraYMod320).l,d4
                add.w   d5,d4
                cmpi.w  #SCREEN_HEIGHT,d4
                bcs.w   init_blit_accumulators_and_src_row_offset
                subi.w  #SCREEN_HEIGHT,d4
init_blit_accumulators_and_src_row_offset:
                move.l  a3,(maskBlitDestPtr).l
                move.w  d6,(blitWordCount).l
                addq.w  #1,(blitWordCount).l
                clr.w   (maskBlitPendingBytesA).l
                clr.w   (maskBlitPendingBytesB).l
                clr.l   (maskBlitSecondStreamPtr).l
                move.w  (cameraY).l,d3
                add.w   d5,d3
                andi.w  #TILE_MASK,d3
                lsl.w   #NUM_PLANES_SHIFT_PLUS1,d3
                ext.l   d3
                subq.w  #1,d1
copy_row_words_loop:
                move.w  d6,d2
                move.l  a1,-(sp)
copy_row_words_inner:
                movea.l (a1)+,a0
                adda.l  d3,a0
                ;move.w  (a0)+,(a3)+
                ;move.w  (a0)+,(a4)+
                ;move.w  (a0)+,(a5)+
                ;move.w  (a0),(a6)+

                ; --- 8-plane store, source is 8 words interleaved (p0..p7) ---
                ; in:  A0 = source stream (already offset by d3)
                ;      A3 = dest plane0 pointer for this scanline word position
                ; clobbers: D0

                move.w  (a0)+,d0
                move.w  d0,(a3)                    ; plane 0

                move.w  (a0)+,d0
                move.w  d0,PLANE_STRIDE(a3)        ; plane 1

                move.w  (a0)+,d0
                move.w  d0,PLANE_STRIDE_TIMES2(a3) ; plane 2

                move.w  (a0)+,d0
                move.w  d0,PLANE_STRIDE_TIMES3(a3) ; plane 3

                move.w  (a0)+,d0
                move.w  d0,PLANE_STRIDE_TIMES4(a3) ; plane 4

                move.w  (a0)+,d0
                move.w  d0,PLANE_STRIDE_TIMES5(a3) ; plane 5

                move.w  (a0)+,d0
                move.w  d0,PLANE_STRIDE_TIMES6(a3) ; plane 6

                move.w  (a0)+,d0
                move.w  d0,PLANE_STRIDE_TIMES7(a3) ; plane 7

                addq.w  #2,a3                      ; advance to next word position

                dbf     d2,copy_row_words_inner
                movea.l (sp)+,a1
                addq.w  #NUM_PLANES,(maskBlitPendingBytesA).l
                addq.w  #NUM_PLANES,(maskBlitPendingBytesB).l
                addi.l  #SRC_SCANLINE_BYTES,d3
                cmpi.w  #TILE_SIZE,d3
                bne.w   advance_dest_ptrs_and_handle_wrap
                adda.l  #PITCH_PTR_ROW_BYTES,a1
                clr.l   d3
advance_dest_ptrs_and_handle_wrap:
                adda.l  d7,a3
                adda.l  d7,a4
                adda.l  d7,a5
                adda.l  d7,a6
                addq.w  #1,d4
                cmpi.w  #SCREEN_HEIGHT,d4
                bne.w   next_row_or_finish_copy
                suba.l  #FRONTBUFFER_SIZE_VISIBLE_BYTES,a3
                suba.l  #FRONTBUFFER_SIZE_VISIBLE_BYTES,a4
                suba.l  #FRONTBUFFER_SIZE_VISIBLE_BYTES,a5
                suba.l  #FRONTBUFFER_SIZE_VISIBLE_BYTES,a6
                clr.w   d4
                move.l  a3,(maskBlitSecondStreamPtr).l
                clr.w   (maskBlitPendingBytesB).l
next_row_or_finish_copy:
                dbf     d1,copy_row_words_loop
                lea     (CUSTOM).l,a6
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_idle_for_mod_setup:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_idle_for_mod_setup
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.w  #BLT_FWM_ALL,BLTAFWM(a6)
                move.w  #BLT_FWM_ALL,BLTALWM(a6)
                clr.w   BLTCON1(a6)
                move.w  #BLTCON0_USEA_USED_LF_F0,BLTCON0(a6)
                move.w  #PLANE_STRIDE_DIV2,d0
                sub.w   (blitWordCount).l,d0
                lsl.w   #1,d0
                move.w  d0,BLTAMOD(a6)
                move.w  d0,BLTDMOD(a6)
                tst.l   (maskBlitSecondStreamPtr).l
                beq.s   adjust_pending_counts_for_wrap_case
                move.w  (maskBlitPendingBytesB).l,d0
                sub.w   d0,(maskBlitPendingBytesA).l
adjust_pending_counts_for_wrap_case:
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_idle_for_mask_ptr_setup:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_idle_for_mask_ptr_setup
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  (maskBlitDestPtr).l,d0
                move.l  d0,BLTAPT(a6)
                sub.l   (frontbufferBasePtr).l,d0
                addi.l  #frontbufferMaskBuffer,d0
                move.l  d0,BLTDPT(a6)
mask_blit_batch_loop_a:
                move.w  (maskBlitPendingBytesA).l,d0
                beq.w   maybe_do_second_mask_blit_stream
                cmpi.w  #$400,d0
                bls.s   mask_blit_issue_batch_a
                move.w  #$400,d0
mask_blit_issue_batch_a:
                sub.w   d0,(maskBlitPendingBytesA).l
                lsl.w   #6,d0
                add.w   (blitWordCount).l,d0
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_idle_for_batch_a:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_idle_for_batch_a
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.w  d0,BLTSIZE(a6)
                bra.s   mask_blit_batch_loop_a
maybe_do_second_mask_blit_stream:
                tst.l   (maskBlitSecondStreamPtr).l
                beq.w   scroll_y_update_return
                move.w  (maskBlitPendingBytesB).l,d0
                beq.w   scroll_y_update_return
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_idle_for_second_stream_ptr_setu:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_idle_for_second_stream_ptr_setu
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  (maskBlitSecondStreamPtr).l,d0
                move.l  d0,BLTAPT(a6)
                sub.l   (frontbufferBasePtr).l,d0
                addi.l  #frontbufferMaskBuffer,d0
                move.l  d0,BLTDPT(a6)
mask_blit_batch_loop_b:
                move.w  (maskBlitPendingBytesB).l,d0
                beq.w   scroll_y_update_return
                cmpi.w  #$400,d0
                bls.s   mask_blit_issue_batch_b
                move.w  #$400,d0
mask_blit_issue_batch_b:
                sub.w   d0,(maskBlitPendingBytesB).l
                lsl.w   #6,d0
                add.w   (blitWordCount).l,d0
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_idle_for_batch_b:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_idle_for_batch_b
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.w  d0,BLTSIZE(a6)
                bra.s   mask_blit_batch_loop_b
scroll_y_update_return:
                rts
blitWordCount:
                dc.w $0000
; unsigned __int32 *
maskBlitDestPtr:
                dc.l $00000000
maskBlitPendingBytesA:
                dc.w $0000
; unsigned __int32 *
maskBlitSecondStreamPtr:
                dc.l $00000000
maskBlitPendingBytesB:
                dc.w $0000

; ===== ApplyFadeStep =====
; prototype: void __usercall ApplyFadeStep(unsigned __int16 fadeLevel@<d2>)
ApplyFadeStep:
                tst.w   (loaderModeFlag).l
                bne.w   ApplyFadeLoaderPath
                lsr.w   #5,d2
                lea     (kFadeShiftMaskTable).l,a0
                lsl.w   #2,d2
                move.w  2(a0,d2.w),d3
                move.w  (a0,d2.w),d2
                move.w  (paletteIndex).l,d0
                lsl.w   #2,d0
                lea     (paletteTable).l,a0
                movea.l (a0,d0.w),a0
                lea     (copperListBuffer+COP_PAL_B0_C0_VAL_OFF).l,a1
                lea     (copperListBuffer+COP_PAL_B1_C0_VAL_OFF).l,a2
                move.w  #$F,d1
fade_write_palette_loop:
                move.w  (a0)+,d0
                lsr.w   d2,d0
                and.w   d3,d0
                move.w  d0,(a1)
                move.w  d0,(a2)
                addq.l  #4,a1
                addq.l  #4,a2
                dbf     d1,fade_write_palette_loop
                rts
; unsigned int[5]
kFadeShiftMaskTable:
                ; unsigned int[5]
                dc.l $00040000,$00030111,$00020333,$00010777,$00000FFF
ApplyFadeLoaderPath:
                lsr.w   #5,d2
                lea     (fadeShiftMaskTable).l,a0
                lsl.w   #2,d2
                move.w  2(a0,d2.w),d3
                move.w  (a0,d2.w),d2
                move.w  (paletteIndex).l,d0
                lsl.w   #2,d0
                lea     (paletteTable).l,a0
                movea.l (a0,d0.w),a0
                lea     (copperListBuffer+COP_PAL_B0_C0_VAL_OFF).l,a1
                lea     (copperListBuffer+COP_PAL_B1_C0_VAL_OFF).l,a2
                move.w  #$F,d1
write_16_colors_loop:
                move.w  (a0)+,d0
                lsr.w   d2,d0
                and.w   d3,d0
                move.w  d0,d4
                andi.w  #$F,d4
                cmpi.w  #2,d4
                bcc.s   clamp_low_nibble_min_2
                andi.w  #$FF0,d0
                ori.w   #2,d0
clamp_low_nibble_min_2:
                move.w  d0,(a1)
                move.w  d0,(a2)
                addq.l  #4,a1
                addq.l  #4,a2
                dbf     d1,write_16_colors_loop
                rts
; __int8[20]
fadeShiftMaskTable:
                dc.b 0,4,0,0,0,3,1,17,0,2,3,51,0,1,7,119
                dc.b 0,0,15,-1

; ===== FadeOutTick =====
; prototype: void __usercall FadeOutTick()
FadeOutTick:
                cmpi.w  #$3E7,(fadeCommand).l
                beq.s   _1033A4_done
                move.w  (fadeCommand).l,d2
                bpl.s   _103386_apply_level_and_update
                move.w  #$80,(fadeCommand).l
                move.w  #$80,d2
_103386_apply_level_and_update:
                bsr.w   ApplyFadeStep
                move.w  fadeStep(pc),d0
                sub.w   d0,(fadeCommand).l
                bpl.s   _1033A4_done
                move.w  #$3E7,(fadeCommand).l
                clr.w   (fadeState).l
_1033A4_done:
                rts

; ===== FadeInTick =====
; prototype: void __usercall FadeInTick()
FadeInTick:
                cmpi.w  #$3E7,(fadeInitFlag).l
                beq.w   _1033EA_done
                move.w  (fadeInitFlag).l,d2
                bpl.s   _1033C2_apply_level_and_update
                clr.w   (fadeInitFlag).l
                clr.w   d2
_1033C2_apply_level_and_update:
                bsr.w   ApplyFadeStep
                move.w  fadeStep(pc),d0
                add.w   d0,(fadeInitFlag).l
                cmpi.w  #$80,(fadeInitFlag).l
                bls.s   _1033EA_done
                move.w  #$3E7,(fadeInitFlag).l
                move.w  #1,(fadeState).l
_1033EA_done:
                rts

; ===== FadeIn =====
; prototype: void __usercall FadeIn()
FadeIn:
                cmpi.w  #$3E7,(fadeCommand).l
