; ===== BlitterSpan4Planes =====
; prototype: void __usercall BlitterSpan4Planes()
; NOTE: now spans NUM_PLANES (kept name so call sites don’t change)
BlitterSpan4Planes:
                lea     (CUSTOM).l,a6
                mulu.w  #ROW_STRIDE_BYTES,d1
                adda.l  d1,a0
                move.w  d0,d1
                lsr.w   #3,d0
                andi.w  #WORD_ALIGN_EVEN_MASK,d0
                adda.w  d0,a0
                andi.w  #TILE_MASK,d1
                move.w  #BLTCON0_USEA_LF_FC,d5
                move.w  #BLTCON0_USED_LF_00,d6

                ; (keep your pre-pass exactly as-is)
                movem.l d1-d2/d4/a0,-(sp)
                bsr.w   align_and_prepare_left_mask
                movem.l (sp)+,d1-d2/d4/a0

                ; --- NEW: loop over all planes ---
                move.w  #NUM_PLANES_MINUS1,d7
.span_plane_loop:
                move.w  d7,-(sp)            ; save loop counter (core clobbers D7)

                movem.l d1-d2/a0,-(sp)
                bsr.w   BlitterSpanCoreMasked
                movem.l (sp)+,d1-d2/a0

                move.w  (sp)+,d7            ; restore loop counter
                lea     PLANE_STRIDE(a0),a0 ; next plane base
                dbf     d7,.span_plane_loop
                rts
leftMaskTable:
                dc.w $8000,$C000,$E000,$F000,$F800,$FC00,$FE00,$FF00
                dc.w $FF80,$FFC0,$FFE0,$FFF0,$FFF8,$FFFC,$FFFE

; ===== BlitterSpanCoreMasked =====
; prototype: void __usercall BlitterSpanCoreMasked()
BlitterSpanCoreMasked:
                move.w  #BLTCON0_USEA_USED_LF_F0,d5
                move.w  #BLTCON0_USED_LF_00,d6
                lsr.w   #1,d4
                bcc.s   align_and_prepare_left_mask
                move.w  #BLTCON0_USEA_USED_LF_FC,d5
                move.w  #BLTCON0_USED_LF_FF,d6
align_and_prepare_left_mask:
                tst.w   d1
                beq.w   blit_aligned_middle_words
                add.w   d1,d1
                ;move.w  loc_103C34(pc,d1.w),d7
                move.w  leftMaskTable-2(pc,d1.w),d7
                lsr.w   #1,d1
                moveq   #$10,d0
                sub.w   d1,d0
                sub.w   d0,d2
                bpl.s   start_left_edge_blit
                neg.w   d2
                add.w   d2,d2
                or.w    partialSpanMaskTable(pc,d2.w),d7
                moveq   #0,d2
start_left_edge_blit:
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_ready_left:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_ready_left
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.w  d7,BLTAFWM(a6)
                move.w  d7,BLTALWM(a6)
                not.w   d7
                move.w  d7,BLTBDAT(a6)
                move.l  a0,BLTAPT(a6)
                move.l  a0,BLTDPT(a6)
                move.w  #FB_BLT_MOD_AFTER_1_WORD,BLTAMOD(a6)
                move.w  #FB_BLT_MOD_AFTER_1_WORD,BLTDMOD(a6)
                move.w  d5,BLTCON0(a6)
                move.w  #0,BLTCON1(a6)
                move.w  d3,d7
                asl.w   #6,d7
                ori.w   #1,d7
                move.w  d7,BLTSIZE(a6)
                addq.w  #2,a0
                tst.w   d2
                bne.s   blit_aligned_middle_words
; unsigned __int16[16]
partialSpanMaskTable:
                ; unsigned __int16[16]
                dc.w $4E75,$0001,$0003,$0007,$000F,$001F,$003F,$007F
                dc.w $00FF,$01FF,$03FF,$07FF,$0FFF,$1FFF,$3FFF,$7FFF
; unsigned __int16[16]
tailMaskTable:
                ; unsigned __int16[16]
                dc.w $FFFF,$8000,$C000,$E000,$F000,$F800,$FC00,$FE00
                dc.w $FF00,$FF80,$FFC0,$FFE0,$FFF0,$FFF8,$FFFC,$FFFE
blit_aligned_middle_words:
                move.w  d2,d0
                lsr.w   #4,d0
                beq.s   blit_right_edge
                move.w  #ROW_STRIDE_BYTES,d1
                sub.w   d0,d1
                sub.w   d0,d1
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_ready_middle:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_ready_middle
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  a0,BLTDPT(a6)
                move.w  d1,BLTDMOD(a6)
                move.w  d6,BLTCON0(a6)
                move.w  #0,BLTCON1(a6)
                move.w  d3,d1
                asl.w   #6,d1
                or.w    d0,d1
                move.w  d1,BLTSIZE(a6)
                add.w   d0,d0
                adda.w  d0,a0
blit_right_edge:
                andi.w  #TILE_MASK,d2
                beq.s   blitter_span_core_masked_return
                add.w   d2,d2
                move.w  tailMaskTable(pc,d2.w),d7
                not.w   d7
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_ready_right:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_ready_right
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.w  d7,BLTAFWM(a6)
                move.w  d7,BLTALWM(a6)
                not.w   d7
                move.w  d7,BLTBDAT(a6)
                move.l  a0,BLTAPT(a6)
                move.l  a0,BLTDPT(a6)
                move.w  #FB_BLT_MOD_AFTER_1_WORD,BLTAMOD(a6)
                move.w  #FB_BLT_MOD_AFTER_1_WORD,BLTDMOD(a6)
                move.w  d5,BLTCON0(a6)
                move.w  #0,BLTCON1(a6)
                move.w  d3,d7
                asl.w   #6,d7
                ori.w   #1,d7
                move.w  d7,BLTSIZE(a6)
blitter_span_core_masked_return:
                rts
blitter_rectrow_masked:
                movem.l d0-d3/a0-a1,-(sp)
                moveq   #0,d4
                movea.l a1,a0
                bsr.w   BlitterSpan4Planes
                movem.l (sp)+,d0-d3/a0-a1
                asl.w   #2,d1
                asl.w   #2,d3
                mulu.w  #PLANE_STRIDE,d1
                adda.l  d1,a0
                adda.l  d1,a1
                move.w  d0,d4
                lsr.w   #4,d4
                subq.w  #1,d2
                move.w  d0,d1
                add.w   d2,d1
                move.w  d1,d5
                lsr.w   #4,d5
                sub.w   d4,d5
                add.w   d4,d4
                adda.w  d4,a0
                adda.w  d4,a1
                andi.w  #TILE_MASK,d0
                andi.w  #TILE_MASK,d1
                lea     (CUSTOM).l,a6
                lea     firstWordMaskTable(pc),a2
                add.w   d0,d0
                add.w   d1,d1
                move.w  (a2,d0.w),d0
                lea     lastWordMaskTable(pc),a2
                move.w  (a2,d1.w),d1
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_blitter_ready:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_blitter_ready
                move.w  #DMACON_BLT_OFF,(DMACON).l
                addq.w  #1,d5
                move.w  #BLTCON0_USEA_USEB_USED_LF_FC,BLTCON0(a6)
                move.w  #0,BLTCON1(a6)
                move.w  d0,BLTAFWM(a6)
                move.w  d1,BLTALWM(a6)
                move.l  a0,BLTAPT(a6)
                move.l  a1,BLTBPT(a6)
                move.l  a1,BLTDPT(a6)
                move.w  #PLANE_STRIDE,d0
                sub.w   d5,d0
                sub.w   d5,d0
                move.w  d0,BLTAMOD(a6)
                move.w  d0,BLTBMOD(a6)
                move.w  d0,BLTDMOD(a6)
                asl.w   #6,d3
                or.w    d5,d3
                move.w  d3,BLTSIZE(a6)
                rts
firstWordMaskTable:
                dc.w $FFFF,$7FFF,$3FFF,$1FFF,$0FFF,$07FF,$03FF,$01FF
                dc.w $00FF,$007F,$003F,$001F,$000F,$0007,$0003,$0001
lastWordMaskTable:
                dc.w $8000,$C000,$E000,$F000,$F800,$FC00,$FE00,$FF00
                dc.w $FF80,$FFC0,$FFE0,$FFF0,$FFF8,$FFFC,$FFFE,$FFFF

; ===== BuildPaletteFromColors =====
; prototype: void __usercall BuildPaletteFromColors(unsigned __int8 *palette@<a0>)
; in:  A0 = color table (48 bytes = 16*(R,G,B) bytes; uses high nibbles only)
; out: A1 = palette (16 words, $0RGB)
BuildPaletteFromColors:
                move.w  #$F,d2
build_triplet_loop:
                clr.w   d1
                move.b  (a0)+,d0
                lsr.b   #4,d0
                add.b   d0,d1
                lsl.w   #4,d1
                move.b  (a0)+,d0
                lsr.b   #4,d0
                add.b   d0,d1
                lsl.w   #4,d1
                move.b  (a0)+,d0
                lsr.b   #4,d0
                add.b   d0,d1
                move.w  d1,(a1)+
                dbf     d2,build_triplet_loop
                rts

; ===== BlitterCopyOverlayToScreen =====
; prototype: void __usercall BlitterCopyOverlayToScreen()
BlitterCopyOverlayToScreen:
                lea     (CUSTOM).l,a6
                move.w  #DMACON_BLT_ON,(DMACON).l
.wait0:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   .wait0
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.w  #BLT_FWM_ALL,BLTALWM(a6)
                move.w  #BLT_FWM_ALL,BLTAFWM(a6)
                clr.w   BLTCON1(a6)
                move.w  #BLTCON0_USEA_USED_LF_F0,BLTCON0(a6)

                ; interleaved planar scanline step: ROW_STRIDE_BYTES - PLANE_STRIDE = 352 - 44 = 308
                move.w  #308,BLTAMOD(a6)
                move.w  #308,BLTDMOD(a6)

                move.l  (frontbufferBasePtr).l,a1
                move.l  #frontbufferBase,d0
                cmpi.l  #frontbufferBaseAlt,(frontbufferBasePtr).l
                beq.s   .sel_done
                move.l  #frontbufferBaseAlt,d0
.sel_done:
                movea.l d0,a0
                moveq   #NUM_PLANES_MINUS1,d7
.plane:
                move.w  #DMACON_BLT_ON,(DMACON).l
.wait1:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   .wait1
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  a0,BLTAPT(a6)
                move.l  a1,BLTDPT(a6)
                move.w  #BLTSIZE_OVERLAY_TO_SCREEN,BLTSIZE(a6)
                adda.l  #PLANE_STRIDE,a0
                adda.l  #PLANE_STRIDE,a1
                dbf     d7,.plane

                move.w  #DMACON_BLT_ON,(DMACON).l
.wait2:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   .wait2
                move.w  #DMACON_BLT_OFF,(DMACON).l
                rts
overlayActiveFlag:
                dc.w $0000

; ===== BlitterCopyPanelToScreen =====
; prototype: void __usercall BlitterCopyPanelToScreen()
BlitterCopyPanelToScreen:
                lea     (CUSTOM).l,a6
                move.w  #DMACON_BLT_ON,(DMACON).l
.wait0:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   .wait0
                move.w  #DMACON_BLT_OFF,(DMACON).l

                move.w  #BLT_FWM_ALL,BLTALWM(a6)
                move.w  #BLT_FWM_ALL,BLTAFWM(a6)
                clr.w   BLTCON1(a6)
                move.w  #BLTCON0_USEA_USED_LF_F0,BLTCON0(a6)

                ; same stride logic as the working routine
                move.w  #308,BLTAMOD(a6)
                move.w  #308,BLTDMOD(a6)

                ; A = source, D = destination
                movea.l #frontbufferMaskBuffer,a0
                movea.l (frontbufferBasePtr).l,a1

                moveq   #NUM_PLANES_MINUS1,d7
.plane:
                move.w  #DMACON_BLT_ON,(DMACON).l
.wait1:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   .wait1
                move.w  #DMACON_BLT_OFF,(DMACON).l

                move.l  a0,BLTAPT(a6)
                move.l  a1,BLTDPT(a6)
                move.w  #BLTSIZE_OVERLAY_TO_SCREEN,BLTSIZE(a6)

                adda.l  #PLANE_STRIDE,a0
                adda.l  #PLANE_STRIDE,a1
                dbf     d7,.plane

                move.w  #DMACON_BLT_ON,(DMACON).l
.wait2:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   .wait2
                move.w  #DMACON_BLT_OFF,(DMACON).l
                rts

; ===== HWSprite_LoadFromSpriteGraphics =====
; prototype: void __usercall HWSprite_LoadFromSpriteGraphics(__int16 spriteIndex@<d0>)
HWSprite_LoadFromSpriteGraphics:
                lea     (CUSTOM).l,a6
                movea.l (spriteGraphicsPtr).l,a0
                lsl.w   #2,d0
                movea.l (a0,d0.w),a0
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
_104040_wait_blitter_idle:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   _104040_wait_blitter_idle
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.w  #BLT_FWM_ALL,BLTALWM(a6)
                move.w  #BLT_FWM_ALL,BLTAFWM(a6)
                clr.w   BLTCON1(a6)
                move.w  #BLTCON0_USED_LF_F0,BLTCON0(a6)
                clr.w   BLTADAT(a6)
                clr.w   BLTDMOD(a6)
                move.l  (a0),BLTDPT(a6)
                move.w  $C(a0),d0
                lsl.w   #8,d0
                add.w   TILE_STRIDE(a0),d0
                move.w  d0,BLTSIZE(a6)
                rts

; ===== BlitSpritePlanar_Word =====
; prototype: void __usercall BlitSpritePlanar_Word()
BlitSpritePlanar_Word:
                movea.l (spriteGraphicsPtr).l,a0
                lsl.w   #2,d0
                movea.l (a0,d0.w),a0
                tst.w   8(a0)
                bne.w   setup_4plane_output
                movea.l 4(a0),a2
                movea.l (a0),a1
                move.w  SPRITEGRAPHICS_NLINES(a0),d1
                move.w  SPRITEGRAPHICS_WQUADS(a0),d2
                cmpi.w  #2,d2
                beq.s   fastpath_2words_setup
                lsl.w   #1,d2
                move.w  d2,d3
                add.w   d2,d3
                move.w  d3,d4
                add.w   d2,d4
                move.w  d2,d5
                lsl.w   #2,d5
                sub.w   d2,d5
                ext.l   d5
                subq.w  #1,d1
row_loop_1plane:
                move.w  $E(a0),d6
                subq.w  #1,d6
_word_loop_1plane:
                move.w  (a1),d0
                or.w    (a1,d2.w),d0
                or.w    (a1,d3.w),d0
                or.w    (a1,d4.w),d0
                move.w  d0,(a2)
                addq.l  #2,a1
                addq.l  #2,a2
                dbf     d6,_word_loop_1plane
                adda.l  d5,a1
                dbf     d1,row_loop_1plane
                rts
fastpath_2words_setup:
                lsl.w   #1,d2
                move.w  d2,d3
                add.w   d2,d3
                move.w  d3,d4
                add.w   d2,d4
                move.w  d2,d5
                lsl.w   #2,d5
                ext.l   d5
                ext.l   d2
                subq.w  #1,d1
row_loop_fastpath:
                move.l  (a1),d0
                or.l    (a1,d2.w),d0
                or.l    (a1,d3.w),d0
                or.l    (a1,d4.w),d0
                move.l  d0,(a2)
                adda.l  d5,a1
                dbf     d1,row_loop_fastpath
                rts
setup_4plane_output:
                movea.l 4(a0),a2
                movea.l (a0),a1
                move.w  SPRITEGRAPHICS_NLINES(a0),d1
                move.w  SPRITEGRAPHICS_WQUADS(a0),d2
                cmpi.w  #2,d2
                beq.s   fastpath_2words_setup_4planes
                lsl.w   #1,d2
                move.w  d2,d3
                add.w   d2,d3
                move.w  d3,d4
                add.w   d2,d4
                move.w  d2,d5
                lsl.w   #2,d5
                sub.w   d2,d5
                ext.l   d5
                subq.w  #1,d1
row_loop_4planes:
                move.w  $E(a0),d6
                subq.w  #1,d6
_word_loop_4planes:
                move.w  (a1),d0
                or.w    (a1,d2.w),d0
                or.w    (a1,d3.w),d0
                or.w    (a1,d4.w),d0
                move.w  d0,(a2)
                move.w  d0,(a2,d2.w)
                move.w  d0,(a2,d3.w)
                move.w  d0,(a2,d4.w)
                addq.l  #2,a1
                addq.l  #2,a2
                dbf     d6,_word_loop_4planes
                adda.l  d5,a1
                adda.l  d5,a2
                dbf     d1,row_loop_4planes
                rts
fastpath_2words_setup_4planes:
                lsl.w   #1,d2
                move.w  d2,d3
                add.w   d2,d3
                move.w  d3,d4
                add.w   d2,d4
                move.w  d2,d5
                lsl.w   #2,d5
                ext.l   d5
                subq.w  #1,d1
row_loop_fastpath_4planes:
                move.l  (a1),d0
                or.l    (a1,d2.w),d0
                or.l    (a1,d3.w),d0
                or.l    (a1,d4.w),d0
                move.l  d0,(a2)
                move.l  d0,(a2,d2.w)
                move.l  d0,(a2,d3.w)
                move.l  d0,(a2,d4.w)
                adda.l  d5,a1
                adda.l  d5,a2
                dbf     d1,row_loop_fastpath_4planes
                rts

; ===== BlitSpritePlanar_Word_StridedDest =====
; prototype: void __usercall BlitSpritePlanar_Word_StridedDest()
BlitSpritePlanar_Word_StridedDest:
                movea.l (spriteGraphicsPtr).l,a0
                lsl.w   #2,d0
                movea.l (a0,d0.w),a0
                tst.w   8(a0)
                bne.w   setup_4plane_output_strided
                movea.l 4(a0),a2
                movea.l (a0),a1
                move.w  $C(a0),d1
                move.w  $E(a0),d2
                lsl.w   #1,d2
                move.w  d2,d3
                add.w   d2,d3
                move.w  d3,d4
                add.w   d2,d4
                move.w  d2,d5
                lsl.w   #2,d5
                ext.l   d5
                ext.l   d2
                subq.w  #1,d1
row_loop_strided:
                move.w  (a1),d0
                or.w    (a1,d2.w),d0
                or.w    (a1,d3.w),d0
                or.w    (a1,d4.w),d0
                move.w  d0,(a2)
                adda.l  d5,a1
                adda.l  d2,a2
                dbf     d1,row_loop_strided
                rts
setup_4plane_output_strided:
                movea.l 4(a0),a2
                movea.l (a0),a1
                move.w  $C(a0),d1
                move.w  $E(a0),d2
                lsl.w   #1,d2
                move.w  d2,d3
                add.w   d2,d3
                move.w  d3,d4
                add.w   d2,d4
                move.w  d2,d5
                lsl.w   #2,d5
                ext.l   d5
                subq.w  #1,d1
row_loop_4planes_strided:
                move.w  (a1),d0
                or.w    (a1,d2.w),d0
                or.w    (a1,d3.w),d0
                or.w    (a1,d4.w),d0
                move.w  d0,(a2)
                move.w  d0,(a2,d2.w)
                move.w  d0,(a2,d3.w)
                move.w  d0,(a2,d4.w)
                adda.l  d5,a1
                adda.l  d5,a2
                dbf     d1,row_loop_4planes_strided
                rts

; ===== BlitSpritePlanar_Long_StridedDest =====
; prototype: void __usercall BlitSpritePlanar_Long_StridedDest()
BlitSpritePlanar_Long_StridedDest:
                movea.l (spriteGraphicsPtr).l,a0
                lsl.w   #2,d0
                movea.l (a0,d0.w),a0
                tst.w   8(a0)
                bne.w   setup_4plane_output_long
                movea.l 4(a0),a2
                movea.l (a0),a1
                move.w  $C(a0),d1
                move.w  $E(a0),d2
                lsl.w   #1,d2
                move.w  d2,d3
                add.w   d2,d3
                move.w  d3,d4
                add.w   d2,d4
                move.w  d2,d5
                lsl.w   #2,d5
                ext.l   d5
                ext.l   d2
                subq.w  #1,d1
row_loop_long_strided:
                move.l  (a1),d0
                or.l    (a1,d2.w),d0
                or.l    (a1,d3.w),d0
                or.l    (a1,d4.w),d0
                move.l  d0,(a2)
                adda.l  d5,a1
                adda.l  d2,a2
                dbf     d1,row_loop_long_strided
                rts
setup_4plane_output_long:
                movea.l 4(a0),a2
                movea.l (a0),a1
                move.w  $C(a0),d1
                move.w  $E(a0),d2
                lsl.w   #1,d2
                move.w  d2,d3
                add.w   d2,d3
                move.w  d3,d4
                add.w   d2,d4
                move.w  d2,d5
                lsl.w   #2,d5
                ext.l   d5
                subq.w  #1,d1
row_loop_4planes_long:
                move.l  (a1),d0
                or.l    (a1,d2.w),d0
                or.l    (a1,d3.w),d0
                or.l    (a1,d4.w),d0
                move.l  d0,(a2)
                move.l  d0,(a2,d2.w)
                move.l  d0,(a2,d3.w)
                move.l  d0,(a2,d4.w)
                adda.l  d5,a1
                adda.l  d5,a2
                dbf     d1,row_loop_4planes_long
                rts

; ===== DrawSprite_entry2 =====
; prototype: void __usercall DrawSprite_entry2()
DrawSprite_entry2:
                movea.l (spriteBlitQueue).l,a3
                move.l  a3,-(sp)
                bsr.w   DrawSpriteClipped
                movea.l (sp)+,a3
                move.l  a3,(spriteBlitQueue).l
                move.l  #$FFFFFFFF,(a3)
                rts

; ===== DrawSprite16Pixels =====
; prototype: void __usercall DrawSprite16Pixels()
DrawSprite16Pixels:
                movea.l (spriteGraphicsPtr).l,a0
                lsl.w   #2,d0
                movea.l (a0,d0.w),a0
                bra.s   DrawSprite_entry2

; ===== DrawSpriteCentered =====
; prototype: __int16 __usercall DrawSpriteCentered@<d0>(__int16 spriteIndex@<d0>, __int16 x@<d1>, __int16 y@<d2>)
; in:
;      D0 - sprite index
;      D1 - x
;      D2 - y
; 
; Destroys ebp.
DrawSpriteCentered:
                movea.l (spriteGraphicsPtr).l,a0
                lsl.w   #2,d0
                movea.l (a0,d0.w),a0
                sub.w   SPRITEGRAPHICS_CENTERX(a0),d1
                sub.w   SPRITEGRAPHICS_CENTERY(a0),d2
                bra.s   DrawSprite_entry2

; ===== CopySprite =====
; prototype: unsigned __int8 __usercall CopySprite@<d0>(unsigned __int16 srcSprite@<d0>, unsigned __int16 xOffset@<d1>, unsigned __int16 yOffset@<d2>, unsigned __int16 dstSprite@<d3>)
; Copies sprite2 into sprite1. Sprite 1 must be big enough.
; in:
;      D0 - src sprite (2)
;      D1 - x offset in dest sprite
;      D2 - y offset in dest sprite (only in EGA)
;      D3 - dest sprite (1)
; 
; Note: x offset can only start from even number (rounded down).
CopySprite:
                movea.l (spriteGraphicsPtr).l,a0
                lsl.w   #2,d3
                movea.l (a0,d3.w),a1
                lsl.w   #2,d0
                movea.l (a0,d0.w),a0
                move.w  TILE_STRIDE(a1),d3
                lsl.w   #1,d3
                movea.l (a1),a1
                bra.w   *+4
blitter_begin:
                lea     (CUSTOM).l,a6
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
_104346_wait_blitter_idle:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   _104346_wait_blitter_idle
                move.w  #DMACON_BLT_OFF,(DMACON).l
                clr.w   d6
                move.w  d1,d0
                andi.w  #TILE_MASK,d0
                move.w  $A(a0),d7
                andi.w  #TILE_MASK,d7
                bne.s   _10436E_compute_firstword_mask
                move.w  #$10,d7
_10436E_compute_firstword_mask:
                add.w   d7,d0
                move.w  TILE_STRIDE(a0),d7
                addq.w  #1,d7
                cmpi.w  #$10,d0
                bhi.s   program_edge_masks
                move.w  #$FFFF,d6
                subq.w  #1,d7
program_edge_masks:
                move.w  d6,BLTALWM(a6)
                move.w  #BLT_FWM_ALL,BLTAFWM(a6)
                move.w  d1,d0
                andi.w  #TILE_MASK,d0
                lsl.w   #6,d0
                lsl.w   #6,d0
                move.w  d0,BLTCON1(a6)
                tst.l   4(a0)
                beq.w   _1043AA_setup_singleplane_mode
                addi.w  #BLTCON0_BASE_LINKED,d0
                bra.w   write_bltcon0_and_continue
_1043AA_setup_singleplane_mode:
                addi.w  #BLTCON0_BASE_SINGLE,d0
                move.w  #$FFFF,BLTADAT(a6)
write_bltcon0_and_continue:
                move.w  d0,BLTCON0(a6)
                move.w  d1,d0
                lsr.w   #3,d0
                andi.l  #WORD_ALIGN_EVEN_MASK,d0
                move.l  d0,d6
                lsl.w   #NUM_PLANES_SHIFT,d3
                mulu.w  d3,d2
                lsr.w   #NUM_PLANES_SHIFT,d3
                add.l   d2,d0
                add.l   a1,d0
                move.l  d0,BLTCPT(a6)
                move.l  d0,BLTDPT(a6)
                tst.w   8(a0)
                beq.w   copy_four_planes_separately
                move.w  $C(a0),d4
                lsl.w   #NUM_PLANES_SHIFT,d4
                lsl.w   #6,d4
                add.w   d7,d4
                lsl.w   #1,d7
                move.w  TILE_STRIDE(a0),d0
                lsl.w   #1,d0
                sub.w   d7,d0
                move.w  d0,BLTAMOD(a6)
                move.w  d0,BLTBMOD(a6)
                sub.w   d7,d3
                move.w  d3,BLTCMOD(a6)
                move.w  d3,BLTDMOD(a6)
                move.l  (a0),BLTBPT(a6)
                move.l  4(a0),BLTAPT(a6)
                move.w  d4,BLTSIZE(a6)
                rts
copy_four_planes_separately:
                move.w  $C(a0),d4
                lsl.w   #6,d4
                add.w   d7,d4
                lsl.w   #1,d7
                move.w  TILE_STRIDE(a0),d2
                lsl.w   #NUM_PLANES_SHIFT_PLUS1,d2
                sub.w   d7,d2
                move.w  d2,BLTBMOD(a6)
                move.w  TILE_STRIDE(a0),d2
                lsl.w   #1,d2
                sub.w   d7,d2
                move.w  d2,BLTAMOD(a6)
                move.w  d3,d2
                lsl.w   #NUM_PLANES_SHIFT,d2
                sub.w   d7,d2
                move.w  d2,BLTCMOD(a6)
                move.w  d2,BLTDMOD(a6)
                move.l  (a0),d1
                move.l  4(a0),d2
                move.l  d1,BLTBPT(a6)
                move.l  d2,BLTAPT(a6)
                move.w  d4,BLTSIZE(a6)
                ext.l   d3
                move.w  TILE_STRIDE(a0),d5
                lsl.w   #1,d5
                ext.l   d5
                add.l   d3,d0
                add.l   d5,d1
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
_104474_pass2_wait_and_setup:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   _104474_pass2_wait_and_setup
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  d0,BLTCPT(a6)
                move.l  d0,BLTDPT(a6)
                move.l  d1,BLTBPT(a6)
                move.l  d2,BLTAPT(a6)
                move.w  d4,BLTSIZE(a6)
                add.l   d3,d0
                add.l   d5,d1
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
_1044AE_pass3_wait_and_setup:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   _1044AE_pass3_wait_and_setup
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  d0,BLTCPT(a6)
                move.l  d0,BLTDPT(a6)
                move.l  d1,BLTBPT(a6)
                move.l  d2,BLTAPT(a6)
                move.w  d4,BLTSIZE(a6)
                add.l   d3,d0
                add.l   d5,d1
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
pass4_wait_and_setup:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   pass4_wait_and_setup
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  d0,BLTCPT(a6)
                move.l  d0,BLTDPT(a6)
                move.l  d1,BLTBPT(a6)
                move.l  d2,BLTAPT(a6)
                move.w  d4,BLTSIZE(a6)
                rts

; ===== DrawSpriteHotspotInCameraView =====
; prototype: void __usercall DrawSpriteHotspotInCameraView()
DrawSpriteHotspotInCameraView:
                movea.l (spriteGraphicsPtr).l,a0
                lsl.w   #2,d0
                movea.l (a0,d0.w),a0
                lsr.w   #2,d0
                sub.w   $10(a0),d1
                sub.w   $12(a0),d2
                bra.w   *+4

; ===== DrawSpriteInCameraView =====
; prototype: void __usercall DrawSpriteInCameraView()
; in:
;      D0 - sprite index
;      D1 - x
;      D2 - y
;      ebp - save sprite flag, -1 = don't save sprite
DrawSpriteInCameraView:
                movea.l (spriteGraphicsPtr).l,a0
                lsl.w   #2,d0
                movea.l (a0,d0.w),a0
                sub.w   (cameraX).l,d1
                sub.w   (cameraY).l,d2
                cmpi.w  #SCREEN_WIDTH,d1
                bge.w   _10456E_exit_rts
                cmpi.w  #SCREEN_HEIGHT,d2
                bge.w   _10456E_exit_rts
                move.w  $A(a0),d0
                neg.w   d0
                cmp.w   d0,d1
                ble.w   _10456E_exit_rts
                move.w  $C(a0),d0
                neg.w   d0
                cmp.w   d0,d2
                ble.w   _10456E_exit_rts
                bra.w   DrawSpriteClipped
_10456E_exit_rts:
                rts

; ===== DarkenRectangle =====
; prototype: void __usercall DarkenRectangle(unsigned __int16 spriteIndex@<d0>, unsigned __int16 x@<d1>, unsigned __int16 y@<d2>)
; in:  
;      D0 - sprite index
;      D1 - x
;      D2 - y
; 
; destroys: eax, ebx, ecx, edx, esi, edi
; 
; Darkens rectangle of sprite dimensions by setting high bit of every pixel in region.
; Game palette is created in such a way that every color with index smaller than 128
; has its darkened counterpart with index + 128.
; Saves sprite area unconditionally.
DarkenRectangle:
                movea.l (spriteGraphicsPtr).l,a0
                lsl.w   #2,d0
                movea.l (a0,d0.w),a0
                bra.w   *+4

; ===== DrawSpriteClipped =====
; prototype: void __usercall DrawSpriteClipped(Sprite *sprite@<a0>, unsigned __int16 x@<d1>, unsigned __int16 y@<d2>)
;
; Requires:
;   NUM_PLANES, NUM_PLANES_MINUS1, NUM_PLANES_SHIFT, NUM_PLANES_SHIFT_PLUS1
;
; Notes:
; - This keeps your existing BLTSIZE/BLTBMOD/skip logic using NUM_PLANES_SHIFT,
;   but fixes the previously hardcoded 4-plane pass sequencing.

DrawSpriteClipped:
                tst.w   SPRITE_ANIMATIONTABLE+2(a0)
                bne.w   branch_linked_planes

                movea.l (spriteBlitQueue).l,a3
                movea.l (frontbufferBasePtr).l,a1

                movem.l a2/a4-a5,-(sp)

                move.w  $C(a0),d3              ; height
                clr.w   d5                     ; top-skip lines (if y < 0)

                tst.w   d2
                bpl.s   clip_top_against_0
                sub.w   d2,d5                  ; d5 = -y
                add.w   d2,d3                  ; height -= -y
                clr.w   d2

clip_top_against_0:
                move.w  d2,d0
                add.w   d3,d0
                subi.w  #SCREEN_HEIGHT,d0
                bmi.s   apply_screen_offsets
                sub.w   d0,d3                  ; clamp height to screen

apply_screen_offsets:
                add.w   (cameraXMod320).l,d1
                add.w   (cameraYMod320).l,d2
                cmpi.w  #SCREEN_HEIGHT,d2
                blt.s   _1045D2_wrap_y_within_buffer
                subi.w  #SCREEN_HEIGHT,d2

_1045D2_wrap_y_within_buffer:
                lea     (CUSTOM).l,a6

                clr.w   d6
                move.w  d1,d0
                andi.w  #TILE_MASK,d0
                move.w  $A(a0),d7
                andi.w  #TILE_MASK,d7
                bne.s   _1045EE_compute_firstword_mask
                move.w  #$10,d7

_1045EE_compute_firstword_mask:
                add.w   d7,d0
                move.w  TILE_STRIDE(a0),d7
                addq.w  #1,d7
                cmpi.w  #$10,d0
                bhi.s   start_blitter_wait
                move.w  #BLT_FWM_ALL,d6
                subq.w  #1,d7

start_blitter_wait:
                move.w  #DMACON_BLT_ON,(DMACON).l
_104612_wait_blitter_idle:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   _104612_wait_blitter_idle
                move.w  #DMACON_BLT_OFF,(DMACON).l

                move.w  d6,BLTALWM(a6)
                move.w  #BLT_FWM_ALL,BLTAFWM(a6)

                move.w  d1,d0
                andi.w  #TILE_MASK,d0
                lsl.w   #6,d0
                lsl.w   #6,d0
                move.w  d0,BLTCON1(a6)

                tst.l   4(a0)
                beq.w   _10464C_setup_singleplane_mode
                addi.w  #BLTCON0_BASE_LINKED,d0
                bra.w   write_bltcon_and_go

_10464C_setup_singleplane_mode:
                addi.w  #BLTCON0_BASE_SINGLE,d0
                move.w  #$FFFF,$74(a6)

write_bltcon_and_go:
                move.w  d0,BLTCON0(a6)

                clr.w   d4                     ; wrap-lines (if bottom crosses)
                move.w  d2,d0
                add.w   d3,d0
                subi.w  #SCREEN_HEIGHT,d0
                bls.w   save_rows_to_blit
                move.w  d0,d4
                sub.w   d0,d3

save_rows_to_blit:
                move.w  d3,(queuedLineCount).l

                move.w  d1,d0
                asr.w   #TILE_SHIFT_X,d0
                asl.w   #1,d0
                ext.l   d0
                move.l  d0,d6                 ; d6 = x word offset (bytes)

                mulu.w  #ROW_STRIDE_BYTES,d2
                add.l   d2,d0
                add.l   a1,d0

                move.l  d0,BLTCPT(a6)
                move.l  d0,BLTDPT(a6)
                movea.l d0,a2

                move.l  d0,4(a3)
                sub.l   a1,d0
                addi.l  #frontbufferMaskBuffer,d0
                move.l  d0,(a3)

                ; queue BLTSIZE for the span
                move.w  d3,d0
                lsl.w   #NUM_PLANES_SHIFT,d0
                lsl.w   #6,d0
                add.w   d7,d0
                move.w  d0,$A(a3)

                ; BLTSIZE for immediate blit (height<<6 + widthWords)
                lsl.w   #6,d3
                add.w   d7,d3

                lsl.w   #1,d7                 ; widthWords -> widthBytes

                move.w  TILE_STRIDE(a0),d0
                lsl.w   #1,d0                 ; rowBytesPerPlane (source plane chunk)
                move.w  d0,d1
                lsl.w   #NUM_PLANES_SHIFT,d1  ; rowBytesPerPlane * NUM_PLANES
                sub.w   d7,d0
                move.w  d0,BLTAMOD(a6)
                sub.w   d7,d1
                move.w  d1,BLTBMOD(a6)

                move.w  #PLANE_STRIDE,d0
                sub.w   d7,d0
                move.w  d0,8(a3)
                addi.w  #PITCH_DEST_MOD_UNALIGNED,d0
                move.w  d0,BLTCMOD(a6)
                move.w  d0,BLTDMOD(a6)

                ; apply top-skip to sources
                ext.l   d5
                beq.s   apply_source_top_skip
                lsl.w   #NUM_PLANES_SHIFT,d5
                mulu.w  TILE_STRIDE(a0),d5
                lsl.l   #1,d5

apply_source_top_skip:
                move.l  (a0),d0
                add.l   d5,d0
                move.l  d0,BLTBPT(a6)
                movea.l d0,a5

                move.l  4(a0),d0
                lsr.w   #NUM_PLANES_SHIFT,d5
                add.l   d5,d0
                move.l  d0,BLTAPT(a6)
                movea.l d0,a4

                adda.l  #$C,a3

                ; ---- START FIRST PLANE BLIT (plane 0) ----
                move.w  d3,BLTSIZE(a6)

                ; save base sources for wrap/tail
                move.l  a4,(savedSrcPlaneB).l      ; mask base
                move.l  a5,(savedSrcPlaneA).l      ; gfx base (interleaved per line)

                ; compute per-plane step values used by loops
                move.w  TILE_STRIDE(a0),d0
                lsl.w   #1,d0
                ext.l   d0                         ; d0 = rowBytesPerPlane (long)

                ; advance dest/src pointers to plane 1 for looping
                adda.l  #PLANE_STRIDE,a2
                adda.l  d0,a5

                ; ---- BLIT REMAINING PLANES (1..NUM_PLANES-1) ----
                move.w  #(NUM_PLANES_MINUS1),d1   ; DBF runs (d1+1) times = NUM_PLANES-1
                move.w  #DMACON_BLT_ON,(DMACON).l

.blit_planes_loop:
.wait_plane_done:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   .wait_plane_done
                move.w  #DMACON_BLT_OFF,(DMACON).l

                move.l  a2,BLTCPT(a6)
                move.l  a2,BLTDPT(a6)
                move.l  a4,BLTAPT(a6)
                move.l  a5,BLTBPT(a6)
                move.w  d3,BLTSIZE(a6)

                adda.l  #PLANE_STRIDE,a2
                adda.l  d0,a5

                move.w  #DMACON_BLT_ON,(DMACON).l
                dbf     d1,.blit_planes_loop

                ; if no vertical wrap, finish (don’t wait; original behavior)
                tst.w   d4
                beq.w   seal_queue_and_exit

                ; ---- WRAP / TAIL SETUP ----
                move.w  (queuedLineCount).l,d2
                mulu.w  TILE_STRIDE(a0),d2
                lsl.l   #1,d2                      ; bytes in mask plane to skip
                move.l  (savedSrcPlaneB).l,d1
                add.l   d2,d1                      ; d1 = mask tail ptr

                lsl.l   #NUM_PLANES_SHIFT,d2        ; bytes in interleaved gfx to skip lines
                add.l   (savedSrcPlaneA).l,d2       ; d2 = gfx tail ptr

                ; wait for the last main plane blit to complete before tail
                move.w  #DMACON_BLT_ON,(DMACON).l
.wait_main_done:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   .wait_main_done
                move.w  #DMACON_BLT_OFF,(DMACON).l

                ; dest base for wrapped lines
                add.l   a1,d6
                move.l  d6,BLTCPT(a6)
                move.l  d6,BLTDPT(a6)
                move.l  d1,BLTAPT(a6)
                move.l  d2,BLTBPT(a6)

                ; queue entry for tail span
                move.l  d6,d0
                move.l  d0,4(a3)
                sub.l   a1,d0
                addi.l  #frontbufferMaskBuffer,d0
                move.l  d0,(a3)

                lsr.w   #1,d7
                move.w  d4,d0
                lsl.w   #NUM_PLANES_SHIFT,d0
                lsl.w   #6,d0
                add.w   d7,d0
                move.w  d0,$A(a3)

                lsl.w   #6,d4
                add.w   d7,d4
                move.w  d4,BLTSIZE(a6)

                ; prime pointers for looping tail planes
                addi.l  #PLANE_STRIDE,d6
                add.l   d0,d2                      ; NOTE: d0 is NOT rowBytesPerPlane here anymore

                ; restore correct rowBytesPerPlane into d0 (we need it for tail plane stepping)
                move.w  TILE_STRIDE(a0),d0
                lsl.w   #1,d0
                ext.l   d0

                ; advance src gfx for plane 1 tail
                add.l   d0,d2

                ; start tail plane 0 already launched by BLTSIZE above
                move.w  #DMACON_BLT_ON,(DMACON).l

                ; ---- BLIT REMAINING TAIL PLANES (1..NUM_PLANES-1) ----
                move.w  #(NUM_PLANES_MINUS1),d5

.tail_planes_loop:
.wait_tail_done:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   .wait_tail_done
                move.w  #DMACON_BLT_OFF,(DMACON).l

                move.l  d6,BLTCPT(a6)
                move.l  d6,BLTDPT(a6)
                move.l  d1,BLTAPT(a6)              ; mask stays the same
                move.l  d2,BLTBPT(a6)              ; gfx advances per plane
                move.w  d4,BLTSIZE(a6)

                addi.l  #PLANE_STRIDE,d6
                add.l   d0,d2

                move.w  #DMACON_BLT_ON,(DMACON).l
                dbf     d5,.tail_planes_loop

                ; keep original queue fixup behavior
                move.w  -4(a3),8(a3)
                adda.l  #$C,a3

seal_queue_and_exit:
                move.l  #BLT_BLITQ_END,(a3)
                move.l  a3,(spriteBlitQueue).l
                movem.l (sp)+,a2/a4-a5
                rts

; ---------------------------------------------------------------------------
; data / locals remain where your original code had them
queuedLineCount:
                dc.w $0000
savedSrcPlaneB:
                dc.l $00000000          ; raw
savedSrcPlaneA:
                dc.l $00000000          ; raw

