                beq.w   _106EA4_exit_rts
                tst.w   (fadeInChantTimer).l
                bne.w   crowd_fadein_tick
                tst.w   (nextChantTimer).l
                bne.w   crowd_cooldown_tick
                tst.w   (fadeOutChantTimer).l
                bne.w   crowd_fadeout_tick
                jsr     Rand
                cmpi.w  #128,d0
                bcs.s   crowd_start_event
                jsr     Rand
                lsl.w   #2,d0
                addi.w  #$1F4,d0
                move.w  d0,(nextChantTimer).l
                bra.w   _106EA4_exit_rts
crowd_start_event:
                move.w  #0,d1
                move.w  #2,d0
                move.w  d1,(crowdChantVolume).l
                bsr.w   SetVolumeOrStopChants
                move.w  (currentCrowdSample).l,d1
                cmpi.w  #$FFFF,d1
                beq.s   loc_106E0A
                jsr     Rand
                cmpi.w  #$80,d0
