                jsr     Rand
                lsl.w   #1,d0
                addi.w  #500,d0
                move.w  d0,(nextChantTimer).l
                move.w  #128,(fadeOutChantTimer).l
                bra.w   _106EA4_exit_rts
crowd_cooldown_tick:
                subq.w  #1,(nextChantTimer).l
                rts
                subq.w  #1,(nextChantTimer).l
                rts
crowd_fadeout_tick:
                subq.w  #1,(fadeOutChantTimer).l
                move.w  (fadeOutChantTimer).l,d1
                lsr.w   #1,d1
                move.w  #2,d0
                move.w  d1,(crowdChantVolume).l
                bsr.w   SetVolumeOrStopChants
                rts
