; ===== CalculateDeltaXAndY =====
; prototype: __int16 __usercall CalculateDeltaXAndY@<d0>(__int16 speed@<d0>, __int16 destX@<d1>, __int16 destY@<d2>, __int16 curX@<d3>, __int16 curY@<d4>)
; in:
;      D0 - speed
;      D1 - destination x
;      D2 - destination y
;      D3 - current x
;      D4 - current y
;      (all inputs are 16-bit integers)
; out:
;      D0 - angle (0..255) (0 is 270 degrees, start of trigonometric circle is 64)
;           -1 if no movement (word)
;      D1 - delta x (32-bit fixed point)
;      D2 - delta y (32-bit fixed point)
;      sign flag: set = no movement, clear = there is movement
; 
; Delta x and y are numbers of pixels that sprite needs to be moved in one cycle to reach
; destination coordinates.
CalculateDeltaXAndY:
                sub.w   d3,d1
                sub.w   d4,d2
                move.w  d0,d5
                lea     (kAngleCoeficients).l,a1
                tst.w   d1
                smi     d3
                bpl.s   delta_x_positive
                neg.w   d1
delta_x_positive:
                tst.w   d2
                smi     d4
                bpl.s   delta_y_positive
                neg.w   d2
delta_y_positive:
                cmpi.w  #32,d1
                blt.s   check_delta_x
                lsr.w   #1,d1
                lsr.w   #1,d2
                bra.s   delta_y_positive
check_delta_x:
                cmpi.w  #32,d2
                blt.s   get_angle_coeficient
                lsr.w   #1,d1
                lsr.w   #1,d2
                bra.s   check_delta_x
get_angle_coeficient:
                asl.w   #5,d2
                or.w    d2,d1
                asl.w   #1,d1
                move.w  (a1,d1.w),d0    ; D0 = tangent of the angle [0..64]
                                        ; D0 < 0 means dx = dy = 0
                bmi.w   no_movement
                asl.w   #1,d0
                tst.b   d3
                bmi.s   left_half_of_circle
                tst.b   d4
                bmi.s   quadrant_4
                move.w  #128,d1         ; x and y positive
                sub.w   d0,d1
                bra.s   calculate_sine_cosine
quadrant_4:
                move.w  #128,d1
                add.w   d0,d1
                bra.s   calculate_sine_cosine
left_half_of_circle:
                tst.b   d4
                bmi.s   quadrant_3
                move.w  #384,d1         ; x negative y positive
                add.w   d0,d1
                bra.s   calculate_sine_cosine
quadrant_3:
                move.w  #384,d1
                sub.w   d0,d1
calculate_sine_cosine:
                andi.w  #$1FF,d1
                move.w  #512,d0
                sub.w   d1,d0
                addi.w  #256,d0
                andi.w  #$1FF,d0
                lsr.w   #1,d0           ; D0 = direction on a circle 0..255
                lea     (kSineCosineTable).l,a1
                move.w  d1,d2           ; D1 = cosine of a direction vector angle
                move.w  (a1,d1.w),d1
                addi.w  #128,d2
                andi.w  #$1FF,d2
                move.w  (a1,d2.w),d2    ; D2 = sine of a direction vector angle
                asr.w   #8,d1           ; shift right in preparation for fixed point multiplication
                asr.w   #8,d2           ; D1 = -128..127, D2 = -128..127
                muls.w  d5,d1           ; multiply cosinus with speed factor
                muls.w  d5,d2           ; multiply sinus with speed factor
                tst.w   d0
                rts
no_movement:
                clr.l   d1
                clr.l   d2
                move.w  #$FFFF,d0
                tst.w   d0
                rts
