                rts
                rts

; ===== SetNextPlayerFrame =====
; prototype: void __usercall SetNextPlayerFrame(struct Sprite *player@<a0>)
; in:
;      A0 -> player
; 
; globals:
;   read:
;     goalScored
;     lastTeamScoredPtr
;     playerScoredPtr
;     currentGameTick
; 
; Sets next picture frame for players. Also takes care of cheering after
; scored goal.
SetNextPlayerFrame:
                tst.w   SPRITE_ONSCREEN(a0)
                beq.w   return_if_anim_inactive
                subq.w  #1,SPRITE_CYCLEFRAMESTIMER(a0)
                bne.w   return_if_anim_inactive
                addq.w  #1,SPRITE_FRAMEINDEX(a0)
                move.w  SPRITE_FRAMEDELAY(a0),SPRITE_CYCLEFRAMESTIMER(a0)
                movea.l SPRITE_FRAMEINDICESTABLE(a0),a1
fetch_next_anim_word:
                move.w  SPRITE_FRAMEINDEX(a0),d0
                lsl.w   #1,d0
                move.w  (a1,d0.w),d0
                bpl.s   emit_anim_frame
                cmpi.w  #$FC19,d0
                beq.s   anim_cmd_reset_index
                cmpi.w  #$FF9B,d0
                beq.s   anim_cmd_step_back_one
                cmpi.w  #$FF9C,d0
                ble.s   anim_cmd_adjust_index_rel
                neg.w   d0
                move.w  d0,SPRITE_FRAMEDELAY(a0)
                move.w  d0,SPRITE_CYCLEFRAMESTIMER(a0)
                addq.w  #1,SPRITE_FRAMEINDEX(a0)
                bra.s   fetch_next_anim_word
anim_cmd_reset_index:
                clr.w   SPRITE_FRAMEINDEX(a0)
                bra.s   fetch_next_anim_word
anim_cmd_adjust_index_rel:
                addi.w  #100,d0
                add.w   d0,SPRITE_FRAMEINDEX(a0)
                bra.s   fetch_next_anim_word
anim_cmd_step_back_one:
                subq.w  #1,SPRITE_FRAMEINDEX(a0)
                bra.s   return_if_anim_inactive
emit_anim_frame:
                addq.w  #1,SPRITE_FRAMESWITCHCOUNTER(a0)
                add.w   4(a0),d0
                tst.w   (goalScored).l
                beq.s   store_frame_to_sprite
                cmpi.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a0)
                bne.s   store_frame_to_sprite
                tst.w   SPRITE_DIRECTION(a0)
                beq.s   goal_celebration_gate
                cmpi.w  #4,SPRITE_DIRECTION(a0)
                bne.s   store_frame_to_sprite
goal_celebration_gate:
                move.w  (lastTeamScoredNumber).l,d1
                cmp.w   (a0),d1
                bne.s   store_frame_to_sprite
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a0)
                beq.s   store_frame_to_sprite
                cmpa.l  (lastPlayerScored).l,a0
                bne.s   nonscorer_flash_window_gate
                move.w  (currentGameTick).l,d1
                andi.w  #$7F,d1
                cmpi.w  #100,d1
                bhi.s   store_frame_to_sprite
                bra.s   apply_celebration_frame_offset
nonscorer_flash_window_gate:
                move.w  SPRITE_PLAYERORDINAL(a0),d1
                lsl.w   #2,d1
                add.w   (currentGameTick).l,d1
                andi.w  #63,d1
                cmpi.w  #31,d1
                bhi.s   store_frame_to_sprite
apply_celebration_frame_offset:
                addi.w  #24,d0
store_frame_to_sprite:
                move.w  d0,SPRITE_IMAGEINDEX(a0)
return_if_anim_inactive:
                rts

; ===== MovePlayer =====
; prototype: void __usercall MovePlayer(struct Sprite *player@<a0>)
; in:
;      A0 -> player
; 
; globals:
;   read:
;      gameStatePl
;      breakCameraMode
;      
; Update x and y coordinates based on deltas. If sprite has reached its
; destination stop it, and set standing animation table.
MovePlayer:
                tst.w   SPRITE_ONSCREEN(a0)
                beq.w   inactive_player_motion
update_pos_and_clamp_loop:
                move.l  SPRITE_DELTAX(a0),d0
                beq.s   after_x_motion
                bpl.s   x_motion_positive_branch
                move.w  SPRITE_DESTX(a0),d1
                add.l   d0,SPRITE_X(a0)
                cmp.w   SPRITE_X(a0),d1
                blt.s   after_x_motion
clamp_x_stop_motion:
                move.w  d1,SPRITE_X(a0)
                clr.l   SPRITE_DELTAX(a0)
                bra.s   after_x_motion
x_motion_positive_branch:
                move.w  SPRITE_DESTX(a0),d1
                add.l   d0,SPRITE_X(a0)
                cmp.w   SPRITE_X(a0),d1
                ble.s   clamp_x_stop_motion
after_x_motion:
                move.l  SPRITE_DELTAY(a0),d0
                beq.s   after_y_motion
                bpl.s   y_motion_positive_branch
                move.w  SPRITE_DESTY(a0),d1
                add.l   d0,SPRITE_Y(a0)
                cmp.w   SPRITE_Y(a0),d1
                blt.w   early_exit_no_anim_change
clamp_y_stop_motion:
                move.w  d1,SPRITE_Y(a0)
                clr.l   SPRITE_DELTAY(a0)
                bra.s   after_y_motion
y_motion_positive_branch:
                move.w  SPRITE_DESTY(a0),d1
                add.l   d0,SPRITE_Y(a0)
                cmp.w   SPRITE_Y(a0),d1
                ble.s   clamp_y_stop_motion
after_y_motion:
                cmpi.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a0)
                bne.s   early_exit_no_anim_change
                tst.l   SPRITE_DELTAX(a0)
                bne.s   early_exit_no_anim_change
                tst.l   SPRITE_DELTAY(a0)
                bne.s   early_exit_no_anim_change
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.s   maybe_switch_to_stand_anim
                cmpi.w  #3,(breakCameraMode).l
                bne.s   maybe_switch_to_stand_anim
                cmpi.w  #2,SPRITE_DESTREACHEDSTATE(a0)
                bne.s   maybe_switch_to_stand_anim
                move.w  #3,SPRITE_DESTREACHEDSTATE(a0)
maybe_switch_to_stand_anim:
                cmpi.l  #playerNormalStandingAnimTable,6(a0)
                beq.s   early_exit_no_anim_change
                movea.l a0,a1
                movea.l a0,a4
                lea     (playerNormalStandingAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                movea.l a4,a0
early_exit_no_anim_change:
                rts
inactive_player_motion:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.w   update_pos_and_clamp_loop
                move.w  SPRITE_DESTX(a0),d1
                move.l  SPRITE_DELTAX(a0),d0
                beq.s   after_x_in_inactive
                bpl.s   x_motion_positive_inactive
                add.l   d0,SPRITE_X(a0)
                cmp.w   SPRITE_X(a0),d1
                blt.s   after_x_in_inactive
clamp_x_stop_motion_inactive:
                move.w  d1,SPRITE_X(a0)
                clr.l   SPRITE_DELTAX(a0)
                bra.s   after_x_in_inactive
x_motion_positive_inactive:
                add.l   d0,SPRITE_X(a0)
                cmp.w   SPRITE_X(a0),d1
                ble.s   clamp_x_stop_motion_inactive
after_x_in_inactive:
                move.w  SPRITE_DESTY(a0),d1
                move.l  SPRITE_DELTAY(a0),d0
                beq.s   return_after_inactive_motion
                bpl.s   y_motion_positive_inactive
                add.l   d0,SPRITE_Y(a0)
                cmp.w   SPRITE_Y(a0),d1
                blt.w   return_after_inactive_motion
clamp_y_stop_motion_inactive:
                move.w  d1,SPRITE_Y(a0)
                clr.l   SPRITE_DELTAY(a0)
                bra.s   return_after_inactive_motion
y_motion_positive_inactive:
                add.l   d0,SPRITE_Y(a0)
                cmp.w   SPRITE_Y(a0),d1
                ble.s   clamp_y_stop_motion_inactive
return_after_inactive_motion:
                rts

; ===== SetPlayerAnimationTableAndPictureIndex =====
; prototype: void __usercall SetPlayerAnimationTableAndPictureIndex(const AnimTable *animTable@<a0>, Sprite *player@<a1>)
; in:
;      A0 -> animation table
;      A1 -> player (sprite)
SetPlayerAnimationTableAndPictureIndex:
                move.l  a0,SPRITE_ANIMATIONTABLE(a1)
                move.w  d0,-(sp)
                move.w  (a1),d0
                subq.w  #1,d0           ; D0 = 0 for team 1, 1 for team 2
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a1)
                bne.s   _108ECE_compute_anim_table_index
                addq.w  #2,d0           ; D0: 0 - player team 1
                                        ;     1 - player team 2
                                        ;     2 - goalkeeper team 1
                                        ;     3 - goalkeeper team 2
_108ECE_compute_anim_table_index:
                lsl.w   #3,d0
                add.w   SPRITE_DIRECTION(a1),d0
                lsl.w   #2,d0           ; index = 8 * player/goalie team + direction (0..7)
                move.w  (a0),SPRITE_FRAMEDELAY(a1)
                move.l  2(a0,d0.w),SPRITE_FRAMEINDICESTABLE(a1)
                beq.s   _108F04_panic_null_anim_table
                move.w  SPRITE_DIRECTION(a1),SPRITE_STARTINGDIRECTION(a1)
                movea.l SPRITE_FRAMEINDICESTABLE(a1),a0
                move.w  SPRITE_FRAMEINDEX(a1),d0
                lsl.w   #1,d0
                move.w  (a0,d0.w),d0
                bmi.s   restore_d0_and_return
                add.w   SPRITE_FRAMEOFFSET(a1),d0
                move.w  d0,SPRITE_IMAGEINDEX(a1)
restore_d0_and_return:
                move.w  (sp)+,d0
                rts
_108F04_panic_null_anim_table:
                move.w  #$E,(panicReasonCode).l
                jsr PanicHaltLoop(pc)

; ===== SetPlayerAnimationTable =====
; prototype: void __usercall SetPlayerAnimationTable(const AnimTable *animTable@<a0>, Sprite *player@<a1>)
; in:
;      A0 -> animation table
;      A1 -> player
; 
; Set player's animation table and frame indices table and sets up starting state.
SetPlayerAnimationTable:
                move.l  a0,SPRITE_ANIMATIONTABLE(a1)
                move.w  d0,-(sp)
                move.w  (a1),d0
                subq.w  #1,d0
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a1)
                bne.s   _108F24_compute_anim_table_index
                addq.w  #2,d0
_108F24_compute_anim_table_index:
                lsl.w   #3,d0           ; 0 = player team 1
                                        ; 1 = player team 2
                                        ; 2 = goalkeeper team 1
                                        ; 3 = goalkeeper team 2
                add.w   SPRITE_DIRECTION(a1),d0 ; direction is 0..7
                lsl.w   #2,d0           ; offset = 32 * playerTeam + 4 * direction
                move.w  (a0),SPRITE_FRAMEDELAY(a1)
                move.l  2(a0,d0.w),SPRITE_FRAMEINDICESTABLE(a1)
                beq.s   _108F54_panic_null_anim_table
                move.w  #$FFFF,SPRITE_FRAMESWITCHCOUNTER(a1)
                move.w  #$FFFF,SPRITE_FRAMEINDEX(a1)
                move.w  #1,SPRITE_CYCLEFRAMESTIMER(a1)
                move.w  SPRITE_DIRECTION(a1),SPRITE_STARTINGDIRECTION(a1)
                move.w  (sp)+,d0
                rts
_108F54_panic_null_anim_table:
                move.w  #$E,(panicReasonCode).l
                jsr PanicHaltLoop(pc)

; ===== SetBallPosition =====
; prototype: void __usercall SetBallPosition(__int16 ballX@<d1>, __int16 ballY@<d2>)
; in:
;      D1 - ball x
;      D2 - ball y
; 
; Stop ball and put it to the ground (z = 0).
SetBallPosition:
                lea     (ballSprite).l,a0
                clr.w   ballSprite+SPRITE_SPEED-ballSprite(a0)
                move.w  d1,SPRITE_X(a0)
                clr.w   SPRITE_X+2(a0)
                move.w  d2,SPRITE_Y(a0)
                clr.w   SPRITE_Y+2(a0)
                move.w  d1,SPRITE_DESTX(a0)
                move.w  d2,SPRITE_DESTY(a0)
                clr.w   SPRITE_Z(a0)
                clr.l   SPRITE_DELTAZ(a0)
                rts
maxCameraMovement:
                dc.l $00050000          ; raw

; ===== MoveCamera =====
; prototype: void __usercall MoveCamera()
MoveCamera:
                tst.w   (showFansCounter).l
                bne.w   move_camera_ret
                lea     (ballSprite).l,a0
                move.l  SPRITE_DELTAX(a0),d3
                move.l  SPRITE_DELTAY(a0),d4
                tst.w   (whichCard).l
                beq.s   check_penalties_mode
                movea.l (bookedPlayer).l,a1
                move.w  SPRITE_X(a1),d3
                move.w  SPRITE_Y(a1),d4
                clr.w   (cameraXVelocity).l
                clr.w   (cameraYVelocity).l
                move.w  #37,d1
                bra.w   offset_and_clamp_to_view
check_penalties_mode:
                tst.w   (playingPenalties).l
                beq.s   check_subs_timers
                move.w  #336,d3
                move.w  #107,d4
                clr.w   (cameraXVelocity).l
                clr.w   (cameraYVelocity).l
                move.w  #0,d1
                bra.w   offset_and_clamp_to_view
check_subs_timers:
                tst.w   (waitForPlayerToGoInTimer).l
                bne.s   bench_camera_mode
                tst.w   (leavingSubsMenu).l
                beq.s   in_subs_menu_branch
                move.w  #37,d1
                move.w  #211,d3
                move.w  #449,d4
                clr.w   (cameraXVelocity).l
                clr.w   (cameraYVelocity).l
                bra.w   offset_and_clamp_to_view
in_subs_menu_branch:
                tst.w   (inSubstitutesMenu).l
                beq.s   preplay_camera_direction_pick
                move.w  #37,d1
                cmpi.w  #303,(cameraY).l
                bcs.s   bench_camera_target_and_zero_vel
                cmpi.w  #323,(cameraY).l
                bhi.s   bench_camera_target_and_zero_vel
                move.w  #37,d1
                lea     (goal1TopSprite).l,a0
                cmpi.w  #$FFFF,goal1TopSprite+SPRITE_IMAGEINDEX-goal1TopSprite(a0)
                beq.s   check_goal2_bottom_sprite_ready
                tst.w   84(a0)
                bne.s   bench_camera_target_and_zero_vel
check_goal2_bottom_sprite_ready:
                lea     (goal2BottomSprite).l,a0
                cmpi.w  #$FFFF,goal2BottomSprite+SPRITE_IMAGEINDEX-goal2BottomSprite(a0)
                beq.s   check_substitution_in_progress
                tst.w   84(a0)
                bne.s   bench_camera_target_and_zero_vel
check_substitution_in_progress:
                tst.w   (substituteInProgress).l
                bne.s   bench_camera_mode
                move.w  #0,d1
                bra.s   bench_camera_target_and_zero_vel
bench_camera_mode:
                move.w  #$33,d1         ; '3'
bench_camera_target_and_zero_vel:
                move.w  (benchXLimit).l,d3
                move.w  #$1C1,d4
                clr.w   (cameraXVelocity).l
                clr.w   (cameraYVelocity).l
                bra.w   offset_and_clamp_to_view
preplay_camera_direction_pick:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.w   apply_accel_limits_setup
                movea.l (lastTeamPlayedBeforeBreak).l,a1
                cmpa.l  #0,a1
                beq.w   fallback_to_camera_direction
                movea.l $20(a1),a1
                cmpa.l  #0,a1
                beq.w   fallback_to_camera_direction
                move.w  $2A(a1),d0
                bra.s   lookup_next_camera_dir_vector
fallback_to_camera_direction:
                move.w  (cameraDirection).l,d0
                bpl.s   lookup_next_camera_dir_vector
                clr.l   d3
                clr.l   d4
                bra.s   apply_accel_limits_setup
lookup_next_camera_dir_vector:
                lsl.w   #3,d0
                lea     (nextCameraDirections).l,a1
                move.l  (a1,d0.w),d3
                move.l  4(a1,d0.w),d4
apply_accel_limits_setup:
                move.w  #2,d0
                move.w  #$28,d1         ; '('
                tst.l   d4
                beq.s   update_x_velocity_positive
                move.w  #$28,d1         ; '('
update_x_velocity_positive:
                tst.l   d3
                beq.s   update_x_velocity_zero
                bmi.s   update_x_velocity_negative
                move.w  #$28,d2         ; '('
                cmp.w   (cameraXVelocity).l,d1
                beq.s   update_y_velocity_dispatch
                add.w   d0,(cameraXVelocity).l
                bra.s   update_y_velocity_dispatch
update_x_velocity_negative:
                move.w  #$28,d2         ; '('
                neg.w   d1
                cmp.w   (cameraXVelocity).l,d1
                beq.s   update_y_velocity_dispatch
                sub.w   d0,(cameraXVelocity).l
                bra.w   update_y_velocity_dispatch
update_x_velocity_zero:
                move.w  #$28,d2         ; '('
update_y_velocity_dispatch:
                tst.l   d4
                beq.s   after_velocity_updates
                bmi.s   update_y_velocity_negative
                cmp.w   (cameraYVelocity).l,d2
                beq.s   after_velocity_updates
                add.w   d0,(cameraYVelocity).l
                bra.s   after_velocity_updates
update_y_velocity_negative:
                neg.w   d2
                cmp.w   (cameraYVelocity).l,d2
                beq.s   after_velocity_updates
                sub.w   d0,(cameraYVelocity).l
                bra.w   *+4
after_velocity_updates:
                move.w  #$3F,d1         ; '?'
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.s   state_based_camera_target
                move.w  #$3F,d1         ; '?'
                cmpi.w  #ST_CORNER_LEFT,(gameState).l
                beq.s   narrow_bounds_for_set_pieces
                cmpi.w  #ST_CORNER_RIGHT,(gameState).l
                beq.s   narrow_bounds_for_set_pieces
                cmpi.w  #ST_THROW_IN_FORWARD_RIGHT,(gameState).l
                bcs.s   state_based_camera_target
                cmpi.w  #ST_THROW_IN_BACK_LEFT,(gameState).l
                bhi.s   state_based_camera_target
narrow_bounds_for_set_pieces:
                move.w  #$25,d1         ; '%'
state_based_camera_target:
                cmpi.w  #ST_STARTING_GAME,(gameState).l
                bcs.w   target_ball_position
                cmpi.w  #ST_GAME_ENDED,(gameState).l
                bhi.w   target_ball_position
                cmpi.w  #ST_STARTING_GAME,(gameState).l
                beq.s   tunnel_halftime_camera_target
                cmpi.w  #ST_CAMERA_GOING_TO_SHOWERS,(gameState).l
                beq.s   tunnel_halftime_camera_target
                cmpi.w  #ST_FIRST_HALF_ENDED,(gameState).l
                beq.s   target_ball_position
                cmpi.w  #ST_GAME_ENDED,(gameState).l
                bne.s   postgame_halftime_branches
                tst.w   (penaltiesState).l
                bmi.s   center_camera_fulltime
                bra.s   target_ball_position
postgame_halftime_branches:
                cmpi.w  #ST_GOING_TO_HALFTIME,(gameState).l
                beq.s   tunnel_halftime_camera_target
                cmpi.w  #ST_PLAYERS_GOING_TO_SHOWER,(gameState).l
                beq.s   tunnel_halftime_camera_target
                cmpi.w  #ST_RESULT_AFTER_THE_GAME,(gameState).l
                beq.s   results_screen_camera_target
center_camera_fulltime:
                move.w  #$150,d3
                move.w  #$1C1,d4
                clr.w   (cameraXVelocity).l
                clr.w   (cameraYVelocity).l
                bra.s   offset_and_clamp_to_view
results_screen_camera_target:
                move.w  #$150,d3
                move.w  #$81,d4
                clr.w   (cameraXVelocity).l
                clr.w   (cameraYVelocity).l
                bra.s   offset_and_clamp_to_view
tunnel_halftime_camera_target:
                move.w  #$24E,d3
                move.w  #$1C1,d4
                clr.w   (cameraXVelocity).l
                clr.w   (cameraYVelocity).l
                bra.s   offset_and_clamp_to_view
target_ball_position:
                move.w  $1E(a0),d3
                move.w  $22(a0),d4
offset_and_clamp_to_view:
                subi.w  #$A8,d3
                subi.w  #$88,d4
                add.w   (cameraXVelocity).l,d3
                add.w   (cameraYVelocity).l,d4
                cmp.w   d1,d3
                bge.s   apply_left_bound
                move.w  d1,d3
apply_left_bound:
                move.w  #$150,d0
                sub.w   d1,d0
                cmp.w   d0,d3
                blt.s   check_training_bounds
                move.w  d0,d3
check_training_bounds:
                tst.w   (trainingGame).l
                beq.s   normal_bounds_low_check
                cmpi.w  #$50,d4         ; 'P'
                bgt.s   training_upper_bound_applied
                move.w  #$50,d4         ; 'P'
training_upper_bound_applied:
                cmpi.w  #$220,d4
                blt.s   compute_delta_from_camera
                move.w  #$220,d4
                bra.s   compute_delta_from_camera
normal_bounds_low_check:
                cmpi.w  #$10,d4
                bgt.s   normal_bounds_high_check
                move.w  #$10,d4
normal_bounds_high_check:
                cmpi.w  #$250,d4
                blt.s   compute_delta_from_camera
                move.w  #$250,d4
compute_delta_from_camera:
                sub.w   (cameraX).l,d3
                sub.w   (cameraY).l,d4
                bne.s   scale_dx_to_fixed
                tst.w   d3
                beq.w   move_camera_ret
scale_dx_to_fixed:
                clr.l   d1
                tst.w   d3
                beq.s   scale_dy_to_fixed
                move.w  #$4000,d1
                asr.w   #2,d3
                muls.w  d3,d1
scale_dy_to_fixed:
                clr.l   d2
                tst.w   d4
                beq.s   clamp_delta_to_max_step
                move.w  #$4000,d2
                asr.w   #2,d4
                muls.w  d4,d2
clamp_delta_to_max_step:
                move.l  maxCameraMovement(pc),d3
                move.l  d3,d4
                neg.l   d4
                cmp.l   d3,d1
                blt.s   clamp_dx_min
                move.l  d3,d1
clamp_dx_min:
                cmp.l   d4,d1
                bgt.s   clamp_dx_max
                move.l  d4,d1
clamp_dx_max:
                cmp.l   d3,d2
                blt.s   clamp_dy_min
                move.l  d3,d2
clamp_dy_min:
                cmp.l   d4,d2
                bgt.s   clamp_dy_max
                move.l  d4,d2
clamp_dy_max:
                add.l   (cameraX).l,d1
                add.l   (cameraY).l,d2
                move.w  d1,(cameraX+2).l
                move.w  d2,(cameraY+2).l
                swap    d1
                swap    d2
                tst.w   d1
                bpl.s   clamp_x_to_screen
