; ===== ManageAdvertisements =====
; prototype: void __usercall ManageAdvertisements()
ManageAdvertisements:
                tst.w   (trainingGame).l
                bne.w   return_no_ads
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.w   reset_ads_for_gameplay_state
                cmpi.w  #84,(cameraY).l
                bgt.w   reset_ads_for_gameplay_state
                tst.w   (blockAdvertisements).l
                bne.w   return_no_ads
                tst.w   (goalCameraMode).l
                bne.w   return_no_ads
                tst.w   (advertIndex).l
                bmi.w   return_no_ads
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                beq.w   return_no_ads
                cmpi.w  #ST_RESULT_AFTER_THE_GAME,(gameState).l
                beq.w   return_no_ads
                tst.w   (advertIndex).l
                bne.s   route_to_selected_ad
                jsr     Rand
                cmpi.w  #128,d0         ; about 50% chance of showing adverts
                bhi.w   stop_ad_cycle
                tst.w   (advertInGameSprites+SPRITE_VISIBLE).l
                bne.s   ensure_sprites_allocated
                bsr.w   SetAdvertisementsVisible
ensure_sprites_allocated:
                jsr     Rand
                andi.w  #1,d0
                addq.w  #1,d0           ; D0 = 1..2
                cmpi.w  #326,(foulXCoordinate).l
                blt.s   commit_random_ad_choice
                addq.w  #1,d0           ; D0 = 2..3
                cmpi.w  #346,(foulXCoordinate).l
                bgt.s   commit_random_ad_choice
                jsr     Rand
                mulu.w  #3,d0
                lsr.w   #8,d0
                addq.w  #1,d0           ; D0 range: 1..3
commit_random_ad_choice:
                move.w  d0,(advertIndex).l ; just picked advert to animate at random
route_to_selected_ad:
                cmpi.w  #2,(advertIndex).l
                beq.s   select_ad2_setup
                cmpi.w  #3,(advertIndex).l
                beq.s   select_ad3_setup
                move.w  #SPR_ADVERT_1_PART_1,d7
                lea     (advert1Pointers).l,a6
                move.w  #112,d1         ; x coordinate of ad
                bra.s   update_slide_timer_or_tick
select_ad3_setup:
                move.w  #SPR_ADVERT_3_PART_1,d7
                lea     (advert3Pointers).l,a6
                move.w  #$1B0,d1
                bra.s   update_slide_timer_or_tick
select_ad2_setup:
                move.w  #SPR_ADVERT_2_PART_1,d7
                lea     (advert2Pointers).l,a6
                move.w  #$111,d1
update_slide_timer_or_tick:
                tst.w   (advertSlideTimer).l
                beq.s   frame_gate_and_line_advance
                subq.w  #1,(advertSlideTimer).l
                bra.s   build_ad_strip_loop_entry
frame_gate_and_line_advance:
                move.w  (frameCount).l,d0
                andi.w  #7,d0
                bne.s   build_ad_strip_loop_entry
                addq.w  #1,(currentAnimatedAdLine).l
                cmpi.w  #6,(currentAnimatedAdLine).l
                beq.s   start_slide_pause
                cmpi.w  #$D,(currentAnimatedAdLine).l
                beq.s   stop_ad_cycle
                bra.s   build_ad_strip_loop_entry
start_slide_pause:
                move.w  #$28,(advertSlideTimer).l ; '('
build_ad_strip_loop_entry:
                lea     (advertInGameSprites).l,a0
                movea.l (spriteGraphicsPtr).l,a2
                lsl.w   #2,d7
                lea     (a2,d7.w),a2
                lsr.w   #2,d7
                move.w  #7,d2
build_ad_strip_next_tile:
                movea.l (a2)+,a1
                move.w  d7,SPRITE_IMAGEINDEX(a0)
                move.w  d1,SPRITE_X(a0)
                move.w  #$5A,SPRITE_Y(a0) ; 'Z'
                clr.w   SPRITE_Z(a0)
                move.w  #6,SPRITEGRAPHICS_NLINES(a1)
