; ===== ResetTime =====
; prototype: void __usercall ResetTime()
ResetTime:
                clr.w   (gameSeconds).l
                clr.l   (gameTime).l
                clr.w   (secondsSwitchAccumulator).l
                move.w  #1,(copyTimeSprite).l
                lea     (currentTimeSprite).l,a0
                move.w  #SPR_8_MINS,SPRITE_IMAGEINDEX(a0)
                clr.w   (currentTimeSprite+SPRITE_VISIBLE).l
                rts

; ===== UpdateTime =====
; prototype: void __usercall UpdateTime()
UpdateTime:
                move.w  #31000,(timeVar).l
                tst.w   (timeVar).l
                beq.w   time_invisible
                bmi.w   make_time_invisible
                cmpi.w  #31000,(timeVar).l
                beq.s   loc_10B3BE      ; jump
                cmpi.w  #32000,(timeVar).l
                bne.w   loc_10B3DA      ; no jump
                move.w  #30000,(timeVar).l
                bra.s   loc_10B3C6      ; never reached
loc_10B3BE:
                move.w  #150,(timeVar).l
loc_10B3C6:
                tst.w   (currentTimeSprite+SPRITE_VISIBLE).l
                bne.s   loc_10B3DA
                move.w  #1,(currentTimeSprite+SPRITE_VISIBLE).l
                bsr.w   InitDisplaySprites
loc_10B3DA:
                move.w  (lastFrameTicks).l,d0
                bra.w   time_invisible
                sub.w   d0,(timeVar).l
                bmi.s   make_time_invisible
                bne.w   not_end_of_second_extra
make_time_invisible:
                clr.w   (timeVar).l
                tst.w   (currentTimeSprite+SPRITE_VISIBLE).l
                beq.s   time_invisible
                clr.w   (currentTimeSprite+SPRITE_VISIBLE).l
                bsr.w   InitDisplaySprites
                bra.w   *+4
time_invisible:
                tst.w   (gameSeconds).l
                bmi.w   last_minute_in_progress
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.w   no_update_to_time
                tst.w   (playingPenalties).l
                bne.w   no_update_to_time
                move.w  (timeDelta).l,d0
                sub.w   d0,(secondsSwitchAccumulator).l
                bpl.w   no_update_to_time
                addi.w  #49,(secondsSwitchAccumulator).l ; increase time cycle
                addq.w  #1,(gameSeconds).l
                cmpi.w  #60,(gameSeconds).l
                bne.w   no_update_to_time
                clr.w   (gameSeconds).l
                addq.b  #1,(gameTime+3).l
                cmpi.b  #$A,(gameTime+3).l
                bne.s   check_game_end
                clr.b   (gameTime+3).l  ; increase time (minutes)
                addq.b  #1,(gameTime+2).l
                cmpi.b  #$A,(gameTime+2).l
                bne.s   check_game_end
                clr.b   (gameTime+2).l
                addq.b  #1,(gameTime+1).l
check_game_end:
                cmpi.l  #1,(gameTime).l
                bne.s   not_first_minute
                bsr.w   BumpPlayersLastPlayedHalfAtHalfStart ; first minute
not_first_minute:
                cmpi.l  #$406,(gameTime).l
                bne.s   not_minute_46
                bsr.w   BumpPlayersLastPlayedHalfAtHalfStart ; minute 46
not_minute_46:
                cmpi.l  #$405,(gameTime).l ; minute 45?
                bne.s   not_halftime
                tst.w   (gameSeconds).l
                bpl.w   last_cycle
                clr.w   (gameSeconds).l ; half time
                bsr.w   PlayEndGameWhistleSample
                jsr     EndFirstHalf
                bsr.w   BumpPlayersLastPlayedHalfAtHalfEnd
                bra.w   not_end_of_second_extra
not_halftime:
                cmpi.l  #$900,(gameTime).l ; minute 90
                bne.w   not_fulltime
                tst.w   (gameSeconds).l ; end of game
                bpl.w   last_cycle
                clr.w   (gameSeconds).l ; 90th minute
                bsr.w   PlayEndGameWhistleSample
                bsr.w   BumpPlayersLastPlayedHalfAtHalfEnd
                move.w  (statsTeam1Goals).l,(statsTeam1GoalsCopy).l
                move.w  (statsTeam2Goals).l,(statsTeam2GoalsCopy).l
                move.w  (team1TotalGoals).l,d0
                cmp.w   (team2TotalGoals).l,d0
                bne.w   not_draw
                tst.w   (secondLeg).l   ; tied
                beq.w   loc_10B53A
                cmpi.w  #1,(playing2ndGame).l
                beq.s   loc_10B552
loc_10B53A:
                tst.w   (extraTimeState).l
                bne.w   cseg_6FDAB
cseg_6FBFD:
                tst.w   (penaltiesState).l
                bne.w   cseg_6FDBE
                bra.w   cseg_6FD97
loc_10B552:
                move.w  (statsTeam2Goals).l,d0
                lsl.w   #1,d0
                add.w   (team2GoalsFirstLeg).l,d0
                move.w  (team1GoalsFirstLeg).l,d1
                lsl.w   #1,d1
                add.w   (statsTeam1Goals).l,d1
                cmp.w   d0,d1
                bne.w   cseg_6FD6C
                bra.s   loc_10B53A
not_fulltime:
                cmpi.l  #$10005,(gameTime).l ; minute 105
                bne.s   not_end_of_first_extra
                tst.w   (gameSeconds).l
                bpl.w   last_cycle
                clr.w   (gameSeconds).l ; end of extra time
                bsr.w   PlayEndGameWhistleSample
                jsr     EndFirstExtraTime
                bra.w   not_end_of_second_extra
not_end_of_first_extra:
                cmpi.l  #$10200,(gameTime).l ; minute 120
                bne.w   not_end_of_second_extra
                tst.w   (gameSeconds).l
                bpl.w   last_cycle
                clr.w   (gameSeconds).l ; end of second extra time
                bsr.w   PlayEndGameWhistleSample
                move.w  (team1TotalGoals).l,d0
                cmp.w   (team2TotalGoals).l,d0
                bne.s   not_draw
                tst.w   (secondLeg).l
                beq.w   cseg_6FBFD
                tst.w   (playing2ndGame).l
                beq.w   cseg_6FBFD
                move.w  (statsTeam2Goals).l,d0
                lsl.w   #1,d0
                add.w   (team2GoalsFirstLeg).l,d0
                move.w  (team1GoalsFirstLeg).l,d1
                lsl.w   #1,d1
                add.w   (statsTeam1Goals).l,d1
                cmp.w   d0,d1
                bne.s   cseg_6FD6C
                bra.w   cseg_6FBFD
cseg_6FD6C:
                cmp.w   d0,d1
                bhi.s   team1_wins
                bra.s   team2_wins
not_draw:
                bhi.s   team1_wins
team2_wins:
                move.l  #bottomTeamInGame,(winningTeamPtr).l
                bra.s   end_game
team1_wins:
                move.l  #topTeamInGame,(winningTeamPtr).l
                bra.s   end_game
cseg_6FD97:
                clr.l   (winningTeamPtr).l
end_game:
                jsr     EndOfGame
                bra.w   not_end_of_second_extra
cseg_6FDAB:
                move.w  #$FFFF,(extraTimeState).l
                jsr     StartFirstExtraTime
                bra.w   not_end_of_second_extra
cseg_6FDBE:
                move.w  #$FFFF,(penaltiesState).l
                bsr.w   StartPenalties
                bra.w   not_end_of_second_extra
last_cycle:
                move.w  #$FFFF,(gameSeconds).l
                move.w  #50,(endGameCounter).l
                bra.w   no_update_to_time
last_minute_in_progress:
                move.w  (lastFrameTicks).l,d0
                sub.w   d0,(endGameCounter).l
                bmi.w   check_game_end
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.s   last_cycle
                lea     (ballSprite).l,a1
                cmpi.w  #216,ballSprite+SPRITE_Y-ballSprite(a1) ; upper penalty area lower line
                bls.s   last_cycle
                cmpi.w  #682,$22(a1)    ; lower penalty area upper line
                bcc.s   last_cycle
                cmpi.w  #449,$22(a1)    ; center line
                bhi.s   loc_10B6B4
                cmpi.l  #bottomTeamData,(lastTeamPlayed).l
                beq.s   last_cycle
                bra.s   no_update_to_time
loc_10B6B4:
                cmpi.l  #topTeamData,(lastTeamPlayed).l
                beq.s   last_cycle
no_update_to_time:
                tst.w   (copyTimeSprite).l
                beq.w   set_time_sprite_x
not_end_of_second_extra:
                clr.w   d1              ; D1 - x offset, depends on number of digits
                clr.w   d2              ; D2 - y offset, always 0
                tst.b   (gameTime+1).l
                beq.s   first_digit_zero
                move.w  #SPR_INVITATION_TOURNAMENT,d3 ; D3 - sprite index, depending on number of digits
                move.w  #5,d1           ; one digit width, assume 1, no need to copy
                bra.s   time_two_digits
first_digit_zero:
                tst.b   (gameTime+2).l
                bne.s   loc_10B6EE
                move.w  #SPR_LITTLE_PLAYER_GENERIC,d3
                bra.s   copy_last_digit
loc_10B6EE:
                move.w  #SPR_PREMIERE_DIVISION_WINNER,d3
time_two_digits:
                move.b  (gameTime+2).l,d0
                ext.w   d0
                addi.w  #SPR_CUP_WINNER,d0
                movem.l d1-d3,-(sp)
                bsr.w   CopySprite
                movem.l (sp)+,d1-d3
                addq.w  #6,d1
copy_last_digit:
                move.b  (gameTime+3).l,d0
                ext.w   d0
                addi.w  #SPR_CUP_WINNER,d0
                movem.l d3,-(sp)
                bsr.w   CopySprite
                movem.l (sp)+,d3
                lea     (currentTimeSprite).l,a0
                move.w  d3,SPRITE_IMAGEINDEX(a0)
                move.w  d3,d0
                cmpi.w  #SPR_INVITATION_TOURNAMENT,d0
                bne.s   cseg_6FF81
                bsr.w   BlitSpritePlanar_Long_StridedDest
                bra.s   cseg_6FF86
cseg_6FF81:
                bsr.w   BlitSpritePlanar_Word_StridedDest
cseg_6FF86:
                clr.w   (copyTimeSprite).l
set_time_sprite_x:
                lea     (currentTimeSprite).l,a1
                move.w  (cameraX).l,SPRITE_X(a1)
                tst.b   (gameTime+1).l
                bne.s   loc_10B774
                tst.b   (gameTime+2).l
                bne.s   loc_10B76C
                addi.w  #$14,$1E(a1)
                bra.s   loc_10B77A
loc_10B76C:
                addi.w  #$14,$1E(a1)
                bra.s   loc_10B77A
loc_10B774:
                addi.w  #$14,$1E(a1)
loc_10B77A:
                move.w  (cameraY).l,$22(a1)
                addi.w  #$2721,$22(a1)
                cmpi.w  #4,(currentPlayerIndicatorPosition).l
                bne.s   loc_10B796
                addq.w  #8,$22(a1)
loc_10B796:
                move.w  #$2710,$26(a1)
                rts

; ===== BumpPlayersLastPlayedHalfAtHalfStart =====
; prototype: void __usercall BumpPlayersLastPlayedHalfAtHalfStart()
BumpPlayersLastPlayedHalfAtHalfStart:
                lea     (topTeamInGame).l,a0
                lea     (bottomTeamInGame).l,a1
                move.w  #10,d0
loc_10B7AE:
                bsr.s   BumpPlayerLastPlayedHalfAtHalfStart
                exg     a0,a1
                bsr.s   BumpPlayerLastPlayedHalfAtHalfStart
                exg     a0,a1
                lea     PLAYERINFO_SIZE+PLAYERINFO_SKIP(a0),a0
                lea     PLAYERINFO_SIZE+PLAYERINFO_SKIP(a1),a1
                dbf     d0,loc_10B7AE
                rts

; ===== BumpPlayerLastPlayedHalfAtHalfStart =====
; prototype: void __usercall BumpPlayerLastPlayedHalfAtHalfStart(struct PlayerInfoHeader *player@<a0>)
; in:
;      A0 -> in-game team player + header
BumpPlayerLastPlayedHalfAtHalfStart:
                cmpi.b  #2,PLAYERINFOHEADER_CARDS(a0)
                bcc.s   locret_10B7DA
                cmpi.b  #2,PLAYERINFOHEADER_HALFPLAYED(a0)
                beq.s   locret_10B7DA
                move.b  #1,PLAYERINFOHEADER_HALFPLAYED(a0)
locret_10B7DA:
                rts

; ===== BumpPlayersLastPlayedHalfAtHalfEnd =====
; prototype: char * BumpPlayersLastPlayedHalfAtHalfEnd()
BumpPlayersLastPlayedHalfAtHalfEnd:
                lea     (topTeamInGame).l,a0
                lea     (bottomTeamInGame).l,a1
                move.w  #10,d0
loc_10B7EC:
                bsr.s   BumpPlayerLastPlayedHalfAtHalfEnd
                exg     a0,a1
                bsr.s   BumpPlayerLastPlayedHalfAtHalfEnd
                exg     a0,a1
                lea     PLAYERINFO_SIZE+PLAYERINFO_SKIP(a0),a0
                lea     PLAYERINFO_SIZE+PLAYERINFO_SKIP(a1),a1
                dbf     d0,loc_10B7EC
                rts

; ===== BumpPlayerLastPlayedHalfAtHalfEnd =====
; prototype: void __usercall BumpPlayerLastPlayedHalfAtHalfEnd(struct PlayerInfoHeader *player@<a0>)
; in:
;      A0 -> player + header (in-game)
BumpPlayerLastPlayedHalfAtHalfEnd:
                cmpi.b  #2,PLAYERINFOHEADER_CARDS(a0)
                bcc.s   locret_10B818
                cmpi.b  #1,PLAYERINFOHEADER_HALFPLAYED(a0)
                bne.s   locret_10B818
                move.b  #2,PLAYERINFOHEADER_HALFPLAYED(a0)
locret_10B818:
                rts
copyTimeSprite:
                dc.w $0000              ; 1 Only right before the game starts
                                        ; if true, in UpdateTime fill time placeholder sprite
                                        ; after that, set this to zero
secondsSwitchAccumulator:
                dc.w $0000              ; Time left until game time will be increased
                                        ; (when timeDelta elapses, game seconds increase)
gameSeconds:
                dc.w $0000              ; Number of seconds elapsed since last minute change
                                        ; scaled as needed, so seconds in a 3 min. game go faster than in a 10 min. game
                                        ; -1 is special value when there is an overflow and we're switching to the next minute
                                        ; this allows prolonging last minute of the game
; unsigned __int8[4]
gameTime:
                dc.b $00,$00,$00,$00    ; In BCD format:
                                        ; +0 = not used
                                        ; +1 = first digit
                                        ; +2 = second digit
                                        ; +3 = third digit (single minutes)
                                        ; for example 118 would be 0x08010100
                                        ; (in memory 0x00010108)
timeDelta:
