                dc.w $0A80              ; =10.5
kNormalKickDeltaZ:
                dc.l $00016000          ; =1.375
kNormalKickBallSpeed:
                dc.w $0A00              ; =10.0
kSpinMultiplierFactor:
                dc.w 5,4,3,2,2,2,2,1    ; Inverse proportional to time elapsed since pass/kick
                dc.w 1,1
; __int8[64]
kKickSpinFactor:
                dc.b -1,-32,0,0,0,32,0,0,0,0,-1,-23,0,23,0,0 ; Apply curved trajectory to kick (ball spin)
                dc.b 0,0,-1,-32,0,0,0,32,0,23,0,0,0,0,0,23
                dc.b 0,32,0,0,-1,-32,0,0,0,0,0,23,-1,-23,0,0
                dc.b 0,0,0,32,0,0,-1,-32,-1,-23,0,0,0,0,-1,-23
                                        ; elements of array are delta x and delta y values for corresponding
                                        ; direction and left/right spin
                                        ; formula: direction * 4 + 2 * right spin = index of delta x, delta y is next
                                        ; (right spin = 1 or 0)
                                        ; Format is the same as table below.
; __int16[32]
kPassingSpinFactor:
                ; __int16[32]
                dc.w -16,0,16,0,0,-11,11,0 ; Applying curved trajectory to the ball during passes
                dc.w 0,-16,0,16,11,0,0,11
                dc.w 16,0,-16,0,0,11,-11,0
                dc.w 0,16,0,-16,-11,0,0,-11
                                        ; holds delta x and y values, and it's indexed in following way:
                                        ; 0 - left spin X  \
                                        ; 1 - left spin Y   |
                                        ; 2 - right spin X  +-> ball direction 0
                                        ; 3 - right spin Y /
                                        ; 4 - left spin X  \
                                        ; 5 - left spin Y   |
                                        ; 6 - right spin X  +-> ball direction 1
                                        ; 7 - right spin Y /
; unsigned __int16[2]
kRefereeSpeed:
                ; unsigned __int16[2]
                dc.w $0400,$0500
kInjuryForeverSpeed:
                dc.w $0300
main:
                jsr     AssetLoaderResetState
                clr.w   (assetLoaderAltPathReady).l
                jsr     InitDisplayAndCopper
                jsr     AssetSys_InitDiskImageSources
                jsr     InitSkinAndDefaultPointers
                move.l  #(menuPalette),a0
                jsr     WriteCopperPalette
                ;lea     (kTitleLogoColors).l,a0
                ;lea     (titleLogoPalette).l,a1
                ;jsr     BuildPaletteFromColors
                ;lea     (kTitleScreenColors).l,a0
                ;lea     (titleScreenPalette).l,a1
                ;jsr     BuildPaletteFromColors
                ;lea     (kTitleTextColors).l,a0
                ;lea     (titleTextPalette).l,a1
                ;jsr     BuildPaletteFromColors
                move.w  #1,(bootTemp0).l
                clr.w   (bootTemp1).l
                clr.w   (bootTemp2).l
                clr.w   (bootTemp3).l
                clr.w   (bootTemp4).l
                clr.w   (bootTemp5).l
                clr.w   (bootTemp6).l
                move.w  #1,(loaderModeFlag).l
                jsr     ShowLoaderIntroSequence
                jsr     AssetLoaderInitAltPathAndBanks
                jsr     AssetPrecacheCore
                jsr     InstallAndInitLoaderBootstrap
                jsr     FadeOutToBlack
                clr.w   (loaderModeFlag).l
                jsr     DoubleBufferSwapSequence
                clr.w   (paletteIndex).l
                lea     (aGrafsOlddisk1R).l,a0 ; "grafs/olddisk1.raw"
                jsr     LoadOverlayToFrontbuffer
                jsr     BlitterCopyPanelToScreen2
                jsr     WaitForVSync
                lea     (aGrafsDisk22Raw).l,a0 ; "grafs/disk22.raw"
                jsr     LoadOverlayToFrontbuffer
                clr.w   (paletteIndex).l
                jsr     FadeIn
poll_loader_op3_with_delays:
                movem.l d0-d1,-(sp)
                move.w  #FPS_50HZ,d1
delay_0x32_ticks_outer:
                move.w  (currentGameTick).l,d0
wait_for_next_tick_inner:
                cmp.w   (currentGameTick).l,d0
                beq.s   wait_for_next_tick_inner
                dbf     d1,delay_0x32_ticks_outer
                movem.l (sp)+,d0-d1
                jsr     AssetSvcLoaderOp3
                bne.s   poll_loader_op3_with_delays
                jsr     InstallAndRunLoaderBootstrap_Op3
                jsr     FadeOutToBlack
                jsr     AssetSvcLoaderOp2
                beq.s   build_intro_menu_assets
                jsr     BlitterCopyPanelToScreen2
                jsr     WaitForVSync
                clr.w   (paletteIndex).l
                jsr     FadeIn
poll_loader_op2_with_delays:
                movem.l d0-d1,-(sp)
                move.w  #FPS_50HZ,d1
delay_0x32_ticks_outer2:
                move.w  (currentGameTick).l,d0
wait_for_next_tick_inner2:
                cmp.w   (currentGameTick).l,d0
                beq.s   wait_for_next_tick_inner2
                dbf     d1,delay_0x32_ticks_outer2
                movem.l (sp)+,d0-d1
                jsr     AssetSvcLoaderOp2
                bne.s   poll_loader_op2_with_delays
                jsr     FadeOutToBlack
build_intro_menu_assets:
                lea     (introMenuImageScript).l,a0
                lea     (imageCmdWorkBuf).l,a3
                jsr     ProcessImageCommandStream
                move.l  (imageStreamCursor).l,(menuImageStreamBaseEnd).l
                jsr     AssetPrecacheMenuPack
                move.w  #1,(assetLoaderAltPathReady).l
                clr.w   (hilNumGoals).l
                jmp     FrontEndMainLoop

