                jsr SetPitchTypeAndNumber(pc)
                bsr.w   InitGameSaveTeams
                jsr WriteCopperPitchPalette

; ===== GameLoop =====
; prototype: void __usercall GameLoop()
; in:
;      A5 -> left team in-game struct
;      A6 -> right team in-game struct
GameLoop:
                clr.w   (gameCanceled).l
                clr.w   (instantReplayFlag).l
                clr.w   (saveHighlightScene).l
                clr.w   (fadeAndSaveHighlightScene).l
                clr.w   (spaceReplayTimer).l
                move.w  #168,d1
                move.w  #313,d2
                tst.w   (trainingGame).l
                bne.s   pre_frame_init
                jsr     Rand
                btst    #0,d0
                beq.s   set_small_scroll
                move.w  #592,d2
                bra.s   reset_base_scroll
set_small_scroll:
                move.w  #16,d2
reset_base_scroll:
                move.w  #168,d1
pre_frame_init:
                bsr.w   ReplayUpdateCameraAndSwapBuffers
                jsr     UpdatePlanePtrsAndBlitParams
                jsr     nullsub_2
                jsr     ReadTimerDelta
poll_keys_until_clear:
                jsr     GetKey
                tst.w   (currentKey).l
                bne.s   poll_keys_until_clear
                bra.w   wait_for_vblank_sync
vblank_return_dispatch:
                bsr.w   ReadTimerDelta
pause_spinloop_entry:
                tst.w   (paused).l
                beq.w   handle_user_stats
                movem.l d0-d1,-(sp)
                move.w  #0,d1
pause_wait_one_tick:
                move.w  (currentTick).l,d0
pause_wait_for_tick_change:
                cmp.w   (currentTick).l,d0
                beq.s   pause_wait_for_tick_change
                dbf     d1,pause_wait_one_tick
                movem.l (sp)+,d0-d1
                jsr     GetKey
                move.w  (currentKey).l,d0
                bsr.w   MainKeysCheck
                move.w  (currentKey).l,d0
                jsr     nullsub_10
                jsr PlayEnqueuedSamples(pc)
                jsr nullsub_5(pc)
                jsr     nullsub_4
                bra.s   pause_spinloop_entry
handle_user_stats:
                tst.w   (showingUserStats).l
                beq.s   frame_counters_update
                bsr.w   KeepStatisticsOnScreen
frame_counters_update:
                addq.w  #1,(frameCount).l
                tst.w   (spaceReplayTimer).l
                beq.s   panel_update_block
                subq.w  #1,(spaceReplayTimer).l
panel_update_block:
                jsr     ProcessSpriteBlitQueue
                tst.w   (subsWriteOnly).l
                beq.s   read_inputs_and_dispatch
                jsr     BlitterCopyPanelToScreen
                subq.w  #1,(subsWriteOnly).l
read_inputs_and_dispatch:
                jsr     GetKey
                move.w  (currentKey).l,d0
                bsr.w   MainKeysCheck
                move.w  (currentKey).l,d0
                jsr     nullsub_10
                jsr     nullsub_9
                tst.w   (playGame).l
                beq.w   end_of_match_flow
                tst.w   (fadeState).l
                bne.s   handle_active_replay
                cmpi.w  #$3E7,(fadeInitFlag).l
                bne.s   handle_active_replay
                move.w  #$FFFF,(fadeInitFlag).l
handle_active_replay:
                tst.w   (goIntoHighlightsLoop).l
                beq.s   handle_replay_state_change
                jsr     FadeOutToBlack
                bsr.w   PlayHighlightsLoop
                bra.w   wait_for_vblank_sync
handle_replay_state_change:
                tst.w   (replayState).l
                beq.s   run_gameplay_update
                jsr     FadeOutToBlack
                bsr.w   PlayInstantReplayLoop
                bra.w   wait_for_vblank_sync
run_gameplay_update:
                bsr.w   MoveCamera
                jsr     ScrollToCurrent
                move.w  #$FFFF,d0
                move.w  (cameraX).l,d4
                move.w  (cameraY).l,d5
                bsr.w   SaveCoordinatesForHighlights
                jsr PlayEnqueuedSamples(pc)
                bsr.w   UpdateTime
                bsr.w   nullsub_8
                bsr.w   UpdateAndApplyTeamControls
                bsr.w   UpdateBall
                bsr.w   MovePlayers
                bsr.w   UpdateReferee
                bsr.w   InjuryUpdateTickGuard
                bsr.w   UpdateCornerFlagSprite
                bsr.w   SpinBig_S_Sprite
                bsr.w   ManageAdvertisements
                bsr.w   DoGoalkeeperSprites
                bsr.w   UpdateControlledPlayerNumbers
                bsr.w   MarkPlayer
                bsr.w   SetCurrentPlayerName
                bsr.w   UpdateBookedPlayerNumberSprite
                bsr.w   ShowResult
                jsr     DrawAnimatedPatterns
                jsr     DrawSprites
                bsr.w   DrawBenchAndSubsMenu
                bsr.w   BenchCheckControls
                jsr     UpdateAndDrawStatistics

                tst.w   g_quitToDos
                bne.w   cleanup_and_return

                move.w  #$FFFE,d0
                bsr.w   SaveCoordinatesForHighlights
                tst.w   (saveHighlightScene).l
                beq.s   handle_fade_and_save_hilite
                bsr.w   SaveHighlightScene
                clr.w   (saveHighlightScene).l
handle_fade_and_save_hilite:
                tst.w   (fadeAndSaveHighlightScene).l
                beq.s   handle_instant_replay_request
                bsr.w   FadeAndSaveHighlightScene
                clr.w   (fadeAndSaveHighlightScene).l
handle_instant_replay_request:
                tst.w   (instantReplayFlag).l
                beq.s   wait_for_vblank_sync
                bsr.w   HandleInstantReplayStateSwitch
                clr.w   (instantReplayFlag).l
                clr.w   (goalCameraMode).l
wait_for_vblank_sync:
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_for_vblank_flag_clear:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_for_vblank_flag_clear
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  (irqCookieObfuscated).l,d0
                eori.l  #$CFD1F9BD,d0
                cmpi.l  #$165A,d0
                bne.w   swap_to_bottom_team_goalkeeper+4
                move.w  #1,(waitingInterrupt).l
                jsr nullsub_5(pc)
                jsr     nullsub_4
wait_for_interrupt_clear:
                tst.w   (waitingInterrupt).l
                bne.s   wait_for_interrupt_clear
                bra.w   vblank_return_dispatch
end_of_match_flow:
                jsr     FadeOutToBlack
                jsr     nullsub_3
                jsr SetHilFileHeader(pc)
                jsr AudioFadeCrowdDownThenPulseMusic(pc)
                jsr ClearAudioActiveFlag(pc)
                tst.w   (isGameFriendly).l
                beq.s   cleanup_and_return
                tst.w   (trainingGame).l
                bne.s   cleanup_and_return
                bsr.w   ReplayExitMenuAfterFriendly
                tst.w   (replaySelected).l
                beq.w   cleanup_and_return
                move.w  #4,(team1NumAllowedInjuries).l
                move.w  #4,(team2NumAllowedInjuries).l
                move.w  #1,(playGame).l
                jsr EnsureSfxLoadedAndStart(pc)
                jsr SetPitchTypeAndNumber(pc)
                bsr.w   InitGameRestoreTeams
                bra.w   GameLoop
cleanup_and_return:
                jsr StopAudioAndClearFlags(pc)
                rts

; ===== KeepStatisticsOnScreen =====
; prototype: void __usercall KeepStatisticsOnScreen()
KeepStatisticsOnScreen:
                movem.l d0-d1,-(sp)
                move.w  #0,d1
wait_for_next_tick:
                move.w  (currentTick).l,d0
spin_until_tick_changes:
                cmp.w   (currentTick).l,d0
                beq.s   spin_until_tick_changes
                dbf     d1,wait_for_next_tick
                movem.l (sp)+,d0-d1
                jsr     GetKey
                move.w  (currentKey).l,d0
                bsr.w   MainKeysCheck
                move.w  (currentKey).l,d0
                jsr     nullsub_10
                jsr PlayEnqueuedSamples(pc)
                jsr nullsub_5(pc)
                jsr     nullsub_4
                jsr     UpdateAndDrawStatistics
                tst.w   (showingUserStats).l
                bne.s   KeepStatisticsOnScreen
                rts

; ===== ViewHighLightsMain =====
; prototype: void __usercall ViewHighLightsMain(void *leftTeam@<a5>, void *rightTeam@<a6>)
; in:
;      A5 -> left team in-game
;      A6 -> right team in-game
ViewHighLightsMain:
                move.w  #1,(playHighlightFlag).l
                bsr.w   CopyTeamsAndHeader
                bsr.w   InitGameSaveTeams
                move.w  #168,d1
                move.w  #313,d2
                bsr.w   ReplayUpdateCameraAndSwapBuffers
                jsr     UpdatePlanePtrsAndBlitParams
                jsr     ReadTimerDelta
wait_for_no_key_pressed:
                jsr     GetKey
                tst.w   (currentKey).l
                bne.s   wait_for_no_key_pressed
                jsr SaveHighlightsPointers(pc)
                bra.w   sync_to_vblank_and_request_irq
frame_loop:
                bsr.w   ReadTimerDelta
                addq.w  #1,(frameCount).l
                jsr     ProcessSpriteBlitQueue
                jsr     GetKey
                move.w  (currentKey).l,d0
                bsr.w   MainKeysCheck
                jsr     nullsub_10
                jsr     nullsub_9
                tst.w   (playHighlightFlag).l
                beq.w   fade_out_and_exit
                tst.w   (goIntoHighlightsLoop).l
                beq.s   sync_to_vblank_and_request_irq
                bsr.w   PlayHighlightsLoop
                clr.w   (playHighlightFlag).l
                bra.w   *+4
sync_to_vblank_and_request_irq:
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
_10ECB6_wait_blitter_idle:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   _10ECB6_wait_blitter_idle
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  (irqCookieObfuscated).l,d0
                eori.l  #$CFD1F96B,d0
                cmpi.l  #$168C,d0
                bne.w   select_team_order_for_stats+4
                move.w  #1,(waitingInterrupt).l
wait_irq_ack_clear:
                tst.w   (waitingInterrupt).l
                bne.s   wait_irq_ack_clear
                bra.w   frame_loop
fade_out_and_exit:
                jsr     FadeOutToBlack
                rts

; ===== PlayInstantReplayLoop =====
; prototype: void __usercall PlayInstantReplayLoop()
; Plays an instant replay when player presses 'R' during the game.
; Doesn't return until it's either played fully or aborted.
PlayInstantReplayLoop:
                bsr.w   ReadTimerDelta
_10ECFE_paused_poll_loop:
                tst.w   (paused).l
                beq.s   _10ED4E_input_and_update_block
                movem.l d0-d1,-(sp)
                move.w  #0,d1
_10ED0E_paused_spin_wait_tick_start:
                move.w  (currentTick).l,d0
_10ED14_paused_spin_wait_tick_change:
                cmp.w   (currentTick).l,d0
                beq.s   _10ED14_paused_spin_wait_tick_change
                dbf     d1,_10ED0E_paused_spin_wait_tick_start
                movem.l (sp)+,d0-d1
                jsr     GetKey
                tst.w   (fadeState).l
                beq.s   _10ED4E_input_and_update_block
                move.w  (currentKey).l,d0
                bsr.w   MainKeysCheck
                jsr PlayEnqueuedSamples(pc)
                jsr     nullsub_5
                jsr     nullsub_4
                bra.s   _10ECFE_paused_poll_loop
_10ED4E_input_and_update_block:
                jsr     ProcessSpriteBlitQueue
                jsr     GetKey
                move.w  (currentKey).l,d0
                tst.w   (fadeState).l
                beq.s   check_replay_continue
                bsr.w   MainKeysCheck
                jsr     nullsub_10
                jsr     nullsub_9
check_replay_continue:
                tst.w   (replayState).l
                beq.w   _10EEBA_return
                jsr PlayEnqueuedSamples(pc)
                tst.w   (fadeState).l
                beq.s   draw_replay_frame_and_handle_fade
                tst.w   (userRequestedReplay).l
                beq.s   loc_10EDB6
multiplayer_read_joys:
                jsr     Player1StatusProc ; Returns
                tst.b   (pl1Fire).l
                bne.w   abort_replay_and_block_fire
                jsr     Player2StatusProc ; Returns
                tst.b   (pl2Fire).l
                bne.s   abort_replay_and_block_fire
                bra.s   draw_replay_frame_and_handle_fade
loc_10EDB6:
                movea.l (teamScoredDataPtr).l,a0
                cmpa.l  #0,a0
                beq.s   draw_replay_frame_and_handle_fade
                cmpi.w  #1,TEAMGENERALINFO_PLAYERNUMBER(a0)
                beq.s   single_read_joy1
                cmpi.w  #2,TEAMGENERALINFO_PLAYERNUMBER(a0)
                beq.s   single_read_joy0
                cmpi.w  #1,TEAMGENERALINFO_PLAYERCOACHNUMBER(a0)
                beq.s   single_read_joy1
                cmpi.w  #2,TEAMGENERALINFO_PLAYERCOACHNUMBER(a0)
                beq.s   single_read_joy0
                bra.s   multiplayer_read_joys
single_read_joy0:
                jsr     Player2StatusProc ; Returns
                tst.b   (pl2Fire).l
                bne.s   abort_replay_and_block_fire
                bra.s   draw_replay_frame_and_handle_fade
single_read_joy1:
                jsr     Player1StatusProc ; Returns
                tst.b   (pl1Fire).l
                bne.s   abort_replay_and_block_fire
draw_replay_frame_and_handle_fade:
                bsr.w   DrawReplayFrame
                tst.w   (fadeState).l
                bne.s   check_replay_state_then_route
                cmpi.w  #$3E7,(fadeInitFlag).l
                bne.s   check_replay_state_then_route
                move.w  #$FFFF,(fadeInitFlag).l
check_replay_state_then_route:
                tst.w   (replayState).l
                beq.s   fade_out_and_cleanup_then_return
                bra.w   handle_postframe_flags
abort_replay_and_block_fire:
                move.w  #1,(fireBlocked).l
                clr.w   (replayState).l
fade_out_and_cleanup_then_return:
                jsr     FadeOutToBlack
                jsr RestoreCameraPosition(pc)
                bra.w   _10EEBA_return
handle_postframe_flags:
                tst.w   (fadeAndSaveHighlightScene).l
                beq.s   handle_instant_replay_switch
                bsr.w   FadeAndSaveHighlightScene
                clr.w   (fadeAndSaveHighlightScene).l
handle_instant_replay_switch:
                tst.w   (instantReplayFlag).l
                beq.s   vblank_sync_and_irq_handshake
                bsr.w   HandleInstantReplayStateSwitch
                clr.w   (instantReplayFlag).l
vblank_sync_and_irq_handshake:
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
_10EE7E_wait_blitter_idle:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   _10EE7E_wait_blitter_idle
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  (irqCookieObfuscated).l,d0
                eori.l  #$CFD1F959,d0
                cmpi.l  #$16BE,d0
                bne.w   draw_fouls_conceded_team2
                move.w  #1,(waitingInterrupt).l
_10EEAE_wait_irq_cleared:
                tst.w   (waitingInterrupt).l
                bne.s   _10EEAE_wait_irq_cleared
                bra.w   PlayInstantReplayLoop
_10EEBA_return:
                rts

; ===== PlayHighlightsLoop =====
; prototype: void __usercall PlayHighlightsLoop()
; Doesn't return until the playback is done, either by playing all scenes
; or user aborting by pressing fire.
PlayHighlightsLoop:
                bsr.w   ReadTimerDelta
_10EEC0_paused_poll_loop:
                tst.w   (paused).l
                beq.w   _10EEFE_input_and_update_block
                movem.l d0-d1,-(sp)
                move.w  #0,d1
_10EED2_paused_spin_wait_tick_start:
                move.w  (currentTick).l,d0
_10EED8_paused_spin_wait_tick_change:
                cmp.w   (currentTick).l,d0
                beq.s   _10EED8_paused_spin_wait_tick_change
                dbf     d1,_10EED2_paused_spin_wait_tick_start
                movem.l (sp)+,d0-d1
                jsr     GetKey
                move.w  (currentKey).l,d0
                bsr.w   MainKeysCheck
                jsr PlayEnqueuedSamples(pc)
                bra.s   _10EEC0_paused_poll_loop
_10EEFE_input_and_update_block:
                jsr     ProcessSpriteBlitQueue
                jsr     GetKey
                move.w  (currentKey).l,d0
                bsr.w   MainKeysCheck
                jsr     nullsub_10
                jsr     nullsub_9
                tst.w   (replayState).l
                beq.w   advance_to_next_highlight
                jsr PlayEnqueuedSamples(pc)
                tst.w   (fadeState).l
                beq.s   draw_replay_and_handle_fade
                jsr     Player1StatusProc ; Returns
                tst.b   (pl1Fire).l
                bne.s   abort_replay_on_fire
                jsr     Player2StatusProc ; Returns
                tst.b   (pl2Fire).l
                bne.s   abort_replay_on_fire
draw_replay_and_handle_fade:
                bsr.w   DrawReplayFrame
                tst.w   (fadeState).l
                bne.s   post_draw_replay_state_check
                cmpi.w  #$3E7,(fadeInitFlag).l
                bne.s   post_draw_replay_state_check
                move.w  #$FFFF,(fadeInitFlag).l
post_draw_replay_state_check:
                tst.w   (replayState).l
                beq.s   end_of_replay_cleanup
                bra.w   vblank_irq_wait_gate
abort_replay_on_fire:
                move.w  #1,(fireBlocked).l
                clr.w   (replayState).l
                jsr     FadeOutToBlack
                jsr RestoreCameraPosition(pc)
                bra.w   stop_replay_and_return
end_of_replay_cleanup:
                jsr     FadeOutToBlack
                jsr RestoreCameraPosition(pc)
advance_to_next_highlight:
                addq.w  #1,(hilSceneNumber).l
                move.w  numScenesInHilFile(pc),d0
                cmp.w   hilSceneNumber(pc),d0
                beq.s   stop_replay_and_return
                move.w  hilSceneNumber(pc),d0
                mulu.w  #19000,d0
                addi.l  #hilStartOfGoalsBuffer,d0
                move.l  d0,(goalBasePtr).l
                move.l  d0,(currentHilPtr).l
                subq.l  #4,(currentHilPtr).l
                addi.l  #19000,d0
                move.l  d0,(nextGoalPtr).l
                jsr HandleInstantReplayStateSwitch(pc)
                bra.s   vblank_irq_wait_gate
stop_replay_and_return:
                jsr RestoreHighlightPointers(pc)
                rts
vblank_irq_wait_gate:
                move.w  #DMACON_BLT_ON,(DMACON).l
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
wait_for_vblank_clear:
                btst    #DMACONR_BLTBUSY_BIT,(DMACONR).l
                bne.s   wait_for_vblank_clear
                move.w  #DMACON_BLT_OFF,(DMACON).l
                move.l  (irqCookieObfuscated).l,d0
                eori.l  #$CFD1F917,d0
                cmpi.l  #$16F0,d0
                bne.w   goalScoredChances+4
                move.w  #1,(waitingInterrupt).l
_10F02A_wait_irq_cleared:
                tst.w   (waitingInterrupt).l
                bne.s   _10F02A_wait_irq_cleared
                bra.w   PlayHighlightsLoop

; ===== ReadTimerDelta =====
