; ===== SaveRand2State =====
; prototype: void __usercall SaveRand2State()
SaveRand2State:
                move.l  a0,-(sp)
                movea.l (savedRandStatePtr).l,a0
                move.b  (seed2).l,(a0)+
                move.b  (randXorIndex2).l,(a0)+
                move.b  (randXorKey2).l,(a0)+
                move.l  a0,(savedRandStatePtr).l
                cmpa.l  #kRandomTable,a0
                bcs.s   loc_10F230
                move.w  #$9793,(panicReasonCode).l
                jsr     PanicHaltLoop
loc_10F230:
                movea.l (sp)+,a0
                rts

; ===== RestoreRand2State =====
; prototype: void __usercall RestoreRand2State()
RestoreRand2State:
                move.l  a0,-(sp)
                movea.l (savedRandStatePtr).l,a0
                move.b  -(a0),(randXorKey2).l
                move.b  -(a0),(randXorIndex2).l
                move.b  -(a0),(seed2).l
                move.l  a0,(savedRandStatePtr).l
                movea.l (sp)+,a0
                rts

; ===== Randomize2 =====
; prototype: void __usercall Randomize2(unsigned __int16 seed@<d0>)
Randomize2:
                movem.l d0-d1/a0,-(sp)
                move.w  (randomSeed).l,d1
                eor.w   d1,d0
                move.w  d0,(seed2).l
                lea     (kRandomTable).l,a0
                move.b  (randXorIndex2).l,d0
                andi.w  #$FF,d0
                move.b  (a0,d0.w),(randXorKey2).l
                movem.l (sp)+,d0-d1/a0
                rts

; ===== GetRandomWord =====
; prototype: unsigned __int16 __usercall GetRandomWord@<d0>()
; out:
;     D0 - random 16-bit int
GetRandomWord:
                move.w  d1,-(sp)
                jsr     Rand2
                move.w  d0,d1
                jsr     Rand2
                lsl.w   #8,d0
                or.w    d1,d0
                move.w  (sp)+,d1
                rts

; ===== Rand2 =====
; prototype: unsigned __int16 __usercall Rand2@<d0>()
; out:
;     D0 - random number 0..255
Rand2:
                movem.l d1/a0,-(sp)
                lea     (kRandomTable).l,a0
                move.b  (seed2).l,d0
                andi.w  #$FF,d0
                bne.s   loc_10F2CE
                addq.b  #1,(randXorIndex2).l
                move.b  (randXorIndex2).l,d1
                andi.w  #$FF,d1
                move.b  (a0,d1.w),(randXorKey2).l
loc_10F2CE:
                move.b  (a0,d0.w),d0
                move.b  (randXorKey2).l,d1
                eor.b   d1,d0
                addq.b  #1,(seed2).l
                movem.l (sp)+,d1/a0
                rts
