; ===== Rand =====
; prototype: unsigned __int16 __usercall Rand@<d0>()
; out:
;      D0 - random number 0-255
;      
; This one seems to be used during the game itself.
Rand:
                movem.l d1/a0,-(sp)
                lea     kRandomTable(pc),a0
                move.b  (seed).l,d0
                andi.w  #$FF,d0
                bne.s   loc_10F426
                addq.b  #1,(randXorIndex).l
                move.b  (randXorIndex).l,d1
                andi.w  #$FF,d1
                move.b  (a0,d1.w),(randXorKey).l
loc_10F426:
                move.b  (a0,d0.w),d0
                move.b  (randXorKey).l,d1
                eor.b   d1,d0
                addq.b  #1,(seed).l
                movem.l (sp)+,d1/a0
                rts
seed:
                dc.b $00
randXorIndex:
                dc.b $00
randXorKey:
                dc.b $00
pad_10F441:
                dc.b $00

; ===== MainKeysCheck =====
; prototype: void __usercall MainKeysCheck(unsigned __int16 key@<d0>)
; Checks keys in game. This is where the pause gets set.
; 
; destroys: eax, esi
; + ecx, edx while in multiplayer game
; [ebp safe]
MainKeysCheck:
                tst.w   d0
                beq.w   _10F770_exit_rts
                tst.w   (paused).l
                bne.w   key_p_toggle_pause
                tst.w   (showingUserStats).l
                bne.w   key_s_close_statistics
                tst.w   (playHighlightFlag).l
                bne.w   key_p_toggle_pause
                tst.w   (normalReplayRunning).l
                bne.w   key_p_toggle_pause
                cmpi.w  #$52,d0         ; 'R'
                bne.w   key_h_normal_replay_after_match
                tst.w   (fadeState).l
                beq.w   _10F770_exit_rts
                tst.w   (inSubstitutesMenu).l
                bne.w   _10F770_exit_rts
                cmpi.w  #ST_RESULT_AFTER_THE_GAME,(gameState).l
                beq.w   _10F770_exit_rts
                cmpi.w  #ST_RESULT_ON_HALFTIME,(gameState).l
                beq.w   _10F770_exit_rts
                move.w  #1,(instantReplayFlag).l
                tst.w   (replayState).l
                bne.w   _10F770_exit_rts
                move.w  #1,(userRequestedReplay).l
                bra.w   _10F770_exit_rts
key_h_normal_replay_after_match:
                cmpi.w  #$48,d0         ; 'H'
                bne.w   key_88_toggle_big_s_spin
                tst.w   (normalReplayRunning).l
                bne.w   _10F770_exit_rts
                tst.w   (replayState).l
