; ===== UpdatePlayerSpeed =====
; prototype: void __usercall UpdatePlayerSpeed(Sprite *player@<a1>, TeamGeneralInfo *team@<a6>)
; in:
;      A1 -> player sprite
;      A6 -> player team (general)
UpdatePlayerSpeed:
                cmpi.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a1)
                bne.w   _110E76_exit_rts
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.s   skip_goalkeeper_speed_check
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a1)
                bne.s   skip_goalkeeper_speed_check
                cmpa.l  TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a1
                bne.w   _110E76_exit_rts
skip_goalkeeper_speed_check:
                bsr.w   GetPlayerPointerFromShirtNumber
                move.b  PLAYERINFOHEADER_SPEED(a4),d0
                ext.w   d0
                lsl.w   #1,d0
                lea     kPlayerSpeedsGameInProgress(pc),a0
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.s   convert_player_speed
                lea     kPlayerSpeedsGameStopped(pc),a0
convert_player_speed:
                move.w  (a0,d0.w),SPRITE_SPEED(a1)
                tst.w   (runSlower).l
                beq.s   try_to_run_full_speed
                move.w  SPRITE_SPEED(a1),d0
                lsr.w   #2,d0
                sub.w   d0,SPRITE_SPEED(a1)
                lsr.w   #1,d0
                sub.w   d0,SPRITE_SPEED(a1)
try_to_run_full_speed:
                tst.w   TEAMGENERALINFO_PLAYERNUMBER(a6)
                bne.s   check_injury_penalty
                tst.w   TEAMGENERALINFO_PLAYERCOACHNUMBER(a6)
                beq.s   skip_injury_penalty
check_injury_penalty:
                move.b  PLAYERINFOHEADER_INJURIESBITFIELD(a4),d0
                beq.s   skip_injury_penalty
                andi.w  #$E0,d0
                lsr.w   #4,d0
                lea     (kInjuriesSpeedHandicap).l,a0
                move.w  (a0,d0.w),d0
                add.w   d0,SPRITE_SPEED(a1)
skip_injury_penalty:
                cmpa.l  TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a1
                bne.s   skip_ball_possession_penalty
                tst.w   TEAMGENERALINFO_PLAYERHASBALL(a6)
                beq.s   skip_ball_possession_penalty
                move.w  SPRITE_SPEED(a1),d0
                lsr.w   #3,d0
                sub.w   d0,SPRITE_SPEED(a1)
skip_ball_possession_penalty:
                tst.w   TEAMGENERALINFO_PLAYERNUMBER(a6)
                beq.w   no_pass_to_target_player
                cmpa.l  TEAMGENERALINFO_PASSTOPLAYERPTR(a6),a1
                bne.w   no_pass_to_target_player
                tst.w   TEAMGENERALINFO_PASSINGTOPLAYER(a6)
                beq.w   no_pass_to_target_player
                tst.l   TEAMGENERALINFO_LONGPASS(a6)
                bne.s   apply_long_pass_speed
                tst.w   TEAMGENERALINFO_LEFTSPIN(a6)
                bne.s   apply_long_pass_speed
                tst.w   TEAMGENERALINFO_RIGHTSPIN(a6)
                beq.w   no_pass_to_target_player
apply_long_pass_speed:
                tst.w   (ballSprite+SPRITE_SPEED).l
                beq.w   no_pass_to_target_player
                move.w  (ballSprite+SPRITE_FULLDIRECTION).l,d0
                sub.b   SPRITE_FULLDIRECTION+1(a1),d0
                cmpi.b  #7,d0           ; check if player has approximately same    direction as ball
                bgt.s   no_pass_to_target_player
                cmpi.b  #-7,d0
                blt.s   no_pass_to_target_player
                move.w  #512,d1         ; 512 - speed for a bit more different    direction
                cmpi.b  #5,d0
                bgt.s   set_pass_target_speed
                cmpi.b  #251,d0
                blt.s   set_pass_target_speed
                move.w  #256,d1         ; 256 - speed for more    similar direction
set_pass_target_speed:
                move.w  d1,SPRITE_SPEED(a1)
no_pass_to_target_player:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.s   calculate_acceleration
                cmpi.w  #ST_FIRST_HALF_ENDED,(gameState).l
                beq.s   reduce_speed_for_stoppage
                cmpi.w  #ST_GAME_ENDED,(gameState).l
                beq.s   reduce_speed_for_stoppage
                cmpi.w  #ST_GOING_TO_HALFTIME,(gameState).l
                beq.s   adjust_speed_for_stoppage
                cmpi.w  #ST_PLAYERS_GOING_TO_SHOWER,(gameState).l
                bne.s   calculate_acceleration
adjust_speed_for_stoppage:
                move.w  (stoppageTimerTotal).l,d0
                lsl.w   #2,d0
                cmpi.w  #100,d0
                bls.s   scale_speed_during_stoppage
                move.w  #100,d0
scale_speed_during_stoppage:
                mulu.w  SPRITE_SPEED(a1),d0
                divu.w  #100,d0
                move.w  d0,SPRITE_SPEED(a1)
                bra.s   calculate_acceleration
reduce_speed_for_stoppage:
                move.w  (stoppageTimerTotal).l,d0
                lsl.w   #5,d0
                sub.w   d0,SPRITE_SPEED(a1)
                bpl.s   calculate_acceleration
                clr.w   SPRITE_SPEED(a1)
calculate_acceleration:
                move.w  #1280,d0
                sub.w   SPRITE_SPEED(a1),d0
                bpl.s   finalize_acceleration
                clr.w   d0
finalize_acceleration:
                lsr.w   #7,d0
                addq.w  #6,d0
                move.w  d0,SPRITE_FRAMEDELAY(a1)
_110E76_exit_rts:
                rts
kInjuriesSpeedHandicap:
                dc.w 0,-96,-128,-160,-192,-224,-256,-288

