; ===== GetPlayerPointerFromShirtNumber =====
; prototype: PlayerInfoHeader *__usercall GetPlayerPointerFromShirtNumber@<a4>(Sprite *player@<a1>, TeamGeneralInfo *team@<a6>)
; in:
;      A1 -> sprite (player)
;      A6 -> team data
; out:
;      A4 -> player + header (in-game), requires addition of sizeof(TeamGame) to it to be a proper pointer
GetPlayerPointerFromShirtNumber:
                move.w  SPRITE_PLAYERORDINAL(a1),d0
                subq.w  #1,d0
                lea     (ingameTeamPlayerOffsets).l,a4
                lsl.w   #1,d0
                move.w  (a4,d0.w),d0
                movea.l TEAMGENERALINFO_INGAMETEAMPTR(a6),a4
                lea     (a4,d0.w),a4
                rts
ballNextX:
                dc.w $0000
ballNextY:
                dc.w $0000
pad_110F6C:
                dc.b 0,0,0,0

; ===== CalculateNextBallPosition =====
; prototype: void __usercall CalculateNextBallPosition()
CalculateNextBallPosition:
                lea     (ballSprite).l,a0
                move.l  SPRITE_X(a0),d5 ; ball x
                move.l  SPRITE_Y(a0),d6 ; ball y
                move.l  SPRITE_Z(a0),d7 ; ball z
                tst.w   SPRITE_SPEED(a0)
                beq.w   store_next_xy_and_return
                move.l  SPRITE_DELTAX(a0),d1 ; ball delta x
                move.l  SPRITE_DELTAY(a0),d2 ; ball delta y
                move.l  SPRITE_DELTAZ(a0),d3 ; ball delta z
                move.l  kGravityConstant(pc),d4 ; air friction
                tst.l   d3
                bgt.s   setup_scale_8_and_integrate ; delta z positive, ball rising
                move.w  SPRITE_Z(a0),d0 ; get z whole part in ax
                cmpi.w  #20,d0          ; check the height of ball
                bls.w   integrate_loop_scale_1
                cmpi.w  #30,d0
                bls.s   setup_scale_2_and_integrate
                cmpi.w  #35,d0
                bls.s   setup_scale_4_and_integrate
setup_scale_8_and_integrate:
                asl.l   #3,d1           ; delta x *= 8
                asl.l   #3,d2           ; delta y *= 8
                asl.l   #3,d4           ; air friction *= 8
                asr.l   #3,d7           ; z /= 8
integrate_loop_scale_8:
                add.l   d1,d5           ; x += delta x
                add.l   d2,d6           ; y += delta y
                sub.l   d4,d3           ; delta z -= air friction (include air friction)
                add.l   d3,d7           ; z += delta z
                bpl.s   integrate_loop_scale_8
                bra.s   store_next_xy_and_return
setup_scale_4_and_integrate:
                asl.l   #2,d1           ; delta x *= 4
                asl.l   #2,d2           ; delta y *= 4
                asl.l   #2,d4           ; air friction *= 4
                asr.l   #2,d7           ; z /= 4
integrate_loop_scale_4:
                add.l   d1,d5           ; x += delta x
                add.l   d2,d6           ; y += delta y
                sub.l   d4,d3           ; delta z -= air friction (include air friction)
                add.l   d3,d7           ; z += delta z
                bpl.s   integrate_loop_scale_4
                bra.s   store_next_xy_and_return
setup_scale_2_and_integrate:
                asl.l   #1,d1           ; delta x *= 2
                asl.l   #1,d2           ; delta y *= 2
                asl.l   #1,d4           ; air friction *= 2
                asr.l   #1,d7           ; z /= 2
integrate_loop_scale_2:
                add.l   d1,d5           ; x += delta x
                add.l   d2,d6           ; y += delta y
                sub.l   d4,d3           ; delta z -= air friction (include air friction)
                add.l   d3,d7           ; z += delta z
                bpl.s   integrate_loop_scale_2
                bra.s   store_next_xy_and_return
integrate_loop_scale_1:
                add.l   d1,d5           ; x += delta x
                add.l   d2,d6           ; y += delta y
                sub.l   d4,d3           ; delta z -= air friction (include air friction)
                add.l   d3,d7           ; z += delta z
                bpl.s   integrate_loop_scale_1
store_next_xy_and_return:
                swap    d5              ; swap words of ball x, so the whole part is at offset 0 now
                swap    d6              ; ditto for ball y
                move.w  d5,(ballNextX).l
                move.w  d6,(ballNextY).l
                rts

; ===== QueueMaskedSpriteBlitClipped =====
; prototype: void __usercall QueueMaskedSpriteBlitClipped(void *sprite@<a0>, unsigned __int16 x@<d1>, unsigned __int16 y@<d2>)
QueueMaskedSpriteBlitClipped:
                cmpi.w  #$F,$C(a0)
                bne.s   skip_sprite_draw
                cmpi.w  #$10,$A(a0)
                bhi.s   skip_sprite_draw
                tst.w   8(a0)
                beq.s   skip_sprite_draw
                tst.w   d2
                bmi.s   skip_sprite_draw
                cmpi.w  #SPRITE_MAX_Y_DRAW,d2
                bgt.s   skip_sprite_draw
                add.w   cameraXMod320(pc),d1
                add.w   cameraYMod320(pc),d2
                cmpi.w  #SCREEN_HEIGHT,d2
                blt.s   set_clipped_y_position
                subi.w  #SCREEN_HEIGHT,d2
set_clipped_y_position:
                move.w  d2,(spriteClippedY).l
                cmpi.w  #SPRITE_MAX_Y_DRAW,d2
                ble.s   check_x_overlap_and_setup
                move.w  (spriteClippedY).l,d2
                sub.w   cameraXMod320(pc),d1
                sub.w   cameraYMod320(pc),d2
skip_sprite_draw:
                jmp     DrawSpriteClipped
check_x_overlap_and_setup:
                move.w  d1,d0
                andi.w  #TILE_MASK,d0
                add.w   $A(a0),d0
                cmpi.w  #$10,d0
                bhi.w   setup_right_edge_clip
                movea.l (spriteBlitQueue).l,a3
                movea.l (frontbufferBasePtr).l,a1
                lea     (CUSTOM).l,a6
                move.w  d1,d0
                andi.w  #TILE_MASK,d0
                lsl.w   #6,d0
