; ===== SetPlayerWithNoBallDestination =====
; prototype: void __usercall SetPlayerWithNoBallDestination(Sprite *player@<a1>, TeamGeneralInfo *team@<a6>)
; in:
;      A1 -> current player sprite
;      A6 -> team data
SetPlayerWithNoBallDestination:
                lea     (teamTacticsTable).l,a0
                move.w  TEAMGENERALINFO_TACTICS(a6),d0
                lsl.w   #2,d0
                movea.l (a0,d0.w),a0
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                beq.s   keepers_ball_or_goalout
                cmpi.w  #ST_GOAL_OUT_LEFT,(gameState).l
                beq.s   keepers_ball_or_goalout
                cmpi.w  #ST_GOAL_OUT_RIGHT,(gameState).l
                bne.s   _111298_game_in_progress
keepers_ball_or_goalout:
                move.b  TEAMTACTICS_BALLOUTOFPLAYTACTICS(a0),d0
                ext.w   d0
                lea     (teamTacticsTable).l,a0
                lsl.w   #2,d0
                movea.l (a0,d0.w),a0
_111298_game_in_progress:
                lea     TEAMTACTICS_POSITIONS(a0),a0
                move.w  SPRITE_PLAYERORDINAL(a1),d0
                subq.w  #2,d0
                bmi.w   goalkeeper
                mulu.w  #35,d0
                move.w  playerXQuadrantOffset(pc),d3
                move.w  playerYQuadrantOffset(pc),d4
                cmpa.l  #topTeamData,a6
                bne.s   right_team_invert
                add.w   ballQuadrantIndex(pc),d0
                move.b  (a0,d0.w),d1
                bra.s   send_player_to_his_quadrant
right_team_invert:
                move.w  #34,d1
                sub.w   ballQuadrantIndex(pc),d1
                add.w   d1,d0
                move.b  #$EF,d1
                sub.b   (a0,d0.w),d1
send_player_to_his_quadrant:
                move.b  d1,d2
                lsr.w   #4,d1
                andi.w  #$F,d1
                andi.w  #$F,d2
                lea     playerXQuadrantsCoordinates(pc),a0
                lsl.w   #1,d1
                add.w   (a0,d1.w),d3
                lea     playerYQuadrantCoordinates(pc),a0
                lsl.w   #1,d2
                add.w   (a0,d2.w),d4
                subq.w  #4,d3
                cmpa.l  #topTeamData,a6
                beq.s   clamp_x_min_entry
                addq.w  #8,d3
clamp_x_min_entry:
                cmpi.w  #81,d3
                bge.s   clamp_x_min
                move.w  #81,d3
clamp_x_min:
                cmpi.w  #590,d3
                ble.s   _111316_clamp_y_min
                move.w  #590,d3
_111316_clamp_y_min:
                cmpi.w  #129,d4
                bge.s   clamp_y_max_entry
                move.w  #129,d4
clamp_y_max_entry:
                cmpi.w  #769,d4
                ble.s   store_destination_and_return
                move.w  #769,d4
store_destination_and_return:
                move.w  d3,SPRITE_DESTX(a1)
                move.w  d4,SPRITE_DESTY(a1)
                rts
                rts
goalkeeper:
                move.w  #285,d2
                move.w  #387,d3
                move.w  d6,d0
                subi.w  #81,d0          ; D0 = ball x -   81 (relative to left pitch border)
                move.w  d3,d1           ; D1 = 387 (right keeper limit)
                sub.w   d2,d1
                addq.w  #1,d1           ; D1 = keeper movement width (right - left + 1 =  103)
                mulu.w  d1,d0
                divu.w  #510,d0         ; D0 = x position goalkeeper should move to
                add.w   d2,d0
                move.w  d0,SPRITE_DESTX(a1) ; finally set goalkeepers x destination
                move.w  #135,d2
                move.w  #161,d3         ; limits for upper goalkeeper
                cmpa.l  #topTeamData,a6
                beq.s   calc_y_goalie_dest
                move.w  #737,d2
                move.w  #763,d3         ; limits for lower goalkeeper
calc_y_goalie_dest:
                move.w  d7,d0
                subi.w  #129,d0         ; playable part of pitch uppper border
                move.w  d3,d1
                sub.w   d2,d1
                addq.w  #1,d1           ; D1 = keeper movement area height
                mulu.w  d1,d0
                divu.w  #641,d0         ; height of   playable part of pitch
                add.w   d2,d0
                move.w  d0,SPRITE_DESTY(a1)
                rts

; ===== PlayerTackled =====
; prototype: void __usercall PlayerTackled(Sprite *playerSprite@<a1>, TeamGeneralInfo *team@<a6>)
; in:
;      A1 -> player sprite
;      A6 -> team (general)
; 
; This function is called when this player was tackled.
; It sets player's state to tackled and sets animation
; table. Also randomly sets injury and injury level.
PlayerTackled:
                tst.w   (trainingGame).l
                beq.s   check_injury_quota_for_team
                bsr.w   Rand
                andi.w  #3,d0           ; random injury -- 25% chance (if not blocked below)
                bne.w   set_tackled_state_and_animation
check_injury_quota_for_team:
                cmpi.w  #1,TEAMGENERALINFO_TEAMNUMBER(a6)
                bne.s   check_team2_quota_or_exit
                tst.w   (team1NumAllowedInjuries).l
                beq.w   set_tackled_state_and_animation
                bra.s   resolve_player_ptr_and_pick_prob_table
check_team2_quota_or_exit:
                tst.w   (team2NumAllowedInjuries).l
                beq.w   set_tackled_state_and_animation
resolve_player_ptr_and_pick_prob_table:
                move.w  SPRITE_PLAYERORDINAL(a1),d0
                subq.w  #1,d0
                lsl.w   #1,d0
                lea     (ingameTeamPlayerOffsets).l,a0
                move.w  (a0,d0.w),d0
                movea.l TEAMGENERALINFO_INGAMETEAMPTR(a6),a0
                lea     (a0,d0.w),a0
                move.w  (gameLengthInGame).l,d1
                lea     (kTackleInjuryProbability).l,a5
                move.b  PLAYERINFOHEADER_INJURIESBITFIELD(a0),d0
                andi.w  #$E0,d0
                cmpi.w  #$20,d0         ; ' '
                bne.s   roll_injury_probability
                lea     (kTackleInjuryProbabilityAlreadyInjured).l,a5
roll_injury_probability:
                jsr Rand(pc)
                cmp.b   (a5,d1.w),d0
                bcc.w   set_tackled_state_and_animation
                lea     (kInjuryLevels).l,a5
                move.b  PLAYERINFOHEADER_INJURIESBITFIELD(a0),d0
                andi.w  #$E0,d0
                cmpi.w  #$20,d0         ; ' '
                bne.s   roll_injury_severity_bucket
                lea     (kInjuryLevelAlreadyInjured).l,a5
roll_injury_severity_bucket:
                jsr Rand(pc)
                andi.w  #$3F,d0         ; '?'
                move.w  #$20,d1         ; ' '
                cmp.b   (a5)+,d0
                bcs.s   apply_injury_and_min_cap_status
                sub.b   -1(a5),d0
                addi.w  #$20,d1         ; ' '
                cmp.b   (a5)+,d0
                bcs.s   apply_injury_and_min_cap_status
                sub.b   -1(a5),d0
                addi.w  #$20,d1         ; ' '
                cmp.b   (a5)+,d0
                bcs.s   apply_injury_and_min_cap_status
                sub.b   -1(a5),d0
                addi.w  #$20,d1         ; ' '
                cmp.b   (a5)+,d0
                bcs.s   apply_injury_and_min_cap_status
                sub.b   -1(a5),d0
                addi.w  #$20,d1         ; ' '
                cmp.b   (a5)+,d0
                bcs.s   apply_injury_and_min_cap_status
                sub.b   -1(a5),d0
                addi.w  #$20,d1         ; ' '
                cmp.b   (a5)+,d0
                bcs.s   apply_injury_and_min_cap_status
                sub.b   -1(a5),d0
                addi.w  #$20,d1         ; ' '
                cmp.b   (a5)+,d0
                bcs.s   apply_injury_and_min_cap_status
                sub.b   -1(a5),d0
                addi.w  #$20,d1         ; ' '
apply_injury_and_min_cap_status:
                move.b  #1,PLAYERINFOHEADER_ISINJURED(a0)
                cmp.b   PLAYERINFOHEADER_INJURIESBITFIELD(a0),d1
                bls.s   map_severity_to_knockdown_time
                move.b  d1,PLAYERINFOHEADER_INJURIESBITFIELD(a0)
map_severity_to_knockdown_time:
                andi.w  #$E0,d1
                lsr.w   #5,d1
                lea     (kInjuryRecoveryTime).l,a0
                lsl.w   #1,d1
                move.w  (a0,d1.w),SPRITE_INJURYLEVEL(a1)
                cmpi.w  #1,TEAMGENERALINFO_TEAMNUMBER(a6)
                bne.s   decrement_team2_quota
                subq.w  #1,(team1NumAllowedInjuries).l
                bra.s   set_tackled_state_and_animation
decrement_team2_quota:
                subq.w  #1,(team2NumAllowedInjuries).l
set_tackled_state_and_animation:
                move.b  #PL_TACKLED,SPRITE_PLAYERSTATE(a1)
                move.b  #$32,SPRITE_PLAYERDOWNTIMER(a1) ; '2'
                lea     (playerTackledAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                rts
