; TeamGeneralInfo *
lastTeamPlayedBeforeBreak:
                dc.l $00000000          ; Pointer to team data structure that last had the ball
                                        ; in possesion after the break; points to upper or lower
                                        ; team, same team has different pointer in first and second
                                        ; half; can be null if the game is not started yet
stoppageTimerTotal:
                dc.w $0000              ; Measures total time when game is stopped (in ticks)
                                        ; reset when the ball comes into play
stoppageTimerActive:
                dc.w $0000              ; Counting time when game is stopped, but only when a player is able to do something
                                        ; it's reset when the ball comes into play
                                        ; (for example, some player kicks the ball out of play, upper timer starts
                                        ; counting immediately, while this one starts only when another player
                                        ; comes to the line, and is ready to do throw in)
gameStatePl:
                dc.w $0000              ; Similar to gameState
                                        ; 100 game in progress
                                        ; 101 when game not running (starting, half-time, keeper holding the ball, etc.)
                                        ; 102 when waiting on player to continue the game (take penalty, free kick, trow-in, etc.)
                                        ; in other situations, copy of gameState
gameState:
                dc.w $0000              ; 0   - Players going to their starting positions
                                        ;    1   - left gol out (to team that's got the ball)
                                        ;    2   - right goal out
                                        ;    3   - keeper is holding the ball
                                        ;    4   - left corner
                                        ;    5   - right corner
                                        ;  6..12 - free kicks (areas from left to right)
                                        ;   13   - foul
                                        ;   14   - penalty
                                        ; 15..20 - throw in (at various positions)
                                        ;   21   - game is starting
                                        ;   22   - camera going from center to shower on halftime
                                        ;   23   - players going to shower for halftime
                                        ;   24   - players going to shower
                                        ;   25   - showing result on halftime
                                        ;   26   - showing result after the game
                                        ;   27   - game ended, first extra time about to begin
                                        ;   28   - second extra time ended
                                        ;   29   - first half ended
                                        ;   30   - game has ended
                                        ;   31   - penalties shootout
                                        ;  100   - game in progress
breakCameraMode:
                dc.w $0000              ; Something 0..8
                                        ; -1 when game just starting, at halftime, game over
                                        ; 0 when the game is stopped but the ball is still moving
                                        ; 1 when the game is stopped and the ball is standing still
                                        ; 2 when waiting on players to go to their positions
                                        ; 3 on initial kick-off/goal (also when moving to it)
                                        ;   also seen shortly on other breaks
                                        ; 4 when goalkeeper's ball
                                        ; 5 seen for a moment during kick-off
                                        ; 7 show up only for a short time, maybe when a player is coming
                                        ; 8 when player can change camera direction with controls
                                        ; (throw-in, for example)
                                        ; while the game is running unpaused simply keeps last the value
stoppageEventTimer:
                dc.w $0000              ; When in game, when it counts to zero after the break, ball is set where it should be
                                        ; times interval to keep score and stats on screen after the game and on half time
                                        ; also times various inter-states, such as when player go to shower, and when they return to pitch
                                        ; 110 until start of first extra time
                                        ; possibly number of ticks until next "scene" (or camera mode transition)
foulXCoordinate:
                dc.w $0000              ; Coordinates where the ball was when the foul has
                                        ; happened - where the referee must run to
                                        ; might also be ball coordinates when the game is interrupted
                                        ; (definitely used for throw-in)
foulYCoordinate:
                dc.w $0000
cameraDirection:
                dc.w $0000              ; Shows direction in which camera should travel after the ball is out of play
                                        ; -1 when not playing (at the start before pressing fire, half-time, after game ends...)
playerTurnFlags:
                dc.b $00                ; Bit set represents allowed directions when the player puts
                                        ; the ball back into play (throw in, penalty..) - bits 0..7
pad_111673:
                dc.b $00
inGameCounter:
                dc.w $0000              ; Counts when the ball is in play
                                        ; halted when the game is stopped
                                        ; resets when player resumes control
breakState:
                dc.w $0000              ; Gets set after the break, when player is about to put ball
                                        ; back in play - then it's a copy of gameState; 0 when not playing,
                                        ; and after the goal; keeps last value right until player regains control
substitutedPlDestX:
                dc.w $0000
substitutedPlDestY:
                dc.w $0000
substitutedPlX:
                dc.w $0000
substitutedPlY:
                dc.w $0000
throwInPassOrKick:
                dc.w $0000              ; 1 (Or non-zero) = pass, 0 = kick
halfNumber:
                dc.w $0000              ; Normal or extra time half number (1 or 2)
teamStarting:
                dc.w $0001              ; Number of team that starts the game or half
                                        ; gets random value 1 or 2; on halftime inverted (1 = 2, 2 = 1)
                                        ; gets new random value before start of first extra time
teamPlayingUp:
                dc.w $0001              ; 1 Or 2
playingPenalties:
                dc.w $0000              ; After the game, boolean
dontShowScorers:
                dc.w $0000              ; If true, do not show list of scorers along with result
                                        ; needed because we don't care about it when (if) penalties start
                                        ; set to true, by of course StartPenalties
team1PenaltyAttempts:
                dc.w $0000              ; Current number of penalty attempts team has made (after the game
                                        ; ended up tied); this number comprises current attempt too
team2PenaltyAttempts:
                dc.w $0000
penaltiesTimer:
                dc.w $0000              ; When penalty is shot, counts down and when reaches
                                        ; zero, next penalty is to be taken
                                        ; (only on penalties after game!)
team1PenaltyShooterIndex:
                dc.w $0000
team2PenaltyShooterIndex:
                dc.w $0000
; Sprite *
penaltyShooterSprite:
                dc.l $00000000          ; Pointer to player that is about to do penalty
                                        ; changed when penaltiesTimer expires
                                        ; NULL before penalties time
; __int16[64]
kBallFriction:
                ; __int16[64]
                dc.w 0,-1000,199,-1000,414,-1000,668,-1000 ; Used when doing long passes
                dc.w 1000,-1000,1000,-668,1000,-414,1000,-199
                dc.w 1000,0,1000,199,1000,414,1000,668
                dc.w 1000,1000,668,1000,414,1000,199,1000
                dc.w 0,1000,-199,1000,-414,1000,-668,1000
                dc.w -1000,1000,-1000,668,-1000,414,-1000,199
                dc.w -1000,0,-1000,-199,-1000,-414,-1000,-668
                dc.w -1000,-1000,-668,-1000,-414,-1000,-199,-1000
; __int16[16]
kDefaultDestinations:
                ; __int16[16]
                dc.w 0,-1000,1000,-1000,1000,0,1000,1000 ; Values that are used as x/y destination depending on direction player is moving
                dc.w 0,1000,-1000,1000,-1000,0,-1000,-1000
                                        ; they're also used for the ball while the game is running
; __int16[16]
kLeftThrowInBallDestDelta:
                ; __int16[16]
                dc.w 250,-1000,1000,-1000,1000,0,1000,1000
                dc.w 250,1000,-1000,1000,-1000,0,-1000,-1000
; __int16[16]
kRightThrowInBallDestDelta:
                ; __int16[16]
                dc.w -250,-1000,1000,-1000,1000,0,1000,1000
                dc.w -250,1000,-1000,1000,-1000,0,-1000,-1000
; __int16[16]
kPenaltyBallDestDelta:
                ; __int16[16]
                dc.w 0,-1000,500,-1000,1000,0,500,1000
                dc.w 0,1000,-500,1000,-1000,0,-500,-1000
; __int16[16]
kUpperLeftCornerBallDestDelta:
                ; __int16[16]
                dc.w 0,-1000,1000,-1000,1000,150,1000,300
                dc.w 250,1000,-1000,1000,-1000,0,-1000,-1000
; __int16[16]
kUpperRightCornerBallDestDelta:
                ; __int16[16]
                dc.w 0,-1000,1000,-1000,1000,0,1000,1000
                dc.w -250,1000,-1000,350,-1000,150,-1000,-1000
; __int16[16]
kLowerLeftCornerBallDestDelta:
                ; __int16[16]
                dc.w 250,-1000,1000,-350,1000,-150,1000,1000
                dc.w 0,1000,-1000,1000,-1000,0,-1000,-1000
; __int16[16]
kLowerRightCornerBallDestDelta:
                ; __int16[16]
                dc.w -250,-1000,1000,-1000,1000,0,1000,1000
                dc.w 0,1000,-1000,1000,-1000,-150,-1000,-350
goalkeeperDiveBallHeights:
                dc.w 7,13,11,8,5,2,20,2 ; Lookup table of ball Z values indexed by goalkeeper animation frame offset during dive animations.
                dc.w 5,8,11,13,7,20,5,11
                dc.w 9,6,3,0,20,0,3,6
                dc.w 9,11,5,20
kGoalKeeperClaimingBallHeight:
                dc.w 17,17,17,10,8,5,255
refState:
                dc.w $0000              ; 0 = Dont draw referee
                                        ; 1 = referee incoming
                                        ; 2 = waiting player
                                        ; 3 = very short, when red card
                                        ; 4 = booking player and showing card
                                        ; 5 = leaving
injuriesForever:
                dc.w $0000,$0000,$0000,$0000,$0000,$0000,$0000 ; Dead variable; if true, player never gets out of injured state
                                        ; probably something for testing
cardsDisallowed:
                dc.w $0000              ; If true don't book players
whichCard:
                dc.w $0000              ; Card handing out in progress:
                                        ; 0 = nothing
                                        ; 1 = yellow
                                        ; 2 = red
                                        ; 3 = second yellow, red
                                        ; Can be interpreted as bit field, bit 0 = yellow card, bit 1 = red card
; Sprite *
bookedPlayer:
                dc.l $00000000          ; Pointer to a player that's beeing booked
; TeamGeneralInfo *
lastTeamBooked:
                dc.l $00000000          ; Points to a team whose player last made bookable offence
refTimer:
                dc.w $0000              ; Starts counting from zero when bookable offence is made,
                                        ; and goes upwards to 232
playerCardChance:
                dc.w $0000              ; CurrentGameTick bits 1-4 need to be greater than this in order
                                        ; for the referee to give out a card when there's a foul;
                                        ; gotten from the tables below
playerCardChances3min:
                dc.w $0004,$0004,$0004,$0004,$0005,$0005,$0005,$0005
                dc.w $0006,$0006,$0006,$0007,$0007,$0008,$0009,$000A
playerCardChances5min:
                dc.w $0002,$0002,$0003,$0003,$0003,$0003,$0003,$0003
                dc.w $0004,$0004,$0004,$0004,$0004,$0005,$0005,$0006
playerCardChances7min:
                dc.w $0001,$0001,$0002,$0002,$0002,$0002,$0002,$0002
                dc.w $0003,$0003,$0003,$0003,$0003,$0004,$0004,$0004
playerCardChances10min:
                dc.w $0001,$0001,$0001,$0001,$0001,$0002,$0002,$0002
                dc.w $0002,$0002,$0002,$0002,$0002,$0002,$0003,$0003
playerCardChancesPerGameLength:
                dc.l playerCardChances3min
                dc.l playerCardChances5min
                dc.l playerCardChances7min
                dc.l playerCardChances10min

; ===== StartPenalties =====
; prototype: void __usercall StartPenalties()
StartPenalties:
                move.w  #$FFFF,(penaltiesState).l
                move.w  statsTeam1Goals(pc),(savedTeam1Goals).l
                move.w  statsTeam2Goals(pc),(savedTeam2Goals).l
                clr.w   (statsTeam1Goals).l
                clr.w   (team1GoalsDigit1).l
                clr.w   (team1GoalsDigit2).l
                clr.w   (statsTeam2Goals).l
                clr.w   (team2GoalsDigit1).l
                clr.w   (team2GoalsDigit2).l
                clr.w   (team1PenaltyGoals).l
                clr.w   (team2PenaltyGoals).l
                bsr.w   Rand
                andi.w  #1,d0
                addq.w  #1,d0
                move.w  d0,(teamPlayingUp).l
                bsr.w   Rand
                andi.w  #1,d0
                addq.w  #1,d0
                move.w  d0,(teamStarting).l
                move.w  #11,(team1PenaltyShooterIndex).l
                move.w  #11,(team2PenaltyShooterIndex).l
                clr.w   (team1PenaltyAttempts).l
                clr.w   (team2PenaltyAttempts).l
                move.w  #1,(playingPenalties).l
                move.w  #1,(dontShowScorers).l
                lea     (team1SpritesTable).l,a0
                move.w  #10,d0
reset_team1_penalty_sprites_loop:
                movea.l (a0)+,a5
                clr.w   SPRITE_CARDS(a5)
                clr.w   SPRITE_SENTAWAY(a5)
                dbf     d0,reset_team1_penalty_sprites_loop
                lea     (team2SpritesTable).l,a0
                move.w  #10,d0
reset_team2_penalty_sprites_loop:
                movea.l (a0)+,a5
                clr.w   SPRITE_CARDS(a5)
                clr.w   SPRITE_SENTAWAY(a5)
                dbf     d0,reset_team2_penalty_sprites_loop
                bsr.w   NextPenalty
                rts

; ===== InitTeamsData =====
; prototype: void __usercall InitTeamsData()
InitTeamsData:
                clr.l   (currentScorer).l
                clr.l   (lastPlayerBeforeGoalkeeper).l
                clr.w   (goalScored).l
                clr.w   (runSlower).l
                clr.w   (whichCard).l
                clr.l   (bookedPlayer).l
                clr.w   (playerHadBall).l
                clr.l   (lastKeeperPlayed).l
                clr.l   (lastTeamPlayed).l
                clr.l   (lastPlayerPlayed).l
                clr.w   (penalty).l
                clr.w   (goalCameraMode).l
                clr.w   (goalOut).l
                clr.w   (gameNotInProgressCounterWriteOnly).l
                clr.w   (fireBlocked).l
                clr.l   (lastTeamPlayedBeforeBreak).l
                clr.w   (stoppageTimerTotal).l
                clr.w   (stoppageTimerActive).l
                clr.w   (stoppageEventTimer).l
                clr.w   (inGameCounter).l
                move.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                move.w  #ST_GAME_IN_PROGRESS,(gameState).l
                move.w  #0,(breakState).l
                move.w  #$FFFF,(breakCameraMode).l
                move.w  #1,d7
                move.w  (topTeamPlayerNo).l,d6
                move.w  (topTeamCoachNo).l,d2
                move.w  (pl1Coach).l,d1
                lea     topTeamData(pc),a0
                lea     bottomTeamData(pc),a1
                lea     (team1SpritesTable).l,a2
                movea.l topTeamPtr(pc),a3
                lea     team1StatsData(pc),a4
                lea     (pl1Tactics).l,a5
                move.w  #1,d5
                cmpi.w  #1,(teamPlayingUp).l
                beq.s   init_team_loop_top
                exg     a0,a1
init_team_loop_top:
                move.l  a1,(a0)
                move.l  a3,TEAMGENERALINFO_INGAMETEAMPTR(a0)
                move.l  a4,TEAMGENERALINFO_TEAMSTATSPTR(a0)
                move.w  d6,TEAMGENERALINFO_PLAYERNUMBER(a0)
                move.w  d2,TEAMGENERALINFO_PLAYERCOACHNUMBER(a0)
                move.w  d1,TEAMGENERALINFO_ISPLCOACH(a0)
                move.l  a2,TEAMGENERALINFO_SPRITESTABLE(a0)
                move.w  d5,TEAMGENERALINFO_TEAMNUMBER(a0)
                move.w  (a5),TEAMGENERALINFO_TACTICS(a0)
                clr.w   TEAMGENERALINFO_GOALKEEPERPLAYING(a0)
                clr.w   TEAMGENERALINFO_RESETCONTROLS(a0)
                move.w  #10,TEAMGENERALINFO_UPDATEPLAYERINDEX(a0)
                clr.l   TEAMGENERALINFO_CONTROLLEDPLAYER(a0)
                clr.l   TEAMGENERALINFO_PASSTOPLAYERPTR(a0)
                clr.l   TEAMGENERALINFO_PASSINGKICKINGPLAYER(a0)
                clr.w   TEAMGENERALINFO_PLAYERHASBALL(a0)
                clr.w   TEAMGENERALINFO_GOALKEEPERDIVINGRIGHT(a0)
                clr.w   TEAMGENERALINFO_GOALKEEPERDIVINGLEFT(a0)
                clr.w   TEAMGENERALINFO_BALLOUTOFPLAYORKEEPER(a0)
                clr.w   TEAMGENERALINFO_GOALIEPLAYINGOROUT(a0)
                clr.w   TEAMGENERALINFO_PASSINGBALL(a0)
                clr.w   TEAMGENERALINFO_PASSINGTOPLAYER(a0)
                clr.w   TEAMGENERALINFO_PLAYERSWITCHTIMER(a0)
                clr.w   TEAMGENERALINFO_BALLINPLAY(a0)
                clr.w   TEAMGENERALINFO_BALLOUTOFPLAY(a0)
                clr.w   TEAMGENERALINFO_PASSKICKTIMER(a0)
                clr.w   TEAMGENERALINFO_BALLCANBECONTROLLED(a0)
                clr.w   TEAMGENERALINFO_FIELD_72(a0)
                move.w  #$FFFF,TEAMGENERALINFO_BALLCONTROLLINGPLAYERDIRECTION(a0)
                clr.w   TEAMGENERALINFO_FIELD_74(a0)
                clr.w   TEAMGENERALINFO_WONTHEBALLTIMER(a0)
                move.w  #$FFFF,TEAMGENERALINFO_SPINTIMER(a0)
                clr.b   TEAMGENERALINFO_FIELD_3C(a0)
                clr.w   TEAMGENERALINFO_GOALKEEPERSAVEDCOMMENTTIMER(a0)
                clr.l   TEAMGENERALINFO_LASTHEADINGTACKLINGPLAYER(a0)
                clr.w   TEAMGENERALINFO_FIELD_4E(a0)
                clr.w   TEAMGENERALINFO_HEADERORTACKLE(a0)
                clr.w   TEAMGENERALINFO_SHOOTING(a0)
                clr.w   TEAMGENERALINFO_PASSINPROGRESS(a0)
                move.w  (bottomTeamPlayerNo).l,d6
                move.w  (bottomTeamCoachNo).l,d2
                move.w  (pl2Coach).l,d1
                lea     bottomTeamData(pc),a0
                lea     topTeamData(pc),a1
                lea     (team2SpritesTable).l,a2
                movea.l bottomTeamPtr(pc),a3
                lea     team2StatsData(pc),a4
                lea     (pl2Tactics).l,a5
                move.w  #2,d5
                cmpi.w  #1,(teamPlayingUp).l
                beq.s   init_team_loop_bottom
                exg     a0,a1
init_team_loop_bottom:
                dbf     d7,init_team_loop_top
                rts

; ===== UpdateControlledPlayer =====
; prototype: void __usercall UpdateControlledPlayer(TeamGeneralInfo *team@<a6>)
; in:
;      A6 -> current team data
;      
; Update players distance from the ball. Update controlling player if
; he's closest to the ball. Stop him if he was getting passed to.
UpdateControlledPlayer:
                lea     (ballSprite).l,a2
                move.w  SPRITE_X(a2),d3
                move.w  SPRITE_Y(a2),d4
                movea.l TEAMGENERALINFO_SPRITESTABLE(a6),a1
                movea.l #0,a3
                movea.l #0,a4
                moveq   #$FFFFFFFF,d5
                moveq   #$FFFFFFFF,d7
                move.w  #10,d6
loop_players_distance_check:
                movea.l (a1)+,a2
                move.w  SPRITE_X(a2),d1
                sub.w   d3,d1
                move.w  SPRITE_Y(a2),d2
                sub.w   d4,d2
                muls.w  d1,d1
                muls.w  d2,d2
                add.l   d2,d1
                move.l  d1,SPRITE_BALLDISTANCE(a2)
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.s   skip_if_player_inactive
                tst.w   SPRITE_ONSCREEN(a2)
                beq.s   next_player_in_loop
skip_if_player_inactive:
                tst.w   SPRITE_SENTAWAY(a2)
                bne.s   next_player_in_loop
                tst.w   TEAMGENERALINFO_GOALIEPLAYINGOROUT(a6)
                bne.s   skip_if_player_invalid
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a2)
                beq.w   next_player_in_loop
skip_if_player_invalid:
                cmpa.l  TEAMGENERALINFO_PASSINGKICKINGPLAYER(a6),a2
                beq.s   next_player_in_loop
                cmpi.b  #PL_TACKLING,SPRITE_PLAYERSTATE(a2)
                beq.s   next_player_in_loop
                cmpi.b  #PL_TACKLED,SPRITE_PLAYERSTATE(a2)
                beq.s   next_player_in_loop
                cmpi.b  #PL_JUMP_HEADING,SPRITE_PLAYERSTATE(a2)
                beq.s   next_player_in_loop
                cmpi.b  #PL_STATIC_HEADING,SPRITE_PLAYERSTATE(a2)
                beq.s   next_player_in_loop
                cmpi.b  #PL_ROLLING_INJURED,SPRITE_PLAYERSTATE(a2)
                beq.s   next_player_in_loop
                cmpa.l  TEAMGENERALINFO_PASSTOPLAYERPTR(a6),a2
                beq.s   next_player_in_loop
                cmp.l   d5,d1
                bcc.s   next_player_in_loop
                move.l  d1,d5
                movea.l a2,a3
next_player_in_loop:
                dbf     d6,loop_players_distance_check
                tst.w   (playingPenalties).l
                beq.s   check_selected_player
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.w   end_find_nearest_player_to_ball
check_selected_player:
                cmpa.l  #0,a3
                beq.w   end_find_nearest_player_to_ball
                tst.w   TEAMGENERALINFO_BALLOUTOFPLAY(a6)
                beq.s   end_find_nearest_player_to_ball
                cmpa.l  TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a3
                beq.s   update_selected_player
                move.l  a3,-(sp)
                movea.l TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a3
                cmpa.l  #0,a3
                beq.s   restore_prev_selected_player
                cmpi.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a3)
                bne.s   restore_prev_selected_player
                move.w  SPRITE_X(a3),SPRITE_DESTX(a3)
                move.w  SPRITE_Y(a3),SPRITE_DESTY(a3)
restore_prev_selected_player:
                movea.l (sp)+,a3
update_selected_player:
                move.l  a3,TEAMGENERALINFO_CONTROLLEDPLAYER(a6)
                cmpa.l  TEAMGENERALINFO_PASSTOPLAYERPTR(a6),a3
                bne.s   end_find_nearest_player_to_ball
                move.l  a3,-(sp)
                movea.l TEAMGENERALINFO_PASSTOPLAYERPTR(a6),a3
                cmpa.l  #0,a3
                beq.s   restore_prev_secondary_player
                cmpi.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a3)
                bne.s   restore_prev_secondary_player
                move.w  SPRITE_X(a3),SPRITE_DESTX(a3)
                move.w  SPRITE_Y(a3),SPRITE_DESTY(a3)
restore_prev_secondary_player:
                movea.l (sp)+,a3
                clr.l   TEAMGENERALINFO_PASSTOPLAYERPTR(a6)
end_find_nearest_player_to_ball:
                rts

; ===== UpdatePlayerBeingPassedTo =====
; prototype: void __usercall UpdatePlayerBeingPassedTo(TeamGeneralInfo *team@<a6>)
; in:
;      A6 -> team data
;      
; Find closest player being passed to and update passToPlayerPtr.
; Stop him so he can get the pass if game is running, do not if game is stopped.
UpdatePlayerBeingPassedTo:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.w   update_secondary_player_selection_stopped
                lea     (ballSprite).l,a2
                move.w  SPRITE_X(a2),TEAMGENERALINFO_BALLX(a6)
                move.w  SPRITE_Y(a2),TEAMGENERALINFO_BALLY(a6)
                tst.w   TEAMGENERALINFO_BALLINPLAY(a6)
                beq.w   exit_rts_gp
                tst.w   TEAMGENERALINFO_PLAYERSWITCHTIMER(a6)
                bne.w   exit_rts_gp
                tst.w   TEAMGENERALINFO_PASSINGTOPLAYER(a6)
                beq.s   check_penalties_branch
                tst.l   TEAMGENERALINFO_PASSTOPLAYERPTR(a6)
                bne.w   exit_rts_gp
check_penalties_branch:
                tst.w   (playingPenalties).l
                beq.s   scan_team_for_secondary_candidate_gp
                cmpi.w  #ST_PENALTIES,(gameStatePl).l
                bne.w   exit_rts_gp
                movea.l penaltyShooterSprite(pc),a3
                clr.w   TEAMGENERALINFO_BALLINPLAY(a6)
                bra.w   update_secondary_player_ptr_gp
scan_team_for_secondary_candidate_gp:
                movea.l TEAMGENERALINFO_SPRITESTABLE(a6),a1
                lea     (ballSprite).l,a2
                move.w  ballSprite+SPRITE_X-ballSprite(a2),d3
                move.w  SPRITE_Y(a2),d4
                movea.l #0,a3
                movea.l #0,a4
                moveq   #$FFFFFFFF,d5
                moveq   #$FFFFFFFF,d7
                move.w  #10,d6
loop_players_secondary_gp:
                movea.l (a1)+,a2
                tst.w   SPRITE_ONSCREEN(a2)
                beq.s   next_player_secondary_gp
                tst.w   SPRITE_SENTAWAY(a2)
                bne.s   next_player_secondary_gp
                tst.w   TEAMGENERALINFO_BALLOUTOFPLAYORKEEPER(a6)
                bne.s   skip_if_primary_or_ball_owner_gp
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a2)
                beq.w   next_player_secondary_gp
skip_if_primary_or_ball_owner_gp:
                cmpa.l  TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a2
                beq.s   next_player_secondary_gp
                cmpa.l  TEAMGENERALINFO_PASSINGKICKINGPLAYER(a6),a2
                beq.s   next_player_secondary_gp
                cmpi.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a2)
                bne.s   next_player_secondary_gp
                move.l  SPRITE_BALLDISTANCE(a2),d1
                cmp.l   d5,d1
                bcc.s   next_player_secondary_gp
                move.l  d1,d5
                movea.l a2,a3
next_player_secondary_gp:
                dbf     d6,loop_players_secondary_gp
                cmpa.l  #0,a3
                beq.w   exit_rts_gp
update_secondary_player_ptr_gp:
                cmpa.l  TEAMGENERALINFO_PASSTOPLAYERPTR(a6),a3
                beq.s   set_secondary_player_ptr_gp
                move.l  a3,-(sp)
                movea.l TEAMGENERALINFO_PASSTOPLAYERPTR(a6),a3
                cmpa.l  #0,a3
                beq.s   restore_prev_secondary_pos_gp
                cmpi.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a3)
                bne.s   restore_prev_secondary_pos_gp
                move.w  SPRITE_X(a3),SPRITE_DESTX(a3)
                move.w  SPRITE_Y(a3),SPRITE_DESTY(a3)
restore_prev_secondary_pos_gp:
                movea.l (sp)+,a3
set_secondary_player_ptr_gp:
                move.l  a3,TEAMGENERALINFO_PASSTOPLAYERPTR(a6)
exit_rts_gp:
                rts
update_secondary_player_selection_stopped:
                lea     (ballSprite).l,a2
                move.w  SPRITE_X(a2),TEAMGENERALINFO_BALLX(a6)
                move.w  SPRITE_Y(a2),TEAMGENERALINFO_BALLY(a6)
                tst.w   TEAMGENERALINFO_BALLINPLAY(a6)
                beq.w   exit_rts_stopped
                tst.w   TEAMGENERALINFO_PLAYERSWITCHTIMER(a6)
                bne.w   exit_rts_stopped
                tst.w   TEAMGENERALINFO_PASSINGTOPLAYER(a6)
                beq.s   check_penalties_branch_stopped
                tst.l   TEAMGENERALINFO_PASSTOPLAYERPTR(a6)
                bne.w   exit_rts_stopped
check_penalties_branch_stopped:
                tst.w   (playingPenalties).l
                beq.s   scan_team_for_secondary_candidate_stopped
                cmpi.w  #ST_PENALTIES,(gameStatePl).l
                bne.w   exit_rts_stopped
                movea.l penaltyShooterSprite(pc),a3
                clr.w   TEAMGENERALINFO_BALLINPLAY(a6)
                bra.w   set_secondary_player_ptr_stopped
scan_team_for_secondary_candidate_stopped:
                movea.l TEAMGENERALINFO_SPRITESTABLE(a6),a1
                lea     (ballSprite).l,a2
                move.w  SPRITE_X(a2),d3
                move.w  SPRITE_Y(a2),d4
                movea.l #0,a3
                movea.l #0,a4
                moveq   #$FFFFFFFF,d5
                moveq   #$FFFFFFFF,d7
                move.w  #10,d6
loop_players_secondary_stopped:
                movea.l (a1)+,a2
                tst.w   SPRITE_SENTAWAY(a2)
                bne.s   next_player_secondary_stopped
                tst.w   TEAMGENERALINFO_BALLOUTOFPLAYORKEEPER(a6)
                bne.s   skip_if_primary_or_ball_owner_stopped
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a2)
                beq.w   next_player_secondary_stopped
skip_if_primary_or_ball_owner_stopped:
                cmpa.l  TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a2
                beq.s   next_player_secondary_stopped
                cmpa.l  TEAMGENERALINFO_PASSINGKICKINGPLAYER(a6),a2
                beq.s   next_player_secondary_stopped
                cmpi.b  #0,SPRITE_PLAYERSTATE(a2)
                bne.s   next_player_secondary_stopped
                move.l  SPRITE_BALLDISTANCE(a2),d1
                cmp.l   d5,d1
                bcc.s   next_player_secondary_stopped
                move.l  d1,d5
                movea.l a2,a3
next_player_secondary_stopped:
                dbf     d6,loop_players_secondary_stopped
                cmpa.l  #0,a3
                beq.w   exit_rts_stopped
set_secondary_player_ptr_stopped:
                move.l  a3,TEAMGENERALINFO_PASSTOPLAYERPTR(a6)
exit_rts_stopped:
                rts

; ===== UpdateGameTimersAndCameraBreakMode =====
; prototype: void __usercall UpdateGameTimersAndCameraBreakMode(TeamGeneralInfo *team@<a6>)
UpdateGameTimersAndCameraBreakMode:
                tst.w   (playingPenalties).l
                beq.s   handle_penalties_and_continue
                cmpi.w  #ST_PENALTIES,(gameState).l
                beq.s   handle_penalties_and_continue
                addq.w  #1,(penaltiesTimer).l
                cmpi.w  #100,(penaltiesTimer).l
                bne.s   handle_penalties_and_continue
                bsr.w   NextPenalty
handle_penalties_and_continue:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.w   update_stoppage_timers
                move.w  lastFrameTicks(pc),d0
                add.w   d0,(inGameCounter).l
                bra.w   _1124F4_out
update_stoppage_timers:
                addq.w  #1,(gameNotInProgressCounterWriteOnly).l
                move.w  lastFrameTicks(pc),d0
                add.w   d0,(stoppageTimerTotal).l
                cmpi.w  #ST_WAITING_ON_PLAYER,(gameStatePl).l
                bne.s   not_waiting_on_player
                add.w   d0,(stoppageTimerActive).l
                movea.l lastTeamPlayedBeforeBreak(pc),a6
                tst.w   TEAMGENERALINFO_PLAYERNUMBER(a6)
                bne.s   jump_out
                cmpi.w  #750,(stoppageTimerActive).l
                bcs.s   jump_out
                jsr     PrepareForInitialKick
                addq.w  #1,(initialKickWriteOnlyTicks).l
                bra.w   _1124F4_out
jump_out:
                bra.w   _1124F4_out
not_waiting_on_player:
                cmpi.w  #ST_STARTING_GAME,(gameState).l
                bcs.w   game_interrupted
                cmpi.w  #ST_GAME_ENDED,(gameState).l
                bhi.w   game_interrupted
                tst.b   (topTeamData+TEAMGENERALINFO_FIREPRESSED).l
                bne.s   end_game_transmission
                tst.b   (bottomTeamData+TEAMGENERALINFO_FIREPRESSED).l
                bne.s   end_game_transmission
                cmpi.w  #1,(topTeamData+TEAMGENERALINFO_PLAYERCOACHNUMBER).l
                beq.s   check_pl1_fire
                cmpi.w  #1,(bottomTeamData+TEAMGENERALINFO_PLAYERCOACHNUMBER).l
                bne.s   check_for_pl2_coach
check_pl1_fire:
                jsr     Player1StatusProc ; Returns
                tst.b   (pl1Fire).l
                bne.s   end_game_transmission
check_for_pl2_coach:
                cmpi.w  #2,(topTeamData+TEAMGENERALINFO_PLAYERCOACHNUMBER).l
                beq.s   check_pl2_fire
                cmpi.w  #2,(bottomTeamData+TEAMGENERALINFO_PLAYERCOACHNUMBER).l
                bne.s   check_control_states_again
check_pl2_fire:
                jsr     Player2StatusProc ; Returns
                tst.b   (pl2Fire).l
                bne.s   end_game_transmission
check_control_states_again:
                cmpi.w  #ST_RESULT_AFTER_THE_GAME,(gameState).l
                bne.w   game_interrupted
                jsr     Player1StatusProc ; Returns
                tst.b   (pl1Fire).l
                bne.s   end_game_transmission
                jsr     Player2StatusProc ; Returns
                tst.b   (pl2Fire).l
                beq.w   game_interrupted
end_game_transmission:
                cmpi.w  #ST_RESULT_ON_HALFTIME,(gameState).l
                bne.s   not_half_time_result
                neg.w   (resultTimer).l
                neg.w   (timeVar).l
                neg.w   (statsTimer).l
                bsr.w   SetCameraMovingToShowerState
                bsr.w   PrepareForInitialKick
                clr.w   (stoppageEventTimer).l
                bra.w   _1124F4_out
not_half_time_result:
                cmpi.w  #ST_RESULT_AFTER_THE_GAME,(gameState).l
                bne.s   not_result_after_the_game
                neg.w   (resultTimer).l
                neg.w   (timeVar).l
                neg.w   (statsTimer).l
                clr.w   (playGame).l
                clr.w   (stoppageEventTimer).l
                bra.w   _1124F4_out
not_result_after_the_game:
                cmpi.w  #ST_STARTING_GAME,(gameState).l
                bne.s   game_not_starting
                clr.w   (showFansCounter).l
                bsr.w   PrepareForInitialKick
                clr.w   (stoppageEventTimer).l
                bra.w   _1124F4_out
game_not_starting:
                cmpi.w  #ST_CAMERA_GOING_TO_SHOWERS,(gameState).l
                bne.s   game_interrupted
                bsr.w   PrepareForInitialKick
                clr.w   (stoppageEventTimer).l
                bra.w   _1124F4_out
game_interrupted:
                tst.w   (stoppageEventTimer).l
                beq.w   event_triggered
                move.w  lastFrameTicks(pc),d0
                sub.w   d0,(stoppageEventTimer).l
                bgt.w   _1124F4_out
                clr.w   (stoppageEventTimer).l
event_triggered:
                movea.l lastTeamPlayedBeforeBreak(pc),a6
                lea     (ballSprite).l,a5
                cmpi.w  #ST_STOPPED,(gameStatePl).l
                bne.w   game_running
                cmpi.w  #ST_RESULT_ON_HALFTIME,(gameState).l
                bne.s   not_result_on_halftime
                neg.w   (resultTimer).l
                neg.w   (timeVar).l
                neg.w   (statsTimer).l
                bsr.w   SetCameraMovingToShowerState
                bra.w   _1124F4_out
not_result_on_halftime:
                cmpi.w  #ST_RESULT_AFTER_THE_GAME,(gameState).l
                bne.s   not_showing_end_game_result
                neg.w   (resultTimer).l
                neg.w   (timeVar).l
                neg.w   (statsTimer).l
                clr.w   (playGame).l
                bra.w   _1124F4_out
not_showing_end_game_result:
                cmpi.w  #ST_STARTING_GAME,(gameState).l
                bne.s   not_starting_the_game
                bsr.w   PrepareForInitialKick
                bra.w   _1124F4_out
not_starting_the_game:
                cmpi.w  #ST_CAMERA_GOING_TO_SHOWERS,(gameState).l
                bne.s   not_going_to_showers
                bsr.w   PrepareForInitialKick
                bra.w   _1124F4_out
not_going_to_showers:
                cmpi.w  #ST_FIRST_HALF_ENDED,(gameState).l
                bne.s   not_1st_half_ended
                bsr.w   FirstHalfJustEnded
                bra.w   _1124F4_out
not_1st_half_ended:
                cmpi.w  #ST_GOING_TO_HALFTIME,(gameState).l
                bne.s   not_going_to_halftime
                neg.w   (resultTimer).l
                neg.w   (timeVar).l
                neg.w   (statsTimer).l
                bsr.w   GoToHalftime
                bra.w   _1124F4_out
not_going_to_halftime:
                cmpi.w  #ST_GAME_ENDED,(gameState).l
                bne.s   game_not_ended
                bsr.w   PlayersLeavingPitch
                bra.w   _1124F4_out
game_not_ended:
                cmpi.w  #ST_PLAYERS_GOING_TO_SHOWER,(gameState).l
                bne.s   players_not_going_to_showers
                bsr.w   GameOver
                bra.w   _1124F4_out
players_not_going_to_showers:
                cmpi.w  #ST_FIRST_EXTRA_STARTING,(gameState).l
                bne.s   first_extra_not_starting
                bsr.w   PrepareForInitialKick
                bra.w   _1124F4_out
first_extra_not_starting:
                cmpi.w  #ST_FIRST_EXTRA_ENDED,(gameState).l
                bne.s   first_extra_not_ended
                bsr.w   PrepareForInitialKick
                bra.w   _1124F4_out
first_extra_not_ended:
                move.w  gameState(pc),(gameStatePl).l
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                bne.s   adjust_for_keeper_holds_ball
                tst.w   (inSubstitutesMenu).l
                bne.s   adjust_for_keeper_holds_ball
                tst.w   (cameraLeavingSubsTimer).l
                bne.s   adjust_for_keeper_holds_ball
                move.w  #31000,(timeVar).l
adjust_for_keeper_holds_ball:
                move.w  #0,(breakCameraMode).l
                bra.w   _1124F4_out
game_running:
                move.w  breakCameraMode(pc),d7
                tst.w   (inSubstitutesMenu).l
                bne.w   _1124F4_out
                tst.w   (waitForPlayerToGoInTimer).l
                bne.w   _1124F4_out
                cmpi.w  #0,d7
                bne.s   break_mode_1_branch
                tst.l   SPRITE_DELTAX(a5)
                bne.w   _1124F4_out
                tst.l   SPRITE_DELTAY(a5)
                bne.w   _1124F4_out
                move.w  #1,(breakCameraMode).l
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                beq.w   _1124F4_out
                move.w  #50,(stoppageEventTimer).l
                tst.w   (goalCameraMode).l
                beq.w   _1124F4_out
                move.w  #75,(stoppageEventTimer).l
                rts
break_mode_1_branch:
                cmpi.w  #1,d7
                bne.w   break_mode_2_branch
                cmpi.w  #ST_PENALTY,(gameState).l
                beq.s   game_stopped_handle_replay_highlight
                cmpi.w  #ST_PENALTIES,(gameState).l
                beq.s   game_stopped_handle_replay_highlight
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                beq.s   game_stopped_handle_replay_highlight
                cmpi.w  #ST_FOUL,(gameState).l
                beq.s   game_stopped_handle_replay_highlight
                cmpi.w  #ST_FREE_KICK_LEFT1,(gameState).l
                bcs.s   game_stopped_handle_replay_highlight
                cmpi.w  #ST_FREE_KICK_RIGHT3,(gameState).l
game_stopped_handle_replay_highlight:
                tst.w   (playingPenalties).l
                bne.s   no_auto_replay
                tst.w   (inSubstitutesMenu).l
                bne.s   no_auto_replay
                tst.w   (goalCameraMode).l
                beq.s   no_auto_replay
                tst.w   (autoSaveHighlights).l
                beq.s   no_auto_save_highlights
                move.w  #1,(saveHighlightScene).l
no_auto_save_highlights:
                tst.w   (autoReplays).l
                beq.s   no_auto_replay
                clr.w   (userRequestedReplay).l
                move.w  #1,(instantReplayFlag).l
no_auto_replay:
                clr.l   (currentScorer).l
                tst.w   (playingPenalties).l
                beq.s   set_ball_pos_after_stoppage
                cmpi.w  #ST_PENALTIES,(gameState).l
                beq.s   set_ball_pos_after_stoppage
                bra.w   _1124F4_out
set_ball_pos_after_stoppage:
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                beq.s   keeper_holds_the_ball
                move.w  foulXCoordinate(pc),d1
                move.w  foulYCoordinate(pc),d2
                jsr     SetBallPosition
keeper_holds_the_ball:
                move.w  #2,(breakCameraMode).l
                rts
break_mode_2_branch:
                cmpi.w  #2,d7
                bne.w   break_mode_4_branch
                tst.w   (whichCard).l
                bne.w   _1124F4_out
                tst.w   (cameraCoordinatesValid).l
                beq.w   _1124F4_out
                clr.w   (goalScored).l
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                bne.s   handle_keeper_holds_ball_break
                move.w  #$66,(gameStatePl).l ; 'f'
                clr.w   (inGameCounter).l
                move.w  gameState(pc),(breakState).l
handle_keeper_holds_ball_break:
                tst.w   (topTeamData+TEAMGENERALINFO_RESETCONTROLS).l
                bne.s   handle_team2_reset_controls
                movea.l topTeamData+TEAMGENERALINFO_SPRITESTABLE(pc),a0
                move.w  #10,d0
set_team1_players_dest_reached:
                movea.l (a0)+,a1
                move.w  #1,SPRITE_DESTREACHEDSTATE(a1)
                dbf     d0,set_team1_players_dest_reached
handle_team2_reset_controls:
                tst.w   (bottomTeamData+TEAMGENERALINFO_RESETCONTROLS).l
                bne.s   maybe_set_goalies_dest_reached
                movea.l bottomTeamData+TEAMGENERALINFO_SPRITESTABLE(pc),a0
                move.w  #10,d0
set_team2_players_dest_reached:
                movea.l (a0)+,a1
                move.w  #1,SPRITE_DESTREACHEDSTATE(a1)
                dbf     d0,set_team2_players_dest_reached
maybe_set_goalies_dest_reached:
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                bne.s   set_break_mode_4
                move.w  #3,(goalie1Sprite+SPRITE_DESTREACHEDSTATE).l
                move.w  #3,(goalie2Sprite+SPRITE_DESTREACHEDSTATE).l
set_break_mode_4:
                move.w  #4,(breakCameraMode).l
                rts
break_mode_4_branch:
                cmpi.w  #4,d7
                bne.s   break_mode_3_branch
                tst.w   (inSubstitutesMenu).l
                bne.w   _1124F4_out
                move.w  #3,(breakCameraMode).l
                rts
break_mode_3_branch:
                cmpi.w  #3,d7
                bne.w   break_mode_5_branch
                tst.w   (refState).l
                bne.w   _1124F4_out
                tst.w   (injuriesForever).l
                bne.w   _1124F4_out
                lea     (team1SpritesTable).l,a0
                move.w  #21,d0
iterate_all_players_for_anim_state:
                movea.l (a0)+,a1
                cmpi.w  #ST_PLAYERS_TO_INITIAL_POSITIONS,(gameState).l
                beq.s   require_player_state_3_or_abort
                cmpi.w  #ST_PENALTY,(gameState).l
                beq.s   require_player_state_3_or_abort
                cmpi.w  #ST_PENALTIES,(gameState).l
                beq.s   require_player_state_3_or_abort
                tst.w   SPRITE_ONSCREEN(a1)
                beq.s   next_player
require_player_state_3_or_abort:
                cmpi.w  #3,SPRITE_DESTREACHEDSTATE(a1)
                bne.w   _1124F4_out
next_player:
                dbf     d0,iterate_all_players_for_anim_state
                clr.w   (runSlower).l
                tst.w   (goalCameraMode).l
                beq.s   set_break_mode_5_reset_patterns_if_goalcam
                movem.l d0-d7/a0-a6,-(sp)
                jsr     ResetAnimatedPatternsForBothTeams
                movem.l (sp)+,d0-d7/a0-a6
set_break_mode_5_reset_patterns_if_goalcam:
                move.w  #5,(breakCameraMode).l
                rts
break_mode_5_branch:
                cmpi.w  #5,d7
                bne.s   break_mode_6_branch
                clr.w   (whichCard).l
                clr.l   (bookedPlayer).l
                move.w  #6,(breakCameraMode).l
                rts
break_mode_6_branch:
                cmpi.w  #6,d7
                bne.s   break_mode_7_branch
                clr.w   (ballOutOfGameTimer).l
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                beq.s   set_break_mode_7
                move.w  #31000,(timeVar).l
set_break_mode_7:
                move.w  #7,(breakCameraMode).l
                rts
break_mode_7_branch:
                cmpi.w  #7,d7
                bne.w   break_mode_8_branch
                move.w  #1,TEAMGENERALINFO_BALLINPLAY(a6)
                addq.w  #1,(ballOutOfGameTimer).l
                cmpi.w  #500,(ballOutOfGameTimer).l
                bcs.s   prepare_throw_in_anim
                addq.w  #1,(deadCameraBreakVar01).l
                move.w  gameStatePl(pc),(deadCameraBreakVar02).l
                move.w  gameState(pc),(deadCameraBreakVar03).l
                jsr     CheckIfGoalkeeperClaimedTheBall
                addq.w  #1,(deadCameraBreakVar04).l
                bra.w   _1124F4_out
prepare_throw_in_anim:
                tst.l   TEAMGENERALINFO_CONTROLLEDPLAYER(a6)
                beq.w   _1124F4_out
                movea.l TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a1
                cmpi.b  #PL_THROW_IN,SPRITE_PLAYERSTATE(a1)
                beq.s   set_throw_in_anim_table
                lea     (playerNormalStandingAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                bra.s   finalize_throw_in_setup
set_throw_in_anim_table:
                lea     (aboutToThrowInAnimTable).l,a0
                jsr     SetPlayerAnimationTable
finalize_throw_in_setup:
                move.w  #1,TEAMGENERALINFO_BALLOUTOFPLAY(a6)
                move.w  #8,(breakCameraMode).l
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                beq.w   _1124F4_out
                tst.w   (inSubstitutesMenu).l
                bne.w   _1124F4_out
                move.w  #31000,(resultTimer).l
                rts
break_mode_8_branch:
                cmpi.w  #8,d7
                bne.w   assert_failed
                clr.w   (stoppageAuxFlag).l
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                beq.s   clear_goalcam_and_wait_player
                jsr     PlayRefereeWhistleSample
clear_goalcam_and_wait_player:
                clr.w   (goalCameraMode).l
                move.w  #ST_WAITING_ON_PLAYER,(gameStatePl).l
                clr.w   (inGameCounter).l
                move.w  gameState(pc),(breakState).l
_1124F4_out:
                rts
assert_failed:
                move.w  #$B,(panicReasonCode).l
                jsr     PanicHaltLoop
ballOutOfGameTimer:
                dc.w $0000              ; I think this is timer for camera when the ball goes out of play
stoppageAuxFlag:
                dc.w $0000

; ===== UpdateAndApplyTeamControls =====
; prototype: void __usercall UpdateAndApplyTeamControls()
; Sets control related fields in team structure. Called once per frame.
; Handles one team per frame (next team in next frame).
UpdateAndApplyTeamControls:
                bsr.w   UpdateGameTimersAndCameraBreakMode
                tst.w   (fireBlocked).l
                beq.s   select_team_for_poll
                jsr     Player1StatusProc ; Returns
                tst.b   (pl1Fire).l
                bne.w   _1126D6_exit_rts
                jsr     Player2StatusProc ; Returns
                tst.b   (pl2Fire).l
                bne.w   _1126D6_exit_rts
                clr.w   (fireBlocked).l
                clr.w   (pl1FireCounter).l
                clr.w   (pl2FireCounter).l
                bra.w   _1126D6_exit_rts
select_team_for_poll:
                lea     topTeamData(pc),a6
                btst    #0,frameCount+1(pc)
                bne.s   update_primary_and_secondary_selection
                lea     bottomTeamData(pc),a6
update_primary_and_secondary_selection:
                bsr.w   UpdateControlledPlayer
                bsr.w   UpdatePlayerBeingPassedTo
                move.w  4(a6),d0
                beq.w   post_input_common_p1
                cmpi.w  #2,d0
                beq.w   read_joy0
                jsr     Player1StatusProc ; Returns
                move.w  pl1Direction(pc),TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                move.w  pl1Direction(pc),TEAMGENERALINFO_DIRECTION(a6)
                move.b  pl1ShortFire(pc),TEAMGENERALINFO_FIRETHISFRAME(a6)
                move.b  pl1Fire(pc),TEAMGENERALINFO_FIREPRESSED(a6)
                beq.s   clear_fire_hold_counter_p1
                addq.w  #1,TEAMGENERALINFO_FIRECOUNTER(a6)
                bra.s   update_button_flags_from_cycles_p1
clear_fire_hold_counter_p1:
                clr.w   TEAMGENERALINFO_FIRECOUNTER(a6)
update_button_flags_from_cycles_p1:
                move.w  pl1FireCounter(pc),d0
                sne     TEAMGENERALINFO_QUICKFIRE(a6)
                sne     TEAMGENERALINFO_NORMALFIRE(a6)
                beq.s   post_input_common_p1
                bmi.s   clear_button_flags_if_negative_p1
                cmpi.w  #4,d0
                sle     TEAMGENERALINFO_QUICKFIRE(a6)
                sgt     TEAMGENERALINFO_NORMALFIRE(a6)
                clr.w   (pl1FireCounter).l
                bra.s   post_input_common_p1
clear_button_flags_if_negative_p1:
                clr.b   TEAMGENERALINFO_QUICKFIRE(a6)
                tst.b   TEAMGENERALINFO_NORMALFIRE(a6)
                beq.s   threshold_repeat_check_p1
                clr.b   TEAMGENERALINFO_NORMALFIRE(a6)
threshold_repeat_check_p1:
                clr.b   TEAMGENERALINFO_QUICKFIRE(a6)
                cmpi.w  #$FFFC,d0
                slt     TEAMGENERALINFO_NORMALFIRE(a6)
                bge.s   post_input_common_p1
                clr.w   (pl1FireCounter).l
post_input_common_p1:
                tst.w   TEAMGENERALINFO_RESETCONTROLS(a6)
                bne.w   _1126D6_exit_rts
                tst.w   (inSubstitutesMenu).l
                beq.s   apply_input_and_update_players_p1
                move.w  #$FFFF,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                clr.b   TEAMGENERALINFO_QUICKFIRE(a6)
                clr.b   TEAMGENERALINFO_NORMALFIRE(a6)
                clr.b   TEAMGENERALINFO_FIREPRESSED(a6)
                clr.b   TEAMGENERALINFO_FIRETHISFRAME(a6)
                clr.w   TEAMGENERALINFO_FIRECOUNTER(a6)
apply_input_and_update_players_p1:
                bsr.w   UpdatePlayers
                tst.w   TEAMGENERALINFO_HEADERORTACKLE(a6)
                beq.w   _1126D6_exit_rts
                clr.w   TEAMGENERALINFO_HEADERORTACKLE(a6)
                clr.w   (pl1FireCounter).l
                rts
read_joy0:
                jsr     Player2StatusProc ; Returns
                move.w  pl2Direction(pc),TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                move.w  pl2Direction(pc),TEAMGENERALINFO_DIRECTION(a6)
                move.b  pl2ShortFire(pc),TEAMGENERALINFO_FIRETHISFRAME(a6)
                move.b  pl2Fire(pc),TEAMGENERALINFO_FIREPRESSED(a6)
                move.b  pl2Fire(pc),TEAMGENERALINFO_FIREPRESSED(a6)
                beq.s   clear_fire_hold_counter_p2
                addq.w  #1,TEAMGENERALINFO_FIRECOUNTER(a6)
                bra.s   update_button_flags_from_cycles_p2
clear_fire_hold_counter_p2:
                clr.w   TEAMGENERALINFO_FIRECOUNTER(a6)
update_button_flags_from_cycles_p2:
                move.w  pl2FireCounter(pc),d0
                sne     TEAMGENERALINFO_QUICKFIRE(a6)
                sne     TEAMGENERALINFO_NORMALFIRE(a6)
                beq.s   post_input_common_p2
                bmi.s   clear_button_flags_if_negative_p2
                cmpi.w  #4,d0
                sle     TEAMGENERALINFO_QUICKFIRE(a6)
                sgt     TEAMGENERALINFO_NORMALFIRE(a6)
                clr.w   (pl2FireCounter).l
                bra.s   post_input_common_p2
clear_button_flags_if_negative_p2:
                clr.b   TEAMGENERALINFO_QUICKFIRE(a6)
                tst.b   TEAMGENERALINFO_NORMALFIRE(a6)
                beq.s   threshold_repeat_check_p2
                clr.b   TEAMGENERALINFO_NORMALFIRE(a6)
threshold_repeat_check_p2:
                clr.b   TEAMGENERALINFO_QUICKFIRE(a6)
                cmpi.w  #$FFFC,d0
                slt     TEAMGENERALINFO_NORMALFIRE(a6)
                bge.s   post_input_common_p2
                clr.w   (pl2FireCounter).l
post_input_common_p2:
                tst.w   TEAMGENERALINFO_RESETCONTROLS(a6)
                bne.s   _1126D6_exit_rts
                tst.w   (inSubstitutesMenu).l
                beq.s   apply_input_and_update_players_p2
                move.w  #$FFFF,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                clr.b   TEAMGENERALINFO_QUICKFIRE(a6)
                clr.b   TEAMGENERALINFO_NORMALFIRE(a6)
                clr.b   TEAMGENERALINFO_FIREPRESSED(a6)
                clr.b   TEAMGENERALINFO_FIRETHISFRAME(a6)
                clr.w   TEAMGENERALINFO_FIRECOUNTER(a6)
apply_input_and_update_players_p2:
                bsr.w   UpdatePlayers
                tst.w   TEAMGENERALINFO_HEADERORTACKLE(a6)
                beq.s   _1126D6_exit_rts
                clr.w   TEAMGENERALINFO_HEADERORTACKLE(a6)
                clr.w   (pl2FireCounter).l
_1126D6_exit_rts:
                rts

; ===== SetJumpHeaderHitAnimTable =====
; prototype: void __usercall SetJumpHeaderHitAnimTable(Sprite *player@<a1>)
; in:
;      A1 -> player
SetJumpHeaderHitAnimTable:
                cmpi.l  #jumpHeaderHitAnimTable,SPRITE_ANIMATIONTABLE(a1)
                beq.s   _112710_exit_rts
                tst.w   SPRITE_HEADING(a1)
                bne.s   _112710_exit_rts
                cmpi.b  #40,SPRITE_PLAYERDOWNTIMER(a1)
                bne.s   _112710_exit_rts
                cmpi.w  #2,SPRITE_FRAMESWITCHCOUNTER(a1)
                bhi.s   _112710_exit_rts
                btst    #1,currentGameTick+1(pc)
                beq.s   _112710_exit_rts
                lea     (jumpHeaderHitAnimTable).l,a0
                jsr     SetPlayerAnimationTableAndPictureIndex
                lsr     SPRITE_SPEED(a1)
_112710_exit_rts:
                rts

; ===== PlayerHittingJumpHeader =====
; prototype: void __usercall PlayerHittingJumpHeader(Sprite *player@<a1>, TeamGeneralInfo *team@<a6>)
; in:
;     A1 -> player
;     A6 -> team
; 
; Hitting flying or lob header. Only triggers on ball contact.
PlayerHittingJumpHeader:
                clr.w   TEAMGENERALINFO_PASSINPROGRESS(a6)
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d1
                bpl.s   header_ref_dir_from_input_or_player_dir
                move.w  SPRITE_DIRECTION(a1),d1
header_ref_dir_from_input_or_player_dir:
                lea     (ballSprite).l,a2
                move.l  kBallJumpHeaderDeltaZ(pc),SPRITE_DELTAZ(a2)
                move.w  SPRITE_SPEED(a1),SPRITE_SPEED(a2)
                move.w  SPRITE_SPEED(a1),d0
                lsr.w   #2,d0
                add.w   d0,SPRITE_SPEED(a2)
                move.w  SPRITE_DIRECTION(a1),d0
                sub.w   d1,d0
                tst.w   TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                bmi.w   header_when_direction_blocked
                andi.w  #7,d0
                beq.w   header_keep_dir
                cmpi.w  #4,d0
                beq.w   header_case_opposite_dir
                cmpi.w  #1,d0
                beq.w   header_decrement_dir
                cmpi.w  #7,d0
                beq.w   header_increment_dir
                cmpi.w  #2,d0
                beq.s   header_adjust_then_decrement_path_fast
                cmpi.w  #6,d0
                beq.s   header_adjust_then_increment_path
                cmpi.w  #3,d0
                beq.s   header_adjust_then_decrement_path
                bsr.w   DoLobHeader
                bra.w   header_increment_dir
header_adjust_then_decrement_path:
                bsr.w   DoLobHeader
                bra.s   header_decrement_dir
header_adjust_then_increment_path:
                bsr.w   DoFlyingHeader
                bra.s   header_increment_dir
header_adjust_then_decrement_path_fast:
                bsr.w   DoFlyingHeader
                bra.s   header_decrement_dir
header_when_direction_blocked:
                bsr.w   DoFlyingHeader
                bra.s   header_keep_dir
header_case_opposite_dir:
                bsr.w   DoLobHeader
                bra.s   header_keep_dir
header_increment_dir:
                move.w  SPRITE_DIRECTION(a1),d0
                addq.w  #1,d0
                bra.s   header_apply_dir_and_set_ball_dest
header_decrement_dir:
                move.w  SPRITE_DIRECTION(a1),d0
                subq.w  #1,d0
                bra.s   header_apply_dir_and_set_ball_dest
header_keep_dir:
                move.w  SPRITE_DIRECTION(a1),d0
header_apply_dir_and_set_ball_dest:
                andi.w  #7,d0
                move.w  d0,TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6)
                lea     kDefaultDestinations(pc),a0
                lsl.w   #2,d0
                move.w  (a0,d0.w),d1
                add.w   SPRITE_X(a2),d1
                move.w  d1,SPRITE_DESTX(a2)
                move.w  SPRITE_Y(a2),d1
                add.w   2(a0,d0.w),d1
                move.w  d1,SPRITE_DESTY(a2)
                bsr.w   GetPlayerPointerFromShirtNumber
                lea     kPlayerHeaderSpeedIncrease(pc),a0
                move.b  PLAYERINFOHEADER_HEADING(a4),d0
                ext.w   d0
                lsl.w   #1,d0
                move.w  (a0,d0.w),d0
                add.w   d0,SPRITE_SPEED(a2)
                lsr     SPRITE_SPEED(a1)
                move.w  #1,SPRITE_HEADING(a1)
                jsr     PlayKickSample
                bsr.w   ResetBothTeamSpinTimers
                rts

; ===== DoFlyingHeader =====
; prototype: void __usercall DoFlyingHeader(Sprite *player@<a1>, Sprite *ball@<a2>)
DoFlyingHeader:
                move.l  (kHeaderLowJumpHeight).l,SPRITE_DELTAZ(a2)
                move.w  SPRITE_SPEED(a2),d0
                lsr.w   #2,d0
                sub.w   d0,SPRITE_SPEED(a2) ; speed = 75%
                bsr.w   SetPlayerJumpHeaderHitAnimationTable
                rts

; ===== DoLobHeader =====
; prototype: void __usercall DoLobHeader(struct Sprite *player@<a1>, struct Sprite *ball@<a2>)
; in:
;     A1 -> player sprite
;     A2 -> ball sprite
DoLobHeader:
                move.l  (kHeaderHighJumpHeight).l,SPRITE_DELTAZ(a2)
                move.w  SPRITE_SPEED(a2),d0
                lsr.w   #4,d0
                sub.w   d0,SPRITE_SPEED(a2) ; speed = 93.75%
                bsr.w   SetPlayerJumpHeaderHitAnimationTable
                rts

; ===== SetPlayerJumpHeaderHitAnimationTable =====
; prototype: void __usercall SetPlayerJumpHeaderHitAnimationTable(Sprite *player@<a1>)
; in:
;     A1 -> player sprite
; 
; Table for flying and lob headers.
SetPlayerJumpHeaderHitAnimationTable:
                cmpi.w  #2,SPRITE_FRAMESWITCHCOUNTER(a1)
                bhi.s   locret_11284E
                lea     (jumpHeaderHitAnimTable).l,a0
                jsr     SetPlayerAnimationTableAndPictureIndex
locret_11284E:
                rts
kHeaderLowJumpHeight:
                dc.l $00020000          ; =2.0, For flying headers
kHeaderHighJumpHeight:
                dc.l $00024000          ; =4.25, For lob headers

; ===== SetStaticHeaderDirection =====
; prototype: void __usercall SetStaticHeaderDirection(Sprite *player@<a1>, TeamGeneralInfo *team@<a6>)
; in:
;      A1 -> player (sprite)
;      A6 -> team general data
; 
; Static header was activated now we need to aim it somewhere.
SetStaticHeaderDirection:
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d0
                bmi.w   _1128A0_exit_rts
                cmpi.b  #18,SPRITE_PLAYERDOWNTIMER(a1)
                bhi.s   _1128A0_exit_rts
                cmpi.l  #staticHeaderAttemptAnimTable,SPRITE_ANIMATIONTABLE(a1)
                bne.s   _1128A0_exit_rts
                sub.w   SPRITE_DIRECTION(a1),d0
                beq.s   apply_static_header_aim_anim
                andi.w  #7,d0
                cmpi.w  #4,d0
                beq.s   apply_static_header_aim_anim
                bcs.s   _11288A_turn_towards_input_increment
                subq.w  #1,SPRITE_DIRECTION(a1)
                bra.s   _11288E_apply_dir_wrap_mod8
_11288A_turn_towards_input_increment:
                addq.w  #1,SPRITE_DIRECTION(a1)
_11288E_apply_dir_wrap_mod8:
                andi.w  #7,SPRITE_DIRECTION(a1)
apply_static_header_aim_anim:
                lea     (staticHeaderAimAnimTable).l,a0
                jsr     SetPlayerAnimationTableAndPictureIndex
_1128A0_exit_rts:
                rts

; ===== PlayerHittingStaticHeader =====
; prototype: void __usercall PlayerHittingStaticHeader(Sprite *player@<a1>, TeamGeneralInfo *team@<a6>)
; in:
;      A1 -> player (sprite)
;      A6 -> team general info
; 
; Runs when a player makes contact with the ball while doing static header.
; Applies ball speed and destination. Increases player speed, updates delta z
; and plays kick sample.
PlayerHittingStaticHeader:
                clr.w   TEAMGENERALINFO_PASSINPROGRESS(a6)
                cmpi.l  #staticHeaderHitAnimTable,SPRITE_ANIMATIONTABLE(a1)
                beq.s   apply_hit_anim_and_continue
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d0
                sub.w   TEAMGENERALINFO_ALLOWEDDIRECTIONS(a1),d0
                beq.s   apply_hit_anim_and_continue
                andi.w  #7,d0
                cmpi.w  #4,d0
                beq.s   apply_hit_anim_and_continue
                bcs.s   _1128E0_turn_towards_input_increment
                move.w  SPRITE_SPEED(a6),d0
                subq.w  #1,SPRITE_DIRECTION(a1)
                andi.w  #7,SPRITE_DIRECTION(a1)
                cmp.w   SPRITE_DIRECTION(a1),d0
                beq.s   _1128F8_apply_dir_wrap_mod8
                subq.w  #1,SPRITE_DIRECTION(a1)
                bra.s   _1128F8_apply_dir_wrap_mod8
_1128E0_turn_towards_input_increment:
                move.w  SPRITE_SPEED(a6),d0
                addq.w  #1,SPRITE_DIRECTION(a1)
                andi.w  #7,SPRITE_DIRECTION(a1)
                cmp.w   SPRITE_DIRECTION(a1),d0
                beq.s   _1128F8_apply_dir_wrap_mod8
                addq.w  #1,SPRITE_DIRECTION(a1)
_1128F8_apply_dir_wrap_mod8:
                andi.w  #7,SPRITE_DIRECTION(a1)
apply_hit_anim_and_continue:
                lea     (staticHeaderHitAnimTable).l,a0
                jsr     SetPlayerAnimationTableAndPictureIndex
                move.w  SPRITE_SPEED(a6),d1
                bpl.s   start_header_hit_direction_and_target
                move.w  SPRITE_DIRECTION(a1),d1
start_header_hit_direction_and_target:
                lea     (ballSprite).l,a2
                move.w  d1,d0
                move.w  d0,TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6)
                lea     kDefaultDestinations(pc),a0
                lsl.w   #2,d0
                move.w  (a0,d0.w),d1
                add.w   SPRITE_X(a2),d1
                move.w  d1,SPRITE_DESTX(a2)
                move.w  SPRITE_Y(a2),d1
                add.w   2(a0,d0.w),d1
                move.w  d1,SPRITE_DESTY(a2)
                move.w  (kStaticHeaderBaseBallSpeed).l,SPRITE_SPEED(a2)
                bsr.w   GetPlayerPointerFromShirtNumber
                lea     kPlayerHeaderSpeedIncrease(pc),a0
                move.b  PLAYERINFOHEADER_HEADING(a4),d0
                ext.w   d0
                lsl.w   #1,d0
                move.w  (a0,d0.w),d0
                add.w   d0,SPRITE_SPEED(a2)
                move.l  SPRITE_DELTAZ(a2),d0
                neg.l   d0
                asr.l   #1,d0
                move.l  d0,SPRITE_DELTAZ(a2)
                move.w  #1,SPRITE_HEADING(a1)
                jsr     PlayKickSample
                bsr.w   ResetBothTeamSpinTimers
                rts
kStaticHeaderBaseBallSpeed:
                dc.w $0700

; ===== AttemptStaticHeader =====
; prototype: void __usercall AttemptStaticHeader(struct Sprite *player@<a1>, unsigned __int16 dir@<d0>)
; in:
;      D0 - some direction
;      A1 -> player sprite
; 
; Players jumps in place trying to hit static header.
AttemptStaticHeader:
                clr.w   SPRITE_HEADING(a1)
                move.w  d0,SPRITE_DIRECTION(a1)
                lea     kDefaultDestinations(pc),a5
                lsl.w   #2,d0
                lea     (a5,d0.w),a5
                move.w  (a5)+,d0
                add.w   SPRITE_X(a1),d0
                move.w  d0,SPRITE_DESTX(a1)
                move.w  (a5),d0
                add.w   SPRITE_Y(a1),d0
                move.w  d0,SPRITE_DESTY(a1)
                move.w  (kStaticHeaderPlayerSpeed).l,SPRITE_SPEED(a1)
                lea     (staticHeaderAttemptAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                move.b  #PL_STATIC_HEADING,SPRITE_PLAYERSTATE(a1)
                move.b  #20,SPRITE_PLAYERDOWNTIMER(a1)
                rts
kStaticHeaderPlayerSpeed:
                dc.w $0100              ; =1.0
ballDefensiveX:
                dc.w $0000              ; Only updates inside penalty areas
ballDefensiveY:
                dc.w $0000
ballDefensiveZ:
                dc.w $0000
ballNotHighX:
                dc.w $0000
ballNotHighY:
                dc.w $0000
ballNotHighZ:
                dc.w $0000              ; Ball z for the goalkeeper
strikeDestX:
                dc.w $0000              ; If strike is crossing pitch line by y
strikeDestY:
                dc.w $0000
strikeDestZ:
                dc.w $0000
ballNextGroundX:
                dc.w $0000
ballNextYGroundY:
                dc.w $0000
ballNextZDeadVar:
                dc.w $0000              ; Not much sense anyway, since z goes to zero (or close) during the calculations
cardAnimStatesNoFlag:
                dc.b 0,1,3,3,3          ; Red card tables
cardAnimStatesWithFlag:
                dc.b 1,2,4,4,4

; ===== TryBookingThePlayer =====
; prototype: unsigned __int16 __usercall TryBookingThePlayer@<d0>(Sprite *player@<a1>, TeamGeneralInfo *team@<a6>)
; in:
;      A1 -> player sprite
;      A6 -> team (general)
; out:
;      zero flag = 1, D0 = 0, card given
;      zero flag = 0, D0 = 1, card not given
TryBookingThePlayer:
                tst.w   (plgD3Param).l
                bne.s   if_highlight_started
                tst.w   TEAMGENERALINFO_PLAYERNUMBER(a6)
                bne.s   if_player_already_booked
                tst.w   TEAMGENERALINFO_PLAYERCOACHNUMBER(a6)
                bne.s   if_player_already_booked
                bra.w   return_not_eligible
if_highlight_started:
                tst.w   TEAMGENERALINFO_PLAYERNUMBER(a6)
                bne.s   if_player_already_booked
                tst.w   TEAMGENERALINFO_PLAYERCOACHNUMBER(a6)
                bne.s   if_player_already_booked
                tst.w   SPRITE_CARDS(a1)
                bne.w   return_not_eligible
if_player_already_booked:
                tst.w   SPRITE_CARDS(a1)
                beq.s   resolve_player_ingame_slot
                cmpi.w  #1,TEAMGENERALINFO_TEAMNUMBER(a6)
                bne.s   _112A30_check_team2_injury_quota
                tst.w   (team1NumAllowedInjuries).l
                beq.w   return_not_eligible
                bra.s   resolve_player_ingame_slot
_112A30_check_team2_injury_quota:
                tst.w   (team2NumAllowedInjuries).l
                beq.w   return_not_eligible
resolve_player_ingame_slot:
                movea.l TEAMGENERALINFO_INGAMETEAMPTR(a6),a5
                move.w  SPRITE_PLAYERORDINAL(a1),d0
                subq.w  #1,d0
                lsl.w   #1,d0
                lea     (ingameTeamPlayerOffsets).l,a0
                move.w  (a0,d0.w),d0
                lea     (a5,d0.w),a5
                move.w  SPRITE_CARDS(a1),d0
                addq.w  #1,d0
                tst.w   (plgD3Param).l
                bne.s   highlight_started_card_state
                lea     cardAnimStatesNoFlag(pc),a0
                tst.b   PLAYERINFOHEADER_PREVIOUSCARDS(a5)
                beq.s   apply_ref_card_state_from_LUT
                lea     cardAnimStatesWithFlag(pc),a0
apply_ref_card_state_from_LUT:
                move.b  PLAYERINFOHEADER_CARDS(a5),d1
                move.b  (a0,d0.w),PLAYERINFOHEADER_CARDS(a5)
                bra.s   done_set_ref_state
highlight_started_card_state:
                move.b  PLAYERINFOHEADER_CARDS(a5),d1
                tst.b   d1
                bne.s   set_ref_state_show_card
                move.b  #1,PLAYERINFOHEADER_CARDS(a5)
                bra.s   commit_booking_and_start_ref
set_ref_state_show_card:
                move.b  #3,PLAYERINFOHEADER_CARDS(a5)
done_set_ref_state:
                bra.s   commit_booking_and_start_ref
return_not_eligible:
                move.w  #1,d0
                rts
commit_booking_and_start_ref:
                addq.w  #1,SPRITE_CARDS(a1)
                move.l  a6,(lastTeamBooked).l
                move.l  a1,(bookedPlayer).l
                clr.w   (refTimer).l
                cmpi.w  #2,SPRITE_CARDS(a1)
                beq.s   issue_red_card
                move.w  #CARD_YELLOW,(whichCard).l
                movea.l TEAMGENERALINFO_TEAMSTATSPTR(a6),a0
                addq.w  #1,TEAMSTATISTICSDATA_BOOKINGS(a0)
                clr.w   d0
                rts
issue_red_card:
                move.w  #CARD_SECOND_YELLOW,(whichCard).l
                movea.l TEAMGENERALINFO_TEAMSTATSPTR(a6),a0
                subq.w  #1,TEAMSTATISTICSDATA_BOOKINGS(a0)
                addq.w  #1,TEAMSTATISTICSDATA_SENDINGSOFF(a0)
                cmpi.w  #1,TEAMGENERALINFO_TEAMNUMBER(a6)
                bne.s   _112AF0_dec_team2_allowed_injuries
                subq.w  #1,(team1NumAllowedInjuries).l
                bra.s   return_card_issued
_112AF0_dec_team2_allowed_injuries:
                subq.w  #1,(team2NumAllowedInjuries).l
return_card_issued:
                clr.w   d0
                rts

; ===== TrySendingOffThePlayer =====
; prototype: unsigned __int16 __usercall TrySendingOffThePlayer@<d0>(Sprite *player@<a1>, TeamGeneralInfo *team@<a6>)
; in:
;      A1 -> player (sprite)
;      A6 -> team (general)
TrySendingOffThePlayer:
                tst.w   TEAMGENERALINFO_PLAYERNUMBER(a6)
                bne.s   check_team1_injury_quota_else_team2
                tst.w   TEAMGENERALINFO_PLAYERCOACHNUMBER(a6)
                beq.w   early_exit_not_eligible
check_team1_injury_quota_else_team2:
                cmpi.w  #1,TEAMGENERALINFO_TEAMNUMBER(a6)
                bne.s   _112B1C_check_team2_injury_quota
                tst.w   (team1NumAllowedInjuries).l
                beq.w   early_exit_not_eligible
                bra.s   load_player_slot_and_select_anim_table
_112B1C_check_team2_injury_quota:
                tst.w   (team2NumAllowedInjuries).l
                beq.w   early_exit_not_eligible
load_player_slot_and_select_anim_table:
                movea.l TEAMGENERALINFO_INGAMETEAMPTR(a6),a5
                move.w  SPRITE_PLAYERORDINAL(a1),d0
                subq.w  #1,d0
                lsl.w   #1,d0
                lea     (ingameTeamPlayerOffsets).l,a0
                move.w  (a0,d0.w),d0
                lea     (a5,d0.w),a5
                move.w  SPRITE_CARDS(a1),d0
                eori.w  #1,d0
                addq.w  #3,d0
                tst.w   (plgD3Param).l
                bne.s   force_anim_state_during_highlight
                lea     cardAnimStatesNoFlag(pc),a0
                tst.b   PLAYERINFOHEADER_PREVIOUSCARDS(a5)
                beq.s   set_ref_anim_state_from_table
                lea     cardAnimStatesWithFlag(pc),a0
set_ref_anim_state_from_table:
                move.b  PLAYERINFOHEADER_CARDS(a5),d1
                move.b  (a0,d0.w),PLAYERINFOHEADER_CARDS(a5)
                bra.s   go_finalize_red_or_exit
force_anim_state_during_highlight:
                move.b  PLAYERINFOHEADER_CARDS(a5),d1
                move.b  #3,PLAYERINFOHEADER_CARDS(a5)
go_finalize_red_or_exit:
                bra.s   finalize_straight_red
early_exit_not_eligible:
                move.w  #1,d0
                rts
finalize_straight_red:
                move.l  a6,(lastTeamBooked).l
                move.l  a1,(bookedPlayer).l
                clr.w   (refTimer).l
                move.w  #CARD_RED,(whichCard).l
                movea.l TEAMGENERALINFO_TEAMSTATSPTR(a6),a0
                cmpi.w  #1,SPRITE_CARDS(a1)
                bne.s   inc_team_sendings_off_stat
                subq.w  #1,TEAMSTATISTICSDATA_BOOKINGS(a0)
inc_team_sendings_off_stat:
                addq.w  #1,TEAMSTATISTICSDATA_SENDINGSOFF(a0)
                cmpi.w  #1,TEAMGENERALINFO_TEAMNUMBER(a6)
                bne.s   _112BBC_dec_team2_allowed_injuries
                subq.w  #1,(team1NumAllowedInjuries).l
                bra.s   return_success_red_card
_112BBC_dec_team2_allowed_injuries:
                subq.w  #1,(team2NumAllowedInjuries).l
return_success_red_card:
                clr.w   d0
                rts

; ===== SendPlayerAway =====
; prototype: void __usercall SendPlayerAway(Sprite *player@<a1>, TeamGeneralInfo *team@<a6>)
; in:
;      A1 -> booked player
;      A6 -> team data
; 
; Called when player gets red card.
SendPlayerAway:
                movea.l TEAMGENERALINFO_INGAMETEAMPTR(a6),a0
                move.w  SPRITE_PLAYERORDINAL(a1),d0
                subq.w  #1,d0
                cmp.w   $14(a0),d0
                bne.s   clear_cards_and_flag_sent_off
                move.w  #-1,TEAMGAME_MARKEDPLAYER(a0)
clear_cards_and_flag_sent_off:
                move.w  #-1,SPRITE_CARDS(a1)
                move.w  #1,SPRITE_SENTAWAY(a1)
                move.w  #-$14,SPRITE_DESTX(a1)
                move.w  #449,SPRITE_DESTY(a1)
                rts

; ===== ShouldGoalkeeperDive =====
; prototype: __int16 __usercall ShouldGoalkeeperDive@<d0>(Sprite *goalie@<a1>, Sprite *ball@<a2>, TeamGeneralInfo *team@<a6>)
; D0 = Attempt Save
ShouldGoalkeeperDive:
                move.w  SPRITE_Y(a2),d0
                sub.w   SPRITE_Y(a1),d0
                cmpa.l  #topTeamData,a6
                beq.s   normalize_dy_for_team_orientation
                neg.w   d0
normalize_dy_for_team_orientation:
                tst.w   d0
                bpl.w   ball_not_in_front_of_keeper
                cmpi.w  #-10,d0
                blt.w   no_dive
                bra.w   should_dive_yes
ball_not_in_front_of_keeper:
                tst.w   d0
                bmi.w   no_dive
                tst.w   (playingPenalties).l
                bne.s   penalty_distance_gate
                tst.w   (penalty).l
                beq.s   open_play_distance_gate
penalty_distance_gate:
                move.w  kKeeperPenaltySaveDistanceFar(pc),d1
                move.w  d0,-(sp)
                bsr.w   Rand
                move.w  d0,d2
                move.w  (sp)+,d0
                andi.w  #$18,d2
                beq.w   apply_penalty_near_far_threshold
                move.w  kKeeperPenaltySaveDistanceNear(pc),d1
apply_penalty_near_far_threshold:
                cmp.w   d1,d0
                bgt.w   no_dive
                bra.w   should_dive_yes
open_play_distance_gate:
                move.w  kKeeperSaveDistance(pc),d1
                cmp.w   d1,d0
                bgt.w   no_dive
                move.w  SPRITE_Y(a2),d4
                sub.w   SPRITE_Y(a1),d4
                bpl.s   abs_ball_dy_done
                neg.w   d4
abs_ball_dy_done:
                move.l  SPRITE_DELTAY(a2),d0
                bsr.w   GetFramesNeededToCoverDistance
                move.w  d7,d1
                beq.w   no_dive
                move.w  ballDefensiveX(pc),d4
                sub.w   SPRITE_X(a1),d4
                bpl.s   abs_ball_dx_to_defense_x_done
                neg.w   d4
abs_ball_dx_to_defense_x_done:
                move.l  SPRITE_DELTAX(a1),d0
                bsr.w   GetFramesNeededToCoverDistance
                move.w  d7,d2
                beq.w   no_dive
                cmp.w   d1,d2
                bls.w   no_dive
                move.w  ballDefensiveX(pc),d4
                sub.w   SPRITE_X(a1),d4
                bpl.s   pick_dive_vector_and_eval
                neg.w   d4
pick_dive_vector_and_eval:
                movea.l TEAMGENERALINFO_SHOTCHANCETABLE(a6),a0
                move.w  currentGameTick(pc),d0
                andi.w  #$3C,d0         ; '<'
                lsr.w   #1,d0
                move.w  GOALIESKILL_INDEX_DSEG_11061B(a0,d0.w),d0
                lea     kGoalkeeperDiveDeltas(pc),a0
                lsl.w   #2,d0
                move.l  (a0,d0.w),d0
                addq.w  #1,(goalkeeperDiveAttemptCount).l
                bsr.w   GetFramesNeededToCoverDistance
                move.w  d7,d3
                beq.w   no_dive
                cmp.w   d1,d3           ; D1 = DeltaY Frames
                bcs.w   no_dive
should_dive_yes:
                move.w  #1,d0
                rts
no_dive:
                clr.w   d0
                rts

; ===== GetFramesNeededToCoverDistance =====
; prototype: unsigned __int16 __usercall GetFramesNeededToCoverDistance@<d7>(__int32 movementDeltaFp16_16@<d0>, unsigned __int16 distance@<d4>)
; in:
;      D0 - movement delta, distance in a single frame (fixed point)
;           (absolute value is taken)
;      D4 - distance to cover (integer)
; out:
;      D7 - frames needed to cover the given distance (integer)
; 
; Does division D4/D0 using loops, without direct divide instruction.
; If they're exactly divisible it will return one more, e.g. 9/3 -> 4.
; If D0 is less than 1, scales it up as well as the value which gets
; subtracted from D4 in a loop, to limit the number of loops when D0 < 1.
; It will fail for extremely low D0 values.
; Called to calculate on both x and y directions.
GetFramesNeededToCoverDistance:
                tst.l   d0
                beq.w   return_zero_frames
                bpl.s   normalize_speed_abs
                neg.l   d0
normalize_speed_abs:
                move.w  #1,d5
                cmpi.l  #$10000,d0
                bcc.s   prep_distance_fp1616
scale_speed_until_ge_1_0:
                lsl.l   #1,d0
                lsl.w   #1,d5
                cmpi.l  #$10000,d0
                bcs.s   scale_speed_until_ge_1_0
prep_distance_fp1616:
                swap    d4
                clr.w   d4
                clr.w   d7
accumulate_frames_until_distance_met:
                add.w   d5,d7
                sub.l   d0,d4
                bpl.s   accumulate_frames_until_distance_met
                rts
return_zero_frames:
                clr.w   d7
                rts

; ===== UpdateBallVariables =====
; prototype: __int16 __usercall UpdateBallVariables@<d0>(Sprite *playerSprite@<a1>, Sprite *ballSprite@<a2>, TeamGeneralInfo *teamInfo@<a6>)
; in:
;      A1 -> player sprite
;      A2 -> ball sprite
;      A6 -> team (general)
UpdateBallVariables:
                movem.l d0/d4-d7,-(sp)
                move.l  SPRITE_X(a2),d1
                move.l  SPRITE_Y(a2),d2
                move.l  SPRITE_Z(a2),d3
                move.l  SPRITE_DELTAX(a2),d4
                move.l  SPRITE_DELTAY(a2),d5
                move.l  SPRITE_DELTAZ(a2),d6
                move.l  kGravityConstant(pc),d7
                cmpi.l  #$FFFF0000,d5
                blt.w   ball_moving_toward_top_goal
                cmpi.l  #$10000,d5
                bgt.w   ball_moving_toward_bottom_goal
                cmpi.l  #$FFFF0000,d4
                blt.w   ball_going_left
                cmpi.l  #$10000,d4
                bgt.w   ball_going_right
                bra.w   sample_defense_at_current_ball_pos
ball_moving_toward_top_goal:
                cmpa.l  #topTeamData,a6
                bne.w   sample_defense_at_current_ball_pos
                sub.l   SPRITE_Y(a1),d2
                bge.s   advance_until_cross_y_then_sample_defense
                move.w  SPRITE_X(a2),(ballDefensiveX).l
                move.w  SPRITE_Y(a2),(ballDefensiveY).l
                move.w  SPRITE_Z(a2),(ballDefensiveZ).l
                add.l   SPRITE_Y(a1),d2
                bra.w   check_above_135px_window
advance_until_cross_y_then_sample_defense:
                sub.l   d7,d6           ; ball is between player and opponent goal
                                        ; delta z -= air friction
                add.l   d6,d3           ; z   += old delta z - air friction, ball speeding up as nearing ground
                add.l   d4,d1           ; x   += delta x
                add.l   d5,d2           ; y   += delta y, while >= 0 repeat...
                bge.s   advance_until_cross_y_then_sample_defense
                sub.l   d4,d1
                sub.l   d5,d2
                sub.l   d6,d3
                add.l   SPRITE_Y(a1),d2
                swap    d1
                swap    d2
                swap    d3
                move.w  d1,(ballDefensiveX).l
                move.w  d2,(ballDefensiveY).l
                tst.w   d3
                bpl.s   maybe_set_goalkeeper_anim_for_static_header
                clr.w   d3
maybe_set_goalkeeper_anim_for_static_header:
                move.w  d3,(ballDefensiveZ).l
                swap    d1
                swap    d2
                swap    d3
check_above_135px_window:
                subi.l  #$870000,d2     ; 135.0
                bge.s   integrate_to_135px_ahead
                move.w  ballDefensiveX(pc),(ballNotHighX).l
                move.w  ballDefensiveY(pc),(ballNotHighY).l
                move.w  ballDefensiveZ(pc),(ballNotHighZ).l
                addi.l  #$870000,d2     ; 135.0, D2 = ball y again
                bra.s   keeper_attempt_static_header_catch
integrate_to_135px_ahead:
                sub.l   d7,d6
                add.l   d6,d3
                add.l   d4,d1
                add.l   d5,d2
                bge.s   integrate_to_135px_ahead
                sub.l   d4,d1
                sub.l   d6,d3
                move.l  #$870000,d2     ; 135.0
                swap    d1
                swap    d2
                swap    d3
                move.w  d1,(ballNotHighX).l
                move.w  d2,(ballNotHighY).l
                tst.w   d3
                bpl.s   keeper_prepare_to_catch_header
                clr.w   d3
keeper_prepare_to_catch_header:
                move.w  d3,(ballNotHighZ).l
                swap    d1
                swap    d2
                swap    d3
keeper_attempt_static_header_catch:
                subi.l  #$810000,d2     ; -129.0
                bge.s   integrate_to_129px_ahead
                clr.w   (strikeDestX).l
                clr.w   (strikeDestY).l
                clr.w   (strikeDestZ).l
                addi.l  #$810000,d2     ; 129.0
                bra.w   return_restore_regs
integrate_to_129px_ahead:
                sub.l   d7,d6
                add.l   d6,d3
                add.l   d4,d1
                add.l   d5,d2
                bge.s   integrate_to_129px_ahead
                sub.l   d4,d1
                sub.l   d6,d3
                move.l  #$810000,d2     ; 129.0
                swap    d1
                swap    d2
                swap    d3
                move.w  d1,(strikeDestX).l
                move.w  d2,(strikeDestY).l
                tst.w   d3
                bpl.s   store_strike_window_sample
                clr.w   d3
store_strike_window_sample:
                move.w  d3,(strikeDestZ).l
                swap    d1
                swap    d2
                swap    d3
                bra.w   return_restore_regs
ball_moving_toward_bottom_goal:
                cmpa.l  #bottomTeamData,a6
                bne.w   sample_defense_at_current_ball_pos
                sub.l   SPRITE_Y(a1),d2
                blt.s   integrate_until_cross_y_then_sample_defense
                move.w  SPRITE_X(a2),(ballDefensiveX).l
                move.w  SPRITE_Y(a2),(ballDefensiveY).l
                move.w  SPRITE_Z(a2),(ballDefensiveZ).l
                add.l   SPRITE_Y(a1),d2
                bra.s   check_plus_498px_threshold
integrate_until_cross_y_then_sample_defense:
                sub.l   d7,d6
                add.l   d6,d3
                add.l   d4,d1
                add.l   d5,d2
                blt.s   integrate_until_cross_y_then_sample_defense
                sub.l   d4,d1
                sub.l   d5,d2
                sub.l   d6,d3
                add.l   SPRITE_Y(a1),d2
                swap    d1
                swap    d2
                swap    d3
                move.w  d1,(ballDefensiveX).l
                move.w  d2,(ballDefensiveY).l
                tst.w   d3
                bpl.s   calc_keeper_anim_index_for_static_header
                clr.w   d3
calc_keeper_anim_index_for_static_header:
                move.w  d3,(ballDefensiveZ).l
                swap    d1
                swap    d2
                swap    d3
check_plus_498px_threshold:
                subi.l  #$2FB0000,d2    ; 763.0
                blt.s   integrate_to_plus_498px
                move.w  ballDefensiveX(pc),(ballNotHighX).l
                move.w  ballDefensiveY(pc),(ballNotHighY).l
                move.w  ballDefensiveZ(pc),(ballNotHighZ).l
                addi.l  #$2FB0000,d2    ; 763.0
                bra.s   check_between_plus_497_plus_505px_window
integrate_to_plus_498px:
                sub.l   d7,d6
                add.l   d6,d3
                add.l   d4,d1
                add.l   d5,d2
                blt.s   integrate_to_plus_498px
                sub.l   d4,d1
                sub.l   d6,d3
                move.l  #$2FB0000,d2    ; 763.0
                swap    d1
                swap    d2
                swap    d3
                move.w  d1,(ballNotHighX).l
                move.w  d2,(ballNotHighY).l
                tst.w   d3
                bpl.s   set_keeper_anim_for_static_header
                clr.w   d3
set_keeper_anim_for_static_header:
                move.w  d3,(ballNotHighZ).l
                swap    d1
                swap    d2
                swap    d3
check_between_plus_497_plus_505px_window:
                subi.l  #$3010000,d2    ; 769.0
                blt.s   integrate_to_plus_505px
                clr.w   (strikeDestX).l
                clr.w   (strikeDestY).l
                clr.w   (strikeDestZ).l
                addi.l  #$3010000,d2    ; 769.0
                bra.w   return_restore_regs
integrate_to_plus_505px:
                sub.l   d7,d6
                add.l   d6,d3
                add.l   d4,d1
                add.l   d5,d2
                blt.s   integrate_to_plus_505px
                sub.l   d4,d1
                sub.l   d6,d3
                move.l  #$3010000,d2    ; 769.0
                swap    d1
                swap    d2
                swap    d3
                move.w  d1,(strikeDestX).l
                move.w  d2,(strikeDestY).l
                tst.w   d3
                bpl.s   store_strike_window_sample_2
                clr.w   d3
store_strike_window_sample_2:
                move.w  d3,(strikeDestZ).l
                swap    d1
                swap    d2
                swap    d3
                bra.w   return_restore_regs
ball_going_left:
                sub.l   SPRITE_X(a1),d1
                bge.s   ball_right_of_player
                add.l   SPRITE_X(a1),d1
                bra.w   sample_defense_at_current_ball_pos
ball_right_of_player:
                sub.l   d7,d6
                add.l   d6,d3
                add.l   d5,d2
                add.l   d4,d1
                bge.s   ball_right_of_player
                sub.l   d4,d1
                sub.l   d5,d2
                sub.l   d6,d3
                add.l   SPRITE_X(a1),d1
                swap    d1
                swap    d2
                swap    d3
                move.w  d1,(ballDefensiveX).l
                move.w  d2,(ballDefensiveY).l
                tst.w   d3
                bpl.s   maybe_adjust_keeper_for_corner_kick
                clr.w   d3
maybe_adjust_keeper_for_corner_kick:
                move.w  d3,(ballDefensiveZ).l
                bra.w   finalize_not_high_and_clear_strike
ball_going_right:
                sub.l   SPRITE_X(a1),d1
                blt.s   ball_left_of_player
                add.l   SPRITE_X(a1),d1
                bra.w   sample_defense_at_current_ball_pos
ball_left_of_player:
                sub.l   d7,d6
                add.l   d6,d3
                add.l   d5,d2
                add.l   d4,d1
                blt.s   ball_left_of_player
                sub.l   d4,d1
                sub.l   d5,d2
                sub.l   d6,d3
                add.l   SPRITE_X(a1),d1
                swap    d1
                swap    d2
                swap    d3
                move.w  d1,(ballDefensiveX).l
                move.w  d2,(ballDefensiveY).l
                tst.w   d3
                bpl.s   maybe_set_keeper_catch_anim_for_corner
                clr.w   d3
maybe_set_keeper_catch_anim_for_corner:
                move.w  d3,(ballDefensiveZ).l
                bra.w   finalize_not_high_and_clear_strike
sample_defense_at_current_ball_pos:
                move.w  SPRITE_X(a2),(ballDefensiveX).l
                move.w  SPRITE_Y(a2),(ballDefensiveY).l
                move.w  SPRITE_Z(a2),(ballDefensiveZ).l
finalize_not_high_and_clear_strike:
                move.w  ballDefensiveX(pc),(ballNotHighX).l
                move.w  ballDefensiveY(pc),(ballNotHighY).l
                move.w  ballDefensiveZ(pc),(ballNotHighZ).l
                clr.w   (strikeDestX).l
                clr.w   (strikeDestY).l
                clr.w   (strikeDestZ).l
return_restore_regs:
                movem.l (sp)+,d0/d4-d7
                rts

; ===== CalculateBallNextGroundXYPositions =====
; prototype: __int16 __usercall CalculateBallNextGroundXYPositions@<d0>(struct Sprite *ball@<a2>)
; in:
;      A2 -> ball sprite
CalculateBallNextGroundXYPositions:
                movem.l d0/d4-d7,-(sp)
                move.l  SPRITE_X(a2),d1 ; ball x
                move.l  SPRITE_Y(a2),d2 ; ball y
                move.l  SPRITE_Z(a2),d3 ; ball z
                move.l  SPRITE_DELTAX(a2),d4 ; ball delta x
                move.l  SPRITE_DELTAY(a2),d5 ; ball delta y
                cmpi.l  #-$10000,d5     ; -1.0
                blt.w   ball_moving
                cmpi.l  #$10000,d5      ; 1.0
                bgt.w   ball_moving
                cmpi.l  #-$10000,d4     ; -1.0
                blt.w   ball_moving
                cmpi.l  #$10000,d4      ; 1.0
                bgt.w   ball_moving
                bra.w   ball_standing
ball_moving:
                move.l  SPRITE_DELTAZ(a2),d6
                move.l  kGravityConstant(pc),d7
                move.l  #$140000,d0     ; D0 = 20.0   (starting ball z difference)
subtract_z:
                sub.l   d0,d3           ; ball z -=   20.0 or less
                bpl.s   z_in_range
                cmpi.l  #$D0000,d0      ; 13.0
                beq.s   ball_standing
                add.l   d0,d3           ; restore ball z as   it was
                subi.l  #$10000,d0      ; decrease ball z difference (by 1.0)
                bra.s   subtract_z
z_in_range:
                add.l   d4,d1           ; ball x +=   delta x
                add.l   d5,d2           ; ball y +=   delta y
                sub.l   d7,d6           ; ball delta z -= ball z constant
                add.l   d6,d3           ; ball z +=   delta z
                bpl.s   z_in_range
                add.l   d0,d3
                swap    d1
                swap    d2
                swap    d3
                move.w  d1,(ballNextGroundX).l
                move.w  d2,(ballNextYGroundY).l
                move.w  d3,(ballNextZDeadVar).l
                clr.w   (ballNextZDeadVar).l
                bra.w   _11311C_out
ball_standing:
