                rts

; ===== PlayerTacklingTestFoul =====
; prototype: void __usercall PlayerTacklingTestFoul(Sprite *playerSprite@<a1>, Sprite *ballSprite@<a2>, TeamGeneralInfo *teamInfo@<a6>)
; in:
;      A1 -> sprite (player)
;      A2 -> sprite (ball)
;      A6 -> team data
; 
; Check if the tackle ends up in faul, there must be a few conditions satisfied:
; - opponent has a controlled player
; - distance between them is more than 32 units
PlayerTacklingTestFoul:
                movea.l (a6),a2
                movea.l TEAMGENERALINFO_CONTROLLEDPLAYER(a2),a2
                cmpa.l  #TEAMGENERALINFO_OPPONENTSTEAM,a2
                beq.s   _11314E_exit_rts
                move.w  SPRITE_X(a1),d0
                sub.w   SPRITE_X(a2),d0
                muls.w  d0,d0
                move.w  SPRITE_Y(a1),d1
                sub.w   SPRITE_Y(a2),d1
                muls.w  d1,d1
                add.l   d1,d0
                cmpi.l  #32,d0
                bls.s   victim_in_range_and_on_pitch
_11314E_exit_rts:
                rts
apply_tackle_slowdown_flag:
                lsr     SPRITE_SPEED(a1)
                lsr     SPRITE_SPEED(a1)
                ori.w   #1,SPRITE_SPEED(a1)
                rts
victim_in_range_and_on_pitch:
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a2)
                beq.s   apply_tackle_slowdown_flag
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a2)
                beq.s   _11314E_exit_rts
                cmpi.w  #81,SPRITE_X(a2)
                blt.s   _11314E_exit_rts
                cmpi.w  #129,SPRITE_Y(a2)
                blt.s   _11314E_exit_rts
                cmpi.w  #590,SPRITE_X(a2)
                bgt.s   _11314E_exit_rts
                cmpi.w  #769,SPRITE_Y(a2)
                bgt.s   _11314E_exit_rts
                lsr     SPRITE_SPEED(a1)
                lsr     SPRITE_SPEED(a1)
                ori.w   #1,SPRITE_SPEED(a1)
                movem.l a1/a6,-(sp)
                movea.l a2,a1
                movea.l (a6),a6
                jsr PlayerTackled(pc)
                movem.l (sp)+,a1/a6
                cmpi.l  #800,SPRITE_BALLDISTANCE(a2)
                bhi.s   _11314E_exit_rts
                tst.w   96(a1)
                beq.s   skip_card_and_end
                cmpi.w  #TS_GOOD_TACKLE,SPRITE_TACKLESTATE(a1)
                beq.s   _11314E_exit_rts
                move.w  SPRITE_DIRECTION(a1),d0
                sub.w   SPRITE_DIRECTION(a2),d0
                cmpi.w  #$FFFF,d0
                blt.w   _11314E_exit_rts
                cmpi.w  #1,d0
                bgt.w   _11314E_exit_rts
skip_card_and_end:
                movea.l TEAMGENERALINFO_TEAMSTATSPTR(a6),a0
                addq.w  #1,TEAMSTATISTICSDATA_FOULSCONCEDED(a0)
                tst.w   (cardsDisallowed).l
                bne.w   skip_cards_go_check_free_kick_penalty
                tst.w   (trainingGame).l
                bne.w   skip_cards_go_check_free_kick_penalty
                move.w  SPRITE_X(a2),d1
                move.w  SPRITE_Y(a2),d2
                cmpi.w  #193,d1
                blt.s   set_discipline_spot_y_for_bottom_team
                cmpi.w  #478,d1
                bgt.s   set_discipline_spot_y_for_bottom_team
                cmpi.w  #129,d2
                blt.s   set_discipline_spot_y_for_bottom_team
                cmpi.w  #769,d2
                bgt.s   set_discipline_spot_y_for_bottom_team
                cmpa.l  #topTeamData,a6
                bne.s   set_discipline_spot_y_for_top_team
                cmpi.w  #216,d2
                ble.w   maybe_issue_card_probabilistic
                bra.s   set_discipline_spot_y_for_bottom_team
set_discipline_spot_y_for_top_team:
                cmpi.w  #682,d2
                bge.w   maybe_issue_card_probabilistic
set_discipline_spot_y_for_bottom_team:
                move.w  #336,d1
                move.w  #129,d2
                cmpa.l  #topTeamData,a6
                beq.s   search_for_nearest_teammate
                move.w  #769,d2
search_for_nearest_teammate:
                movea.l a2,a5
                move.w  SPRITE_X(a2),d6
                sub.w   d1,d6
                muls.w  d6,d6
                move.w  SPRITE_Y(a2),d3
                sub.w   d2,d3
                muls.w  d3,d3
                add.l   d6,d3
                movea.l TEAMGENERALINFO_SPRITESTABLE(a6),a0
                move.w  #10,d0
update_nearest_teammate_if_closer:
                movea.l (a0)+,a4
                tst.w   SPRITE_SENTAWAY(a4)
                bne.s   store_nearest_teammate_and_continue
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a4)
                beq.s   store_nearest_teammate_and_continue
                cmpa.l  a1,a4
                beq.s   store_nearest_teammate_and_continue
                move.w  SPRITE_X(a4),d6
                sub.w   d1,d6
                muls.w  d6,d6
                move.w  SPRITE_Y(a4),d7
                sub.w   d2,d7
                muls.w  d7,d7
                add.l   d7,d6
                cmp.l   d3,d6
