                bcs.s   try_straight_red_then_notify
issue_yellow_or_upgrade_and_notify:
                jsr TryBookingThePlayer(pc)
                bne.s   skip_cards_go_check_free_kick_penalty
                bsr.w   TestFoulForPenaltyAndFreeKick
                movem.l a1,-(sp)
                jsr     ActivateReferee
                movem.l (sp)+,a1
                rts
same_player_priority_branch:
                jsr Rand(pc)
                cmpi.w  #32,d0
                bcs.s   issue_yellow_or_upgrade_and_notify
try_straight_red_then_notify:
                jsr TrySendingOffThePlayer(pc)
                bne.s   skip_cards_go_check_free_kick_penalty
                bsr.w   TestFoulForPenaltyAndFreeKick
                movem.l a1,-(sp)
                jsr     ActivateReferee
                movem.l (sp)+,a1
                rts
skip_cards_go_check_free_kick_penalty:
                bra.w   TestFoulForPenaltyAndFreeKick
                rts

