                move.w  d1,SPRITE_DESTY(a2) ; update dest x and y
                move.w  currentGameTick(pc),d0
                andi.w  #$1F,d0         ; D0 = 0..31
                lsl.w   #5,d0           ; D0 = 0..992
                subi.w  #512,d0         ; D0 = -512..480
                add.w   d0,SPRITE_DESTX(a2)
                movea.l TEAMGENERALINFO_SHOTCHANCETABLE(a6),a0
                move.w  currentGameTick(pc),d1
                andi.w  #$3C,d1         ; '<'
