                lsl.l   #8,d0           ; 0..32,512
                subi.l  #16384,d0       ; -16,384..16,128
                add.l   d1,d0
                move.l  d0,SPRITE_DELTAZ(a2)
                bsr.w   ResetBothTeamSpinTimers
                jsr     PlayKickSample
                rts
                lea     (goalieDeflectBallAnimTable).l,a0
