; ===== GoalkeeperJumping =====
; prototype: void __usercall GoalkeeperJumping(__int16 direction@<d0>, __int16 farJumpVariant@<d1>, __int16 dir2@<d3>, Sprite *player@<a1>, Sprite *ball@<a2>, TeamGeneralInfo *team@<a6>)
; in:
;      D0 -  direction
;      D1 -  goalkeeper far jump speed flag, overrides goalkeeper jump speed if:
;                0 - no influence, use high speed as usual (2048)
;                1 - use lower speed (1280)
;                * - anything else: use low speed (1024) + low byte of currentGameTick
;                    effectively random: 1024..1279
;      D3 -  also some direction
;      A1 -> player sprite
;      A6 -> player team (general)
GoalkeeperJumping:
                cmpi.l  #128,SPRITE_BALLDISTANCE(a1)
                bhi.s   set_far_jump_speed_by_variant
                move.w  kGoalkeeperNearJumpSpeed(pc),d1
                move.w  d1,SPRITE_SPEED(a1)
                bra.s   decide_jump_anim_low_or_high
set_far_jump_speed_by_variant:
                move.w  kGoalkeeperFarJumpSpeed(pc),SPRITE_SPEED(a1)
                tst.w   d1
                beq.s   decide_jump_anim_low_or_high
                move.w  kGoalkeeperFarJumpSlowerSpeed(pc),SPRITE_SPEED(a1)
                cmpi.w  #1,d1
                beq.s   decide_jump_anim_low_or_high
                move.w  currentGameTick(pc),d1
                andi.w  #$FF,d1
                add.w   kGoalkeeperNearJumpSpeed(pc),d1
                move.w  d1,SPRITE_SPEED(a1)
decide_jump_anim_low_or_high:
                move.w  SPRITE_Y(a2),d1
                sub.w   SPRITE_Y(a1),d1
                move.w  SPRITE_X(a2),d1
                sub.w   SPRITE_X(a1),d1
                clr.b   TEAMGENERALINFO_FIELD_46(a6)
                clr.w   TEAMGENERALINFO_GOALKEEPERDIVINGRIGHT(a6)
                cmpi.w  #5,(ballNotHighZ).l
                bhi.s   set_high_jump_anim_left_team
                move.b  #PL_GOALIE_DIVING_LOW,SPRITE_PLAYERSTATE(a1)
                cmpa.l  #bottomTeamData,a6
                beq.s   set_low_jump_anim_right_team
                lea     (leftGoalieJumpingLowAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                bra.w   finalize_jump_anim_and_destination
set_low_jump_anim_right_team:
                lea     (rightGoalieJumpingLowAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                bra.s   finalize_jump_anim_and_destination
set_high_jump_anim_left_team:
                move.b  #PL_GOALIE_DIVING_HIGH,SPRITE_PLAYERSTATE(a1)
                cmpa.l  #bottomTeamData,a6
                beq.s   set_high_jump_anim_right_team
                lea     (leftGoalieJumpingHighAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                bra.s   finalize_jump_anim_and_destination
set_high_jump_anim_right_team:
                lea     (rightGoalieJumpingHighAnimTable).l,a0
                jsr     SetPlayerAnimationTable
finalize_jump_anim_and_destination:
                move.b  #75,SPRITE_PLAYERDOWNTIMER(a1)
                move.w  d0,TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6)
                move.w  d3,d0
                lea     kDefaultDestinations(pc),a5
                lsl.w   #2,d0
                lea     (a5,d0.w),a5
                move.w  (a5)+,d0
                add.w   SPRITE_X(a1),d0
                move.w  d0,SPRITE_DESTX(a1)
                move.w  (a5),d0
                add.w   SPRITE_Y(a1),d0
                move.w  d0,SPRITE_DESTY(a1)
                rts

; ===== PlayerBeginTackling =====
; prototype: void __usercall PlayerBeginTackling(__int16 pressedDir@<d0>, Sprite *player@<a1>, TeamGeneralInfo *team@<a6>)
; in:
