PlayerBeginTackling:
                clr.w   SPRITE_TACKLESTATE(a1)
                move.w  d0,TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6)
                move.w  d0,TEAMGENERALINFO_ALLOWEDDIRECTIONS(a1)
                lea     (plTacklingAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                move.b  #PL_TACKLING,SPRITE_PLAYERSTATE(a1)
                move.b  #50,SPRITE_PLAYERDOWNTIMER(a1)
                move.w  2(a1),d1
                subq.w  #1,d1
                lea     (ingameTeamPlayerOffsets).l,a0
                lsl.w   #1,d1
                move.w  (a0,d1.w),d1
                movea.l $A(a6),a0
                lea     (a0,d1.w),a0
                tst.b   PLAYERINFOHEADER_FASTERTACKLE(a0)
                beq.w   set_tackle_dest_and_speed
                move.b  #25,SPRITE_PLAYERDOWNTIMER(a1)
set_tackle_dest_and_speed:
                move.b  #$FF,SPRITE_PLAYERDOWNTIMER(a1)
                lea     kDefaultDestinations(pc),a5
                lsl.w   #2,d0
                lea     (a5,d0.w),a5
                move.w  (a5)+,d0
                add.w   SPRITE_X(a1),d0
                move.w  d0,SPRITE_DESTX(a1)
                move.w  (a5),d0
                add.w   SPRITE_Y(a1),d0
                move.w  d0,SPRITE_DESTY(a1)
