; ===== PlayerTackledTheBallStrong =====
; prototype: void __usercall PlayerTackledTheBallStrong(Sprite *player@<a1>, TeamGeneralInfo *team@<a6>)
; in:
;      A1 -> sprite (player)
;      A6 -> team (general)
;      
; Player is tackling and hitting the ball. Adjust ball direction according to the player direction and
; controls direction (do deflected tackles). Set ball destination coordinates far away in that direction.
; Adjust ball speed after tackle to 125% of player's speed (100% if CPU player). Set player's speed
; afterward to 50%. If opponent's controlled player is more than 9u away from the ball and distance
; between the 2 players is greater than 32u it is considered a good tackle.
;  u = sqr((x1 - x2) ^ 2) + sqr((y1 - y2) ^ 2)
PlayerTackledTheBallStrong:
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d1
                bpl.s   choose_ref_dir_from_input
                move.w  SPRITE_DIRECTION(a1),d1
choose_ref_dir_from_input:
                lea     (ballSprite).l,a2
                move.w  SPRITE_DIRECTION(a1),d0
                sub.w   d1,d0           ; D0 = difference between player and controls direction
                beq.w   keep_dir        ; do they have same direction?
                andi.w  #7,d0           ; ANDing difference with 7 maps it to a counter-clockwise oriented circle (top=0)
                cmpi.w  #4,d0           ; if it's equal to 4 those two directions are opposite
                beq.s   keep_dir
                bcs.s   decrement_dir
                move.w  SPRITE_DIRECTION(a1),d0 ; controls leaning rightward
                addq.w  #1,d0           ; turn the ball a bit to the right
                bra.s   apply_dir_and_compute_dest
decrement_dir:
                move.w  SPRITE_DIRECTION(a1),d0
                subq.w  #1,d0
                bra.s   apply_dir_and_compute_dest
keep_dir:
                move.w  SPRITE_DIRECTION(a1),d0
apply_dir_and_compute_dest:
                andi.w  #7,d0
                move.w  d0,TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6)
                lea     kDefaultDestinations(pc),a0
                lsl.w   #2,d0
                move.w  (a0,d0.w),d1
                add.w   SPRITE_X(a2),d1
                move.w  d1,SPRITE_DESTX(a2)
                move.w  SPRITE_Y(a2),d1
                add.w   2(a0,d0.w),d1
                move.w  d1,SPRITE_DESTY(a2)
                tst.w   4(a6)
                bne.s   boost_ball_speed_when_flag_set
                move.w  SPRITE_SPEED(a1),d0
                move.w  d0,SPRITE_SPEED(a2)
                bra.s   finalize_kick_and_mark_type
boost_ball_speed_when_flag_set:
                move.w  SPRITE_SPEED(a1),d0
                lsr.w   #2,d0
                add.w   SPRITE_SPEED(a1),d0
                move.w  d0,SPRITE_SPEED(a2)
                move.w  SPRITE_SPEED(a1),d0
                lsr.w   #2,d0
                add.w   SPRITE_SPEED(a1),d0
                move.w  d0,SPRITE_SPEED(a2)
finalize_kick_and_mark_type:
                lsr     SPRITE_SPEED(a1)
                move.w  #1,SPRITE_TACKLESTATE(a1)
                movea.l (a6),a0
                movea.l TEAMGENERALINFO_CONTROLLEDPLAYER(a0),a0
                cmpa.l  #TEAMGENERALINFO_OPPONENTSTEAM,a0
                beq.s   maybe_mark_kick_as_clearance
                cmpi.l  #9,SPRITE_BALLDISTANCE(a0)
                bcs.s   maybe_mark_kick_as_clearance
                move.w  SPRITE_X(a1),d0
                sub.w   SPRITE_X(a0),d0
                muls.w  d0,d0
                move.w  SPRITE_Y(a1),d1
                sub.w   SPRITE_Y(a0),d1
                muls.w  d1,d1
                add.l   d1,d0
                cmpi.l  #32,d0
                bls.s   maybe_mark_kick_as_clearance
                move.w  #2,SPRITE_TACKLESTATE(a1)
maybe_mark_kick_as_clearance:
                jsr     PlayKickSample
                bsr.w   ResetBothTeamSpinTimers
                rts

; ===== PlayerAttemptingJumpHeader =====
; prototype: void __usercall PlayerAttemptingJumpHeader(__int16 direction@<d0>, Sprite *player@<a1>)
; in:
;      D0 -  direction
;      A1 -> player sprite
;      
; Player starts jumping in attempt to hit the ball with his head. Set his state
; and render him 'inoperable' for the next 55 cycles. Sets his animation table,
; dest x and y, and his speed. Only triggers for flying and lob header attempts,
; not for static ones. 
PlayerAttemptingJumpHeader:
                clr.w   SPRITE_HEADING(a1)
                move.w  d0,SPRITE_DIRECTION(a1)
                lea     (jumpHeaderAttemptAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                move.b  #50,SPRITE_PLAYERDOWNTIMER(a1)
                move.b  #PL_JUMP_HEADING,SPRITE_PLAYERSTATE(a1)
                lea     kDefaultDestinations(pc),a5
                lsl.w   #2,d0
                lea     (a5,d0.w),a5
                move.w  (a5)+,d0
                add.w   SPRITE_X(a1),d0
                move.w  d0,SPRITE_DESTX(a1)
                move.w  (a5),d0
                add.w   SPRITE_Y(a1),d0
                move.w  d0,SPRITE_DESTY(a1)
                move.w  kJumpHeaderSpeed(pc),SPRITE_SPEED(a1)
                rts
                lea     (ballSprite).l,a2
                move.w  d0,$38(a6)
                bmi.s   loc_113712
                lea     kDefaultDestinations(pc),a0
                lsl.w   #2,d0
                move.w  $1E(a2),d1
                add.w   (a0,d0.w),d1
                move.w  d1,$3A(a2)
                move.w  $22(a2),d1
                add.w   2(a0,d0.w),d1
                move.w  d1,$3C(a2)
                move.w  $2C(a1),d0
                lsr.w   #1,d0
                move.w  d0,$2C(a2)
                lsr     $2C(a1)
loc_113712:
                neg.l   $36(a1)
                addi.l  #(goalBase+$2292),$36(a1)
                jsr     PlayKickSample
                bsr.w   ResetBothTeamSpinTimers
                rts

; ===== GetBallDestCoordinatesTable =====
; prototype: __int16 *__usercall GetBallDestCoordinatesTable@<a0>()
; out:
;      A0 -> ball factor table, depending on game state
; 
; Even indices are delta x, odd are delta y. They are added to ball
; delta x and y. Tables are different for each type of game halt.
; Called when player kicks the ball or does a pass.
GetBallDestCoordinatesTable:
                cmpi.w  #ST_THROW_IN_FORWARD_RIGHT,(gameState).l
                bcs.s   branch_not_throw_in
                cmpi.w  #ST_THROW_IN_BACK_LEFT,(gameState).l
                bhi.s   branch_not_throw_in
                cmpi.w  #336,(foulXCoordinate).l
                bhi.s   throw_in_right_side
                lea     kLeftThrowInBallDestDelta(pc),a0
                rts
throw_in_right_side:
                lea     kRightThrowInBallDestDelta(pc),a0
                rts
branch_not_throw_in:
                cmpi.w  #ST_PENALTY,(gameState).l
                beq.s   use_penalty_ball_deltas
                cmpi.w  #ST_PENALTIES,(gameState).l
                bne.s   branch_not_penalty
use_penalty_ball_deltas:
                lea     kPenaltyBallDestDelta(pc),a0
                rts
branch_not_penalty:
                cmpi.w  #ST_CORNER_LEFT,(gameState).l
                beq.s   select_corner_variant
                cmpi.w  #ST_CORNER_RIGHT,(gameState).l
                bne.s   not_corner
select_corner_variant:
                cmpi.w  #449,(foulYCoordinate).l
                bhi.s   select_lower_corner_variant
                cmpi.w  #336,(foulXCoordinate).l
                bhi.s   corner_upper_right
                lea     kUpperLeftCornerBallDestDelta(pc),a0
                rts
corner_upper_right:
                lea     kUpperRightCornerBallDestDelta(pc),a0
                rts
select_lower_corner_variant:
                cmpi.w  #336,(foulXCoordinate).l
                bhi.s   corner_lower_right
                lea     kLowerLeftCornerBallDestDelta(pc),a0
                rts
corner_lower_right:
                lea     kLowerRightCornerBallDestDelta(pc),a0
                rts
not_corner:
                lea     kDefaultDestinations(pc),a0
                rts

; ===== GetClosestNonControlledPlayerInDirection =====
; prototype: Sprite *__usercall GetClosestNonControlledPlayerInDirection@<a0>(unsigned __int16 direction@<d0>, TeamGeneralInfo *team@<a6>)
; in:
;      D0 -  direction
;      A6 -> team (general)
; out:
;      A0 -> player sprite
;      D2 -  ball distance
; 
; Return pointer to player closest to the ball facing approximately given
; direction. Also return his distance from the ball.
GetClosestNonControlledPlayerInDirection:
                movea.l a1,a5
                movea.l TEAMGENERALINFO_SPRITESTABLE(a6),a2
                lea     (ballSprite).l,a0
                move.w  SPRITE_X(a0),d3
                move.w  SPRITE_Y(a0),d4
                lsl.w   #5,d0
                movea.l #$FFFFFFFF,a0
                moveq   #$FFFFFFFF,d2
                move.w  #10,d7
iterate_teammates:
                movea.l (a2)+,a1
                cmpa.l  TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a1
                beq.s   next_teammate_or_skip
                tst.w   SPRITE_SENTAWAY(a1)
                bne.s   next_teammate_or_skip
                cmpi.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a1)
                bne.s   next_teammate_or_skip
                move.w  SPRITE_FULLDIRECTION(a1),d1
                sub.b   d0,d1
                cmpi.b  #240,d1
                blt.s   next_teammate_or_skip
                cmpi.b  #16,d1
                bgt.s   next_teammate_or_skip
                move.l  SPRITE_BALLDISTANCE(a1),d1
                cmp.l   d2,d1
                bcc.s   next_teammate_or_skip
                move.l  d1,d2
                movea.l a1,a0
next_teammate_or_skip:
                dbf     d7,iterate_teammates
                rts

; ===== UpdateControllingPlayer =====
; prototype: void __usercall UpdateControllingPlayer(Sprite *player@<a1>)
; in:
;      A1 -> sprite (player)
UpdateControllingPlayer:
                move.w  SPRITE_DIRECTION(a1),d0
                lsl.w   #2,d0
                lea     (kBallPlOffsets).l,a0
                move.w  SPRITE_X(a1),d1
                add.w   (a0,d0.w),d1
                move.w  SPRITE_Y(a1),d2
                add.w   2(a0,d0.w),d2
                lea     (ballSprite).l,a0
                clr.w   ballSprite+SPRITE_SPEED-ballSprite(a0)
                move.w  d1,SPRITE_X(a0)
                move.w  d2,SPRITE_Y(a0)
                move.w  d1,SPRITE_DESTX(a0)
                move.w  d2,SPRITE_DESTY(a0)
                clr.w   SPRITE_Z(a0)
                move.l  SPRITE_DELTAZ(a0),d0
                asr.l   #1,d0
                move.l  d0,SPRITE_DELTAZ(a0)
                bsr.w   ResetBothTeamSpinTimers
                rts
; __int16[16]
kBallPlOffsets:
                ; __int16[16]
                dc.w 0,-1,1,-1,1,0,1,1  ; Player direction is index
                dc.w 0,1,-1,1,-1,0,-1,-1
                                        ; even indices are for x, and odd for y coordinate
                                        ; these values are added to x and y coordinate of player
                                        ; to form ball coordinates when player has the ball
                                        ; indexed with direction of player

; ===== UpdateBallWithControllingGoalkeeper =====
; prototype: void __usercall UpdateBallWithControllingGoalkeeper(Sprite *playerHoldingBall@<a1>)
; in:
;      A1 -> sprite of player that holds the ball
; 
; Set ball coordinates in regard to player that controls it. Ball is
; always about a pixel in front of player, wherever he may be turned.
; If it's in the air, steady it down.
UpdateBallWithControllingGoalkeeper:
                move.w  SPRITE_DIRECTION(a1),d0
                lsl.w   #2,d0
                lea     kBallPlOffsets(pc),a0
                move.w  SPRITE_X(a1),d1
                add.w   (a0,d0.w),d1
                move.w  SPRITE_Y(a1),d2
                add.w   2(a0,d0.w),d2
                lea     (ballSprite).l,a0
                clr.w   ballSprite+SPRITE_SPEED-ballSprite(a0)
                move.w  d1,SPRITE_X(a0)
                move.w  d2,SPRITE_Y(a0)
                move.w  d1,SPRITE_DESTX(a0)
                move.w  d2,SPRITE_DESTY(a0)
                move.l  SPRITE_DELTAZ(a0),d0
                asr.l   #1,d0
                bmi.s   apply_downward_half_deltaZ
                neg.l   d0
apply_downward_half_deltaZ:
                move.l  d0,SPRITE_DELTAZ(a0)
                bsr.w   ResetBothTeamSpinTimers
                rts

; ===== UpdatePlayerWithBall =====
; prototype: void __usercall UpdatePlayerWithBall(Sprite *player@<a1>)
; in:
;      A1 -> sprite
; 
; Set coordinates of player that has the ball. Make him dodge
; a little, by varying x and y coordinates by 1.
UpdatePlayerWithBall:
                lea     (ballSprite).l,a0
                move.w  ballSprite+SPRITE_X-ballSprite(a0),d1
                move.w  SPRITE_Y(a0),d2
                move.w  SPRITE_DIRECTION(a1),d0
                lsl.w   #2,d0
                lea     (kPlayerWithBallOffsets).l,a0
                add.w   (a0,d0.w),d1
                add.w   2(a0,d0.w),d2
                move.w  d1,SPRITE_X(a1)
                move.w  d2,SPRITE_Y(a1)
                move.w  d1,SPRITE_DESTX(a1)
                move.w  d2,SPRITE_DESTY(a1)
                bsr.w   ResetBothTeamSpinTimers
                rts
                move.w  #$38D,(panicReasonCode).l
                jsr     PanicHaltLoop
; __int16[16]
kPlayerWithBallOffsets:
                ; __int16[16]
                dc.w 0,1,-1,1,-1,0,-1,-1
                dc.w 0,-1,1,-1,1,0,1,1

; ===== SetThrowInPlayerDestinationCoordinates =====
; prototype: void __usercall SetThrowInPlayerDestinationCoordinates(Sprite *player@<a1>)
; in:
;      A1 -> player sprite that's taking the throw-in
; 
; Sets the coordinates of a player that takes the throw in.
SetThrowInPlayerDestinationCoordinates:
                lea     (ballSprite).l,a0
                move.w  ballSprite+SPRITE_X-ballSprite(a0),d1
                cmpi.w  #336,d1
                bcs.s   move_left_for_throwin
                addq.w  #3,d1
                bra.s   write_throwin_x
move_left_for_throwin:
                subq.w  #3,d1
write_throwin_x:
                move.w  d1,SPRITE_X(a1)
                move.w  d1,SPRITE_DESTX(a1)
                move.w  SPRITE_Y(a0),SPRITE_Y(a1)
                move.w  SPRITE_Y(a0),SPRITE_DESTY(a1)
                rts

; ===== ApplyBallAfterTouch =====
; prototype: void __usercall ApplyBallAfterTouch(struct TeamGeneralInfo *team@<a6>)
; in:
;      A6 -> team data
;      
; Apply "after effects" to pass/kick. Apply spin if player holding left/right
; directions, and high kick if player holding back direction. Also update ball
; for normal kicks too. Slow down ball after kick/pass.
ApplyBallAfterTouch:
                tst.w   TEAMGENERALINFO_PASSINPROGRESS(a6)
                bne.w   passing_now
                movea.l (a6),a0
                tst.w   TEAMGENERALINFO_GOALKEEPERSAVEDCOMMENTTIMER(a0)
                bmi.w   reset_spin_timer_out
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.w   _113988_game_in_progress
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                beq.w   reset_spin_timer_out
_113988_game_in_progress:
                move.w  TEAMGENERALINFO_SPINTIMER(a6),d0
                bmi.w   _113ABE_out
                bne.s   accepting_spin
                clr.w   TEAMGENERALINFO_LEFTSPIN(a6)
                clr.w   TEAMGENERALINFO_RIGHTSPIN(a6)
accepting_spin:
                lea     (ballSprite).l,a1
                tst.w   TEAMGENERALINFO_LEFTSPIN(a6)
                bne.s   apply_left_spin
                tst.w   TEAMGENERALINFO_RIGHTSPIN(a6)
                bne.s   apply_right_spin
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d1
                bmi.w   not_starting_spin
                move.w  TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6),d0
                sub.w   d1,d0
                beq.w   not_starting_spin
                andi.w  #7,d0
                cmpi.w  #4,d0
                beq.s   not_starting_spin
                bcs.s   spin_left
                move.w  #1,TEAMGENERALINFO_RIGHTSPIN(a6)
apply_right_spin:
                moveq   #4,d1
                bra.s   calculate_initial_spin
spin_left:
                move.w  #1,TEAMGENERALINFO_LEFTSPIN(a6)
apply_left_spin:
                clr.w   d1
calculate_initial_spin:
                move.w  TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6),d0
                lea     kKickSpinFactor(pc),a0
                lsl.w   #3,d0
                add.w   d1,d0
                lea     kSpinMultiplierFactor(pc),a2
                move.w  TEAMGENERALINFO_SPINTIMER(a6),d2
                lsl.w   #1,d2
                move.w  (a2,d2.w),d2
                move.w  (a0,d0.w),d1
                muls.w  d2,d1
                add.w   d1,SPRITE_DESTX(a1)
                move.w  2(a0,d0.w),d1
                muls.w  d2,d1
                add.w   d1,SPRITE_DESTY(a1)
not_starting_spin:
                cmpi.w  #4,TEAMGENERALINFO_SPINTIMER(a6) ; spin time = 4 here, check for high kick
                bne.w   increase_spin_timer
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d1
                bmi.w   normal_not_high_kick
                move.w  TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6),d0
                sub.w   d1,d0
                beq.w   jmp_increase_spin_timer
                andi.w  #7,d0
                cmpi.w  #2,d0
                beq.s   normal_not_high_kick
                cmpi.w  #6,d0
                beq.s   normal_not_high_kick
                cmpi.w  #3,d0
                bcs.s   jmp_increase_spin_timer
                cmpi.w  #5,d0
                bhi.s   jmp_increase_spin_timer
                move.l  kHighKickDeltaZ(pc),SPRITE_DELTAZ(a1)
                move.w  kHighKickBallSpeed(pc),SPRITE_SPEED(a1)
                bra.w   do_some_speed_adjustment
normal_not_high_kick:
                move.l  kNormalKickDeltaZ(pc),SPRITE_DELTAZ(a1)
                move.w  kNormalKickBallSpeed(pc),SPRITE_SPEED(a1)
                bra.w   do_some_speed_adjustment
jmp_increase_spin_timer:
                bra.w   increase_spin_timer
do_some_speed_adjustment:
                cmpi.w  #0,TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6)
                beq.s   decrease_ball_speed_by_quarter
                cmpi.w  #4,TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6)
                beq.s   decrease_ball_speed_by_quarter
                btst    #0,TEAMGENERALINFO_CONTROLLEDPLDIRECTION+1(a6)
                beq.w   increase_spin_timer
                move.w  SPRITE_SPEED(a1),d1
                lsr.w   #2,d1
                neg.w   d1
                add.w   SPRITE_SPEED(a1),d1
                move.w  SPRITE_SPEED(a1),d2
                lsr.w   #3,d2
                add.w   d2,d1
                move.w  d1,SPRITE_SPEED(a1)
                bra.w   increase_spin_timer
decrease_ball_speed_by_quarter:
                move.w  SPRITE_SPEED(a1),d1
                lsr.w   #2,d1
                neg.w   d1
                add.w   SPRITE_SPEED(a1),d1
                move.w  d1,SPRITE_SPEED(a1)
increase_spin_timer:
                addq.w  #1,TEAMGENERALINFO_SPINTIMER(a6)
                cmpi.w  #10,TEAMGENERALINFO_SPINTIMER(a6)
                bne.s   _113ABE_out
reset_spin_timer_out:
                move.w  #$FFFF,TEAMGENERALINFO_SPINTIMER(a6)
_113ABE_out:
                rts
passing_now:
                movea.l (a6),a0
                tst.w   TEAMGENERALINFO_GOALKEEPERSAVEDCOMMENTTIMER(a0)
                bmi.w   out_reset_spin_timer
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.w   game_in_progress2
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                beq.w   out_reset_spin_timer
game_in_progress2:
                move.w  TEAMGENERALINFO_SPINTIMER(a6),d0
                bmi.w   out2
                bne.s   spin_timer_running
                clr.w   TEAMGENERALINFO_LEFTSPIN(a6)
                clr.w   TEAMGENERALINFO_RIGHTSPIN(a6)
                clr.w   TEAMGENERALINFO_LONGPASS(a6)
                clr.w   TEAMGENERALINFO_LONGSPINPASS(a6)
spin_timer_running:
                lea     (ballSprite).l,a1
                tst.w   TEAMGENERALINFO_LEFTSPIN(a6)
                bne.s   pass_spining_left
                tst.w   TEAMGENERALINFO_RIGHTSPIN(a6)
                bne.s   pass_spining_right
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d1
                bmi.w   no_spin_to_apply
                move.w  TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6),d0
                sub.w   d1,d0
                beq.w   no_spin_to_apply
                andi.w  #7,d0
                cmpi.w  #4,d0
                beq.w   no_spin_to_apply
                bcs.s   turn_on_left_spin
                move.w  #1,TEAMGENERALINFO_RIGHTSPIN(a6)
pass_spining_right:
                moveq   #4,d1
                bra.s   apply_spin_factor
turn_on_left_spin:
                move.w  #1,TEAMGENERALINFO_LEFTSPIN(a6)
pass_spining_left:
                clr.w   d1
apply_spin_factor:
                move.w  (ballSprite+SPRITE_DIRECTION).l,d0
                lea     kPassingSpinFactor(pc),a0
                lsl.w   #3,d0
                add.w   d1,d0
                lea     kSpinMultiplierFactor(pc),a2
                move.w  TEAMGENERALINFO_SPINTIMER(a6),d2
                lsl.w   #1,d2
                move.w  (a2,d2.w),d2
                move.w  (a0,d0.w),d1
                muls.w  d2,d1
                add.w   d1,SPRITE_DESTX(a1)
                move.w  2(a0,d0.w),d1
                muls.w  d2,d1
                add.w   d1,SPRITE_DESTY(a1)
no_spin_to_apply:
                tst.l   TEAMGENERALINFO_LONGPASS(a6)
                bne.w   update_spin_timer
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d1
                bmi.w   holding_left_or_right
                move.w  TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6),d0
                sub.w   d1,d0
                beq.w   update_spin_timer2
                andi.w  #7,d0
                cmpi.w  #2,d0
                beq.s   holding_left_or_right
                cmpi.w  #6,d0
                beq.s   holding_left_or_right
                cmpi.w  #3,d0
                bcs.s   update_spin_timer2
                cmpi.w  #5,d0
                bhi.s   update_spin_timer2
                move.w  #1,TEAMGENERALINFO_LONGSPINPASS(a6)
                move.w  SPRITE_SPEED(a1),d0
                lsr.w   #3,d0
                add.w   d0,SPRITE_SPEED(a1)
                bra.w   update_spin_timer
holding_left_or_right:
                move.w  #1,TEAMGENERALINFO_LONGPASS(a6)
                move.w  SPRITE_SPEED(a1),d0
                lsr.w   #3,d0
                add.w   d0,SPRITE_SPEED(a1)
                bra.w   update_spin_timer
update_spin_timer2:
                bra.w   *+4
update_spin_timer:
                addq.w  #1,TEAMGENERALINFO_SPINTIMER(a6)
                cmpi.w  #$A,TEAMGENERALINFO_SPINTIMER(a6)
                bne.s   out2
out_reset_spin_timer:
                move.w  #$FFFF,TEAMGENERALINFO_SPINTIMER(a6)
out2:
                rts

; ===== ResetBothTeamSpinTimers =====
; prototype: void __usercall ResetBothTeamSpinTimers()
ResetBothTeamSpinTimers:
                move.w  #$FFFF,(topTeamData+TEAMGENERALINFO_SPINTIMER).l
                move.w  #$FFFF,(bottomTeamData+TEAMGENERALINFO_SPINTIMER).l
                rts

; ===== TestFoulForPenaltyAndFreeKick =====
; prototype: void __usercall TestFoulForPenaltyAndFreeKick(Sprite *player@<a2>, TeamGeneralInfo *team@<a6>)
; in:
;      A2 -> fouled player (sprite)
;      A6 -> team that fouled (general info)
; 
; Foul has been made. See where, and make it a penalty or
; free kick, depending on location. If not in appropriate
; areas, it's an ordinary foul.
TestFoulForPenaltyAndFreeKick:
                cmpi.w  #ST_STOPPED,(gameStatePl).l
                beq.w   _113DEA_ret
                jsr     PlayFoulWhistleSample
                jsr     nullsub_6
                move.w  SPRITE_X(a2),d1
                move.w  SPRITE_Y(a2),d2
                cmpa.l  #topTeamData,a6
                beq.s   top_team_penalty_check
                move.w  #4,(cameraDirection).l
                cmpi.w  #682,d2
                blt.w   bottom_free_kick_band_check
                cmpi.w  #193,d1
                blt.w   bottom_free_kick_band_check
                cmpi.w  #478,d1
                bgt.w   bottom_free_kick_band_check
                move.w  #ST_PENALTY,(gameState).l
                move.w  #$FFFF,(breakCameraMode).l
                move.b  #$38,(playerTurnFlags).l ; '8'
                move.w  #336,(foulXCoordinate).l
                move.w  #711,(foulYCoordinate).l
                movem.l d0-d7/a0-a6,-(sp)
                jsr     PlayPenalty
                movem.l (sp)+,d0-d7/a0-a6
                bra.w   apply_break_and_stop_play
top_team_penalty_check:
                move.w  #0,(cameraDirection).l
                cmpi.w  #216,d2
                bgt.s   top_free_kick_band_check
                cmpi.w  #193,d1
                blt.s   top_free_kick_band_check
                cmpi.w  #478,d1
                bgt.s   top_free_kick_band_check
                move.w  #ST_PENALTY,(gameState).l
                move.w  #$FFFF,(breakCameraMode).l
                move.b  #$83,(playerTurnFlags).l
                move.w  #336,(foulXCoordinate).l
                move.w  #187,(foulYCoordinate).l
                movem.l d0-d7/a0-a6,-(sp)
                jsr     PlayPenalty
                movem.l (sp)+,d0-d7/a0-a6
                bra.w   apply_break_and_stop_play
top_free_kick_band_check:
                cmpi.w  #216,d2
                blt.w   set_state_foul
                cmpi.w  #331,d2
                blt.s   select_fk_quadrant_by_side
                bra.w   set_state_foul
bottom_free_kick_band_check:
                cmpi.w  #567,d2
                blt.w   set_state_foul
                cmpi.w  #682,d2
                bgt.w   set_state_foul
select_fk_quadrant_by_side:
                cmpa.l  #bottomTeamData,a6
                beq.s   select_fk_quadrant_bottom_side
                cmpi.w  #153,d1
                blt.s   set_free_kick_left1
                cmpi.w  #261,d1
                blt.s   set_free_kick_left2
                cmpi.w  #309,d1
                blt.s   set_free_kick_left3
                cmpi.w  #362,d1
                blt.s   set_free_kick_center
                cmpi.w  #410,d1
                blt.s   set_free_kick_right1
