; ===== NextPenalty =====
; prototype: void __usercall NextPenalty()
; Next penalty is about to be shot. Check if penalties are over. If not,
; initialize globals for penalty, set penaltyShooterSprite.
; (penalties after the game)
NextPenalty:
                move.w  team1PenaltyAttempts(pc),d0
                add.w   team2PenaltyAttempts(pc),d0
                cmpi.w  #10,d0
                bcs.s   check_penalty_remaining_chances_team1
                move.w  team1PenaltyAttempts(pc),d0
                cmp.w   team2PenaltyAttempts(pc),d0
                bne.s   setup_next_penalty_round
                move.w  (team1PenaltyGoals).l,d0
                cmp.w   (team2PenaltyGoals).l,d0
                beq.s   setup_next_penalty_round
end_penalty_shootout:
                clr.w   (playingPenalties).l
                move.w  savedTeam1Goals(pc),(statsTeam1Goals).l
                move.w  savedTeam2Goals(pc),(statsTeam2Goals).l
                lea     (topTeamInGame).l,a0
                move.w  (team1PenaltyGoals).l,d0
                cmp.w   (team2PenaltyGoals).l,d0
                bhi.s   set_winning_team_pointer
                lea     (bottomTeamInGame).l,a0
set_winning_team_pointer:
                move.l  a0,(winningTeamPtr).l
                bsr.w   EndOfGame
                rts
check_penalty_remaining_chances_team1:
                move.w  #5,d0
                sub.w   team1PenaltyAttempts(pc),d0
                add.w   (team1PenaltyGoals).l,d0
                cmp.w   (team2PenaltyGoals).l,d0
                bcs.s   end_penalty_shootout
                move.w  #5,d0
                sub.w   team2PenaltyAttempts(pc),d0
                add.w   (team2PenaltyGoals).l,d0
                cmp.w   (team1PenaltyGoals).l,d0
                bcs.s   end_penalty_shootout
setup_next_penalty_round:
                clr.w   (ballSprite+SPRITE_Z).l
                neg.w   (teamPlayingUp).l
                addq.w  #3,(teamPlayingUp).l
                neg.w   (teamStarting).l
                addq.w  #3,(teamStarting).l
                clr.w   (hideBall).l
                bsr.w   InitTeamsData
                move.w  #ST_PENALTIES,(gameState).l
                move.w  #$FFFF,(breakCameraMode).l
                move.w  #0,(cameraDirection).l ; north
                move.b  #$83,(playerTurnFlags).l ; allow only NW, N, NE
                move.w  #336,(foulXCoordinate).l ; upper white spot
                move.w  #187,(foulYCoordinate).l
                move.w  #ST_STOPPED,(gameStatePl).l
                clr.w   (gameNotInProgressCounterWriteOnly).l
                lea     bottomTeamData(pc),a6
                move.l  a6,(lastTeamPlayedBeforeBreak).l
                clr.w   (stoppageTimerTotal).l
                clr.w   (stoppageTimerActive).l
                bsr.w   StopAllPlayers
                clr.w   (cameraXVelocity).l
                clr.w   (cameraYVelocity).l
                clr.w   (penaltiesTimer).l
                lea     team1PenaltyShooterIndex(pc),a0
                cmpi.w  #1,TEAMGENERALINFO_TEAMNUMBER(a6)
                beq.s   decrement_penalty_shooter_index
                lea     team2PenaltyShooterIndex(pc),a0
decrement_penalty_shooter_index:
                subq.w  #1,(a0)
                bne.s   load_penalty_shooter_sprite
                move.w  #10,(a0)
load_penalty_shooter_sprite:
                move.w  (a0),d0         ; player index to take the penalty
                movea.l TEAMGENERALINFO_SPRITESTABLE(a6),a0
                lsl.w   #2,d0
                move.l  (a0,d0.w),(penaltyShooterSprite).l
                cmpi.w  #1,TEAMGENERALINFO_TEAMNUMBER(a6)
                bne.s   increment_team2_penalty_attempts
                addq.w  #1,(team1PenaltyAttempts).l
                rts
increment_team2_penalty_attempts:
                addq.w  #1,(team2PenaltyAttempts).l
                rts

