; ===== UpdatePlayers =====
; prototype: char __usercall UpdatePlayers@<d0>(struct TeamGeneralInfo *teamInfo@<a6>)
; in:
;      A6 -> team data
;      
; This is practically main SWOS procedure. Everything happens here.
; Binary size: 0x5438/21,560 bytes
UpdatePlayers:
                move.l  lastPlayerPlayed(pc),(prevLastPlayer).l
                move.l  lastTeamPlayed(pc),(prevLastTeamPlayed).l
                tst.l   (lastKeeperPlayed).l
                beq.s   update_goalkeeper_saved_timer
                cmpi.l  #goalie1Sprite,(lastPlayerPlayed).l
                beq.s   update_goalkeeper_saved_timer
                cmpi.l  #goalie2Sprite,(lastPlayerPlayed).l
                beq.s   update_goalkeeper_saved_timer
                clr.l   (lastKeeperPlayed).l ; some sanity check, if last played keeper pointer doesn't point to any of two
                                        ; goalkeepers in the game, set it to null (maybe goalkeeper was substituted?)
update_goalkeeper_saved_timer:
                tst.w   TEAMGENERALINFO_GOALKEEPERSAVEDCOMMENTTIMER(a6)
                beq.s   update_pass_kick_timer
                bmi.s   decay_goalkeeper_saved_timer
                subq.w  #1,TEAMGENERALINFO_GOALKEEPERSAVEDCOMMENTTIMER(a6)
                bra.s   update_pass_kick_timer
decay_goalkeeper_saved_timer:
                addq.w  #1,TEAMGENERALINFO_GOALKEEPERSAVEDCOMMENTTIMER(a6) ; goalkeeper saved timer is negative, increase it
update_pass_kick_timer:
                tst.w   TEAMGENERALINFO_PASSKICKTIMER(a6)
                beq.s   pass_kick_timer_expired
                subq.w  #1,TEAMGENERALINFO_PASSKICKTIMER(a6) ; pass kick timer not zero, decrease it
                bne.s   pass_kick_timer_expired
                clr.l   TEAMGENERALINFO_PASSINGKICKINGPLAYER(a6)
pass_kick_timer_expired:
                tst.w   TEAMGENERALINFO_WONTHEBALLTIMER(a6)
                beq.s   update_player_switch_timer
                subq.w  #1,TEAMGENERALINFO_WONTHEBALLTIMER(a6)
update_player_switch_timer:
                tst.w   TEAMGENERALINFO_PLAYERSWITCHTIMER(a6)
                beq.s   switch_timer_expired
                subq.w  #1,TEAMGENERALINFO_PLAYERSWITCHTIMER(a6)
switch_timer_expired:
                bsr.w   ApplyBallAfterTouch ; handle kicks, passes, after touch
                lea     (ballSprite).l,a2 ; A2 -> ball sprite, from now on
                move.w  SPRITE_X(a2),d1 ; D1 = ball x, D2 = ball y
                move.w  SPRITE_Y(a2),d2
                clr.w   (ballInUpperPenaltyArea).l
                clr.w   (ballInLowerPenaltyArea).l
                clr.w   (ballInGoalkeeperArea).l
                cmpi.w  #193,d1         ; left penalty area limit
                blt.s   not_in_penalty_area
                cmpi.w  #478,d1         ; right penalty area limit
                bgt.s   not_in_penalty_area
                cmpi.w  #129,d2         ; top goal line
                blt.s   not_in_penalty_area
                cmpi.w  #769,d2         ; bottom goal line
                bgt.s   not_in_penalty_area
                cmpi.w  #216,d2         ; top penalty line
                ble.s   upper_penalty_area
                cmpi.w  #682,d2         ; bottom penalty line
                blt.s   not_in_penalty_area
                move.w  #1,(ballInLowerPenaltyArea).l
                bra.s   check_goalkeeper_area
upper_penalty_area:
                move.w  #1,(ballInUpperPenaltyArea).l
check_goalkeeper_area:
                cmpi.w  #273,d1         ; goalkeeper area left
                blt.s   not_in_penalty_area
                cmpi.w  #398,d1         ; goalkeeper area right
                bgt.s   not_in_penalty_area
                cmpi.w  #158,d2         ; top goalkeepeer area bottom
                ble.s   goalkeeper_area
                cmpi.w  #740,d2         ; bottom goalkeeper area top
                blt.s   not_in_penalty_area
goalkeeper_area:
                move.w  #1,(ballInGoalkeeperArea).l
not_in_penalty_area:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.s   no_reset_goal_out
                tst.w   (goalOut).l
                beq.s   no_reset_goal_out
                tst.l   (ballInUpperPenaltyArea).l
                bne.s   no_reset_goal_out
                clr.w   (goalOut).l
no_reset_goal_out:
                addq.w  #1,TEAMGENERALINFO_UPDATEPLAYERINDEX(a6)
                cmpi.w  #11,TEAMGENERALINFO_UPDATEPLAYERINDEX(a6)
                bne.s   init_players_loop
                clr.w   TEAMGENERALINFO_UPDATEPLAYERINDEX(a6)
init_players_loop:
                move.w  #10,d4          ; counter, 11 players
                movea.l TEAMGENERALINFO_SPRITESTABLE(a6),a3 ; A3 -> sprites table
players_loop:
                move.w  d4,-(sp)        ; save how many players are left (0 based)
                movea.l (a3)+,a1        ; A1 -> current player sprite
                move.w  SPRITE_DIRECTION(a1),SPRITE_PLAYERDIRECTION(a1)
                move.l  SPRITE_DELTAX(a1),d0
                or.l    SPRITE_DELTAY(a1),d0
                sne     SPRITE_ISMOVING(a1)
                cmpi.b  #PL_TACKLED,SPRITE_PLAYERSTATE(a1)
                beq.w   player_tackled_state
                cmpi.b  #PL_ROLLING_INJURED,SPRITE_PLAYERSTATE(a1)
                beq.w   player_injured_recover_tick
                cmpa.l  TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a1
                beq.w   this_is_controlled_player
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a1)
                beq.w   this_is_controlled_player
                cmpa.l  TEAMGENERALINFO_PASSTOPLAYERPTR(a6),a1
                beq.w   this_is_controlled_player
                cmpi.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a1)
                bne.s   this_is_controlled_player
                tst.w   (injuriesForever).l
                beq.s   jmp_not_controlled_player ; jump!
                cmpi.w  #$FFFF,SPRITE_INJURYLEVEL(a1)
                beq.w   injury_forever_tick
jmp_not_controlled_player:
                bra.w   not_controlled_player
this_is_controlled_player:
                move.b  TEAMGENERALINFO_PLVERYCLOSETOBALL(a6),TEAMGENERALINFO_PREVPLVERYCLOSETOBALL(a6)
                clr.b   TEAMGENERALINFO_PLVERYCLOSETOBALL(a6)
                clr.b   TEAMGENERALINFO_PLCLOSETOBALL(a6)
                clr.b   TEAMGENERALINFO_PLNOTFARFROMBALL(a6)
                move.l  SPRITE_BALLDISTANCE(a1),d0
                cmpi.l  #32,d0
                bls.s   very_close_to_ball
                cmpi.l  #72,d0
                bls.s   close_to_ball
                cmpi.l  #2450,d0
                bls.s   little_bit_close_to_ball
                bra.s   ball_distance_set
very_close_to_ball:
                move.b  #1,TEAMGENERALINFO_PLVERYCLOSETOBALL(a6)
                bra.s   ball_distance_set
close_to_ball:
                move.b  #1,TEAMGENERALINFO_PLCLOSETOBALL(a6)
                bra.s   ball_distance_set
little_bit_close_to_ball:
                move.b  #1,TEAMGENERALINFO_PLNOTFARFROMBALL(a6)
ball_distance_set:
                clr.b   TEAMGENERALINFO_BALLLESSEQUAL4(a6)
                clr.b   TEAMGENERALINFO_BALL4TO8(a6)
                clr.b   TEAMGENERALINFO_BALL8TO12(a6)
                clr.b   TEAMGENERALINFO_BALL12TO17(a6)
                clr.b   TEAMGENERALINFO_BALLABOVE17(a6)
                move.w  SPRITE_Z(a2),d0
                cmpi.w  #17,d0
                bhi.s   ball_too_high
                cmpi.w  #12,d0
                bhi.s   ball_high
                cmpi.w  #8,d0
                bhi.s   ball_medium_height
                cmpi.w  #4,d0
                bhi.s   ball_low
                move.b  #1,TEAMGENERALINFO_BALLLESSEQUAL4(a6)
                bra.s   check_player_state
ball_low:
                move.b  #1,TEAMGENERALINFO_BALL4TO8(a6)
                bra.s   check_player_state
ball_medium_height:
                move.b  #1,TEAMGENERALINFO_BALL8TO12(a6)
                bra.s   check_player_state
ball_high:
                move.b  #1,TEAMGENERALINFO_BALL12TO17(a6)
                bra.s   check_player_state
ball_too_high:
                move.b  #1,TEAMGENERALINFO_BALLABOVE17(a6)
check_player_state:
                cmpi.b  #PL_TACKLING,SPRITE_PLAYERSTATE(a1)
                beq.w   tackle_update_state
                cmpi.b  #PL_JUMP_HEADING,SPRITE_PLAYERSTATE(a1)
                beq.w   player_jump_heading
                cmpi.b  #PL_STATIC_HEADING,SPRITE_PLAYERSTATE(a1)
                beq.w   player_static_heading
                cmpi.b  #PL_THROW_IN,SPRITE_PLAYERSTATE(a1)
                beq.w   throw_in_state_handler
                cmpi.b  #PL_GOALIE_DIVING_HIGH,SPRITE_PLAYERSTATE(a1)
                beq.w   goalie_diving
                cmpi.b  #PL_GOALIE_DIVING_LOW,SPRITE_PLAYERSTATE(a1)
                beq.w   goalie_diving
                cmpi.b  #PL_GOALIE_CATCHING_BALL,SPRITE_PLAYERSTATE(a1)
                beq.w   goalie_catching_ball
                cmpi.b  #PL_DOWN,SPRITE_PLAYERSTATE(a1)
                beq.w   player_down_st_10
                cmpi.b  #PL_BOOKED,SPRITE_PLAYERSTATE(a1)
                beq.w   booking_handler_waiting
                cmpi.b  #PL_SAD,SPRITE_PLAYERSTATE(a1)
                beq.w   player_sad_or_happy
                cmpi.b  #PL_HAPPY,SPRITE_PLAYERSTATE(a1)
                beq.w   player_sad_or_happy
                cmpi.b  #PL_GOALIE_CLAIMED,SPRITE_PLAYERSTATE(a1)
                beq.w   goalie_claimed
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a1)
                beq.w   player_goalkeeper
                cmpa.l  TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a1
                beq.w   its_controlled_player
                cmpa.l  TEAMGENERALINFO_PASSTOPLAYERPTR(a6),a1
                beq.w   receiver_expect_pass_tick
                move.w  #2,(panicReasonCode).l
                jsr     PanicHaltLoop
player_goalkeeper:
                tst.w   (playingPenalties).l
                beq.s   not_playing_penalties
                cmpi.w  #50,(penaltiesTimer).l
                bhi.w   finalize_control_and_speed
not_playing_penalties:
                jsr UpdatePlayerShotChanceTable(pc)
                tst.w   (goalkeeperSkipFlag).l
                bne.w   return_last_player_block
                move.w  #$FFFF,(ballNextGroundX).l
                tst.w   TEAMGENERALINFO_GOALKEEPERPLAYING(a6)
                beq.s   goalie_not_posing_as_player
                move.b  #1,TEAMGENERALINFO_GOALIEPLAYINGOROUT(a6)
                clr.b   TEAMGENERALINFO_BALLOUTOFPLAYORKEEPER(a6)
                cmpa.l  TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a1
                beq.w   its_controlled_player
                clr.w   TEAMGENERALINFO_GOALKEEPERPLAYING(a6)
goalie_not_posing_as_player:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                sne     TEAMGENERALINFO_GOALIEPLAYINGOROUT(a6)
                sne     TEAMGENERALINFO_BALLOUTOFPLAYORKEEPER(a6)
                beq.s   set_goalkeeper_speed_for_play
                move.w  kGoalkeeperSpeedWhenGameStopped(pc),SPRITE_SPEED(a1)
set_goalkeeper_speed_for_play:
                move.w  kGoalkeeperGameSpeed(pc),SPRITE_SPEED(a1)
                cmpi.w  #449,SPRITE_Y(a1)
                bhi.s   goalkeeper_in_lower_half
                cmpa.l  #bottomTeamData,a6
                beq.w   return_last_player_block
                bra.s   goalkeeper_in_upper_half
goalkeeper_in_lower_half:
                cmpa.l  #topTeamData,a6
                beq.w   return_last_player_block
goalkeeper_in_upper_half:
                cmpi.b  #PL_GOALIE_CATCHING_BALL,$C(a1)
                bne.w   goalie_not_catching_the_ball ; this jump is always taken
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l ; unreachable code (state was checked above and it wasn't goalie catching ball)
                subq.b  #1,SPRITE_PLAYERDOWNTIMER(a1)
                beq.s   player_got_up   ; goalkeeper in the air, set ball coordinates as player destination (with y +/-1)
                move.w  SPRITE_X(a2),SPRITE_DESTX(a1) ; A1 -> player sprite
                                        ; A2 -> ball sprite
                move.w  SPRITE_Y(a2),SPRITE_DESTY(a1)
                cmpa.l  #bottomTeamData,a6
                beq.s   increase_y_dest
                subq.w  #1,SPRITE_DESTY(a1) ; decrease y for upper team (go a little behind the ball)
                bra.w   goalie_can_catch_checks
increase_y_dest:
                addq.w  #1,SPRITE_DESTY(a1)
                bra.w   goalie_can_catch_checks
player_got_up:
                move.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a1) ; player just got up
                lea     (playerNormalStandingAnimTable).l,a0
                jsr     SetPlayerAnimationTable
goalie_not_catching_the_ball:
                cmpa.l  TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a1
                beq.w   its_controlled_player
                cmpa.l  TEAMGENERALINFO_PASSTOPLAYERPTR(a6),a1
                beq.w   receiver_expect_pass_tick
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l ; goalkeeper that is not controlled or passed to
                bne.w   not_controlled_player
                move.w  SPRITE_X(a2),d1 ; D1 = ball x
                                        ; D2 = ball y
                                        ; A2 -> ball sprite
                move.w  SPRITE_Y(a2),d2
                cmpa.l  #bottomTeamData,a6
                beq.s   check_lower_penalty_area
                tst.w   (ballInUpperPenaltyArea).l ; upper team
                beq.w   clear_keeper_hold_flags_then_return
                bra.w   ball_in_penalty_area
check_lower_penalty_area:
                tst.w   (ballInLowerPenaltyArea).l ; lower team
                beq.w   clear_keeper_hold_flags_then_return
ball_in_penalty_area:
                cmpa.l  lastPlayerPlayed(pc),a1
                beq.w   return_last_player_block
                jsr UpdateBallVariables(pc) ; goalkeeper hasn't touched the ball in previous frame,
                                        ; and the ball isn't in penalty area
                jsr CalculateBallNextGroundXYPositions(pc)
                tst.w   (ballInGoalkeeperArea).l
                bne.s   ball_in_lower_goalkeeper_area
                movea.l TEAMGENERALINFO_SHOTCHANCETABLE(a6),a0 ; ball not in penalty or goalkeeper area
                move.w  currentGameTick(pc),d0
                andi.w  #$F0,d0
                lsr.w   #4,d0
                cmp.w   GOALIESKILL_FIELD_3A(a0),d0 ; compared to stoppagetimer
                bcc.w   ball_standing_in_goalkeeper_area
ball_in_lower_goalkeeper_area:
                tst.w   (ballNextGroundX).l
                bmi.w   ball_standing_in_goalkeeper_area
                move.w  ballNextGroundX(pc),d1
                move.w  ballNextYGroundY(pc),d2
                cmpa.l  #bottomTeamData,a6
                beq.s   bottom_goalkeeper_area_bounds_check
                cmpi.w  #137,d2
                blt.w   ball_standing_in_goalkeeper_area
                cmpi.w  #216,d2         ; penalty area limit
                bgt.w   ball_standing_in_goalkeeper_area
                cmpi.w  #193,d1
                blt.w   ball_standing_in_goalkeeper_area
                cmpi.w  #478,d1
                bgt.w   ball_standing_in_goalkeeper_area
                bra.w   in_penalty_area
bottom_goalkeeper_area_bounds_check:
                cmpi.w  #682,d2
                blt.w   ball_standing_in_goalkeeper_area
                cmpi.w  #761,d2
                bgt.w   ball_standing_in_goalkeeper_area
                cmpi.w  #193,d1
                blt.w   ball_standing_in_goalkeeper_area
                cmpi.w  #478,d1
                bgt.w   ball_standing_in_goalkeeper_area
in_penalty_area:
                move.w  ballNextGroundX(pc),d0
                sub.w   SPRITE_X(a1),d0
                move.w  ballNextYGroundY(pc),d1
                sub.w   SPRITE_Y(a1),d1
                muls.w  d0,d0
                muls.w  d1,d1
                add.l   d0,d1
                move.w  ballNextGroundX(pc),d0
                sub.w   SPRITE_X(a2),d0
                move.w  ballNextYGroundY(pc),d2
                sub.w   SPRITE_Y(a2),d2
                muls.w  d0,d0
                muls.w  d2,d2
                add.l   d0,d2           ; D1 = sqr(ball landing location - goalkeeper location)
                lsl.l   #2,d1           ; D2 = sqr(ball landing location - current location)
                cmp.l   d2,d1
                bhi.w   ball_standing_in_goalkeeper_area
                move.w  ballNextGroundX(pc),SPRITE_DESTX(a1) ; ball is flying into the penalty area and goalkeeper is 4 times closer to the
                                        ; predicted ground hit location than the ball currently is -- make the
                                        ; goalkeeper move to the place where the ball will land
                move.w  ballNextYGroundY(pc),SPRITE_DESTY(a1)
                move.w  kGoalkeeperMoveToBallSpeed(pc),SPRITE_SPEED(a1)
                bra.w   goalie_can_catch_checks
ball_standing_in_goalkeeper_area:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.w   return_to_last_played_player
                cmpi.w  #295,(strikeDestX).l
                bcs.s   shot_on_goal_or_close
                cmpi.w  #376,(strikeDestX).l
                bls.w   goal_attempt
shot_on_goal_or_close:
                cmpi.l  #512,SPRITE_BALLDISTANCE(a1)
                bcc.s   goalkeeper_dont_throw
                tst.b   TEAMGENERALINFO_BALLABOVE17(a6)
                bne.s   goalkeeper_dont_throw
                move.w  SPRITE_X(a2),SPRITE_DESTX(a1) ; it's a dangerous shot, goalie needs to dive to stop this
                move.w  SPRITE_Y(a2),SPRITE_DESTY(a1) ; set goalkeepers destination to balls coordinates
                bra.w   goalie_can_catch_checks
goalkeeper_dont_throw:
                tst.b   TEAMGENERALINFO_BALLABOVE17(a6) ; goalkeeper is 512 pixels or more away from the ball, and it's a shot on goal (or close)
                bne.s   evaluate_catchability_and_nearest_owner
                tst.w   (ballInGoalkeeperArea).l
                bne.s   center_goalkeeper_on_ball_x
                cmpi.w  #449,SPRITE_Y(a2)
                bcs.s   ball_moving_up_check
                tst.l   SPRITE_DELTAY(a2)
                ble.s   evaluate_catchability_and_nearest_owner
                bra.s   set_dest_x_toward_center_from_ball_x
ball_moving_up_check:
                tst.l   SPRITE_DELTAY(a2)
                bpl.w   evaluate_catchability_and_nearest_owner
set_dest_x_toward_center_from_ball_x:
                move.w  SPRITE_X(a2),d0
                subi.w  #336,d0
                asr.w   #1,d0
                addi.w  #336,d0
                move.w  d0,SPRITE_DESTX(a1)
                bra.s   compute_dest_y_from_ball
center_goalkeeper_on_ball_x:
                move.w  SPRITE_X(a2),SPRITE_DESTX(a1)
compute_dest_y_from_ball:
                cmpi.w  #449,SPRITE_Y(a2)
                bcs.s   dest_y_upper_half
                move.w  #769,d0
                sub.w   SPRITE_Y(a2),d0
                lsr.w   #1,d0
                add.w   SPRITE_Y(a2),d0
                bra.s   commit_dest_y
dest_y_upper_half:
                move.w  SPRITE_Y(a2),d0
                subi.w  #129,d0
                lsr.w   #1,d0
                addi.w  #129,d0
commit_dest_y:
                move.w  d0,SPRITE_DESTY(a1)
                movea.l TEAMGENERALINFO_SHOTCHANCETABLE(a6),a0
                move.w  6(a0),SPRITE_SPEED(a1)
                move.w  6(a0),d0
                lsr.w   #1,d0
                bra.w   goalie_can_catch_checks
evaluate_catchability_and_nearest_owner:
                cmpi.w  #16,SPRITE_Z(a2)
                bhi.w   cannot_intercept_fallback
                tst.w   (ballDefensiveX).l
                bmi.w   cannot_intercept_fallback
                move.l  SPRITE_BALLDISTANCE(a1),d0
                movea.l TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a0
                cmpa.l  #0,a0
                beq.s   check_team_controlled_player_dist
                cmp.l   SPRITE_BALLDISTANCE(a0),d0
                bhi.s   cannot_intercept_fallback
check_team_controlled_player_dist:
                movea.l TEAMGENERALINFO_PASSTOPLAYERPTR(a6),a0
                cmpa.l  #0,a0
                beq.s   check_opponent_controlled_player_dist
                cmp.l   SPRITE_BALLDISTANCE(a0),d0
                bhi.s   cannot_intercept_fallback
check_opponent_controlled_player_dist:
                movea.l (a6),a0
                movea.l TEAMGENERALINFO_CONTROLLEDPLAYER(a0),a0
                cmpa.l  #TEAMGENERALINFO_OPPONENTSTEAM,a0
                beq.s   check_opponent_pass_target_dist
                cmp.l   SPRITE_BALLDISTANCE(a0),d0
                bhi.s   cannot_intercept_fallback
check_opponent_pass_target_dist:
                movea.l (a6),a0
                movea.l TEAMGENERALINFO_PASSTOPLAYERPTR(a0),a0
                cmpa.l  #TEAMGENERALINFO_OPPONENTSTEAM,a0
                beq.w   set_dest_to_ball_defensive_coords
                cmp.l   SPRITE_BALLDISTANCE(a0),d0
                bhi.w   cannot_intercept_fallback
set_dest_to_ball_defensive_coords:
                move.w  ballDefensiveX(pc),SPRITE_DESTX(a1)
                move.w  ballDefensiveY(pc),SPRITE_DESTY(a1)
                bra.w   goalie_can_catch_checks
cannot_intercept_fallback:
                tst.w   TEAMGENERALINFO_PLAYERHASBALL(a6)
                bne.w   return_last_player_block
                bra.w   return_last_player_block
goal_attempt:
                cmpa.l  lastTeamPlayed(pc),a6
                bne.s   pre_save_possession_distance_gate
                tst.w   (playerHadBall).l
                beq.w   save_attempted_set_burst_speed
pre_save_possession_distance_gate:
                cmpi.l  #512,SPRITE_BALLDISTANCE(a1)
                bcc.s   midrange_positioning_from_ball
                tst.b   TEAMGENERALINFO_BALLABOVE17(a6)
                bne.s   midrange_positioning_from_ball
                move.w  SPRITE_X(a2),SPRITE_DESTX(a1)
                move.w  SPRITE_Y(a2),SPRITE_DESTY(a1)
                bra.w   shot_at_goal
midrange_positioning_from_ball:
                cmpi.l  #2048,SPRITE_BALLDISTANCE(a1)
                bhi.s   far_or_unfavorable_shot_branch
                tst.b   TEAMGENERALINFO_BALLABOVE17(a6)
                bne.s   far_or_unfavorable_shot_branch
                move.w  SPRITE_X(a2),d0
                subi.w  #336,d0
                asr.w   #1,d0
                addi.w  #336,d0
                move.w  d0,SPRITE_DESTX(a1)
                cmpi.w  #449,SPRITE_Y(a2)
                bcs.s   midrange_dest_y_upper_half
                move.w  #769,d0
                sub.w   SPRITE_Y(a2),d0
                lsr.w   #1,d0
                add.w   SPRITE_Y(a2),d0
                bra.s   commit_midrange_dest_y
midrange_dest_y_upper_half:
                move.w  SPRITE_Y(a2),d0
                subi.w  #129,d0
                lsr.w   #1,d0
                addi.w  #129,d0
commit_midrange_dest_y:
                move.w  d0,SPRITE_DESTY(a1)
                movea.l TEAMGENERALINFO_SHOTCHANCETABLE(a6),a0
                move.w  6(a0),SPRITE_SPEED(a1)
                move.w  6(a0),d0
                lsr.w   #1,d0
                bra.w   shot_at_goal
far_or_unfavorable_shot_branch:
                movea.l (a6),a0
                tst.w   TEAMGENERALINFO_PLAYERHASBALL(a0)
                bne.w   mark_opponent_and_chase
                tst.w   TEAMGENERALINFO_PLAYERHASBALL(a6)
                bne.w   mark_opponent_and_chase
                tst.b   TEAMGENERALINFO_PLVERYCLOSETOBALL(a6)
                bne.w   mark_opponent_and_chase
                cmpa.l  lastTeamPlayed(pc),a6
                bne.s   consider_save_vs_last_possession
                tst.w   (playerHadBall).l
                beq.w   save_attempted_set_burst_speed
consider_save_vs_last_possession:
                move.w  kShotAtGoalMinumumSpeed(pc),d0
                cmp.w   SPRITE_SPEED(a2),d0
                bcs.s   shot_at_goal
                cmpi.l  #5000,$4A(a1)
                bhi.w   save_not_attempted_set_run_speed
                cmpi.w  #12,SPRITE_Z(a2)
                bhi.w   save_not_attempted_set_run_speed
                cmpi.l  #$8000,SPRITE_DELTAZ(a2)
                bgt.w   save_not_attempted_set_run_speed
                cmpi.l  #-$8000,SPRITE_DELTAZ(a2)
                blt.w   save_not_attempted_set_run_speed
                bra.w   mark_opponent_and_chase
shot_at_goal:
                cmpi.w  #16,SPRITE_Z(a2)
                bhi.w   save_not_attempted_set_run_speed
                tst.w   TEAMGENERALINFO_GOALKEEPERSAVEDCOMMENTTIMER(a6)
                bgt.w   goalie_save_attempt_entry
                cmpi.l  #128,SPRITE_BALLDISTANCE(a1)
                bhi.w   goalie_save_attempt_entry
                tst.b   TEAMGENERALINFO_BALLABOVE17(a6)
                bne.w   goalie_save_attempt_entry
                movea.l (a6),a0
                tst.b   TEAMGENERALINFO_FIREPRESSED(a0)
                beq.w   goalie_save_attempt_entry
                tst.w   TEAMGENERALINFO_PLAYERHASBALL(a0)
                bne.s   prepare_finisher_vs_goalie_skill_delta
                cmpi.w  #22,TEAMGENERALINFO_PASSKICKTIMER(a0)
                bcs.w   goalie_save_attempt_entry
prepare_finisher_vs_goalie_skill_delta:
                clr.w   d1
                movea.l (a6),a0
                movea.l TEAMGENERALINFO_LASTHEADINGTACKLINGPLAYER(a0),a0
                cmpa.l  #TEAMGENERALINFO_OPPONENTSTEAM,a0
                beq.s   get_goalie_skill
                exg     a0,a1
                bsr.w   GetPlayerPointerFromShirtNumber
                exg     a0,a1
                move.b  PLAYERINFOHEADER_FINISHING(a4),d1
get_goalie_skill:
                bsr.w   GetPlayerPointerFromShirtNumber
                sub.b   PLAYERINFOHEADER_GOALIESKILL(a4),d1
                ext.w   d1
                addq.w  #7,d1
                lea     goalScoredChances(pc),a0
                move.w  currentGameTick(pc),d0
                lsr.w   #1,d0
                andi.w  #$F,d0          ; lower number means goalkeeper is much better
                cmp.b   (a0,d1.w),d0
                bcs.s   goalie_react_goal_scored
                move.w  #5,TEAMGENERALINFO_GOALKEEPERSAVEDCOMMENTTIMER(a6)
                bra.w   goalie_save_attempt_entry
goalie_react_goal_scored:
                move.w  #-5,TEAMGENERALINFO_GOALKEEPERSAVEDCOMMENTTIMER(a6)
                move.w  #2,d1
                move.w  SPRITE_X(a2),d0
                cmp.w   SPRITE_X(a1),d0
                bcs.s   face_left_after_goal
                move.w  #2,d0           ; turn right
                move.w  #2,d3
                bra.w   apply_facing_and_jump_prep
face_left_after_goal:
                move.w  #6,d0           ; turn left
                move.w  #6,d3
apply_facing_and_jump_prep:
                move.w  d0,SPRITE_DIRECTION(a1)
                move.w  (ballSprite+SPRITE_SPEED).l,(ballSpeed).l
                movea.l (a6),a0
                move.w  #$FFFF,SPRITE_ANIMATIONTABLE+$70(a0)
                cmpi.w  #1536,(ballSprite+SPRITE_SPEED).l
                bls.s   clamp_ball_speed
                move.w  #1536,(ballSprite+SPRITE_SPEED).l
clamp_ball_speed:
                movem.l a1,-(sp)        ; A1 -> player sprite
                bsr.w   GoalkeeperJumping
                movem.l (sp)+,a1
                move.w  (ballSprite+SPRITE_SPEED).l,(ballSpeedAfterSave).l
                clr.w   TEAMGENERALINFO_PASSKICKTIMER(a6)
                clr.l   TEAMGENERALINFO_PASSINGKICKINGPLAYER(a6)
                bra.w   clamp_keeper_y_min
goalie_save_attempt_entry:
                jsr ShouldGoalkeeperDive(pc) ; D0 = Attempt Save
                tst.w   d0
                beq.w   save_not_attempted_set_run_speed
                move.w  ballDefensiveX(pc),d0 ; Attempt save
                cmp.w   SPRITE_X(a1),d0
                bcs.s   ball_left_of_goalie_branch
                clr.w   d1
                tst.w   (playingPenalties).l
                bne.s   penalties_dive_blink_gate_a
                tst.w   (penalty).l
                beq.s   choose_turn_right_for_dive
penalties_dive_blink_gate_a:
                move.w  #1,d1
                move.w  currentGameTick(pc),d0
                andi.w  #6,d0
                beq.s   choose_turn_left_for_dive
                clr.w   d1
choose_turn_right_for_dive:
                move.w  #2,d0
                move.w  #2,d3
                bra.w   apply_facing_then_jump
ball_left_of_goalie_branch:
                clr.w   d1
                tst.w   (playingPenalties).l
                bne.s   penalties_dive_blink_gate_b
                tst.w   (penalty).l
                beq.s   choose_turn_left_for_dive
penalties_dive_blink_gate_b:
                move.w  #1,d1
                move.w  currentGameTick(pc),d0
                andi.w  #$C,d0
                beq.s   choose_turn_right_for_dive
                clr.w   d1
choose_turn_left_for_dive:
                move.w  #6,d0
                move.w  #6,d3
apply_facing_then_jump:
                move.w  d0,SPRITE_DIRECTION(a1)
                movem.l a1,-(sp)
                bsr.w   GoalkeeperJumping
                movem.l (sp)+,a1
                clr.w   TEAMGENERALINFO_PASSKICKTIMER(a6)
                clr.l   TEAMGENERALINFO_PASSINGKICKINGPLAYER(a6)
                bra.w   clamp_keeper_y_min
save_attempted_set_burst_speed:
                move.w  kGoalkeeperBurstSpeed(pc),SPRITE_SPEED(a1)
                bra.s   chase_ball_set_dest_from_ball_flat
save_not_attempted_set_run_speed:
                movea.l TEAMGENERALINFO_SHOTCHANCETABLE(a6),a0
                move.w  GOALIESKILL_SPEED_UNK2(a0),SPRITE_SPEED(a1)
chase_ball_set_dest_from_ball_flat:
                move.w  ballNotHighX(pc),SPRITE_DESTX(a1)
                move.w  ballNotHighY(pc),SPRITE_DESTY(a1)
                bra.w   goalie_can_catch_checks
mark_opponent_and_chase:
                tst.b   TEAMGENERALINFO_BALLABOVE17(a6)
                bne.s   save_not_attempted_set_run_speed
                move.w  SPRITE_X(a2),SPRITE_DESTX(a1)
                move.w  SPRITE_Y(a2),SPRITE_DESTY(a1)
                movea.l TEAMGENERALINFO_SHOTCHANCETABLE(a6),a0
                move.w  GOALIESKILL_SPEED_UNK(a0),SPRITE_SPEED(a1)
                bra.w   goalie_can_catch_checks
return_to_last_played_player:
                bra.w   return_last_player_block
                move.w  SPRITE_X(a1),SPRITE_DESTX(a1)
                move.w  SPRITE_Y(a1),SPRITE_DESTY(a1)
                bra.w   *+4
goalie_can_catch_checks:
                cmpa.l  lastTeamPlayed(pc),a6
                bne.s   if_opponent_last_touched
                tst.w   (playerHadBall).l
                beq.w   cannot_catch_exit
if_opponent_last_touched:
                tst.w   (ballInGoalkeeperArea).l
                bne.s   attempt_catch_conditions
                movea.l TEAMGENERALINFO_SHOTCHANCETABLE(a6),a0
                move.w  currentGameTick(pc),d0
                andi.w  #$F0,d0
                lsr.w   #4,d0
                cmp.w   58(a0),d0
                bcc.s   cannot_catch_exit
attempt_catch_conditions:
                tst.w   (ballNextGroundX).l
                bmi.s   cannot_catch_exit
                cmpi.w  #22,(ballDefensiveZ).l
                bgt.s   cannot_catch_exit
                cmpi.w  #12,(ballDefensiveZ).l
                ble.s   cannot_catch_exit
                cmpi.l  #2116,SPRITE_BALLDISTANCE(a1) ; 46^2
                bhi.s   cannot_catch_exit
                move.w  SPRITE_X(a1),d0
                sub.w   ballDefensiveX(pc),d0
                cmpi.w  #12,d0
                bgt.s   cannot_catch_exit
                cmpi.w  #-12,d0
                blt.s   cannot_catch_exit
                move.w  SPRITE_Y(a1),d0
                sub.w   ballDefensiveY(pc),d0
                cmpi.w  #12,d0
                bgt.s   cannot_catch_exit
                cmpi.w  #65524,d0
                blt.s   cannot_catch_exit
                jsr GoalkeeperCaughtTheBall(pc)
cannot_catch_exit:
                cmpa.l  lastPlayerPlayed(pc),a1
                beq.w   clamp_keeper_y_min
                cmpi.l  #72,SPRITE_BALLDISTANCE(a1)
                bhi.w   clamp_keeper_y_min
                tst.b   TEAMGENERALINFO_BALLABOVE17(a6)
                bne.w   clamp_keeper_y_min
                cmpi.b  #PL_GOALIE_CATCHING_BALL,SPRITE_PLAYERSTATE(a1)
                beq.w   prepare_catch_pose
                tst.b   TEAMGENERALINFO_BALL12TO17(a6)
                bne.w   clamp_keeper_y_min
prepare_catch_pose:
                move.w  SPRITE_X(a1),SPRITE_DESTX(a1)
                move.w  SPRITE_Y(a1),SPRITE_DESTY(a1)
                cmpa.l  lastTeamPlayed(pc),a6
                bne.w   opponent_player_touched_the_ball
                tst.w   (playerHadBall).l
                bne.w   opponent_player_touched_the_ball
                bsr.w   UpdateBallWithControllingGoalkeeper ; goalkeeper gets ball as a player
                move.l  a1,TEAMGENERALINFO_CONTROLLEDPLAYER(a6)
                clr.l   TEAMGENERALINFO_PASSTOPLAYERPTR(a6)
                move.w  #25,TEAMGENERALINFO_PLAYERSWITCHTIMER(a6)
                clr.w   TEAMGENERALINFO_PASSINGBALL(a6)
                clr.w   TEAMGENERALINFO_PASSINGTOPLAYER(a6)
                move.w  SPRITE_X(a1),SPRITE_DESTX(a1)
                move.w  SPRITE_Y(a1),SPRITE_DESTY(a1)
                move.l  a6,(lastTeamPlayed).l
                move.l  a1,(lastPlayerPlayed).l
                clr.w   (penalty).l
                clr.w   (playerHadBall).l
                clr.w   TEAMGENERALINFO_PASSKICKTIMER(a6)
                clr.l   104(a6)
                clr.w   116(a6)
                move.w  #1,TEAMGENERALINFO_GOALKEEPERPLAYING(a6)
