ensure_dest_matches_pos_when_unset:
                tst.w   TEAMGENERALINFO_PASSTOPLAYERPTR+2(a1)
                bne.w   finalize_control_and_speed
                tst.w   TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                bpl.s   maybe_grant_possession_if_close
                move.w  SPRITE_X(a1),SPRITE_DESTX(a1)
                move.w  SPRITE_Y(a1),SPRITE_DESTY(a1)
maybe_grant_possession_if_close:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.w   attempt_quick_pass
                tst.w   TEAMGENERALINFO_QUICKFIRE(a6)
                bne.w   attempt_quick_pass
                tst.w   TEAMGENERALINFO_SHOOTING(a6)
                bne.w   attempt_quick_pass
                tst.b   TEAMGENERALINFO_PLVERYCLOSETOBALL(a6)
                bne.s   enter_possession_and_clear_opponent_spin
                tst.b   TEAMGENERALINFO_PLCLOSETOBALL(a6)
                beq.w   unset_dir_header_tackle_gate
enter_possession_and_clear_opponent_spin:
                tst.w   TEAMGENERALINFO_ALLOWEDDIRECTIONS(a6)
                bne.s   attempt_header_or_tackle
                clr.w   TEAMGENERALINFO_UNKBALLTIMER(a6)
attempt_header_or_tackle:
                move.w  #1,TEAMGENERALINFO_PLAYERHASBALL(a6)
                movea.l (a6),a0
                move.w  #$FFFF,TEAMGENERALINFO_SPINTIMER(a0)
unset_dir_header_tackle_gate:
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d0
                bpl.s   start_win_ball_sequence
                tst.w   TEAMGENERALINFO_PLAYERNUMBER(a6)
                beq.s   jump_finalize_control_and_speed
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a1)
                beq.s   jump_finalize_control_and_speed
                tst.b   TEAMGENERALINFO_FIRETHISFRAME(a6)
                beq.s   jump_finalize_control_and_speed
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d0
                bpl.s   jump_finalize_control_and_speed
                tst.b   TEAMGENERALINFO_PLVERYCLOSETOBALL(a6)
                bne.s   require_ball_in_header_window
                tst.b   TEAMGENERALINFO_PLCLOSETOBALL(a6)
                bne.s   require_ball_in_header_window
                tst.b   TEAMGENERALINFO_PLNOTFARFROMBALL(a6)
                beq.s   jump_finalize_control_and_speed
require_ball_in_header_window:
                tst.b   TEAMGENERALINFO_BALL8TO12(a6)
                bne.s   attempt_static_header_sequence
                tst.b   TEAMGENERALINFO_BALL12TO17(a6)
                bne.s   attempt_static_header_sequence
                tst.b   TEAMGENERALINFO_BALLABOVE17(a6)
                beq.s   jump_finalize_control_and_speed
attempt_static_header_sequence:
                move.w  #1,TEAMGENERALINFO_HEADERORTACKLE(a6)
                move.w  SPRITE_DIRECTION(a1),d0
                movem.l a0-a3,-(sp)
                bsr.w   AttemptStaticHeader
                movem.l (sp)+,a0-a3
                move.l  a1,TEAMGENERALINFO_LASTHEADINGTACKLINGPLAYER(a6)
                clr.w   TEAMGENERALINFO_BALLCANBECONTROLLED(a6)
                bra.w   finalize_control_and_speed
jump_finalize_control_and_speed:
                bra.w   finalize_control_and_speed
start_win_ball_sequence:
                movea.l (a6),a0
                tst.w   TEAMGENERALINFO_PLAYERHASBALL(a0)
                bne.s   gate_on_win_timer_and_proximity
                clr.w   TEAMGENERALINFO_WONTHEBALLTIMER(a6)
gate_on_win_timer_and_proximity:
                tst.w   TEAMGENERALINFO_WONTHEBALLTIMER(a6)
                bne.w   compute_oob_dir_mask_and_block
                tst.b   TEAMGENERALINFO_PLVERYCLOSETOBALL(a6)
                beq.w   attempt_quick_pass
                tst.b   TEAMGENERALINFO_BALLABOVE17(a6)
                bne.w   attempt_quick_pass
                tst.b   TEAMGENERALINFO_BALL12TO17(a6)
                bne.w   attempt_quick_pass
                tst.b   TEAMGENERALINFO_PREVPLVERYCLOSETOBALL(a6)
                bne.w   validate_control_direction_consistency
                clr.w   TEAMGENERALINFO_BALLCANBECONTROLLED(a6)
validate_control_direction_consistency:
                cmp.w   TEAMGENERALINFO_BALLCONTROLLINGPLAYERDIRECTION(a6),d0
                beq.s   accumulate_ball_control_frames
                clr.w   TEAMGENERALINFO_BALLCANBECONTROLLED(a6)
accumulate_ball_control_frames:
                addq.w  #1,TEAMGENERALINFO_BALLCANBECONTROLLED(a6)
                move.w  TEAMGENERALINFO_BALLCANBECONTROLLED(a6),d1
                move.w  d0,TEAMGENERALINFO_BALLCONTROLLINGPLAYERDIRECTION(a6)
                move.l  a6,(lastTeamPlayed).l
                move.l  a1,(lastPlayerPlayed).l
                clr.w   (penalty).l
                clr.w   (playerHadBall).l
                movea.l (a6),a0
                tst.w   TEAMGENERALINFO_PLAYERHASBALL(a0)
                beq.s   invoke_calculate_win_ball
                move.w  #1,(playerHadBall).l
invoke_calculate_win_ball:
                movem.l d0/a0-a3,-(sp)
                bsr.w   CalculateIfPlayerWinsBall
                movem.l (sp)+,d0/a0-a3
                movea.l (a6),a0
                move.w  #$FFFF,TEAMGENERALINFO_SPINTIMER(a0)
                clr.w   TEAMGENERALINFO_PASSINGTOPLAYER(a0)
                clr.l   TEAMGENERALINFO_PASSINGKICKINGPLAYER(a0)
                bra.w   compute_oob_dir_mask_and_block
attempt_quick_pass:
                tst.b   TEAMGENERALINFO_QUICKFIRE(a6)
                beq.w   abort_quick_pass
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d0
                bmi.w   abort_quick_pass
                tst.b   TEAMGENERALINFO_PLVERYCLOSETOBALL(a6)
                bne.s   check_turn_allowance_if_stopped
                tst.b   TEAMGENERALINFO_PLCLOSETOBALL(a6)
                beq.w   abort_quick_pass
check_turn_allowance_if_stopped:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.w   check_ordinal_and_ball_range_for_pass
                btst    d0,playerTurnFlags(pc)
                beq.w   abort_quick_pass
check_ordinal_and_ball_range_for_pass:
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a1)
                beq.s   execute_pass_and_update_context
                tst.b   TEAMGENERALINFO_BALLLESSEQUAL4(a6)
                beq.w   abort_quick_pass
execute_pass_and_update_context:
                move.l  a6,(lastTeamPlayed).l ; 001960B2 Goalie kicking towards centre, debugging reached here
                move.l  a1,(lastPlayerPlayed).l
                clr.w   (penalty).l
                clr.w   (playerHadBall).l
                clr.w   SPRITE_Z(a2)
                movem.l d0/a0-a3,-(sp)
                bsr.w   DoPass
                movem.l (sp)+,d0/a0-a3
                move.l  a1,TEAMGENERALINFO_LASTHEADINGTACKLINGPLAYER(a6)
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.s   set_penalty_flag_if_in_penalty_state
                movem.l d0,-(sp)
                jsr     ThrowInDeadProc
                movem.l (sp)+,d0
                clr.w   (gameNotInProgressCounterWriteOnly).l
set_penalty_flag_if_in_penalty_state:
                cmpi.w  #ST_PENALTY,(gameState).l
                bne.s   finalize_pass_and_resume_play
                move.w  #1,(penalty).l
finalize_pass_and_resume_play:
                move.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                move.w  #ST_GAME_IN_PROGRESS,(gameState).l
                move.w  #1,TEAMGENERALINFO_BALLINPLAY(a6)
                move.w  #1,TEAMGENERALINFO_BALLOUTOFPLAY(a6)
                movea.l (a6),a0
                move.w  #1,TEAMGENERALINFO_BALLINPLAY(a0)
                move.w  #1,TEAMGENERALINFO_BALLOUTOFPLAY(a0)
                move.w  #$FFFF,TEAMGENERALINFO_SPINTIMER(a0)
                clr.l   TEAMGENERALINFO_CONTROLLEDPLAYER(a6)
                move.l  a1,TEAMGENERALINFO_PASSINGKICKINGPLAYER(a6)
                move.w  #25,TEAMGENERALINFO_PASSKICKTIMER(a6)
                clr.w   TEAMGENERALINFO_BALLCANBECONTROLLED(a6)
                movea.l (a6),a0
                clr.w   TEAMGENERALINFO_PASSINGTOPLAYER(a0)
                clr.l   TEAMGENERALINFO_PASSINGKICKINGPLAYER(a0)
                bra.w   snap_dest_to_current_pos
abort_quick_pass:
                tst.b   TEAMGENERALINFO_NORMALFIRE(a6)
                beq.w   handle_fire_for_tackle_or_header
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d0
                bmi.w   handle_fire_for_tackle_or_header
                tst.b   TEAMGENERALINFO_PLVERYCLOSETOBALL(a6)
                bne.s   check_turn_allowance_if_stopped_shot
                tst.b   TEAMGENERALINFO_PLCLOSETOBALL(a6)
                beq.w   handle_fire_for_tackle_or_header
check_turn_allowance_if_stopped_shot:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.w   check_ordinal_and_ball_range_for_shot
                btst    d0,playerTurnFlags(pc)
                beq.w   handle_fire_for_tackle_or_header
check_ordinal_and_ball_range_for_shot:
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a1)
                beq.s   execute_shot_and_update_context
                tst.b   TEAMGENERALINFO_BALLLESSEQUAL4(a6)
                beq.w   handle_fire_for_tackle_or_header
execute_shot_and_update_context:
                move.l  a6,(lastTeamPlayed).l
                move.l  a1,(lastPlayerPlayed).l
                clr.w   (penalty).l
                clr.w   (playerHadBall).l
                movem.l d0/a0-a3,-(sp)
                bsr.w   PlayerKickingBall
                movem.l (sp)+,d0/a0-a3
                move.l  a1,TEAMGENERALINFO_LASTHEADINGTACKLINGPLAYER(a6)
                cmpi.w  #100,(gameStatePl).l
                beq.s   set_penalty_flag_if_in_penalty_state2
                movem.l d0,-(sp)
                jsr     ThrowInDeadProc
                movem.l (sp)+,d0
                clr.w   (gameNotInProgressCounterWriteOnly).l
set_penalty_flag_if_in_penalty_state2:
                cmpi.w  #ST_PENALTY,(gameState).l
                bne.s   finalize_shot_and_resume_play
                move.w  #1,(penalty).l
finalize_shot_and_resume_play:
                move.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                move.w  #ST_GAME_IN_PROGRESS,(gameState).l
                move.w  #1,TEAMGENERALINFO_BALLINPLAY(a6)
                move.w  #1,TEAMGENERALINFO_BALLOUTOFPLAY(a6)
                movea.l (a6),a0
                move.w  #1,TEAMGENERALINFO_BALLINPLAY(a0)
                move.w  #1,TEAMGENERALINFO_BALLOUTOFPLAY(a0)
                move.w  #$FFFF,TEAMGENERALINFO_SPINTIMER(a0)
                clr.l   TEAMGENERALINFO_CONTROLLEDPLAYER(a6)
                move.l  a1,TEAMGENERALINFO_PASSINGKICKINGPLAYER(a6)
                move.w  #25,TEAMGENERALINFO_PASSKICKTIMER(a6)
                clr.w   TEAMGENERALINFO_BALLCANBECONTROLLED(a6)
                move.w  #1,TEAMGENERALINFO_SHOOTING(a6)
                movea.l (a6),a0
                clr.w   TEAMGENERALINFO_PASSINGTOPLAYER(a0)
                clr.l   TEAMGENERALINFO_PASSINGKICKINGPLAYER(a0)
                bra.w   snap_dest_to_current_pos
handle_fire_for_tackle_or_header:
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a1)
                beq.s   evaluate_jump_header_flow
                tst.b   TEAMGENERALINFO_FIRETHISFRAME(a6)
                beq.s   evaluate_jump_header_flow
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d0
                bmi.s   evaluate_jump_header_flow
                tst.b   TEAMGENERALINFO_PLNOTFARFROMBALL(a6)
                beq.s   evaluate_jump_header_flow
                tst.b   TEAMGENERALINFO_BALLLESSEQUAL4(a6)
                bne.s   prefer_closer_pass_target_over_tackle_check
                tst.b   TEAMGENERALINFO_BALL4TO8(a6)
                beq.s   evaluate_jump_header_flow
prefer_closer_pass_target_over_tackle_check:
                movea.l TEAMGENERALINFO_PASSTOPLAYERPTR(a6),a5
                cmpa.l  #0,a5
                beq.s   begin_tackle_and_clear_control
                move.l  SPRITE_BALLDISTANCE(a5),d1
                cmp.l   SPRITE_BALLDISTANCE(a1),d1
                bcs.s   evaluate_jump_header_flow
begin_tackle_and_clear_control:
                move.w  #1,TEAMGENERALINFO_HEADERORTACKLE(a6)
                movem.l a0-a3,-(sp)
                bsr.w   PlayerBeginTackling
                movem.l (sp)+,a0-a3
                clr.w   TEAMGENERALINFO_BALLCANBECONTROLLED(a6)
                bra.w   finalize_control_and_speed
evaluate_jump_header_flow:
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a1)
                beq.s   gate_in_play_and_valid_dir
                tst.b   TEAMGENERALINFO_FIRETHISFRAME(a6)
                beq.s   gate_in_play_and_valid_dir
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d0
                bmi.s   gate_in_play_and_valid_dir
                tst.b   TEAMGENERALINFO_PLVERYCLOSETOBALL(a6)
                bne.s   check_ball_height_for_header
                tst.b   TEAMGENERALINFO_PLCLOSETOBALL(a6)
                bne.s   check_ball_height_for_header
                tst.b   TEAMGENERALINFO_PLNOTFARFROMBALL(a6)
                beq.s   gate_in_play_and_valid_dir
check_ball_height_for_header:
                tst.b   TEAMGENERALINFO_BALL8TO12(a6)
                bne.s   do_jump_header_and_update_context
                tst.b   TEAMGENERALINFO_BALL12TO17(a6)
                bne.s   do_jump_header_and_update_context
                tst.b   TEAMGENERALINFO_BALLABOVE17(a6)
                beq.s   gate_in_play_and_valid_dir
do_jump_header_and_update_context:
                move.w  #1,TEAMGENERALINFO_HEADERORTACKLE(a6)
                movem.l a0-a3,-(sp)
                bsr.w   PlayerAttemptingJumpHeader
                movem.l (sp)+,a0-a3
                move.l  a1,TEAMGENERALINFO_LASTHEADINGTACKLINGPLAYER(a6)
                clr.w   TEAMGENERALINFO_BALLCANBECONTROLLED(a6)
                bra.w   finalize_control_and_speed
gate_in_play_and_valid_dir:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.w   finalize_control_and_speed
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d0
                bmi.w   finalize_control_and_speed
compute_oob_dir_mask_and_block:
                move.w  SPRITE_X(a1),d1
                move.w  SPRITE_Y(a1),d2
                clr.b   d3
                cmpi.w  #79,d1
                bge.s   check_left_pitch_bound
                ori.b   #$E0,d3
check_left_pitch_bound:
                cmpi.w  #592,d1
                ble.s   check_right_pitch_bound
                ori.b   #$E,d3
check_right_pitch_bound:
                cmpi.w  #127,d2
                bge.s   check_top_pitch_bound
                ori.b   #$83,d3
check_top_pitch_bound:
                cmpi.w  #771,d2
                ble.s   check_bottom_pitch_bound
                ori.b   #$38,d3         ; '8'
check_bottom_pitch_bound:
                btst    d0,d3
                beq.s   apply_default_dest_from_dir
                move.w  SPRITE_X(a1),SPRITE_DESTX(a1)
                move.w  SPRITE_Y(a1),SPRITE_DESTY(a1)
                bra.w   finalize_control_and_speed
apply_default_dest_from_dir:
                lea     kDefaultDestinations(pc),a5
                lsl.w   #2,d0
                lea     (a5,d0.w),a5
                move.w  (a5),d1
                add.w   SPRITE_X(a1),d1
                move.w  2(a5),d2
                add.w   SPRITE_Y(a1),d2
                move.w  d1,SPRITE_DESTX(a1)
                move.w  d2,SPRITE_DESTY(a1)
                bra.w   finalize_control_and_speed
throw_in_state_handler:
                tst.w   TEAMGENERALINFO_PLAYERNUMBER(a6)
                bne.s   align_throw_in_facing_with_flags
                movem.l a1-a3,-(sp)
                bsr.w   AI_SetControlsDirection
                movem.l (sp)+,a1-a3
align_throw_in_facing_with_flags:
                move.w  SPRITE_DIRECTION(a1),d0
                btst    d0,playerTurnFlags(pc)
                bne.s   choose_permitted_throw_in_dir
                move.w  cameraDirection(pc),SPRITE_DIRECTION(a1)
                addq.w  #1,(disallowedTurnFlagsCounter).l
choose_permitted_throw_in_dir:
                move.w  SPRITE_DIRECTION(a1),d0
                btst    d0,playerTurnFlags(pc)
                bne.s   handle_throw_in_substitution_case
                move.w  #7,d0
find_permitted_throw_in_dir_ccw:
                btst    d0,playerTurnFlags(pc)
                bne.s   apply_throw_in_dir_and_camera
                dbf     d0,find_permitted_throw_in_dir_ccw
                clr.w   d0
apply_throw_in_dir_and_camera:
                move.w  d0,(cameraDirection).l
                move.w  d0,SPRITE_DIRECTION(a1)
                addq.w  #1,(deadThrowInDirectionVar).l
handle_throw_in_substitution_case:
                tst.w   (substituteInProgress).l
                beq.s   throw_in_countdown_and_anim_gate
                cmpa.l  substitutedPlSprite(pc),a1
                beq.w   throw_in_unhide_ball
throw_in_countdown_and_anim_gate:
                cmpi.w  #ST_THROW_IN_FORWARD_RIGHT,(gameState).l
                bcs.w   throw_in_unhide_ball
                cmpi.w  #ST_THROW_IN_BACK_LEFT,(gameState).l
                bhi.w   throw_in_unhide_ball
                tst.b   SPRITE_PLAYERDOWNTIMER(a1)
                beq.w   manage_throw_in_ui_and_fire_block
                subq.b  #1,SPRITE_PLAYERDOWNTIMER(a1)
                beq.w   throw_in_reset_to_idle
                cmpi.b  #18,SPRITE_PLAYERDOWNTIMER(a1)
                bne.w   finalize_control_and_speed
                tst.w   (inSubstitutesMenu).l
                beq.w   prepare_throw_in_and_route
                lea     (aboutToThrowInAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                move.b  #PL_THROW_IN,SPRITE_PLAYERSTATE(a1)
                clr.b   SPRITE_PLAYERDOWNTIMER(a1)
                bra.s   manage_throw_in_ui_and_fire_block
prepare_throw_in_and_route:
                move.w  SPRITE_DIRECTION(a1),d0
                move.w  #12,SPRITE_Z(a2)
                clr.w   (hideBall).l
                tst.w   (throwInPassOrKick).l
                bne.w   throw_in_commit_pass
                bra.w   throw_in_commit_kick
manage_throw_in_ui_and_fire_block:
                tst.w   TEAMGENERALINFO_PLAYERNUMBER(a6)
                bne.s   throw_in_check_has_allowed_dir
                cmpi.w  #50,(stoppageTimerActive).l
                bhi.s   toggle_stats_timers
                bra.s   throw_in_fire_input_gate
throw_in_check_has_allowed_dir:
                tst.w   TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                bpl.s   apply_stats_hide_fire_block
throw_in_fire_input_gate:
                tst.b   TEAMGENERALINFO_FIREPRESSED(a6)
                bne.s   apply_stats_hide_fire_block
                tst.b   TEAMGENERALINFO_QUICKFIRE(a6)
                bne.s   apply_stats_hide_fire_block
                tst.b   TEAMGENERALINFO_NORMALFIRE(a6)
                beq.s   ensure_throw_in_allowed_dir_from_facing
apply_stats_hide_fire_block:
                tst.w   (statsTimer).l
                beq.s   toggle_stats_timers
                move.w  #1,(fireBlocked).l
toggle_stats_timers:
                neg.w   (timeVar).l
                neg.w   (resultTimer).l
ensure_throw_in_allowed_dir_from_facing:
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d0
                bpl.s   throw_in_apply_dir_and_arm
load_allowed_dir_from_sprite:
                move.w  SPRITE_DIRECTION(a1),TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                move.w  TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6),d0
                bra.s   throw_in_quick_pass_trigger
throw_in_apply_dir_and_arm:
                btst    d0,playerTurnFlags(pc)
                beq.s   load_allowed_dir_from_sprite
                cmp.w   SPRITE_DIRECTION(a1),d0
                beq.s   throw_in_quick_pass_trigger
                move.w  d0,SPRITE_DIRECTION(a1)
                movem.l d0,-(sp)
                bsr.w   SetThrowInPlayerDestinationCoordinates
                movem.l (sp)+,d0
                lea     (aboutToThrowInAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                move.b  #PL_THROW_IN,SPRITE_PLAYERSTATE(a1)
                clr.b   SPRITE_PLAYERDOWNTIMER(a1)
throw_in_quick_pass_trigger:
                tst.b   TEAMGENERALINFO_QUICKFIRE(a6)
                beq.w   throw_in_kick_trigger
                btst    d0,playerTurnFlags(pc)
                beq.w   throw_in_kick_trigger
                move.w  #1,(throwInPassOrKick).l
                lea     (throwInPassAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                move.b  #20,SPRITE_PLAYERDOWNTIMER(a1)
                bra.w   finalize_control_and_speed
throw_in_kick_trigger:
                tst.b   TEAMGENERALINFO_NORMALFIRE(a6)
                beq.w   finalize_control_and_speed
                btst    d0,playerTurnFlags(pc)
                beq.w   finalize_control_and_speed
                clr.w   (throwInPassOrKick).l
                lea     (throwInKickAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                move.b  #25,SPRITE_PLAYERDOWNTIMER(a1)
                bra.w   finalize_control_and_speed
throw_in_commit_pass:
                move.l  a6,(lastTeamPlayed).l
                move.l  a1,(lastPlayerPlayed).l
                move.w  #1,(playerHadBall).l
                movem.l d0/a0-a3,-(sp)
                bsr.w   DoPass
                movem.l (sp)+,d0/a0-a3
                move.l  a1,TEAMGENERALINFO_LASTHEADINGTACKLINGPLAYER(a6)
                move.l  #1,SPRITE_DELTAZ(a2)
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.s   throw_in_post_pass_state_setup
                movem.l d0,-(sp)
                jsr     ThrowInDeadProc
                movem.l (sp)+,d0
                clr.w   (gameNotInProgressCounterWriteOnly).l
throw_in_post_pass_state_setup:
                move.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                move.w  #ST_GAME_IN_PROGRESS,(gameState).l
                move.w  #1,TEAMGENERALINFO_BALLINPLAY(a6)
                move.w  #1,TEAMGENERALINFO_BALLOUTOFPLAY(a6)
                movea.l (a6),a0
                move.w  #1,TEAMGENERALINFO_BALLINPLAY(a0)
                move.w  #1,TEAMGENERALINFO_BALLOUTOFPLAY(a0)
                move.w  #$FFFF,TEAMGENERALINFO_SPINTIMER(a0)
                clr.l   TEAMGENERALINFO_CONTROLLEDPLAYER(a6)
                move.l  a1,TEAMGENERALINFO_PASSINGKICKINGPLAYER(a6)
                move.w  #25,TEAMGENERALINFO_PASSKICKTIMER(a6)
                clr.w   TEAMGENERALINFO_BALLCANBECONTROLLED(a6)
                movea.l (a6),a0
                clr.w   TEAMGENERALINFO_PASSINGTOPLAYER(a0)
                clr.l   TEAMGENERALINFO_PASSINGKICKINGPLAYER(a0)
                bra.w   finalize_control_and_speed
throw_in_commit_kick:
                move.l  a6,(lastTeamPlayed).l
                move.l  a1,(lastPlayerPlayed).l
                move.w  #1,(playerHadBall).l
                movem.l d0/a0-a3,-(sp)
                bsr.w   PlayerKickingBall
                movem.l (sp)+,d0/a0-a3
                move.l  a1,TEAMGENERALINFO_LASTHEADINGTACKLINGPLAYER(a6)
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.s   throw_in_post_kick_state_setup
                movem.l d0,-(sp)
                jsr     ThrowInDeadProc
                movem.l (sp)+,d0
                clr.w   (gameNotInProgressCounterWriteOnly).l
throw_in_post_kick_state_setup:
                move.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                move.w  #ST_GAME_IN_PROGRESS,(gameState).l
                move.w  #1,TEAMGENERALINFO_BALLINPLAY(a6)
                move.w  #1,TEAMGENERALINFO_BALLOUTOFPLAY(a6)
                movea.l (a6),a0
                move.w  #1,TEAMGENERALINFO_BALLINPLAY(a0)
                move.w  #1,TEAMGENERALINFO_BALLOUTOFPLAY(a0)
                move.w  #$FFFF,TEAMGENERALINFO_SPINTIMER(a0)
                clr.l   TEAMGENERALINFO_CONTROLLEDPLAYER(a6)
                move.l  a1,TEAMGENERALINFO_PASSINGKICKINGPLAYER(a6)
                move.w  #25,TEAMGENERALINFO_PASSKICKTIMER(a6)
                clr.w   TEAMGENERALINFO_BALLCANBECONTROLLED(a6)
                movea.l (a6),a0
                clr.w   TEAMGENERALINFO_PASSINGTOPLAYER(a0)
                clr.l   TEAMGENERALINFO_PASSINGKICKINGPLAYER(a0)
                bra.w   finalize_control_and_speed
throw_in_unhide_ball:
                clr.w   (hideBall).l
throw_in_reset_to_idle:
                move.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a1)
                lea     (playerNormalStandingAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                bra.w   finalize_control_and_speed
tackle_update_state:
                tst.w   SPRITE_TACKLINGTIMER(a1)
                bmi.s   tackle_finish_if_timer_elapsed
                addq.w  #1,SPRITE_TACKLINGTIMER(a1)
tackle_finish_if_timer_elapsed:
                subq.b  #1,SPRITE_PLAYERDOWNTIMER(a1)
                bne.s   tackle_early_release_window
                move.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a1)
                lea     (playerNormalStandingAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                bra.w   snap_dest_to_current_pos
tackle_early_release_window:
                tst.w   SPRITE_TACKLINGTIMER(a1)
                bmi.s   tackle_apply_ground_decel_or_downtime
                tst.w   TEAMGENERALINFO_PLAYERNUMBER(a6)
                beq.s   tackle_apply_ground_decel_or_downtime
                tst.b   TEAMGENERALINFO_FIREPRESSED(a6)
                bne.s   tackle_apply_ground_decel_or_downtime
                neg.w   SPRITE_TACKLINGTIMER(a1)
                cmpi.w  #$FFFE,SPRITE_TACKLINGTIMER(a1)
                blt.s   tackle_apply_ground_decel_or_downtime
                move.w  #$FFFF,SPRITE_TACKLINGTIMER(a1)
tackle_apply_ground_decel_or_downtime:
                tst.w   SPRITE_SPEED(a1)
                beq.w   finalize_control_and_speed
                move.w  (kPlayerGroundConstant).l,d0
                sub.w   d0,SPRITE_SPEED(a1)
                bgt.s   tackle_out_of_pitch_slow_near_goalmouth
                clr.w   SPRITE_SPEED(a1)
                jsr SetPlayerDowntimeAfterTackle(pc)
                bra.w   finalize_control_and_speed
tackle_out_of_pitch_slow_near_goalmouth:
                cmpi.w  #73,SPRITE_X(a1)
                blt.w   tackle_edge_generic_slowdown
                cmpi.w  #598,SPRITE_X(a1)
                bgt.w   tackle_edge_generic_slowdown
                cmpi.w  #129,SPRITE_Y(a1) ; player in pitch by x
                blt.s   tackle_out_of_pitch_y_checks
                cmpi.w  #769,SPRITE_Y(a1)
                ble.s   tackle_in_pitch_gate_near_ball
tackle_out_of_pitch_y_checks:
                cmpi.w  #275,SPRITE_X(a1) ; player in pitch by x, out of pitch by y
                blt.w   tackle_out_of_pitch_generic_gate
                cmpi.w  #396,SPRITE_X(a1)
                bgt.w   tackle_out_of_pitch_generic_gate
                lsr     SPRITE_SPEED(a1) ; player tackling out of pitch horizontally, but near goal
                lsr     SPRITE_SPEED(a1)
                lsr     SPRITE_SPEED(a1)
                lsr     SPRITE_SPEED(a1)
                ori.w   #1,SPRITE_SPEED(a1) ; sprite speed /= 32
                bra.w   finalize_control_and_speed
tackle_out_of_pitch_generic_gate:
                cmpi.w  #121,SPRITE_Y(a1)
                blt.s   tackle_edge_generic_slowdown
                cmpi.w  #777,SPRITE_Y(a1)
                ble.w   finalize_control_and_speed
tackle_edge_generic_slowdown:
                move.w  SPRITE_SPEED(a1),d0
                lsr.w   #3,d0
                sub.w   d0,SPRITE_SPEED(a1) ; decrease speed by 1/8
                bra.w   finalize_control_and_speed
tackle_in_pitch_gate_near_ball:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l ; normal tackling in pitch
                bne.w   tackle_off_ball_foul_check
                tst.w   SPRITE_TACKLESTATE(a1) ; tackling inside pitch and game running
                bne.w   tackle_off_ball_foul_check
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.w   tackle_check_ball_proximity ; game state here must be game in progress
                cmpi.l  #64,SPRITE_BALLDISTANCE(a1)
                bhi.w   tackle_off_ball_foul_check
tackle_check_ball_proximity:
                tst.b   TEAMGENERALINFO_BALLLESSEQUAL4(a6)
                bne.s   tackle_setup_attempt_context
                tst.b   TEAMGENERALINFO_BALL4TO8(a6)
                beq.w   tackle_off_ball_foul_check
tackle_setup_attempt_context:
                move.w  SPRITE_DIRECTION(a1),d0
                move.l  a6,(lastTeamPlayed).l
                move.l  a1,(lastPlayerPlayed).l
                clr.w   (penalty).l
                clr.w   (playerHadBall).l
                movea.l (a6),a0
                tst.w   TEAMGENERALINFO_PLAYERHASBALL(a0)
                beq.s   tackle_dispatch_weak_or_strong
                move.w  #1,(playerHadBall).l
tackle_dispatch_weak_or_strong:
                cmpi.w  #$FFFF,$6A(a1)
                bne.s   tackle_commit_strong
                movem.l a0-a3,-(sp)
                bsr.w   PlayerTackledTheBallWeak
                movem.l (sp)+,a0-a3
                bra.s   tackle_post_win_bookkeeping
tackle_commit_strong:
                movem.l a0-a3,-(sp)
                bsr.w   PlayerTackledTheBallStrong
                movem.l (sp)+,a0-a3
tackle_post_win_bookkeeping:
                move.l  a1,TEAMGENERALINFO_LASTHEADINGTACKLINGPLAYER(a6)
                move.w  #25,TEAMGENERALINFO_PASSKICKTIMER(a6)
                movea.l (a6),a0
                clr.w   TEAMGENERALINFO_PASSINGTOPLAYER(a0)
                clr.l   TEAMGENERALINFO_PASSINGKICKINGPLAYER(a0)
                move.w  #$FFFF,TEAMGENERALINFO_SPINTIMER(a0)
                move.w  #12,TEAMGENERALINFO_WONTHEBALLTIMER(a0)
                bra.w   finalize_control_and_speed
tackle_off_ball_foul_check:
                cmpi.w  #512,SPRITE_SPEED(a1)
                bcs.w   finalize_control_and_speed
                movem.l a0-a3,-(sp)
                bsr.w   PlayerTacklingTestFoul
                movem.l (sp)+,a0-a3
                bra.w   finalize_control_and_speed
player_static_heading:
                subq.b  #1,SPRITE_PLAYERDOWNTIMER(a1)
                bne.s   static_header_decelerate
                move.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a1)
                lea     (playerNormalStandingAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                bra.w   snap_dest_to_current_pos
static_header_decelerate:
                subi.w  #16,SPRITE_SPEED(a1)
                bpl.s   static_header_try_execute
                clr.w   SPRITE_SPEED(a1)
static_header_try_execute:
                bsr.w   SetStaticHeaderDirection
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.w   finalize_control_and_speed
                tst.w   SPRITE_HEADING(a1)
                bne.w   finalize_control_and_speed
                cmpi.l  #64,SPRITE_BALLDISTANCE(a1)
                bhi.w   finalize_control_and_speed
                cmpi.w  #8,SPRITE_Z(a2)
                bcs.w   finalize_control_and_speed
                cmpi.w  #15,SPRITE_Z(a2)
                bhi.w   finalize_control_and_speed
                tst.w   TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                bmi.w   finalize_control_and_speed
                move.w  SPRITE_DIRECTION(a1),d0
                move.l  a6,(lastTeamPlayed).l
                move.l  a1,(lastPlayerPlayed).l
                clr.w   (penalty).l
                move.w  #1,(playerHadBall).l
                movem.l a0-a3,-(sp)
                bsr.w   PlayerHittingStaticHeader
                movem.l (sp)+,a0-a3
                move.w  #25,TEAMGENERALINFO_PASSKICKTIMER(a6)
                movea.l (a6),a0
                clr.w   TEAMGENERALINFO_PASSINGTOPLAYER(a0)
                clr.l   TEAMGENERALINFO_PASSINGKICKINGPLAYER(a0)
                bra.w   finalize_control_and_speed
player_jump_heading:
                subq.b  #1,SPRITE_PLAYERDOWNTIMER(a1)
                bne.s   jump_heading_motion_and_anim
heading_reset_to_idle:
                move.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a1)
                lea     (playerNormalStandingAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                bra.w   snap_dest_to_current_pos
jump_heading_motion_and_anim:
                tst.w   SPRITE_SPEED(a1)
                beq.s   heading_boundary_checks
                bsr.w   SetJumpHeaderHitAnimTable
                cmpi.l  #jumpHeaderAttemptAnimTable,SPRITE_ANIMATIONTABLE(a1)
                beq.s   jump_header_attempt_window_slowdown
                cmpi.b  #17,SPRITE_PLAYERDOWNTIMER(a1)
                bhi.s   apply_air_drag_until_stop
                lsr     SPRITE_SPEED(a1)
                bra.w   finalize_control_and_speed
jump_header_attempt_window_slowdown:
                cmpi.b  #37,SPRITE_PLAYERDOWNTIMER(a1)
                bhi.s   apply_air_drag_until_stop
                lsr     SPRITE_SPEED(a1)
                bra.w   finalize_control_and_speed
apply_air_drag_until_stop:
                move.w  (kPlayerAirConstant).l,d0
                sub.w   d0,SPRITE_SPEED(a1)
                bpl.s   heading_boundary_checks
                clr.w   SPRITE_SPEED(a1)
                bra.w   finalize_control_and_speed
heading_boundary_checks:
                cmpi.w  #73,SPRITE_X(a1)
                blt.w   heading_general_oob_slowdown
                cmpi.w  #598,SPRITE_X(a1)
                bgt.w   heading_general_oob_slowdown
                cmpi.w  #132,SPRITE_Y(a1)
                blt.s   heading_out_of_pitch_goalmouth_stop
                cmpi.w  #766,SPRITE_Y(a1)
                ble.w   jump_header_try_execute
heading_out_of_pitch_goalmouth_stop:
                cmpi.w  #296,SPRITE_X(a1)
                blt.s   heading_goal_line_band_checks
                cmpi.w  #375,SPRITE_X(a1)
                bgt.s   heading_goal_line_band_checks
                cmpi.w  #305,SPRITE_X(a1)
                blt.s   heading_stop_and_reset_goalmouth
                cmpi.w  #366,SPRITE_X(a1)
                bls.s   heading_goal_line_band_checks
heading_stop_and_reset_goalmouth:
                clr.w   SPRITE_SPEED(a1)
                clr.b   SPRITE_PLAYERDOWNTIMER(a1)
                bra.w   heading_reset_to_idle
heading_goal_line_band_checks:
                cmpi.w  #129,SPRITE_Y(a1)
                blt.w   heading_goal_line_x_window_gate
                cmpi.w  #769,SPRITE_Y(a1)
                ble.w   jump_header_try_execute
heading_goal_line_x_window_gate:
                cmpi.w  #$122,SPRITE_X(a1)
                blt.s   heading_out_of_bounds_y_band
                cmpi.w  #$17D,SPRITE_X(a1)
                ble.s   heading_stop_and_reset_goalmouth
heading_out_of_bounds_y_band:
                cmpi.w  #$79,SPRITE_Y(a1) ; 'y'
                blt.s   heading_general_oob_slowdown
                cmpi.w  #$309,SPRITE_Y(a1)
                ble.w   jump_header_try_execute
heading_general_oob_slowdown:
                move.w  SPRITE_SPEED(a1),d0
                lsr.w   #2,d0
                sub.w   d0,SPRITE_SPEED(a1)
                lsr.w   #1,d0
                sub.w   d0,SPRITE_SPEED(a1) ; lower speed to 62,5%
                bra.w   finalize_control_and_speed
jump_header_try_execute:
                cmpi.b  #42,SPRITE_PLAYERDOWNTIMER(a1)
                bcs.w   finalize_control_and_speed
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.w   finalize_control_and_speed
                tst.w   SPRITE_HEADING(a1)
                bne.w   finalize_control_and_speed
                cmpi.l  #64,SPRITE_BALLDISTANCE(a1)
                bhi.w   finalize_control_and_speed
                cmpi.w  #8,SPRITE_Z(a2)
                bcs.w   finalize_control_and_speed
                cmpi.w  #15,SPRITE_Z(a2)
                bhi.w   finalize_control_and_speed
                move.w  SPRITE_DIRECTION(a1),d0
                move.l  a6,(lastTeamPlayed).l
                move.l  a1,(lastPlayerPlayed).l
                clr.w   (penalty).l
                move.w  #1,(playerHadBall).l
                movem.l a0-a3,-(sp)
                bsr.w   PlayerHittingJumpHeader
                movem.l (sp)+,a0-a3
                move.w  #25,TEAMGENERALINFO_PASSKICKTIMER(a6)
                movea.l (a6),a0
                clr.w   TEAMGENERALINFO_PASSINGTOPLAYER(a0)
                clr.l   TEAMGENERALINFO_PASSINGKICKINGPLAYER(a0)
                bra.w   finalize_control_and_speed
player_injured_recover_tick:
                tst.w   (injuriesForever).l
                bne.w   finalize_control_and_speed
                subq.b  #1,SPRITE_PLAYERDOWNTIMER(a1)
                bne.w   finalize_control_and_speed
                move.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a1)
                lea     (playerNormalStandingAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                bra.w   snap_dest_to_current_pos
player_tackled_state:
                subq.b  #1,SPRITE_PLAYERDOWNTIMER(a1)
                bne.w   tackled_ground_deceleration
                move.w  SPRITE_INJURYLEVEL(a1),d0
                beq.s   tackled_recover_to_idle
                clr.w   SPRITE_SPEED(a1)
                move.b  #PL_ROLLING_INJURED,SPRITE_PLAYERSTATE(a1)
                move.b  d0,SPRITE_PLAYERDOWNTIMER(a1)
                lea     (plInjuredAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                bra.w   finalize_control_and_speed
tackled_recover_to_idle:
                move.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a1)
                lea     (playerNormalStandingAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                bra.w   snap_dest_to_current_pos
tackled_ground_deceleration:
                tst.w   SPRITE_SPEED(a1)
                beq.w   finalize_control_and_speed
                cmpi.w  #159,SPRITE_Y(a1)
                blt.s   tackled_goal_area_slowdown_gate
                cmpi.w  #739,SPRITE_Y(a1)
                ble.w   tackled_apply_ground_friction
tackled_goal_area_slowdown_gate:
                cmpi.w  #265,SPRITE_X(a1)
                blt.w   tackled_apply_ground_friction
                cmpi.w  #406,SPRITE_X(a1)
                bgt.w   tackled_apply_ground_friction
                move.w  SPRITE_SPEED(a1),d0
                lsr.w   #2,d0
                sub.w   d0,SPRITE_SPEED(a1)
tackled_apply_ground_friction:
                move.w  (kPlayerGroundConstant).l,d0
                sub.w   d0,SPRITE_SPEED(a1)
                bpl.w   finalize_control_and_speed
                clr.w   SPRITE_SPEED(a1)
                bra.w   finalize_control_and_speed
receiver_expect_pass_tick:
                move.w  $1E(a1),d1
                cmpi.w  #81,d1          ; left pitch edge
                blt.w   clear_pass_state_out_of_bounds
                cmpi.w  #590,d1         ; right pitch edge
                bgt.w   clear_pass_state_out_of_bounds
                move.w  $22(a1),d2
                cmpi.w  #129,d2         ; top pitch edge
                blt.w   clear_pass_state_out_of_bounds
                cmpi.w  #769,d2         ; bottom pitch edge
                ble.w   pass_assist_entry_checks
clear_pass_state_out_of_bounds:
                clr.w   TEAMGENERALINFO_PASSINGTOPLAYER(a6)
                clr.w   TEAMGENERALINFO_PASSINGBALL(a6)
                bra.w   snap_dest_to_current_pos
pass_assist_entry_checks:
                tst.w   TEAMGENERALINFO_PLAYERNUMBER(a6)
                beq.w   post_pass_assist_common
                tst.l   TEAMGENERALINFO_LONGPASS(a6)
                bne.s   ball_speed_and_expect_ready
                tst.w   TEAMGENERALINFO_LEFTSPIN(a6)
                bne.s   ball_speed_and_expect_ready
                tst.w   TEAMGENERALINFO_RIGHTSPIN(a6)
                beq.w   post_pass_assist_common
ball_speed_and_expect_ready:
                cmpi.w  #512,(ballSprite+SPRITE_SPEED).l
                bcs.w   post_pass_assist_common
                tst.w   TEAMGENERALINFO_PASSINGTOPLAYER(a6)
                beq.w   post_pass_assist_common
                tst.w   (ballSprite+SPRITE_DIRECTION).l
                bmi.s   pass_assist_set_landing_to_player_xy
                move.w  (ballSprite+SPRITE_FULLDIRECTION).l,d0
                sub.b   SPRITE_FULLDIRECTION+1(a1),d0
                cmpi.b  #64,d0
                bgt.s   pass_assist_cancel_bad_angle
                cmpi.b  #192,d0
                bge.s   pass_assist_small_angle_ok
pass_assist_cancel_bad_angle:
                clr.w   TEAMGENERALINFO_PASSINGTOPLAYER(a6)
                clr.w   TEAMGENERALINFO_PASSINGBALL(a6)
                bra.w   post_pass_assist_common
pass_assist_small_angle_ok:
                cmpi.b  #4,d0
                bgt.s   pass_assist_compute_lead_offset
                cmpi.b  #252,d0
                blt.s   pass_assist_compute_lead_offset
pass_assist_set_landing_to_player_xy:
                move.w  SPRITE_X(a1),TEAMGENERALINFO_BALLX(a6)
                move.w  SPRITE_Y(a1),TEAMGENERALINFO_BALLY(a6)
                bra.w   post_pass_assist_common
pass_assist_compute_lead_offset:
                move.b  #192,d1
                tst.l   TEAMGENERALINFO_LONGPASS(a6)
                beq.s   pass_assist_apply_lead_sign
                move.b  #224,d1
pass_assist_apply_lead_sign:
                tst.b   d0
                blt.s   pass_assist_build_friction_index
                neg.b   d1
pass_assist_build_friction_index:
                move.w  (ballSprite+SPRITE_FULLDIRECTION).l,d0
                add.b   d1,d0
                addq.w  #4,d0
                andi.w  #$FF,d0
                lea     kBallFriction(pc),a0
                andi.w  #$FF,d0
                lsr.w   #3,d0
                lsl.w   #2,d0
                move.w  SPRITE_X(a1),d1
                add.w   (a0,d0.w),d1
                move.w  d1,TEAMGENERALINFO_BALLX(a6)
                move.w  SPRITE_Y(a1),d1
                add.w   2(a0,d0.w),d1
                move.w  d1,TEAMGENERALINFO_BALLY(a6)
post_pass_assist_common:
                tst.w   TEAMGENERALINFO_PLAYERNUMBER(a6)
                bne.s   breakplay_control_setup_entry
                movem.l a1-a3,-(sp)
                bsr.w   AI_Kick
                movem.l (sp)+,a1-a3
breakplay_control_setup_entry:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.w   inplay_try_begin_tackle
                cmpa.l  lastTeamPlayedBeforeBreak(pc),a6
                bne.w   finalize_control_and_speed
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                bne.s   breakplay_keeper_hold_or_ball_contact_gate
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a1)
                beq.s   breakplay_sync_camera_from_player
breakplay_keeper_hold_or_ball_contact_gate:
                tst.l   SPRITE_BALLDISTANCE(a1)
                bne.w   pass_follow_decide_controller_or_anchor
breakplay_sync_camera_from_player:
                cmpi.w  #8,(cameraDirection).l
