                move.w  d2,SPRITE_DESTY(a1)
                bra.w   finalize_control_and_speed
freekick_offset_top_plus:
                addi.w  #1000,d1
                add.w   (freeKickDestX).l,d1
                bra.s   apply_restart_base_offset
freekick_offset_top_minus:
                subi.w  #1000,d1
                add.w   (freeKickDestX).l,d1
                bra.s   apply_restart_base_offset
freekick_offset_bottom_plus_mirror:
                addi.w  #1000,d1
                neg.w   d1
                neg.w   d2
                sub.w   (freeKickDestX).l,d1
                bra.s   apply_restart_base_offset
freekick_offset_bottom_minus_mirror:
                subi.w  #1000,d1
                neg.w   d1
                neg.w   d2
                sub.w   (freeKickDestX).l,d1
apply_restart_base_offset:
                add.w   d6,d1
                add.w   d7,d2
                move.w  d1,SPRITE_DESTX(a1)
                move.w  d2,SPRITE_DESTY(a1)
                bra.w   finalize_control_and_speed
set_player_with_no_ball_destination:
                bsr.w   SetPlayerWithNoBallDestination
                bra.w   *+4
enforce_free_kick_distance:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.w   finalize_control_and_speed
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a1)
                beq.w   finalize_control_and_speed
                cmpa.l  lastTeamPlayedBeforeBreak(pc),a6
                beq.w   finalize_control_and_speed
                move.w  SPRITE_DESTX(a1),d0
                sub.w   foulXCoordinate(pc),d0
                muls.w  d0,d0
                move.w  SPRITE_DESTY(a1),d1
                sub.w   foulYCoordinate(pc),d1
                muls.w  d1,d1
                add.l   d1,d0
                cmpi.l  #4225,d0
                bhi.w   finalize_control_and_speed
                move.w  foulXCoordinate(pc),d0
                cmpi.w  #336,d0
                blt.s   foul_adjustX_add70
                subi.w  #70,d0
                bra.s   foul_adjustX_store
foul_adjustX_add70:
                addi.w  #70,d0
foul_adjustX_store:
                move.w  d0,SPRITE_DESTX(a1)
                bra.w   finalize_control_and_speed
snap_dest_to_current_pos:
                move.w  SPRITE_X(a1),SPRITE_DESTX(a1)
                move.w  SPRITE_Y(a1),SPRITE_DESTY(a1)
finalize_control_and_speed:
                bsr.w   UpdatePlayerSpeed
                move.w  SPRITE_DESTX(a1),d1
                move.w  SPRITE_DESTY(a1),d2
                move.w  SPRITE_X(a1),d3
                move.w  SPRITE_Y(a1),d4
                move.w  SPRITE_SPEED(a1),d0
                movem.l a1,-(sp)
                jsr     CalculateDeltaXAndY
                movem.l (sp)+,a1
                move.l  d1,SPRITE_DELTAX(a1)
                move.l  d2,SPRITE_DELTAY(a1)
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a1)
                bne.s   non_keeper_facing_gate
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                bne.s   non_keeper_facing_gate
                tst.w   TEAMGENERALINFO_GOALKEEPERPLAYING(a6)
                bne.s   non_keeper_facing_gate
                tst.l   (ballInUpperPenaltyArea).l
                bne.s   compute_facing_from_full_direction
non_keeper_facing_gate:
                tst.w   d0
                bpl.s   quantize_direction_to_octant
                cmpa.l  TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a1 ; check if it's controlled player, he gets direction directly from controller
                beq.w   preserve_manual_direction
                cmpa.l  TEAMGENERALINFO_PASSINGKICKINGPLAYER(a6),a1
                beq.s   preserve_manual_direction
compute_facing_from_full_direction:
                move.w  SPRITE_FULLDIRECTION(a1),d0
                addi.w  #128,d0
                andi.w  #$FF,d0
quantize_direction_to_octant:
                addi.w  #16,d0          ; divide with 32 rounding at 0.5
                andi.w  #$FF,d0
                lsr.w   #5,d0
                move.w  d0,SPRITE_DIRECTION(a1) ; direction 0..7
preserve_manual_direction:
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.s   ball_going_to_player
                cmpi.w  #ST_THROW_IN_BACK_LEFT,(gameState).l
                bhi.w   ball_going_to_player
                move.w  foulXCoordinate(pc),d3
                move.w  foulYCoordinate(pc),d4
                bra.s   set_player_coordinates
ball_going_to_player:
                move.w  SPRITE_X(a2),d3
                move.w  SPRITE_Y(a2),d4
set_player_coordinates:
                move.w  SPRITE_X(a1),d1
                move.w  SPRITE_Y(a1),d2
                move.w  #256,d0
                movem.l a1,-(sp)
                jsr     CalculateDeltaXAndY
                movem.l (sp)+,a1
                bpl.s   store_full_direction
                clr.w   d0
store_full_direction:
                move.w  d0,SPRITE_FULLDIRECTION(a1)
                cmpi.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a1)
                bne.w   advance_to_next_player
                move.l  SPRITE_DELTAX(a1),d1
                or.l    SPRITE_DELTAY(a1),d1
                sne     d1
                cmp.b   SPRITE_ISMOVING(a1),d1
                beq.s   animate_on_heading_change_guard
switch_anim_on_move_state_change:
                tst.b   d1
                bne.s   set_running_animation
                lea     (playerNormalStandingAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                bra.s   advance_to_next_player
set_running_animation:
                lea     (playerRunningAnimTable).l,a0
                jsr     SetPlayerAnimationTable
                bra.s   advance_to_next_player
animate_on_heading_change_guard:
                move.w  SPRITE_PLAYERDIRECTION(a1),d0
                cmp.w   SPRITE_DIRECTION(a1),d0
                bne.s   switch_anim_on_move_state_change
advance_to_next_player:
                move.w  (sp)+,d4
                dbf     d4,players_loop
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.s   goalkeeper_possession_gate
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                bne.s   update_players_ret
goalkeeper_possession_gate:
                cmpi.l  #goalie1Sprite,(lastPlayerPlayed).l
                bne.s   goalie2_possession_check
                cmpi.l  #goalie1Sprite,(prevLastPlayer).l
                beq.s   update_players_ret
                bra.s   record_pre_goalie_possession
goalie2_possession_check:
                cmpi.l  #goalie2Sprite,(lastPlayerPlayed).l
                bne.s   update_players_ret
                cmpi.l  #goalie2Sprite,(prevLastPlayer).l
                beq.s   update_players_ret
record_pre_goalie_possession:
                move.l  (prevLastPlayer).l,(lastPlayerBeforeGoalkeeper).l
                move.l  (prevLastTeamPlayed).l,(lastTeamScored).l
                move.w  #50,(nobodysBallTimer).l
update_players_ret:
                rts
prevLastPlayer:
                dc.l $00000000          ; raw
prevLastTeamPlayed:
                dc.l $00000000          ; raw
freeKickFactorsX:
                dc.w 0,3,4,5,4,3,0
freeKickDestX:
                dc.w $0000
deadVarAlways0:
                dc.w $0000
; TeamGeneralInfo *
playerKickerPtr:
                dc.l $00000000

; ===== AI_SetControlsDirection =====
; prototype: void __usercall AI_SetControlsDirection(struct TeamGeneralInfo *team@<a6>)
; in:
;      A6 -> team data
AI_SetControlsDirection:
                tst.w   TEAMGENERALINFO_RESETCONTROLS(a6) ; size 0x164d
                bne.w   locret_118178
                tst.w   (aiCounter).l
                beq.s   check_ai_resume_timer
                subq.w  #1,(aiCounter).l
check_ai_resume_timer:
                tst.w   (aiResumePlayTimer).l
                beq.s   generate_rand
                subq.w  #1,(aiResumePlayTimer).l
generate_rand:
                jsr     Rand
                move.w  d0,(aiRand).l
                addq.w  #1,TEAMGENERALINFO_AI_TIMER(a6)
                move.w  #$FFFF,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                clr.b   TEAMGENERALINFO_FIREPRESSED(a6)
                clr.b   TEAMGENERALINFO_FIRETHISFRAME(a6)
                clr.b   TEAMGENERALINFO_QUICKFIRE(a6)
                clr.b   TEAMGENERALINFO_NORMALFIRE(a6)
                tst.w   (inSubstitutesMenu).l
                bne.w   locret_118178   ; do only if we're not in subs menu
                move.w  #$FFFF,d7
                movea.l TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a5 ; A5 -> controlled player
                movea.l TEAMGENERALINFO_PASSTOPLAYERPTR(a6),a4 ; A4 -> player receiving a pass
                cmpa.l  #0,a5
                beq.s   no_controlled_player
                move.w  SPRITE_DIRECTION(a5),d7
no_controlled_player:
                lea     (ballSprite).l,a0
                cmpa.l  #bottomTeamData,a6
                beq.w   right_team
                move.w  #769,d2         ; lower goal line (for left team)
                bra.s   load_pitch_center_and_ball_pos
right_team:
                move.w  #129,d2         ; upper goal line (for right team)
load_pitch_center_and_ball_pos:
                move.w  #336,d1         ; D1 = pitch center by x
                move.w  SPRITE_X(a0),d3
                move.w  SPRITE_Y(a0),d4
                sub.w   d1,d3           ; D3 = ball x -   pitch center x
                sub.w   d2,d4           ; D4 = ball y -  opponents goal line y
                muls.w  d3,d3           ; D3 = sqr(ball x - pitch center x)
                muls.w  d4,d4           ; D4 = sqr(ball y - opponents   goal line y)
                add.l   d4,d3
                move.l  d3,d6
                move.w  SPRITE_X(a0),d3
                move.w  SPRITE_Y(a0),d4
                move.w  #256,d0
                movem.l d5,-(sp)
                jsr     CalculateDeltaXAndY ; calculate angle from the ball toward the middle of the opponents goal
                movem.l (sp)+,d5
                bpl.s   angle_positive
                clr.w   d0              ; ball right at the center of the goal line
angle_positive:
                move.w  d0,d5           ; D5 = angle between the ball and the center of the opponent's goal
                cmpi.w  #ST_GAME_IN_PROGRESS,(gameStatePl).l
                beq.w   game_is_in_progress
                cmpa.l  lastTeamPlayedBeforeBreak(pc),a6 ; is this the team that last played?
                bne.w   locret_118178   ; no, opponents ball, bail
                cmpi.w  #ST_STARTING_GAME,(gameState).l
                bcs.w   game_not_over
                cmpi.w  #ST_GAME_ENDED,(gameState).l
                bhi.w   game_not_over
                tst.w   (team1Computer).l ; some result is showing
                beq.w   game_not_over
                tst.w   (team2Computer).l
                beq.w   game_not_over
                cmpi.w  #ST_RESULT_ON_HALFTIME,(gameState).l
                beq.s   showing_result_on_halftime
                cmpi.w  #ST_RESULT_AFTER_THE_GAME,(gameState).l
                bne.s   not_showing_final_result
                cmpi.w  #600,(stoppageTimerTotal).l ; showing result after the game for 660 ticks
                bcs.w   locret_118178
                bra.s   interval_expired_fire
showing_result_on_halftime:
                cmpi.w  #600,(stoppageTimerTotal).l
                bcs.w   locret_118178
                bra.s   interval_expired_fire
not_showing_final_result:
                cmpi.w  #350,(stoppageTimerTotal).l ; 350 ticks if showing result after 2nd half (but not final)
                bcs.w   locret_118178
interval_expired_fire:
                move.b  #1,TEAMGENERALINFO_FIREPRESSED(a6) ; simulate joy fire, to remove the result from the screen
                rts
set_direction:
                bra.w   *+4
set_direction_core:
                tst.w   (resultTimer).l
                bne.w   locret_118178
                cmpi.w  #ST_GOAL_OUT_LEFT,(gameState).l
                beq.w   no_player_facing
                cmpi.w  #ST_GOAL_OUT_RIGHT,(gameState).l
                beq.w   no_player_facing
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                beq.w   no_player_facing
                cmpi.w  #ST_THROW_IN_FORWARD_RIGHT,(gameState).l
                bcs.s   no_throw_in
                cmpi.w  #ST_THROW_IN_BACK_LEFT,(gameState).l
                bls.w   no_player_facing
no_throw_in:
                cmpi.w  #ST_FOUL,(gameState).l
                beq.s   foul_or_free_kick
                cmpi.w  #ST_FREE_KICK_LEFT1,(gameState).l
                bcs.w   locret_118178
                cmpi.w  #ST_FREE_KICK_RIGHT3,(gameState).l
                bhi.w   locret_118178
foul_or_free_kick:
                move.w  d5,d0           ; D5 = angle between the ball and the center of the opponent's goal
                addi.w  #16,d0
                andi.w  #$FF,d0
                lsr.w   #5,d0           ; clamp it into 0..7 range, rounding not truncating
                move.w  d0,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6) ; force only that direction - toward opponents goal
                bra.w   locret_118178
game_not_over:
                move.w  (currentGameTick).l,d0
                andi.w  #$3F,d0         ; '?'
                addi.w  #50,d0
                addi.w  #50,d0
                cmp.w   stoppageTimerActive(pc),d0
                bhi.w   set_direction
                tst.w   (playingPenalties).l
                bne.w   penalties_after_the_game
                cmpi.w  #ST_PENALTY,(gameState).l
                beq.w   penalties_after_the_game
                cmpi.w  #ST_KEEPER_HOLDS_BALL,(gameState).l
                beq.w   keepers_ball
                cmpi.w  #ST_GOAL_OUT_LEFT,(gameState).l
                beq.w   keepers_ball
                cmpi.w  #ST_GOAL_OUT_RIGHT,(gameState).l
                beq.w   keepers_ball
                cmpi.w  #ST_PLAYERS_TO_INITIAL_POSITIONS,(gameState).l
                beq.w   goal_scored
                cmpi.w  #ST_FREE_KICK_LEFT1,(gameState).l
                bcs.s   check_throw_in_window
                cmpi.w  #ST_FREE_KICK_RIGHT3,(gameState).l
                bls.w   foul
check_throw_in_window:
                cmpi.w  #ST_THROW_IN_FORWARD_RIGHT,(gameState).l
                bcs.s   not_a_throw_in
                cmpi.w  #ST_THROW_IN_BACK_LEFT,(gameState).l
                bhi.s   not_a_throw_in
                move.w  gameState(pc),d1
                subi.w  #ST_THROW_IN_FORWARD_RIGHT,d1 ; ST_THROW_IN_FORWARD_RIGHT
                lea     (aiThrowInDirections).l,a0
                move.b  (a0,d1.w),d1
                cmpa.l  #bottomTeamData,a6
                beq.w   decide_throw_in_direction_bits
                ror.b   #4,d1
                bra.w   decide_throw_in_direction_bits
not_a_throw_in:
                cmpi.w  #ST_FOUL,(gameState).l
                beq.w   foul
                bra.w   apply_turn_delta_from_angle
keepers_ball:
                move.w  (aiRand).l,d0
                andi.w  #1,d0
                beq.w   check_closest_player_facing
                cmp.w   cameraDirection(pc),d7
                beq.w   apply_turn_delta_from_angle
                cmpi.w  #336,(ballSprite+SPRITE_X).l
                bhi.s   keeper_dir_right_half_checks
                cmpi.w  #1,d7
                beq.w   apply_turn_delta_from_angle
                cmpi.w  #3,d7
                beq.w   apply_turn_delta_from_angle
                bra.w   check_closest_player_facing
keeper_dir_right_half_checks:
                cmpi.w  #5,d7
                beq.w   apply_turn_delta_from_angle
                cmpi.w  #7,d7
                beq.w   apply_turn_delta_from_angle
                bra.w   check_closest_player_facing
goal_scored:
                cmpi.w  #150,(stoppageTimerActive).l
                bcs.w   check_closest_player_facing
                cmp.w   cameraDirection(pc),d7
                beq.w   apply_turn_delta_from_angle
                bra.w   check_closest_player_facing
                move.w  (aiRand).l,d0
                andi.w  #$F,d0
                bne.w   apply_turn_delta_from_angle
                bra.w   check_closest_player_facing
                move.w  (aiRand).l,d0
                andi.w  #$F,d0
                bne.w   check_closest_player_facing
                bra.w   apply_turn_delta_from_angle
foul:
                move.w  (aiRand).l,d0
                andi.w  #$F,d0
                bne.w   compute_allowed_dir_from_angle_bucket
                bra.w   check_closest_player_facing
decide_throw_in_direction_bits:
                move.w  (aiRand).l,d0
                andi.w  #$F,d0
                bne.w   check_closest_player_facing
                btst    d7,d1
                bne.w   apply_turn_delta_from_angle
                bra.w   check_closest_player_facing
penalties_after_the_game:
                move.w  (aiRand).l,d0
                andi.w  #7,d0
                btst    d0,playerTurnFlags(pc)
                beq.w   random_direction_disallowed
                move.w  d0,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                bra.w   locret_118178
random_direction_disallowed:
                tst.w   SPRITE_DIRECTION(a5)
                beq.w   locret_118178
                cmpi.w  #4,SPRITE_DIRECTION(a5)
                beq.w   locret_118178
                bra.w   apply_turn_delta_from_angle
compute_allowed_dir_from_angle_bucket:
                move.w  d5,d0
                addi.w  #16,d0
                andi.w  #$FF,d0
                lsr.w   #5,d0
                cmp.w   d7,d0
                beq.s   apply_turn_delta_from_angle
                bra.w   set_allowed_dir_and_return
apply_turn_delta_from_angle:
                move.w  d7,d2           ; D2 = controlled player direction
                bmi.w   locret_118178
                lsl.w   #5,d2           ; D2 = controller player direction, scaled to full byte
                sub.b   d5,d2           ; D5 = angle between the ball and the opponent's goal center
                                        ; D2 = difference between player's facing direction and ball->goal center direction
                bra.w   prep_aftertouch_and_fire_decision
check_closest_player_facing:
                move.w  d7,d0
                lsl.w   #5,d0
                bsr.w   FindClosestPlayerToBallFacing
                cmpa.l  #$FFFFFFFF,a0   ; do we have closest player?
                beq.w   no_player_facing
                move.w  (a5),d0
                cmp.w   (a0),d0         ; is this closest player from our team?
                bne.s   no_player_facing
                bra.w   our_player_closest
                move.w  d7,d0
                lsl.w   #5,d0
                bsr.w   FindClosestPlayerToBallFacing
                cmpa.l  #$FFFFFFFF,a0
                beq.s   apply_turn_delta_from_angle
                move.w  (a5),d0
                cmp.w   (a0),d0
                bne.s   apply_turn_delta_from_angle
                bra.w   our_player_closest
set_allowed_dir_and_return:
                move.w  d5,d0
                addi.w  #16,d0
                andi.w  #$FF,d0
                lsr.w   #5,d0
                move.w  d0,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                rts
no_player_facing:
                move.w  (currentGameTick).l,d0
                andi.w  #$E,d0          ; timer mod 16, but only 0,2,4,6,8,10,12,14
                bne.w   locret_118178
                tst.w   (aiTurnDirection).l ; pass only if timer mod 16 == 1 or 0
                bpl.s   set_turn_step_negative_path
                cmpi.w  #$FFFF,(aiTurnDirection).l
                beq.s   set_turn_step_positive
                addq.w  #1,(aiTurnDirection).l
                cmpi.w  #$FFFF,(aiTurnDirection).l
                bne.w   locret_118178
set_turn_step_positive:
                move.w  #1,d1
                bra.s   try_apply_turn_step
set_turn_step_negative_path:
                cmpi.w  #1,(aiTurnDirection).l
                beq.s   set_turn_step_negative
                subq.w  #1,(aiTurnDirection).l
                cmpi.w  #1,(aiTurnDirection).l
                bne.w   locret_118178
set_turn_step_negative:
                move.w  #$FFFF,d1
try_apply_turn_step:
                move.w  d7,d0
                add.w   (aiTurnDirection).l,d0
                andi.w  #7,d0
                btst    d0,playerTurnFlags(pc)
                beq.s   commit_turn_direction_and_return
                move.w  d0,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                rts
commit_turn_direction_and_return:
                move.w  d1,(aiTurnDirection).l
                rts
game_is_in_progress:
                tst.w   (playingPenalties).l
                bne.s   got_penalty
                tst.w   (penalty).l
                beq.s   no_penalty
got_penalty:
                tst.w   TEAMGENERALINFO_SPINTIMER(a6)
                bpl.w   we_have_ball_spin
no_penalty:
                tst.w   (aiCounter).l
                beq.w   after_ai_counter_direction_toward_goal
                bsr.w   AI_SetDirectionTowardOpponentsGoal
after_ai_counter_direction_toward_goal:
                cmpa.l  #0,a5
                beq.w   locret_118178
                tst.w   TEAMGENERALINFO_SPINTIMER(a6)
                bpl.w   we_have_ball_spin
                tst.b   TEAMGENERALINFO_PLVERYCLOSETOBALL(a6)
                bne.s   theres_a_player_near
                tst.b   TEAMGENERALINFO_PLCLOSETOBALL(a6)
                bne.s   theres_a_player_near
                bra.w   noone_near
                cmpa.l  lastTeamPlayed(pc),a6
                beq.w   noone_near
                movea.l (a6),a0
                tst.w   TEAMGENERALINFO_PLAYERHASBALL(a0)
                beq.w   noone_near
                bra.w   branch_to_not_very_close
theres_a_player_near:
                bsr.w   AI_DecideWhetherToTriggerFire
                beq.w   locret_118178
                tst.w   (deadVarAlways0).l
                beq.s   check_direction_and_field_half_gates
                movea.l (a6),a0
                cmpa.l  playerKickerPtr(pc),a0
                bne.s   check_direction_and_field_half_gates
                tst.w   TEAMGENERALINFO_PLAYERHASBALL(a0)
                bne.w   locret_118178
check_direction_and_field_half_gates:
                cmpi.w  #2,SPRITE_DIRECTION(a5)
                beq.s   horizontal_dir_half_gate
                cmpi.w  #6,SPRITE_DIRECTION(a5)
                bne.s   distance_and_random_fire_gate
horizontal_dir_half_gate:
                cmpa.l  #topTeamData,a6
                beq.s   top_team_ball_y_gate
                cmpi.w  #158,(ballSprite+SPRITE_Y).l
                ble.s   no_fire_fallback_flow
                bra.s   distance_and_random_fire_gate
top_team_ball_y_gate:
                cmpi.w  #740,(ballSprite+SPRITE_Y).l
                bge.s   no_fire_fallback_flow
distance_and_random_fire_gate:
                cmpi.l  #28800,d6
                bhi.w   no_fire_fallback_flow
                cmpi.l  #12800,d6
                bcs.w   set_angle_tolerance_by_distance
                move.w  (aiRand).l,d0
                andi.w  #3,d0
                bne.w   no_fire_fallback_flow
set_angle_tolerance_by_distance:
                move.b  #$F,d1
                cmpi.l  #3200,d6
                bhi.w   compare_angle_to_tolerance
                move.b  #$32,d1         ; '2'
compare_angle_to_tolerance:
                move.w  SPRITE_DIRECTION(a5),d2
                bmi.w   no_fire_fallback_flow
                lsl.w   #5,d2
                sub.b   d5,d2
                cmp.b   d1,d2
                bgt.w   no_fire_fallback_flow
                neg.b   d1
                cmp.b   d1,d2
                bgt.w   angle_within_tolerance_action
no_fire_fallback_flow:
                tst.w   TEAMGENERALINFO_FIELD_84(a6)
                beq.s   field84_cooldown_expired_path
                subq.w  #1,TEAMGENERALINFO_FIELD_84(a6)
                move.w  d7,d0
                lsl.w   #5,d0
                bsr.w   FindClosestPlayerToBallFacing
                cmpa.l  #$FFFFFFFF,a0
                beq.w   closest_facing_player_not_ours
                move.w  (a5),d0
                cmp.w   (a0),d0
                beq.w   our_player_closest
                bra.w   closest_facing_player_not_ours
field84_cooldown_expired_path:
                cmpi.l  #9800,d6
                bcs.w   choose_dir_when_not_very_close
                cmpa.l  #0,a5
                beq.w   choose_dir_when_not_very_close
                movea.l (a6),a0
                movea.l TEAMGENERALINFO_CONTROLLEDPLAYER(a0),a2
                cmpa.l  #0,a2
                beq.s   use_pass_target_if_valid
                cmpi.l  #800,SPRITE_BALLDISTANCE(a2)
                bcs.s   evaluate_closest_facing_player_midrange
                cmpi.l  #5000,SPRITE_BALLDISTANCE(a2)
                bcs.s   far_distance_decision_gate
use_pass_target_if_valid:
                movea.l TEAMGENERALINFO_PASSTOPLAYERPTR(a0),a2
                cmpa.l  #0,a2
                beq.w   choose_dir_when_not_very_close
                cmpi.l  #800,$4A(a2)
                bcs.s   evaluate_closest_facing_player_midrange
                cmpi.l  #5000,$4A(a2)
                bcs.s   far_distance_decision_gate
                bra.w   choose_dir_when_not_very_close
evaluate_closest_facing_player_midrange:
                cmpi.l  #180000,d6
                bhi.w   decide_immediate_turn_or_gate
                move.w  d7,d0
                lsl.w   #5,d0
                bsr.w   FindClosestPlayerToBallFacing
                cmpa.l  #$FFFFFFFF,a0
                beq.w   gate_field84_cooldown_and_set
                move.w  (a5),d0
                cmp.w   (a0),d0
                beq.w   our_player_closest
                bra.w   gate_field84_cooldown_and_set
                cmpa.l  #$FFFFFFFF,a0
                bne.w   our_player_closest
                move.w  130(a6),d0
                andi.w  #3,d0
                bne.w   choose_dir_when_not_very_close
                bra.w   our_player_closest
far_distance_decision_gate:
                cmpi.w  #8,(aiRand).l
                bhi.s   tick_gated_closest_facing_check
                cmpi.l  #48400,d6
                bhi.w   decide_immediate_turn_or_gate
tick_gated_closest_facing_check:
                move.w  (currentGameTick).l,d0
                andi.w  #$C,d0
                bne.w   choose_dir_when_not_very_close
                move.w  d7,d0
                lsl.w   #5,d0
                bsr.w   FindClosestPlayerToBallFacing
                cmpa.l  #$FFFFFFFF,a0
                beq.w   gate_field84_cooldown_and_set
                move.w  (a5),d0
                cmp.w   (a0),d0
                beq.w   our_player_closest
                bra.w   *+4
gate_field84_cooldown_and_set:
                tst.w   TEAMGENERALINFO_FIELD_84(a6)
                bne.w   choose_dir_when_not_very_close
                move.w  (frameCount).l,d0
                andi.w  #$7F,d0
                cmpi.w  #$20,d0         ; ' '
                bcc.w   choose_dir_when_not_very_close
                move.w  #4,TEAMGENERALINFO_FIELD_84(a6)
closest_facing_player_not_ours:
                tst.b   TEAMGENERALINFO_PLVERYCLOSETOBALL(a6)
                beq.w   copy_current_direction_as_allowed
                btst    #7,(currentGameTick+1).l
                beq.s   choose_ccw_turn_when_very_close
                move.w  SPRITE_DIRECTION(a5),d0
                addq.w  #1,d0
                andi.w  #7,d0
                move.w  d0,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                rts
choose_ccw_turn_when_very_close:
                move.w  SPRITE_DIRECTION(a5),d0
                subq.w  #1,d0
                andi.w  #7,d0
                move.w  d0,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                rts
choose_dir_when_not_very_close:
                tst.b   TEAMGENERALINFO_PLVERYCLOSETOBALL(a6)
                beq.w   copy_current_direction_as_allowed
set_allowed_dir_from_angle_bucket:
                move.w  d5,d0
                addi.w  #$10,d0
                andi.w  #$FF,d0
                lsr.w   #5,d0
                move.w  d0,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                rts
copy_current_direction_as_allowed:
                move.w  SPRITE_DIRECTION(a5),TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                rts
derive_allowed_dir_from_full_angle:
                move.w  SPRITE_FULLDIRECTION(a5),d0
                addi.b  #-$80,d0
                addi.w  #16,d0
                andi.w  #$FF,d0
                lsr.w   #5,d0
                cmp.w   SPRITE_DIRECTION(a5),d0
                beq.w   commit_allowed_dir_from_bucket
                cmpi.l  #800,SPRITE_BALLDISTANCE(a5)
                bcs.s   commit_allowed_dir_from_bucket
                move.w  (currentGameTick).l,d1
                andi.w  #$E,d1
                beq.s   commit_allowed_dir_from_bucket
                move.w  SPRITE_DIRECTION(a5),TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                rts
commit_allowed_dir_from_bucket:
                move.w  d0,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                rts
set_allowed_dir_to_base_dir:
                move.w  d7,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                rts
our_player_closest:
                clr.w   TEAMGENERALINFO_FIELD_84(a6)
                tst.w   (aiResumePlayTimer).l
                bne.w   locret_118178   ; small delay before getting the ball back to play
                bsr.w   AI_ResumeGameDelay
                bcc.w   locret_118178   ; wait a little while for player to get rid of the ball
                move.w  #15,(aiResumePlayTimer).l
                move.w  d7,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6) ; D7 should be controlled player direction...
                move.b  #1,TEAMGENERALINFO_QUICKFIRE(a6) ; fire! (passing)
                move.w  (AI_maxStoppageTime).l,d0
                cmp.w   stoppageTimerActive(pc),d0
                bhi.s   jmp_return
                move.w  stoppageTimerActive(pc),(AI_maxStoppageTime).l
jmp_return:
                bra.w   locret_118178
decide_immediate_turn_or_gate:
                move.w  d5,d0
                addi.w  #16,d0
                andi.w  #$FF,d0
                lsr.w   #5,d0
                sub.w   d7,d0
                andi.w  #7,d0
                beq.w   setup_resume_play_and_turn_bias
                cmpi.w  #1,d0
                beq.w   setup_resume_play_and_turn_bias
                cmpi.w  #$FFFF,d0
                beq.w   setup_resume_play_and_turn_bias
                bra.w   gate_field84_cooldown_and_set
setup_resume_play_and_turn_bias:
                move.w  #2,TEAMGENERALINFO_AI_AFTERTOUCHSTRENGTH(a6)
                cmpi.l  #115600,d6
                bhi.s   set_facing_and_action_flag
                move.w  #1,TEAMGENERALINFO_AI_AFTERTOUCHSTRENGTH(a6)
set_facing_and_action_flag:
                move.w  d7,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                move.b  #1,TEAMGENERALINFO_NORMALFIRE(a6)
                move.w  d7,d2
                lsl.w   #5,d2
                sub.b   d5,d2
                move.w  #15,(aiResumePlayTimer).l
                move.w  #$FFFF,d0
                tst.b   d2
                bpl.w   adjust_turn_by_ball_motion
                neg.w   d0
adjust_turn_by_ball_motion:
                tst.l   (ballSprite+SPRITE_DELTAY).l
                bmi.s   ball_moving_up_gate
                cmpi.w  #555,(ballSprite+SPRITE_Y).l
                bhi.s   commit_turn_to_ai_state
                bra.s   time_bucket_and_ballx_branch
ball_moving_up_gate:
                cmpi.w  #342,(ballSprite+SPRITE_Y).l
                bcs.s   commit_turn_to_ai_state
time_bucket_and_ballx_branch:
                move.w  (currentGameTick).l,d1
                andi.w  #$1C,d1
                lsr.w   #2,d1
                cmpi.w  #193,(ballSprite+SPRITE_X).l
                bcs.s   outer_wings_x_gate
                cmpi.w  #478,(ballSprite+SPRITE_X).l
                bcs.s   mid_right_x_gate
outer_wings_x_gate:
                cmpi.w  #118,(ballSprite+SPRITE_X).l
                bcs.s   outerwide_x_gate
                cmpi.w  #553,(ballSprite+SPRITE_X).l
                bhi.s   outerwide_x_gate
                bra.s   midfield_x_gate
mid_right_x_gate:
                tst.w   d1
                beq.s   set_zero_turn
                cmpi.w  #5,d1
                bcs.s   commit_turn_to_ai_state
                bra.s   invert_turn
midfield_x_gate:
                tst.w   d1
                beq.s   invert_turn
                cmpi.w  #4,d1
                bcs.s   set_zero_turn
                bra.s   commit_turn_to_ai_state
outerwide_x_gate:
                cmpi.w  #4,d1
                bcs.s   commit_turn_to_ai_state
set_zero_turn:
                clr.w   d0
                bra.s   commit_turn_to_ai_state
invert_turn:
                neg.w   d0
commit_turn_to_ai_state:
                move.w  d0,TEAMGENERALINFO_AI_BALLSPINDIRECTION(a6)
                bra.w   locret_118178
angle_within_tolerance_action:
                tst.w   (aiResumePlayTimer).l
                bne.w   locret_118178
                bsr.w   AI_ResumeGameDelay
                bcc.w   locret_118178
                move.w  #0,TEAMGENERALINFO_AI_AFTERTOUCHSTRENGTH(a6)
                bra.s   resume_play_and_apply_turn_bias
                tst.w   (aiResumePlayTimer).l
                bne.w   locret_118178
                bsr.w   AI_ResumeGameDelay
                bcc.w   locret_118178
                move.w  #1,TEAMGENERALINFO_AI_AFTERTOUCHSTRENGTH(a6)
                bra.s   resume_play_and_apply_turn_bias
                tst.w   (aiResumePlayTimer).l
                bne.w   locret_118178
                bsr.w   AI_ResumeGameDelay
                bcc.w   locret_118178
                move.w  #2,TEAMGENERALINFO_AI_AFTERTOUCHSTRENGTH(a6)
resume_play_and_apply_turn_bias:
                move.w  #15,(aiResumePlayTimer).l
                move.w  d7,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                move.b  #1,TEAMGENERALINFO_NORMALFIRE(a6)
                move.w  #$FFFF,d0
                tst.b   d2
                bpl.w   store_turn_value
                neg.w   d0
store_turn_value:
                move.w  d0,$88(a6)
                bra.w   locret_118178
prep_aftertouch_and_fire_decision:
                move.w  (AI_maxStoppageTime).l,d0
                cmp.w   stoppageTimerActive(pc),d0
                bhi.s   arm_resume_timer
                move.w  stoppageTimerActive(pc),(AI_maxStoppageTime).l
arm_resume_timer:
                move.w  #15,(aiResumePlayTimer).l
                cmpi.w  #ST_PENALTY,(gameState).l
                beq.s   set_aftertouch_none
                cmpi.w  #ST_PENALTIES,(gameState).l
                beq.s   set_aftertouch_none
                cmpi.w  #ST_FREE_KICK_LEFT1,(gameState).l
                bcs.s   non_setpiece_random_branch
                cmpi.w  #ST_FREE_KICK_RIGHT3,(gameState).l
                bls.s   aftertouch_by_distance
non_setpiece_random_branch:
                cmpi.w  #ST_CORNER_LEFT,(gameState).l
                beq.s   set_aftertouch_medium
                cmpi.w  #ST_CORNER_RIGHT,(gameState).l
                beq.s   set_aftertouch_medium
                move.w  (aiRand).l,d0
                andi.w  #$18,d0
                bne.s   aftertouch_by_distance
                cmpi.w  #$10,d0
                beq.s   set_aftertouch_none
                cmpi.w  #8,d0
                beq.s   set_aftertouch_medium
                bra.s   set_aftertouch_strong
aftertouch_by_distance:
                cmpi.l  #28800,d6
                bcs.w   set_aftertouch_none
                cmpi.l  #57800,d6
                bcs.w   set_aftertouch_medium
set_aftertouch_strong:
                move.w  #2,TEAMGENERALINFO_AI_AFTERTOUCHSTRENGTH(a6)
                bra.s   apply_dir_and_normal_fire
set_aftertouch_medium:
                move.w  #1,TEAMGENERALINFO_AI_AFTERTOUCHSTRENGTH(a6)
                bra.s   apply_dir_and_normal_fire
set_aftertouch_none:
                move.w  #0,TEAMGENERALINFO_AI_AFTERTOUCHSTRENGTH(a6)
apply_dir_and_normal_fire:
                move.w  d7,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                move.b  #1,TEAMGENERALINFO_NORMALFIRE(a6)
                cmpi.w  #ST_PENALTY,(gameState).l
                beq.w   zero_turn_and_return
                cmpi.w  #ST_PENALTIES,(gameState).l
                beq.w   zero_turn_and_return
                cmpi.w  #ST_CORNER_LEFT,(gameState).l
                beq.w   corner_spin_direction_randomizer
                cmpi.w  #ST_CORNER_RIGHT,(gameState).l
                beq.w   corner_spin_direction_randomizer
                move.w  #15,(aiResumePlayTimer).l
                move.w  d7,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                move.b  #1,TEAMGENERALINFO_NORMALFIRE(a6)
                clr.w   d0
                cmpi.w  #ST_FOUL,(gameState).l
                bne.s   compute_turn_from_angle_sign
                cmpa.l  #topTeamData,a6
                bne.s   foul_y_gate_bottom_team
                cmpi.w  #682,SPRITE_Y(a2)
                bge.w   apply_turn_and_return
                bra.s   compute_turn_from_angle_sign
foul_y_gate_bottom_team:
                cmpi.w  #216,SPRITE_Y(a2)
                ble.w   apply_turn_and_return
compute_turn_from_angle_sign:
                move.w  #$FFFF,d0
                tst.b   d2
                bpl.w   apply_turn_and_return
                neg.w   d0
apply_turn_and_return:
                move.w  d0,TEAMGENERALINFO_AI_BALLSPINDIRECTION(a6)
                bra.w   locret_118178
corner_spin_direction_randomizer:
                move.w  (aiRand).l,d0
                andi.w  #7,d0
                cmpi.w  #3,d0
                bcs.s   spin_cw_candidate
                cmpi.w  #6,d0
                bcs.s   spin_ccw_candidate
zero_turn_and_return:
                clr.w   TEAMGENERALINFO_AI_BALLSPINDIRECTION(a6)
                bra.w   locret_118178
spin_ccw_candidate:
                move.w  #$FFFF,d1
                move.w  d7,d0
                subq.w  #1,d0
                bra.s   validate_spin_and_apply
spin_cw_candidate:
                move.w  #1,d1
                move.w  d7,d0
                addq.w  #1,d0
validate_spin_and_apply:
                andi.w  #7,d0
                btst    d0,playerTurnFlags(pc)
                beq.s   zero_turn_and_return
                move.w  d1,TEAMGENERALINFO_AI_BALLSPINDIRECTION(a6)
                bra.w   locret_118178
noone_near:
                bsr.w   AI_DecideWhetherToTriggerFire
                beq.w   locret_118178
                cmpa.l  #0,a4
                beq.s   choose_full_angle_or_random_bucket
                move.l  SPRITE_BALLDISTANCE(a4),d0
                sub.l   SPRITE_BALLDISTANCE(a5),d0
                cmpi.l  #50,d0
                blt.s   choose_full_angle_or_random_bucket
                move.l  TEAMGENERALINFO_PASSTOPLAYERPTR(a6),d0
                move.l  TEAMGENERALINFO_CONTROLLEDPLAYER(a6),TEAMGENERALINFO_PASSTOPLAYERPTR(a6)
                move.l  d0,TEAMGENERALINFO_CONTROLLEDPLAYER(a6)
                bra.w   locret_118178
choose_full_angle_or_random_bucket:
                cmpa.l  #0,a4
                beq.w   derive_allowed_dir_from_full_angle
                tst.w   (deadVarAlways0).l
                bne.w   set_allowed_dir_from_angle_bucket
                tst.w   (topTeamData+TEAMGENERALINFO_PLAYERNUMBER).l
                bne.s   skip_to_full_angle_check
                tst.w   (bottomTeamData+TEAMGENERALINFO_PLAYERNUMBER).l
                bne.s   skip_to_full_angle_check
                bra.w   random_rotate_when_no_target
skip_to_full_angle_check:
                bra.w   derive_allowed_dir_from_full_angle
                move.l  SPRITE_BALLDISTANCE(a4),d0
                sub.l   SPRITE_BALLDISTANCE(a5),d0
                cmpi.l  #800,d0
                bgt.w   derive_allowed_dir_from_full_angle
random_rotate_when_no_target:
                move.w  #$FFFF,d0
                cmpi.w  #273,SPRITE_X(a5)
                blt.s   random_rotate_or_base_dir_gate
                cmpi.w  #398,SPRITE_X(a5)
                bgt.s   random_rotate_or_base_dir_gate
                cmpi.w  #158,SPRITE_Y(a5)
                ble.s   loc_118040
                cmpi.w  #740,SPRITE_Y(a5)
                bge.s   loc_118040
random_rotate_or_base_dir_gate:
                move.w  (currentGameTick).l,d0
                andi.w  #$18,d0         ; 12.5% chance of direction flip
                bne.w   set_allowed_dir_to_base_dir
                move.w  (aiRand).l,d0
                andi.w  #2,d0
                lea     (aiRandomRotateTable).l,a0
                move.w  (a0,d0.w),d0
                add.w   SPRITE_FULLDIRECTION(a5),d0 ; rotate left/right one position randomly
                addi.b  #128,d0         ; flip direction
                addi.w  #16,d0
                andi.w  #$FF,d0
                lsr.w   #5,d0
loc_118040:
                move.w  d0,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                rts
branch_to_not_very_close:
                bra.w   choose_dir_when_not_very_close
                cmpa.l  #0,a4
                beq.w   derive_allowed_dir_from_full_angle
                cmpi.l  #2450,SPRITE_BALLDISTANCE(a5)
                bhi.w   derive_allowed_dir_from_full_angle
                move.w  SPRITE_DIRECTION(a5),d0
                bmi.w   derive_allowed_dir_from_full_angle
                lsl.w   #5,d0
                sub.b   d5,d0
                cmpi.b  #15,d0
                bgt.w   derive_allowed_dir_from_full_angle
                cmpi.b  #241,d0
                blt.w   derive_allowed_dir_from_full_angle
                move.w  d7,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                move.b  #1,TEAMGENERALINFO_FIRETHISFRAME(a6)
                bra.w   locret_118178
we_have_ball_spin:
                move.w  TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6),d1
                tst.w   (playingPenalties).l
                bne.w   apply_spin_quick_or_copy_dir
                tst.w   (penalty).l
                bne.w   apply_spin_quick_or_copy_dir
                move.w  (aiRand).l,d0
                andi.w  #1,d0
                beq.s   apply_spin_quick_or_copy_dir
                tst.w   TEAMGENERALINFO_AI_BALLSPINDIRECTION(a6)
                bmi.s   use_left_spin_table
                bne.s   use_right_spin_table
                nop
apply_spin_quick_or_copy_dir:
                cmpi.w  #1,TEAMGENERALINFO_AI_AFTERTOUCHSTRENGTH(a6)
                bne.s   use_long_kick_table
                move.w  #$FFFF,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                rts
                move.w  TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6),TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                rts
use_long_kick_table:
                lea     (aiLongKickTable).l,a0
                bra.s   apply_spin_table_offset
use_left_spin_table:
                move.w  d1,d0
                subq.w  #1,d0
                andi.w  #7,d0
                lea     (aiLeftSpinTable).l,a0
                bra.s   apply_spin_table_offset
use_right_spin_table:
                move.w  d1,d0
                addq.w  #1,d0
                andi.w  #7,d0
                lea     (aiRotateRightTable).l,a0
apply_spin_table_offset:
                move.w  TEAMGENERALINFO_AI_AFTERTOUCHSTRENGTH(a6),d0
                lsl.w   #1,d0
                add.w   (a0,d0.w),d1
                andi.w  #7,d1
                move.w  d1,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                rts
                move.w  TEAMGENERALINFO_CONTROLLEDPLDIRECTION(a6),TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                rts

; ===== AI_SetDirectionTowardOpponentsGoal =====
; prototype: __int16 __usercall AI_SetDirectionTowardOpponentsGoal@<d0>(struct TeamGeneralInfo *team@<a6>)
; in:
;     A6 -> team data
; 
; Set the direction toward the opposing goal and the ball.
; Limits for ball x are less than 300, 300...371 and greater than 371.
AI_SetDirectionTowardOpponentsGoal:
                tst.w   (aiCounter).l
                beq.w   early_return_no_update
                move.w  (ballSprite+SPRITE_X).l,d0
                cmpi.w  #1,(aiAttackHalf).l
                beq.s   bottom_team_direction_by_ballx
                cmpa.l  #topTeamData,a6
                bne.s   early_return_no_update
                move.w  #3,d1
                cmpi.w  #300,d0
                bcs.s   set_allowed_direction_and_return
                move.w  #5,d1
                cmpi.w  #371,d0
                bhi.s   set_allowed_direction_and_return
                move.w  #4,d1
                bra.s   set_allowed_direction_and_return
bottom_team_direction_by_ballx:
                cmpa.l  #bottomTeamData,a6
                bne.s   early_return_no_update
                move.w  #1,d1
                cmpi.w  #300,d0
                bcs.s   set_allowed_direction_and_return
                move.w  #7,d1
                cmpi.w  #371,d0
                bhi.s   set_allowed_direction_and_return
                move.w  #0,d1
set_allowed_direction_and_return:
                move.w  d1,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                bra.w   locret_118178
early_return_no_update:
                rts
locret_118178:
                rts
                rts

; ===== AI_DecideWhetherToTriggerFire =====
; prototype: int __usercall AI_DecideWhetherToTriggerFire@<d0>(struct Sprite *player@<a5>, struct TeamGeneralInfo *team@<a6>, unsigned __int16 dir@<d7>)
; in:
;      D7 - controlled player direction
;      A5 -> controlled player sprite
;      A6 -> team general data
; out:
;      D0, zero flag - 0/set: firing, !0/clear: not gonna fire
AI_DecideWhetherToTriggerFire:
                cmpi.w  #1,SPRITE_PLAYERORDINAL(a5)
                beq.w   no_fire_return_one
                cmpa.l  #topTeamData,a6
                bne.s   check_right_team_facing_sectors ; we're bottom
                cmpi.w  #3,d7           ; is the player facing downwards, toward opponent's goal?
                beq.s   valid_facing_sector_gate
                cmpi.w  #4,d7
                beq.s   valid_facing_sector_gate
                cmpi.w  #5,d7
                beq.s   valid_facing_sector_gate
                bra.w   no_fire_return_one ; not facing toward opponent goal (directions 3,4,5)
check_right_team_facing_sectors:
                cmpi.w  #7,d7
                beq.s   valid_facing_sector_gate
                cmpi.w  #0,d7
                beq.s   valid_facing_sector_gate
                cmpi.w  #1,d7
                bne.w   no_fire_return_one
valid_facing_sector_gate:
                cmpi.l  #648,SPRITE_BALLDISTANCE(a5) ; 18 ^ 2 + 18 ^ 2
                bhi.w   no_fire_return_one
                tst.l   (ballSprite+SPRITE_DELTAZ).l ; the player is near the ball
                bmi.s   ball_descending_height_gate
                cmpi.w  #8,(ballSprite+SPRITE_Z).l ; ball going up or on the ground
                bcs.w   no_fire_return_one
                cmpi.w  #$E,(ballSprite+SPRITE_Z).l
                bhi.w   no_fire_return_one
                bra.s   arm_shot_and_set_direction
ball_descending_height_gate:
                cmpi.w  #12,(ballSprite+SPRITE_Z).l
                bcs.s   no_fire_return_one
                cmpi.w  #20,(ballSprite+SPRITE_Z).l
                bhi.s   no_fire_return_one
arm_shot_and_set_direction:
                move.b  #1,TEAMGENERALINFO_FIRETHISFRAME(a6) ; ball z must be [8..14]
                move.w  SPRITE_FULLDIRECTION(a5),d0
                addi.b  #-128,d0
                andi.w  #$FF,d0         ; reverse the direction top-down
                lsr.w   #5,d0           ; turn into 0..7 range
                move.w  d0,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                move.w  SPRITE_FULLDIRECTION(a5),d0
                addi.b  #-128,d0
                addi.w  #16,d0          ; round up (+0.5 when converted to 0..7 range)
                andi.w  #$FF,d0
                lsr.w   #5,d0
                cmp.w   d7,d0
                bne.s   no_fire_return_one
                move.w  d0,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                move.w  #15,(aiCounter).l
                move.w  d0,(aiCounterWriteOnly).l
                move.w  #2,(aiAttackHalf).l
                cmpa.l  #topTeamData,a6
                beq.s   set_attack_half_by_team
                move.w  #1,(aiAttackHalf).l
set_attack_half_by_team:
                clr.w   d0
                rts
no_fire_return_one:
                move.w  #1,d0
                rts

; ===== AI_ResumeGameDelay =====
; prototype: struct TeamGeneralInfo *__usercall AI_ResumeGameDelay@<a0>(struct TeamGeneralInfo *team@<a6>)
; in:
;      A6 -> team (general)
; out:
;      A0 -> opponents team
;      carry flag = pass/kick time == 13
; 
; Only used by AI.
AI_ResumeGameDelay:
                movea.l (a6),a0
                cmpi.w  #13,TEAMGENERALINFO_PASSKICKTIMER(a6)
                rts
aiTurnDirection:
                dc.w $0001
aiResumePlayTimer:
                dc.w $0000              ; When AI puts the ball back into play this counts down from 15 to 0
aiRand:
                dc.w $0000              ; Random number generated each time DoAI is called; 0..255
pad_11826C:
                dc.b $00,$00
; __int16[2]
aiRandomRotateTable:
                ; __int16[2]
                dc.w -32,32
; __int16[3]
aiLeftSpinTable:
                ; __int16[3]
                dc.w -1,-2,-3
; __int16[3]
aiRotateRightTable:
                ; __int16[3]
                dc.w 1,2,3
; __int16[3]
aiLongKickTable:
                ; __int16[3]
                dc.w 0,-999,4
; __int16
aiCounter:
                dc.w 0                  ; Zero during the game
                                        ; positive, counts down to zero
                                        ; while non-zero, AI is allowed to modify direction (for ball spin?)
; __int16
aiAttackHalf:
                dc.w 0                  ; Which half does the AI attack? 1 or 2
                                        ; set when AI decides to trigger fire
; __int16
aiCounterWriteOnly:
                dc.w 0
; __int8[6]
aiThrowInDirections:
                dc.b 3,6,12,-127,-64,96 ; Angle range 0..255, indexed by game state enum, values for throw-in

; ===== AI_Kick =====
; prototype: char __usercall AI_Kick@<d0>(struct Sprite *player@<a1>, struct TeamGeneralInfo *team@<a6>)
; in:
;      A1 -> player controlling the ball
;      A6 -> team general info
AI_Kick:
                tst.w   (deadVarAlways0).l
                beq.s   kick_prechecks_and_angle_diff
                cmpa.l  playerKickerPtr(pc),a6
                beq.s   return_from_ai_kick
                movea.l (a6),a0
                cmpa.l  playerKickerPtr(pc),a0
                beq.s   return_from_ai_kick
kick_prechecks_and_angle_diff:
                move.w  (currentGameTick).l,d0
                andi.w  #6,d0
                cmpi.l  #200,SPRITE_BALLDISTANCE(a1)
                bhi.s   return_from_ai_kick
                move.w  TEAMGENERALINFO_ALLOWEDDIRECTIONS(a1),d7
                movea.l (a6),a0
                tst.w   TEAMGENERALINFO_PLAYERHASBALL(a0)
                beq.s   return_from_ai_kick
                movea.l TEAMGENERALINFO_CONTROLLEDPLAYER(a0),a0
                cmpa.l  #0,a0
                beq.s   return_from_ai_kick
                move.w  TEAMGENERALINFO_ALLOWEDDIRECTIONS(a0),d0
                lsl.w   #5,d0
                move.w  SPRITE_DIRECTION(a1),d1
                lsl.w   #5,d1
                sub.b   d1,d0
                cmpi.b  #224,d0
                blt.s   trigger_kick_flags_and_direction
                cmpi.b  #32,d0
                ble.s   return_from_ai_kick
trigger_kick_flags_and_direction:
                move.w  d7,TEAMGENERALINFO_CURRENTALLOWEDDIRECTION(a6)
                move.b  #1,TEAMGENERALINFO_FIREPRESSED(a6)
                move.b  #1,TEAMGENERALINFO_FIRETHISFRAME(a6)
                move.b  #1,TEAMGENERALINFO_NORMALFIRE(a6)
return_from_ai_kick:
                rts

; ===== FindClosestPlayerToBallFacing =====
; prototype: Sprite *__usercall FindClosestPlayerToBallFacing@<a0>(unsigned __int16 fullDir@<d0>, TeamGeneralInfo *team@<a6>)
; in:
;      D0 -  full direction player must be facing (+/- 16)
;      A6 -> team (general)
; out:
;      D2 - ball distance
;      A0 -> player
; 
; Find player closest to ball facing specified direction. Search both teams.
FindClosestPlayerToBallFacing:
                lea     (ballSprite).l,a0
                move.w  SPRITE_X(a0),d3
                move.w  SPRITE_Y(a0),d4
                movea.l #$FFFFFFFF,a0
                moveq   #$FFFFFFFF,d2
                move.w  #1,d3
                move.w  #$A,d4
                lea     topTeamData(pc),a3
                movea.l topTeamData+TEAMGENERALINFO_SPRITESTABLE-topTeamData(a3),a2
scan_players_facing_ball_loop:
                movea.l (a2)+,a1
                cmpa.l  TEAMGENERALINFO_CONTROLLEDPLAYER(a6),a1
                beq.s   next_candidate_player
                tst.w   SPRITE_SENTAWAY(a1)
                bne.s   next_candidate_player
                cmpi.b  #PL_NORMAL,SPRITE_PLAYERSTATE(a1)
                bne.s   next_candidate_player
                move.w  SPRITE_FULLDIRECTION(a1),d1
                sub.b   d0,d1
                cmpi.b  #240,d1
                blt.s   next_candidate_player
                cmpi.b  #16,d1
                bgt.s   next_candidate_player
                move.l  SPRITE_BALLDISTANCE(a1),d1
                cmp.l   d2,d1
                bcc.s   next_candidate_player
                move.l  d1,d2
                movea.l a1,a0
next_candidate_player:
                dbf     d4,scan_players_facing_ball_loop
                move.w  #10,d4
                lea     bottomTeamData(pc),a3
                movea.l 20(a3),a2
                dbf     d3,scan_players_facing_ball_loop
                rts
