; ===== PrintFormatted =====
; prototype: void __usercall PrintFormatted(const char *fmt@<a0>, char *out@<a1>, unsigned __int16 n0@<d0>, unsigned __int16 n1@<d1>, unsigned __int16 n2@<d2>, unsigned __int16 n3@<d3>, unsigned __int16 n4@<d4>, unsigned __int16 n5@<d5>, unsigned __int16 n6@<d6>, const char *a@<a2>, const char *b@<a3>, const char *c@<a4>)
; in:
;     A0 -> format string
;     A1 -> converted string in the end (words)
;     D0 - number 0
;     D1 - number 1
;     D2 - number 2
;     D3 - number 3
;     D4 - number 4
;     D5 - number 5
;     D6 - number 6
;     A2 - string a
;     A3 - string b
;     A4 - string c
; 
; Format string can contain simple commands that start with %.
; %a, %b and %c mark string insertation, where actual strings
; are in A2, A3 and A4. Ascii representation of 0, 1,
; 2, 3, 4, 5, or 6 after % means converting number in D0-D6
; to ascii and inserting in output string.
PrintFormatted:
                movem.l d7/a5,-(sp)
copy_until_percent_or_nul:
                cmpi.b  #'%',(a0)
                beq.s   handle_percent_and_select_source
                move.b  (a0)+,(a1)+
                bne.s   copy_until_percent_or_nul
                subq.l  #1,a1
                movem.l (sp)+,d7/a5
                rts
handle_percent_and_select_source:
                addq.l  #2,a0
                movea.l a2,a5
                cmpi.b  #'a',-1(a0)
                beq.w   emit_alpha_value
                movea.l a3,a5
                cmpi.b  #'b',-1(a0)
                beq.w   emit_alpha_value
                movea.l a4,a5
                cmpi.b  #'c',-1(a0)
                beq.w   emit_alpha_value
                move.w  d0,d7
                cmpi.b  #'0',-1(a0)
                beq.s   emit_decimal_value
                move.w  d1,d7
                cmpi.b  #'1',-1(a0)
                beq.s   emit_decimal_value
                move.w  d2,d7
                cmpi.b  #'2',-1(a0)
                beq.s   emit_decimal_value
                move.w  d3,d7
                cmpi.b  #'3',-1(a0)
                beq.s   emit_decimal_value
                move.w  d4,d7
                cmpi.b  #'4',-1(a0)
                beq.s   emit_decimal_value
                move.w  d5,d7
                cmpi.b  #'5',-1(a0)
                beq.s   emit_decimal_value
                move.w  d6,d7
                cmpi.b  #'6',-1(a0)
                beq.s   emit_decimal_value
                move.w  #$5916,(panicReasonCode).l
                jsr     PanicHaltLoop
emit_decimal_value:
                cmpi.w  #10,d7
                bcs.s   emit_units_and_continue
                cmpi.w  #100,d7
                bcs.s   emit_tens_digit
                cmpi.w  #1000,d7
                bcs.s   emit_hundreds_digit
                cmpi.w  #10000,d7
                bcs.s   emit_thousands_digit
                andi.l  #$FFFF,d7
                divu.w  #10000,d7
                move.b  d7,(a1)
                addi.b  #'0',(a1)+
                swap    d7
emit_thousands_digit:
                ext.l   d7
                divu.w  #1000,d7
                move.b  d7,(a1)
                addi.b  #'0',(a1)+
                swap    d7
emit_hundreds_digit:
                ext.l   d7
                divu.w  #100,d7
                move.b  d7,(a1)
                addi.b  #'0',(a1)+
                swap    d7
emit_tens_digit:
                ext.l   d7
                divu.w  #10,d7
                move.b  d7,(a1)
                addi.b  #'0',(a1)+
                swap    d7
emit_units_and_continue:
                move.b  d7,(a1)
                addi.b  #'0',(a1)+
                bra.w   copy_until_percent_or_nul
emit_alpha_value:
                move.b  (a5)+,(a1)+
