; ===== GetPlayerPrice =====
; prototype: unsigned __int16 __usercall GetPlayerPrice@<d7>(TeamFile *team@<a0>, PlayerFile *player@<a1>, unsigned __int16 position@<d7>)
; in:
;      A0 -> team (file)
;      A1 -> player (file)
;      D7 = player number (position)
; out:
;      D7 - player price
;      
; Calculate and return player's price. Deduce tactics from player's team.
GetPlayerPrice:
                move.l  a1,-(sp)
                move.b  PLAYERFILE_POSITIONANDFACE+$4C(a1),d0
                andi.w  #$E0,d0
                lsr.w   #5,d0
                mulu.w  #35,d0
                lea     skillsPerQuadrant(pc),a5
                lea     loc_122D6A+1-skillsPerQuadrant(a5,d0.w),a5
                move.l  PLAYERFILE_PASSING+$4C(a1),d5
                andi.l  #$7777777,d5
                addi.l  #$1111111,d5
                move.b  24(a0),d0
                ext.w   d0
                lsl.w   #2,d0
                lea     teamTacticsTable(pc),a3
                movea.l (a3,d0.w),a3
                lea     9(a3),a3
                move.l  a3,(plPositions).l
                subq.w  #1,d7
                mulu.w  #35,d7
