; ===== AreBasicColorsConflicting =====
; prototype: void __usercall AreBasicColorsConflicting(unsigned __int8 color1@<d0>, unsigned __int8 color2@<d4>)
; in:
;      D0 - team color 1 (0..9)
;      D4 - team color 2 (0..9)
; out:
;      zero flag: set = OK, clear = conflict
AreBasicColorsConflicting:
                andi.w  #$FF,d0
                andi.w  #$FF,d4
                lsl.w   #1,d0
                lea     (conflictingBasicTeamColorsTable).l,a0
                move.w  (a0,d0.w),d0
                btst    d4,d0           ; bit set = conflict
                rts

; ===== AreShortsAndStripeColorsConflicting =====
; prototype: void __usercall AreShortsAndStripeColorsConflicting(unsigned __int8 shortsColor@<d0>, unsigned __int8 stripeColor@<d4>)
AreShortsAndStripeColorsConflicting:
                andi.w  #$FF,d0
                andi.w  #$FF,d4
                lsl.w   #1,d0
                lea     (conflictingShortsTeamColorsTable).l,a0
                move.w  (a0,d0.w),d0
                btst    d4,d0
                rts
; unsigned __int16[10]
conflictingBasicTeamColorsTable:
                ; unsigned __int16[10]
                dc.w $01A1,$0002,$0164,$0218,$0058,$00A5,$0054,$00A1 ; Index with 1st color then if 2nd color bit is set -> conflict
                dc.w $0105,$0208
                                        ;        gray white black orange red blue brown l.blue green yellow
                                        ; gray     x                           x           x     x
                                        ; white         x
                                        ; black               x                x    x            x
                                        ; orange                    x     x                             x
                                        ; red                       x     x         x
                                        ; blue     x          x                x           x
                                        ; brown               x           x         x
                                        ; l.blue   x                           x           x
                                        ; green    x          x                                  x
                                        ; yellow                    x                                   x
; unsigned __int16[10]
conflictingShortsTeamColorsTable:
                ; unsigned __int16[10]
                dc.w $01A3,$0283,$0164,$0218,$0058,$00E5,$0074,$00A3 ; Gray white black orange red blue brown l.blue green yellow
                dc.w $0105,$020A
                                        ; gray     x    x                      x           x     x
                                        ; white    x    x                                  x            x
                                        ; black               x                x    x            x
                                        ; orange                    x     x                             x
                                        ; red                       x     x         x
                                        ; blue     x          x                x    x      x
                                        ; brown               x           x    x    x
                                        ; l.blue   x    x                      x           x
                                        ; green    x          x                                  x
                                        ; yellow        x            x                                  x
kitsSimilarityLookupTable:
                dc.b $01,$05,$07,$01,$02,$00,$04,$05,$06,$04,$09,$03,$01,$09,$09,$01
                dc.b $07,$07,$01,$00,$00,$04,$03,$03,$04,$06,$06,$04,$02,$06,$00,$05
                dc.b $07,$06,$03,$04,$02,$07,$05,$09,$05,$08,$09,$07,$08,$FF
shirtType1:
                dc.b $00
shirtType2:
                dc.b $00
similarityFactor:
                dc.w $0000              ; How similar are the colors of two teams

