                move.b  d3,d0
                bsr.w   ConvertTeamColor
                move.w  d0,TEAMGAME_PRSHORTSCOL(a1)
                move.b  d4,d0
                bsr.w   ConvertTeamColor
                move.w  d0,TEAMGAME_PRSOCKSCOL(a1)
                rts

