                jsr     SaveDIYTournament
                jsr     InitDIYTournament
                clr.w   (diyTournamentLookOnly).l
                clr.w   (diyTournamentSelectTeams).l
                lea     (designDiyTournamentMenu).l,a6
                jmp     ShowMenu

