; ===== FormatSaveDiskMenu =====
; prototype: void __usercall FormatSaveDiskMenu()
FormatSaveDiskMenu:
                lea     (aFormatSaveDisk).l,a0 ; "FORMAT SAVE DISK"
                lea     (aInsertBlankDis).l,a1 ; "\x01INSERT BLANK DISK IN DF0:"
                lea     (aContinue).l,a2 ; "CONTINUE"
                lea     (aAbort).l,a3   ; "ABORT"
                move.w  #1,d0
                jsr     DoContinueAbortMenu
                bne.s   format_save_return
                move.w  #ASSET_OP_OPEN_ANY_SOURCE,d7
                jsr     AssetSys_Dispatch
                beq.s   disk_ready
                cmpi.w  #$1D,d0
                beq.s   FormatSaveDiskMenu
                bra.s   show_fs_error_and_return
disk_ready:
                jsr     StopMusic
                lea     (aSwosu).l,a0   ; "SWOSU"
                move.w  #ASSET_OP_DO_CRITICAL,d7
                jsr     AssetSys_Dispatch
                tst.w   (menuMusic).l
                beq.s   play_menu_music_if_any
                movem.l d0,-(sp)
                jsr     TryPlayMusic
                movem.l (sp)+,d0
play_menu_music_if_any:
                tst.w   d0
                bne.s   show_fs_error_and_return
                lea     (aSwos4Dku).l,a0 ; "swos4.dku"
                lea     (saveFileBuffer).l,a1
                moveq   #2,d1
                move.w  #ASSET_OP_LOAD_FILE,d7
                jsr     AssetSys_Dispatch
                bne.s   show_fs_error_and_return
format_save_return:
                rts
show_fs_error_and_return:
                jsr ShowFsErrorByCode(pc)
                rts
aSwosu:
                dc.b "SWOSU",0
saveFileBuffer:
                dc.w $0000              ; Buffer start address used as destination when loading swos4.dku save file data.

