; ===== ContinueAbortInit =====
; prototype: __int16 ContinueAbortInit()
ContinueAbortInit:
                movea.l (promptHeader).l,a0
                cmpa.l  #0,a0
                bne.s   loc_140A1E
                move.w  #1,(menuEntries+MENUENTRY_ISINVISIBLE).l
                bra.s   loc_140A4E
loc_140A1E:
                lea     (smallCharsTable).l,a1
                jsr     GetTextWidth
                addi.w  #20,d7
                cmpi.w  #120,d7
                bhi.s   loc_140A38
                move.w  #120,d7
loc_140A38:
                lea     (menuEntries).l,a0
                move.w  d7,MENUENTRY_DWWIDTH(a0)
                lsr.w   #1,d7
                sub.w   d7,MENUENTRY_X(a0)
                move.l  (promptHeader).l,MENUENTRY_FG+ENTRYTYPE2UNION_STRING(a0)
loc_140A4E:
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$38)).l,a0
                move.l  (whatIsChanging).l,MENUENTRY_FG+ENTRYTYPE2UNION_STRING(a0)
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$70)).l,a0
                move.l  (continueText).l,MENUENTRY_FG+ENTRYTYPE2UNION_STRING(a0)
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$A8)).l,a0
                move.l  (abortText).l,MENUENTRY_FG+ENTRYTYPE2UNION_STRING(a0)
                bne.s   loc_140A7C
                move.w  #1,(menuEntries+MENUENTRY_ISINVISIBLE+$A8).l
                rts
loc_140A7C:
                cmpi.l  #aAbort,(abortText).l ; "ABORT" ...
                bne.s   loc_140A9C
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$A8)).l,a0
                move.w  MENUENTRY_BG+ENTRYTYPE1UNION_BACKANDFRAMECOLOR(a0),d0
                andi.w  #$FFF0,d0
                addi.w  #RED_10,d0
                move.w  d0,MENUENTRY_BG+ENTRYTYPE1UNION_BACKANDFRAMECOLOR(a0)
loc_140A9C:
                tst.w   (contAbortDefault).l
                beq.s   locret_140AAE
                move.w  #3,d0
                jsr     SetCurrentEntry
locret_140AAE:
                rts

; ===== ContinueSelected =====
; prototype: void ContinueSelected()
ContinueSelected:
                clr.w   (contAbortResult).l
                jmp     SetExitMenuFlag

; ===== AbortSelected =====
; prototype: void AbortSelected()
AbortSelected:
                move.w  #1,(contAbortResult).l
                jmp     SetExitMenuFlag
