contAbortDefault:
                dc.w $0000              ; Select default entry:
                                        ; 0 = continue default
                                        ; !0 = abort default
contAbortResult:
                dc.w $0000              ; Contains result from continue/abort prompt
                                        ; 0 = continue, 1 = abort
