FriendlyMenu:
                move.w  (currentTick).l,(seed).l
                jsr     Friendly
                bra.w   CommonMenuExit

; ===== DIYCompetitionMenu =====
; prototype: void __usercall DIYCompetitionMenu()
DIYCompetitionMenu:
                move.w  (currentTick).l,(seed).l
                lea     (aDiyCompetition_0).l,a0 ; "DIY COMPETITION"
                jsr     CheckContinueAbortPrompt
                bne.s   loc_140DD8
                lea     (diyCompetitionMenu).l,a6
                jsr     ShowMenu
                tst.w   (diySelected).l
                bmi.s   loc_140DD8
                tst.w   (diySelected).l
                beq.s   loc_140DBE
                cmpi.w  #1,(diySelected).l
                beq.s   loc_140DB6
                jsr     ShowDesignDIYTournamentMenu
                bra.s   loc_140DC4
loc_140DB6:
                jsr     ShowDesignDIYCupMenu
                bra.s   loc_140DC4
loc_140DBE:
                jsr     ShowDesignDIYLeagueMenu
loc_140DC4:
                cmpi.w  #0,(gameType).l
                beq.s   loc_140DD8
                move.w  #$B,d0
                jsr     SetCurrentEntry
loc_140DD8:
                bra.w   CommonMenuExit

