                bsr.w   CommonMenuExit
locret_140E04:
                rts
loc_140E06:
                move.w  #2,d0
                jsr     InitCareerVariables
                movea.l selectedContest(pc),a6
                cmpi.b  #0,1(a6)
                beq.s   loc_140E26
                cmpi.b  #1,1(a6)
                beq.s   loc_140E64
                bra.s   loc_140E9E
loc_140E26:
                lea     (diyLeagueTeamIds).l,a0
                move.w  (numSelectedTeams).l,d0
                jsr     CopySelectedTeamNumbers
                movea.l selectedContest(pc),a0
