; ===== ChooseTacticsInit =====
; prototype: void __usercall ChooseTacticsInit()
; Init choose tactics menu. Set menu item names to names of tactics - simply put
; addresses of tactics into item name pointers - because tactics structure
; begins with zero terminated string (tactics name).
ChooseTacticsInit:
                jsr     CheckIsTeamNational
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$38)).l,a0
                move.l  #teamTacticsUSERA+TEAMTACTICS_NAME,MENUENTRY_FG+ENTRYTYPE2UNION_STRING(a0)
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$70)).l,a0
                move.l  #teamTacticsUSERB+TEAMTACTICS_NAME,MENUENTRY_FG+ENTRYTYPE2UNION_STRING(a0)
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$A8)).l,a0
                move.l  #teamTacticsUSERC+TEAMTACTICS_NAME,MENUENTRY_FG+ENTRYTYPE2UNION_STRING(a0)
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$E0)).l,a0
                move.l  #teamTacticsUSERD+TEAMTACTICS_NAME,MENUENTRY_FG+ENTRYTYPE2UNION_STRING(a0)
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$118)).l,a0
                move.l  #teamTacticsUSERE+TEAMTACTICS_NAME,MENUENTRY_FG+ENTRYTYPE2UNION_STRING(a0)
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$150)).l,a0
                move.l  #teamTacticsUSERF+TEAMTACTICS_NAME,MENUENTRY_FG+ENTRYTYPE2UNION_STRING(a0)
                rts

