; ===== LoadTactics =====
; prototype: void __usercall LoadTactics()
LoadTactics:
                move.w  #$FFFF,(importMenuSelectedTactics).l
                lea     (aLoadEditedTact).l,a0 ; "LOAD EDITED TACTICS"
                jsr     Asset_PromptInsertSaveDiskDf0
                bne.s   loc_14D5B6
                lea     (aLoadEditedTact).l,a1 ; "LOAD EDITED TACTICS"
                jsr     GetFilenameAndExtension
                bne.s   loc_14D5AA
                cmpi.l  #'.TAC',d1
                bne.s   loc_14D59E
                movem.l a0,-(sp)
                bsr.w   SaveCurrentTactics
                movem.l (sp)+,a0
                lea     (editTacticsCurrentTactics).l,a1
                movem.l a0,-(sp)
                jsr     ReadTacticsFile
                movem.l (sp)+,a0
                bne.s   loc_14D5AA
                lea     (importTacticsFilename).l,a1
                jsr     StringCopy
                move.w  #1000,(importMenuSelectedTactics).l
                move.w  #1,(tacticsChangedFlag).l
                bra.s   loc_14D5AA
loc_14D59E:
                lea     (aNotATacticsFil).l,a0 ; "NOT A TACTICS FILE"
                jsr     ShowErrorMenu
loc_14D5AA:
                lea     (aLoadEditedTact).l,a0 ; "LOAD EDITED TACTICS"
                jsr     ShowInsertDisk2Dialog
loc_14D5B6:
                jmp     SetExitMenuFlag
importMenuSelectedTactics:
                dc.w $0000              ; In import tactics menu, number of selected tactic
                                        ; 1000 = imported tactic, rest is in enumeration
                                        ; -1 = import aborted

